var REFRI_QUESTIONS=[{id:"refri_1",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema dom\xE9stico con R-600a (Isobutano), se detecta una fuga. \xBFPor qu\xE9 est\xE1 estrictamente prohibido usar nitr\xF3geno con trazas de helio para presurizar sin antes evacuar?",opciones:["Por el riesgo de explosi\xF3n al mezclar aire/refrigerante con presi\xF3n.","Porque el R-600a se vuelve \xE1cido en contacto con el helio.","Porque el nitr\xF3geno da\xF1a el aceite mineral del sistema.","No est\xE1 prohibido, es el procedimiento est\xE1ndar."],respuesta_correcta:0,explicacion:"El R-600a es altamente inflamable. Mezclar presiones altas de nitr\xF3geno/aire con residuos de hidrocarburos puede alcanzar el punto de autoignici\xF3n.",question:"In a domestic system using R-600a (Isobutane), a leak is detected. Why is it strictly prohibited to pressurize with nitrogen/helium trace gas without first evacuating the system?",options:["Due to the risk of explosion when mixing air/refrigerant under pressure.","Because R-600a becomes acidic in contact with helium.","Because nitrogen damages the mineral oil in the system.","It is not prohibited; it is the standard procedure."],explanation:"R-600a is highly flammable. Mixing high-pressure nitrogen/air with hydrocarbon residues can reach the auto-ignition point."},{id:"refri_2",categoria:"REFRI_DOMESTICA",pregunta:"En una unidad sellada, \xBFcu\xE1l es el s\xEDntoma principal de una v\xE1lvula de descarga del compresor que no sella bien (leaking bypass)?",opciones:["Presi\xF3n de succi\xF3n muy baja.","Presi\xF3n de succi\xF3n sube r\xE1pidamente al apagar el equipo.","El condensador se calienta uniformemente.","El tubo capilar se congela."],respuesta_correcta:1,explicacion:"Si la v\xE1lvula de descarga no sella, la alta presi\xF3n vuelve al lado de baja apenas el compresor se detiene, igualando presiones casi instant\xE1neamente.",question:"In a sealed unit, what is the main symptom of a compressor discharge valve that does not seal properly (leaking bypass)?",options:["Very low suction pressure.","Suction pressure rises rapidly when the unit is shut off.","The condenser heats up uniformly.","The capillary tube freezes."],explanation:"If the discharge valve does not seal, high pressure flows back to the low side as soon as the compressor stops, equalizing pressures almost instantly."},{id:"refri_3",categoria:"REFRI_DOMESTICA",pregunta:"Si conviertes un sistema de R-134a a R-600a (no recomendado), \xBFqu\xE9 cambio principal notar\xEDas en el desplazamiento del compresor?",opciones:["El R-600a requiere un compresor casi el doble de grande para la misma capacidad.","El R-600a requiere un compresor m\xE1s peque\xF1o.","Las presiones ser\xEDan exactamente las mismas.","El R-600a da\xF1ar\xEDa el barniz de las bobinas instant\xE1neamente."],respuesta_correcta:0,explicacion:"El R-600a tiene una capacidad volum\xE9trica mucho menor que el R-134a; por lo tanto, necesita un volumen de desplazamiento mucho mayor para mover la misma carga t\xE9rmica.",question:"If you convert a system from R-134a to R-600a (not recommended), what main change would you notice in compressor displacement?",options:["R-600a requires a compressor nearly twice as large for the same capacity.","R-600a requires a smaller compressor.","The pressures would be exactly the same.","R-600a would instantly damage the winding varnish."],explanation:"R-600a has a much lower volumetric capacity than R-134a; therefore, it needs a much larger displacement volume to move the same thermal load."},{id:"refri_4",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una restricci\xF3n total en el tubo capilar. \xBFC\xF3mo se comportar\xE1 el amperaje del compresor?",opciones:["Subir\xE1 dr\xE1sticamente por encima del RLA.","Bajar\xE1 por debajo de lo normal despu\xE9s de unos minutos.","Se mantendr\xE1 exactamente en el LRA.","El t\xE9rmico disparar\xE1 instant\xE1neamente."],respuesta_correcta:1,explicacion:"Al estar obstruido, el compresor deja de mover masa de refrigerante. Menos trabajo (bombeo) resulta en una ca\xEDda del amperaje de operaci\xF3n.",question:"A domestic refrigerator has a total restriction in the capillary tube. How will the compressor amperage behave?",options:["It will rise drastically above the RLA.","It will drop below normal after a few minutes.","It will stay exactly at the LRA.","The thermal overload will trip instantly."],explanation:"When blocked, the compressor stops moving refrigerant mass. Less work (pumping) results in a drop in operating amperage."},{id:"refri_5",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema de deshielo de un refrigerador No-Frost, \xBFqu\xE9 componente se encarga de conectar la resistencia cuando el serpent\xEDn est\xE1 fr\xEDo?",opciones:["El Timer.","El Bimetal.","El Termostato de ambiente.","El Compresor."],respuesta_correcta:1,explicacion:"El bimetal est\xE1 en serie con la resistencia; si no hay fr\xEDo (ej. 25\xB0F o menos), el circuito permanece abierto para evitar calentamiento innecesario.",question:"In a No-Frost refrigerator defrost system, which component is responsible for energizing the defrost heater when the coil is cold?",options:["The defrost timer.","The bimetal thermostat.","The room thermostat.","The compressor."],explanation:"The bimetal is wired in series with the heater; if the coil is not cold enough (e.g., 25 degrees F or below), the circuit remains open to prevent unnecessary heating."},{id:"refri_6",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene el condensador empotrado en las paredes laterales. Si estas paredes est\xE1n fr\xEDas al tacto mientras el compresor funciona, el diagn\xF3stico es:",opciones:["El equipo funciona eficientemente.","Falta total de refrigerante o compresor que no bombea.","Exceso de carga.","Termostato pegado."],respuesta_correcta:1,explicacion:"Si no hay calor en el condensador, no hay transferencia de energ\xEDa desde el interior; el sistema no est\xE1 operando t\xE9rmicamente.",question:"A domestic refrigerator has the condenser embedded in the side walls. If these walls are cold to the touch while the compressor is running, the diagnosis is:",options:["The unit is operating efficiently.","Complete loss of refrigerant charge or a compressor that is not pumping.","Overcharge of refrigerant.","Thermostat stuck."],explanation:"If there is no heat in the condenser, there is no energy transfer from the interior; the system is not operating thermally."},{id:"refri_7",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema con R-134a, encuentras una mancha de aceite en la uni\xF3n de la descarga. \xBFQu\xE9 indica?",opciones:["Es normal, el aceite sale por los poros.","Existe una fuga de refrigerante en ese punto.","El compresor tiene exceso de aceite.","El sistema est\xE1 muy limpio."],respuesta_correcta:1,explicacion:"El refrigerante y el aceite viajan juntos; donde hay una mancha de aceite, casi siempre hay una fuga de gas.",question:"In a system using R-134a, you find an oil stain at the discharge line joint. What does this indicate?",options:["It is normal; oil seeps through the pores.","There is a refrigerant leak at that point.","The compressor has excess oil.","The system is very clean."],explanation:"Refrigerant and oil travel together; where there is an oil stain, there is almost always a refrigerant leak."},{id:"refri_8",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico usa R-134a. Al medir presiones, encuentras que la succi\xF3n est\xE1 en vac\xEDo (0-5 inHg) y la alta est\xE1 normal tirando a baja. \xBFQu\xE9 sospechas?",opciones:["Compresor agotado.","Humedad congelada en la salida del capilar o restricci\xF3n total.","Fuga de gas masiva.","Ventilador del evaporador quemado."],respuesta_correcta:1,explicacion:"Si el sistema entra en vac\xEDo pero tiene gas, significa que el refrigerante est\xE1 atrapado antes del evaporador por una obstrucci\xF3n (t\xEDpicamente hielo por humedad).",question:"A domestic refrigerator uses R-134a. When measuring pressures, you find suction is in a vacuum (0-5 inHg) and the high side is normal to slightly low. What do you suspect?",options:["Worn-out compressor.","Moisture frozen at the capillary tube outlet or a total restriction.","Massive refrigerant leak.","Burned evaporator fan motor."],explanation:"If the system pulls into a vacuum but still has charge, the refrigerant is trapped before the evaporator by an obstruction (typically ice from moisture)."},{id:"refri_9",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador con R-600a, la carga t\xEDpica suele ser de:",opciones:["2 a 5 kilogramos.","50 a 150 gramos.","1 a 2 libras.","10 a 20 onzas."],respuesta_correcta:1,explicacion:"El R-600a es muy eficiente y requiere cargas muy peque\xF1as. Por seguridad (inflamabilidad), se limita a menos de 150g en aplicaciones dom\xE9sticas.",question:"In a refrigerator using R-600a, the typical charge is usually:",options:["2 to 5 kilograms.","50 to 150 grams.","1 to 2 pounds.","10 to 20 ounces."],explanation:"R-600a is very efficient and requires very small charges. For safety reasons (flammability), it is limited to less than 150 grams in domestic applications."},{id:"refri_10",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 los refrigeradores dom\xE9sticos modernos usan condensadores 'est\xE1ticos' (sin ventilador)?",opciones:["Para ahorrar costos y reducir el ruido, aprovechando la convecci\xF3n natural.","Porque el R-600a no genera calor.","Porque los ventiladores est\xE1n prohibidos en casas.","Para aumentar la presi\xF3n de descarga."],respuesta_correcta:0,explicacion:"En sistemas de baja capacidad, la superficie del gabinete o una rejilla trasera es suficiente para rechazar el calor sin partes m\xF3viles.",question:"Why do modern domestic refrigerators use static condensers (without a fan)?",options:["To save costs and reduce noise by relying on natural convection.","Because R-600a does not generate heat.","Because fans are prohibited in homes.","To increase discharge pressure."],explanation:"In low-capacity systems, the cabinet surface or a rear grille provides enough area to reject heat without any moving parts."},{id:"refri_11",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es el s\xEDntoma de una v\xE1lvula de expansi\xF3n capilar obstruida por parafina?",opciones:["El equipo enfr\xEDa demasiado.","El equipo deja de enfriar intermitentemente cuando la temperatura baja mucho.","Sube el amperaje del compresor.","El condensador se calienta mucho."],respuesta_correcta:1,explicacion:"Al bajar la temperatura, la parafina se endurece y tapa el flujo; al apagarse y calentarse, vuelve a fluir (falla intermitente).",question:"What is the symptom of a capillary tube obstructed by wax (paraffin)?",options:["The unit overcools.","The unit stops cooling intermittently when the temperature drops very low.","Compressor amperage increases.","The condenser gets very hot."],explanation:"When the temperature drops, the wax hardens and blocks flow; when the unit shuts off and warms up, flow resumes (intermittent failure)."},{id:"refri_12",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico con R-600a presenta un consumo de amperaje menor al nominal y el condensador est\xE1 fr\xEDo. Al cortar el ap\xE9ndice, no sale gas. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Compresor quemado.","Fuga de refrigerante (Sistema vac\xEDo).","Filtro tapado.","Exceso de aceite en el evaporador."],respuesta_correcta:1,explicacion:"Si no hay refrigerante, el compresor no realiza trabajo (baja el amperaje) y no hay calor que rechazar en el condensador.",question:"A domestic refrigerator using R-600a shows lower-than-rated amperage and the condenser is cold. When cutting the process tube, no gas escapes. What is the diagnosis?",options:["Burned compressor.","Refrigerant leak (system is empty).","Clogged filter.","Excess oil in the evaporator."],explanation:"If there is no refrigerant, the compressor performs no work (amperage drops) and there is no heat to reject at the condenser."},{id:"refri_13",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 los sistemas de R-600a requieren el uso de herramientas 'no chispantes' y uniones mec\xE1nicas (tipo Lokring) en lugar de soldadura directa en algunos casos?",opciones:["Porque el cobre se debilita.","Debido a la alta inflamabilidad del refrigerante y el riesgo de explosi\xF3n con residuos de gas.","Porque la soldadura tapa el capilar.","Para ahorrar gas de soldar."],respuesta_correcta:1,explicacion:"El isobutano es un hidrocarburo. Cualquier residuo en el sistema puede encenderse con la llama del soplete.",question:"Why do R-600a systems require the use of non-sparking tools and mechanical fittings (such as Lokring) instead of direct brazing in some cases?",options:["Because the copper weakens.","Due to the high flammability of the refrigerant and the risk of explosion from residual gas.","Because brazing clogs the capillary tube.","To save brazing gas."],explanation:"Isobutane is a hydrocarbon. Any residual gas in the system can ignite from a torch flame."},{id:"refri_14",categoria:"REFRI_DOMESTICA",pregunta:"Al cambiar un compresor quemado en un refrigerador, \xBFpor qu\xE9 es obligatorio instalar un filtro deshidratador nuevo?",opciones:["Por est\xE9tica.","Para atrapar \xE1cidos y humedad liberados durante la quemadura del motor anterior.","Para aumentar la presi\xF3n de alta.","Porque el filtro viejo se rompe al desoldar."],respuesta_correcta:1,explicacion:"Un 'Burnout' deja residuos \xE1cidos que, si no se eliminan, destruir\xE1n el barniz del compresor nuevo en poco tiempo.",question:"When replacing a burned-out compressor in a refrigerator, why is it mandatory to install a new filter drier?",options:["For aesthetics.","To trap acids and moisture released during the burnout of the previous motor.","To increase high-side pressure.","Because the old filter breaks during debrazing."],explanation:"A burnout leaves acidic residues that, if not removed, will destroy the winding varnish of the new compressor in a short time."},{id:"refri_15",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la presi\xF3n de reposo (equilibrada) aproximada de un sistema con R-134a a una temperatura ambiente de 80\xB0F?",opciones:["30 PSI","87 PSI","150 PSI","200 PSI"],respuesta_correcta:1,explicacion:"Siguiendo la tabla de Presi\xF3n-Temperatura, a 80\xB0F el R-134a tiene una presi\xF3n de saturaci\xF3n de aproximadamente 86.7 PSI.",question:"What is the approximate equalized (standstill) pressure of an R-134a system at an ambient temperature of 80 degrees F?",options:["30 PSI","87 PSI","150 PSI","200 PSI"],explanation:"According to the Pressure-Temperature chart, at 80 degrees F, R-134a has a saturation pressure of approximately 86.7 PSI."},{id:"refri_16",categoria:"REFRI_DOMESTICA",pregunta:"Un compresor dom\xE9stico intenta arrancar, hace un sonido 'clic' y se detiene. El amperaje medido es de 15A por un segundo. El LRA en la etiqueta es 16A. \xBFQu\xE9 sospechas?",opciones:["Falta de gas.","Compresor trabado mec\xE1nicamente o relay de arranque da\xF1ado.","Termostato en corto.","Voltaje muy alto."],respuesta_correcta:1,explicacion:"Si el amperaje llega casi al LRA (Locked Rotor Amps) y corta, el motor no puede girar.",question:"A domestic compressor attempts to start, makes a 'click' sound, and shuts off. The measured amperage is 15A for one second. The nameplate LRA is 16A. What do you suspect?",options:["Low refrigerant charge.","Mechanically seized compressor or a faulty start relay.","Thermostat short circuit.","Excessively high voltage."],explanation:"If the amperage reaches near the LRA (Locked Rotor Amps) and then cuts out, the motor cannot rotate."},{id:"refri_17",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 sucede si el ventilador del evaporador de un refrigerador No-Frost se quema?",opciones:["El compresor se apaga por alta presi\xF3n.","El serpent\xEDn se bloquea de hielo y el gabinete deja de enfriar.","El refrigerador consume menos energ\xEDa.","El condensador se calienta m\xE1s."],respuesta_correcta:1,explicacion:"Sin flujo de aire, el calor del gabinete no llega al refrigerante; el hielo se acumula r\xE1pidamente hasta bloquear todo el flujo de aire.",question:"What happens if the evaporator fan motor in a No-Frost refrigerator burns out?",options:["The compressor shuts off on high pressure.","The evaporator coil ices over and the cabinet stops cooling.","The refrigerator consumes less energy.","The condenser gets hotter."],explanation:"Without airflow, the heat from the cabinet does not reach the refrigerant; ice accumulates rapidly until it blocks all airflow."},{id:"refri_18",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador de escarcha (manual defrost) tiene hielo solo en la parte superior del evaporador. \xBFCu\xE1l es la causa?",opciones:["Puerta abierta.","Falta parcial de refrigerante.","Filtro sucio.","Termostato da\xF1ado."],respuesta_correcta:1,explicacion:"Al faltar gas, este se expande totalmente al inicio del serpent\xEDn; el resto del evaporador permanece caliente.",question:"A manual-defrost refrigerator has frost only on the upper portion of the evaporator. What is the cause?",options:["Door left open.","Partial loss of refrigerant charge.","Dirty filter.","Faulty thermostat."],explanation:"When refrigerant is low, it fully expands at the beginning of the coil; the remainder of the evaporator stays warm."},{id:"refri_19",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 un compresor de R-134a no debe cargarse con R-12 aunque las presiones sean similares?",opciones:["Porque el R-12 es ilegal.","Porque los aceites (POE del 134a y Mineral del R-12) son incompatibles y el compresor fallar\xE1.","Porque el R-12 enfr\xEDa demasiado.","Porque las tuber\xEDas explotan."],respuesta_correcta:1,explicacion:"El aceite POE es altamente higrosc\xF3pico y dise\xF1ado para HFC; el R-12 no regresar\xE1 el aceite POE correctamente al compresor.",question:"Why must a compressor designed for R-134a not be charged with R-12 even though the pressures are similar?",options:["Because R-12 is illegal.","Because the oils (POE for R-134a and mineral for R-12) are incompatible and the compressor will fail.","Because R-12 cools too much.","Because the tubing would burst."],explanation:"POE oil is highly hygroscopic and designed for HFC refrigerants; R-12 will not properly return POE oil to the compressor."},{id:"refri_20",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador tiene una fuga en el serpent\xEDn interno (dentro del gabinete). \xBFPor qu\xE9 suele ser irreparable?",opciones:["Porque el gas es t\xF3xico.","Porque las tuber\xEDas est\xE1n inyectadas en espuma de poliuretano y el acceso destruir\xEDa la estructura.","Porque no se puede soldar aluminio.","Porque el cliente no quiere pagar."],respuesta_correcta:1,explicacion:"La mayor\xEDa de los equipos modernos son desechables ante fugas internas debido al costo de reconstruir el gabinete.",question:"A refrigerator has a leak in the internal evaporator coil (inside the cabinet). Why is it usually irreparable?",options:["Because the gas is toxic.","Because the tubing is embedded in polyurethane foam insulation and accessing it would destroy the cabinet structure.","Because aluminum cannot be brazed.","Because the customer does not want to pay."],explanation:"Most modern units are considered disposable when an internal leak occurs due to the cost of rebuilding the cabinet."},{id:"refri_21",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador No-Frost hace un ruido de 'raspado' fuerte que se detiene al abrir la puerta del congelador. \xBFQu\xE9 es?",opciones:["El compresor muriendo.","El ventilador del evaporador chocando con hielo acumulado.","El gas circulando.","Un rat\xF3n."],respuesta_correcta:1,explicacion:"Al abrir la puerta, el interruptor apaga el ventilador. El ruido indica un problema de desescarche que acumul\xF3 hielo hasta el aspa.",question:"A No-Frost refrigerator makes a loud scraping noise that stops when the freezer door is opened. What is it?",options:["The compressor dying.","The evaporator fan blade hitting accumulated ice.","Refrigerant circulating.","A mouse."],explanation:"Opening the door triggers the door switch, which shuts off the fan. The noise indicates a defrost problem that allowed ice to build up to the fan blade."},{id:"refri_22",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta escarcha en la l\xEDnea de succi\xF3n hasta llegar al compresor. \xBFCu\xE1l es el diagn\xF3stico m\xE1s probable?",opciones:["Falta de gas.","Exceso de carga de refrigerante o ventilador del evaporador detenido.","Filtro tapado.","Ambiente externo muy caluroso."],respuesta_correcta:1,explicacion:"La escarcha en la succi\xF3n indica que el refrigerante no termin\xF3 de evaporarse en el evaporador. Esto ocurre si no hay intercambio de calor (ventilador malo) o si hay demasiado refrigerante.",question:"A domestic refrigerator has frost on the suction line all the way back to the compressor. What is the most likely diagnosis?",options:["Low refrigerant charge.","Overcharge of refrigerant or a stalled evaporator fan motor.","Clogged filter.","Excessively hot ambient temperature."],explanation:"Frost on the suction line indicates that the refrigerant did not fully evaporate in the evaporator. This occurs when there is insufficient heat exchange (bad fan) or when there is too much refrigerant."},{id:"refri_23",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Intercambiador de calor' formado por el capilar soldado a la l\xEDnea de succi\xF3n?",opciones:["Calentar el gabinete.","Subenfriar el l\xEDquido que va al evaporador y sobrecalentar el vapor que regresa al compresor para evitar golpes de l\xEDquido.","Aumentar la presi\xF3n de descarga.","Evitar que el capilar se rompa."],respuesta_correcta:1,explicacion:"Es una mejora de eficiencia: el fr\xEDo de la succi\xF3n ayuda al capilar y el calor del capilar asegura que no llegue l\xEDquido al compresor.",question:"What is the function of the heat exchanger formed by the capillary tube soldered to the suction line?",options:["To heat the cabinet.","To subcool the liquid going to the evaporator and superheat the vapor returning to the compressor, preventing liquid slugging.","To increase discharge pressure.","To prevent the capillary tube from breaking."],explanation:"It is an efficiency improvement: the cold suction line helps the capillary tube, and the warm capillary tube ensures no liquid reaches the compressor."},{id:"refri_24",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador con sistema capilar, si se produce un vac\xEDo en el lado de succi\xF3n inmediatamente despu\xE9s de encenderlo, el problema es:",opciones:["Falta de refrigerante.","Obstrucci\xF3n total (t\xEDpicamente humedad congelada) en el capilar.","Compresor muy potente.","Condensador sucio."],respuesta_correcta:1,explicacion:"El compresor succiona lo poco que hay en el evaporador, pero como el capilar est\xE1 tapado, no entra refrigerante nuevo al lado de baja.",question:"In a capillary tube system, if a vacuum develops on the suction side immediately after startup, the problem is:",options:["Low refrigerant charge.","Total obstruction (typically frozen moisture) in the capillary tube.","Oversized compressor.","Dirty condenser."],explanation:"The compressor draws out whatever is in the evaporator, but since the capillary tube is blocked, no new refrigerant enters the low side."},{id:"refri_25",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 un t\xE9cnico nunca debe tocar los tubos de un refrigerador encendido con las manos mojadas?",opciones:["Por el riesgo de dejar manchas.","Por el riesgo de descarga el\xE9ctrica si hay una falla de aislamiento y para evitar quemaduras por fr\xEDo/calor extremos.","Porque el sudor da\xF1a el cobre.","Porque el refrigerante se escapa por los poros."],respuesta_correcta:1,explicacion:"El agua reduce la resistencia el\xE9ctrica del cuerpo y aumenta el riesgo de shock, adem\xE1s de que la piel puede pegarse a tuber\xEDas a temperaturas bajo cero.",question:"Why should a technician never touch the tubing of a running refrigerator with wet hands?",options:["Risk of leaving fingerprint marks.","Risk of electrical shock if there is an insulation fault, and to avoid burns from extremely hot or cold surfaces.","Because sweat damages the copper.","Because refrigerant escapes through the pores."],explanation:"Water reduces the body's electrical resistance and increases shock risk; additionally, skin can stick to tubing at sub-zero temperatures."},{id:"refri_26",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 gas se utiliza para la 'Limpieza de Barrido' en un sistema dom\xE9stico antes de soldar?",opciones:["Ox\xEDgeno.","Nitr\xF3geno seco (OFN).","Aire comprimido.","Gas propano."],respuesta_correcta:1,explicacion:"El nitr\xF3geno desplaza el aire y la humedad sin reaccionar qu\xEDmicamente y evita la formaci\xF3n de holl\xEDn interno al soldar.",question:"What gas is used for a purge sweep in a domestic system before brazing?",options:["Oxygen.","Dry nitrogen (OFN - Oxygen Free Nitrogen).","Compressed air.","Propane gas."],explanation:"Nitrogen displaces air and moisture without reacting chemically and prevents the formation of internal scale (oxide) during brazing."},{id:"refri_27",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 sucede si el cable de tierra de un refrigerador se desconecta y hay una fuga de corriente en el compresor?",opciones:["El refrigerador deja de enfriar.","El chasis del equipo se energiza, representando un riesgo mortal de electrocuci\xF3n al tocarlo.","El consumo de luz baja.","El compresor gira m\xE1s r\xE1pido."],respuesta_correcta:1,explicacion:"La tierra es la protecci\xF3n que desv\xEDa la corriente de falla. Sin ella, el cuerpo humano se convierte en el camino a tierra.",question:"What happens if the ground wire of a refrigerator is disconnected and there is a current leak in the compressor?",options:["The refrigerator stops cooling.","The chassis of the unit becomes energized, posing a lethal electrocution risk when touched.","The power consumption decreases.","The compressor spins faster."],explanation:"The ground wire is the safety path that diverts fault current. Without it, the human body becomes the path to ground."},{id:"refri_28",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 componente de un refrigerador dom\xE9stico es responsable de derivar el aire fr\xEDo del congelador hacia el refrigerador?",opciones:["El termostato.","El Damper (puerta de aire).","El evaporador.","El bimetal."],respuesta_correcta:1,explicacion:"El damper regula cu\xE1nto aire fr\xEDo pasa hacia abajo; si falla cerrado, el refrigerador estar\xE1 caliente aunque el congelador est\xE9 perfecto.",question:"Which component in a domestic refrigerator is responsible for directing cold air from the freezer to the fresh food compartment?",options:["The thermostat.","The air damper.","The evaporator.","The bimetal thermostat."],explanation:"The damper regulates how much cold air passes to the lower compartment; if it fails in the closed position, the fresh food section will be warm even though the freezer is fine."},{id:"refri_29",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema de refrigeraci\xF3n por absorci\xF3n peque\xF1o (como los de hoteles o casas rodantes), \xBFcu\xE1l es la fuente de energ\xEDa?",opciones:["Un compresor miniatura.","Una resistencia el\xE9ctrica o una llama de gas propano que calienta la soluci\xF3n.","Pilas AA.","Fricci\xF3n magn\xE9tica."],respuesta_correcta:1,explicacion:"Son sistemas silenciosos (sin partes m\xF3viles) que usan calor para generar el ciclo de refrigeraci\xF3n.",question:"In a small absorption refrigeration system (such as those in hotels or RVs), what is the energy source?",options:["A miniature compressor.","An electric heating element or a propane gas flame that heats the solution.","AA batteries.","Magnetic friction."],explanation:"These are silent systems (no moving parts) that use heat to drive the refrigeration cycle."},{id:"refri_30",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador dom\xE9stico, \xBFpor qu\xE9 el tubo de descarga suele entrar al c\xE1rter antes de ir al condensador en algunos modelos?",opciones:["Para calentar el aceite y evitar migraci\xF3n de l\xEDquido.","Para enfriar el gas de descarga aprovechando el aceite.","Para que el compresor no haga ruido.","Es un error de fabricaci\xF3n."],respuesta_correcta:0,explicacion:"Ayuda a mantener el aceite caliente durante el ciclo de operaci\xF3n, mejorando la lubricaci\xF3n y evitando que el refrigerante se mezcle con el aceite.",question:"In a domestic refrigerator, why does the discharge tube sometimes pass through the crankcase before going to the condenser in some models?",options:["To heat the oil and prevent liquid migration.","To cool the discharge gas using the oil.","To make the compressor quieter.","It is a manufacturing defect."],explanation:"It helps keep the oil warm during operation, improving lubrication and preventing refrigerant from mixing with the oil."},{id:"refri_31",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 material es el desecante m\xE1s com\xFAn en los filtros de refrigeradores dom\xE9sticos?",opciones:["Arena sil\xEDcea.","Tamiz molecular (Zeolita).","Algod\xF3n prensado.","Carb\xF3n activado."],respuesta_correcta:1,explicacion:"Las perlas de tamiz molecular tienen poros microsc\xF3picos que atrapan las mol\xE9culas de agua pero dejan pasar el refrigerante.",question:"What material is the most common desiccant used in domestic refrigerator filter driers?",options:["Silica sand.","Molecular sieve (Zeolite).","Compressed cotton.","Activated carbon."],explanation:"Molecular sieve beads have microscopic pores that trap water molecules but allow the refrigerant to pass through."},{id:"refri_32",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico con R-134a tiene una presi\xF3n de succi\xF3n de 20 PSI y una descarga de 150 PSI. \xBFEst\xE1 operando correctamente para un conservador?",opciones:["S\xED, son presiones est\xE1ndar.","No, la presi\xF3n de succi\xF3n es demasiado alta (saturaci\xF3n a 22\xB0F); deber\xEDa estar cerca de los 2-10 PSI.","No, la presi\xF3n de descarga es muy baja.","Falta gas."],respuesta_correcta:1,explicacion:"Para refrigeraci\xF3n dom\xE9stica (35-40\xB0F de aire), el evaporador debe estar a unos 10-20\xB0F (aprox. 5-12 PSI). 20 PSI es una temperatura de evaporaci\xF3n demasiado alta para enfriar bien.",question:"A domestic refrigerator using R-134a has a suction pressure of 20 PSI and a discharge pressure of 150 PSI. Is it operating correctly for a fresh food compartment?",options:["Yes, those are standard pressures.","No, the suction pressure is too high (saturates at 22 degrees F); it should be near 2-10 PSI.","No, the discharge pressure is too low.","Low on refrigerant."],explanation:"For domestic refrigeration (35-40 degrees F air), the evaporator should be at about 10-20 degrees F (approximately 5-12 PSI). 20 PSI gives a saturation temperature that is too high to cool effectively."},{id:"refri_33",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Relay PTC' en un compresor dom\xE9stico?",opciones:["Proteger contra sobrevoltaje.","Conectar el devanado de arranque y desconectarlo por aumento de temperatura/resistencia una vez que el motor gira.","Medir la presi\xF3n de succi\xF3n.","Controlar la luz interna."],respuesta_correcta:1,explicacion:"El PTC (Coeficiente de Temperatura Positivo) aumenta su resistencia al calentarse por el paso de corriente, 'sacando' el arranque del circuito.",question:"What is the function of a PTC relay in a domestic compressor?",options:["To protect against overvoltage.","To engage the start winding and disconnect it as its temperature/resistance increases once the motor is running.","To measure suction pressure.","To control the interior light."],explanation:"The PTC (Positive Temperature Coefficient) device increases its resistance as it heats up from current flow, effectively removing the start winding from the circuit."},{id:"refri_34",categoria:"REFRI_DOMESTICA",pregunta:"Si el bimetal de deshielo se queda 'pegado' (siempre cerrado), \xBFqu\xE9 s\xEDntoma presentar\xE1 el refrigerador?",opciones:["No enfriar\xE1 nada.","El ciclo de deshielo durar\xE1 demasiado, pudiendo calentar el gabinete en exceso y deformar pl\xE1sticos si el timer no corta a tiempo.","El compresor no arrancar\xE1.","La luz interna no encender\xE1."],respuesta_correcta:1,explicacion:"La funci\xF3n del bimetal es abrir el circuito cuando ya no hay hielo. Si se queda pegado, la resistencia seguir\xE1 calentando hasta que el timer termine el tiempo.",question:"If the defrost bimetal thermostat gets stuck closed (always closed), what symptom will the refrigerator show?",options:["It will not cool at all.","The defrost cycle will last too long, potentially overheating the cabinet and warping plastic parts if the timer does not cut off in time.","The compressor will not start.","The interior light will not turn on."],explanation:"The bimetal's function is to open the circuit when the ice is gone. If it stays closed, the heater will keep heating until the timer ends the cycle."},{id:"refri_35",categoria:"REFRI_DOMESTICA",pregunta:"Al instalar un compresor nuevo, el t\xE9cnico usa fundente (flux) en exceso para soldar cobre con cobre. \xBFQu\xE9 riesgo hay?",opciones:["Que la soldadura quede fea.","Que el fundente entre al sistema, se mezcle con el aceite y cause corrosi\xF3n interna o tape el capilar.","Que el tubo se derrita.","Que el gas no pase."],respuesta_correcta:1,explicacion:"El fundente es \xE1cido. En refrigeraci\xF3n cobre-cobre con varilla de foscocu no se requiere fundente precisamente para evitar contaminar el sistema.",question:"When installing a new compressor, a technician uses excessive flux to braze copper to copper. What is the risk?",options:["The joint will look ugly.","The flux can enter the system, mix with the oil, and cause internal corrosion or clog the capillary tube.","The tubing will melt.","The gas will not flow."],explanation:"Flux is acidic. In copper-to-copper refrigeration brazing with phos-copper (BCuP) alloy, flux is not required precisely to avoid contaminating the system."},{id:"refri_36",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema dom\xE9stico, \xBFqu\xE9 componente regula la presi\xF3n de baja durante el funcionamiento?",opciones:["La TXV.","El tubo capilar, que crea una restricci\xF3n fija basada en su longitud y di\xE1metro.","El termostato.","El ventilador del condensador."],respuesta_correcta:1,explicacion:"A diferencia de sistemas comerciales, el capilar es un control pasivo que no se ajusta a la carga t\xE9rmica.",question:"In a domestic system, which component regulates the low-side pressure during operation?",options:["The TXV.","The capillary tube, which creates a fixed restriction based on its length and inside diameter.","The thermostat.","The condenser fan."],explanation:"Unlike commercial systems, the capillary tube is a passive control device that does not adjust to thermal load changes."},{id:"refri_37",categoria:"REFRI_DOMESTICA",pregunta:"Si el drenaje del refrigerador se tapa, \xBFd\xF3nde aparecer\xE1 el agua usualmente?",opciones:["Dentro del motor.","En el piso del compartimento de alimentos frescos (abajo de los cajones de verduras).","En el condensador.","En la l\xEDnea de succi\xF3n."],respuesta_correcta:1,explicacion:"El agua del deshielo no tiene por d\xF3nde salir y se desborda desde el canal del evaporador hacia el interior del gabinete.",question:"If the drain line of a refrigerator gets clogged, where will the water typically appear?",options:["Inside the motor.","On the floor of the fresh food compartment (under the vegetable crisper drawers).","In the condenser.","On the suction line."],explanation:"The defrost water has nowhere to go and overflows from the evaporator drain channel into the cabinet interior."},{id:"refri_38",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador con R-600a presenta una presi\xF3n de succi\xF3n de -5 inHg (vac\xEDo). El t\xE9cnico a\xF1ade gas y el equipo funciona 20 min y vuelve a vac\xEDo. \xBFCausa?",opciones:["Compresor agotado.","Humedad en el sistema que se congela en la salida del capilar, bloqueando el flujo.","Fuga masiva.","Exceso de aceite."],respuesta_correcta:1,explicacion:"Es la falla cl\xE1sica de humedad. Al apagarse, el hielo se derrite; al encender, se vuelve a congelar.",question:"A refrigerator using R-600a shows a suction pressure of -5 inHg (vacuum). The technician adds refrigerant and the unit works for 20 minutes before returning to vacuum. What is the cause?",options:["Worn-out compressor.","Moisture in the system that freezes at the capillary tube outlet, blocking flow.","Massive leak.","Excess oil."],explanation:"This is the classic moisture failure. When the unit shuts off, the ice melts; when it starts again, it refreezes."},{id:"refri_39",categoria:"REFRI_DOMESTICA",pregunta:"Si un refrigerador dom\xE9stico tiene el condensador pegado a la pared trasera y se llena de pelusa, \xBFqu\xE9 s\xEDntoma presentar\xE1?",opciones:["Baja presi\xF3n de succi\xF3n.","Ciclos de trabajo m\xE1s largos y menor eficiencia de enfriamiento.","Se congela el evaporador.","El motor se enfr\xEDa m\xE1s."],respuesta_correcta:1,explicacion:"El calor no puede salir del sistema; la presi\xF3n de alta sube, el compresor rinde menos y debe trabajar m\xE1s tiempo para lograr la temperatura.",question:"If a domestic refrigerator has the condenser mounted on the back wall and it becomes covered in lint, what symptom will it show?",options:["Low suction pressure.","Longer run cycles and reduced cooling efficiency.","The evaporator freezes up.","The motor runs cooler."],explanation:"Heat cannot leave the system; the high-side pressure rises, the compressor becomes less efficient, and it must run longer to reach the set temperature."},{id:"refri_40",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 no se debe usar un soplete de propano para soldar tuber\xEDas de refrigeraci\xF3n con varilla de plata al 15%?",opciones:["Porque es muy caro.","Porque el propano no alcanza la temperatura necesaria de manera eficiente; se requiere oxi-acetileno o MAP-Pro para una soldadura fuerte (brazing) de calidad.","Porque el propano ensucia el cobre.","Porque el propano es ilegal."],respuesta_correcta:1,explicacion:"La soldadura fuerte requiere calentar el tubo a un rojo cereza que el aire-propano rara vez logra de forma puntual y r\xE1pida.",question:"Why should a propane torch not be used to braze refrigeration tubing with 15% silver brazing alloy?",options:["Because it is too expensive.","Because propane does not reach the required temperature efficiently; oxy-acetylene or MAP-Pro is needed for quality brazing.","Because propane dirties the copper.","Because propane is illegal."],explanation:"Brazing requires heating the tube to a cherry-red color, which an air-propane torch rarely achieves quickly and precisely."},{id:"refri_41",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador No-Frost, el compresor funciona pero el ventilador del evaporador no. \xBFCu\xE1l ser\xE1 la lectura de amperaje del compresor despu\xE9s de 1 hora?",opciones:["M\xE1s alta de lo normal.","M\xE1s baja de lo normal debido a la ca\xEDda en la presi\xF3n de succi\xF3n por falta de carga t\xE9rmica.","Igual a la de placa.","Cero."],respuesta_correcta:1,explicacion:"Al no haber aire, el refrigerante no absorbe calor. La presi\xF3n de succi\xF3n baja, el gas es menos denso y el compresor hace menos trabajo f\xEDsico.",question:"In a No-Frost refrigerator, the compressor runs but the evaporator fan does not. What will the compressor amperage reading be after 1 hour?",options:["Higher than normal.","Lower than normal due to the drop in suction pressure from lack of heat load.","Same as the nameplate rating.","Zero."],explanation:"Without air, the refrigerant does not absorb heat. The suction pressure drops, the gas becomes less dense, and the compressor does less physical work."},{id:"refri_42",categoria:"REFRI_DOMESTICA",pregunta:"Mides un compresor dom\xE9stico y encuentras resistencia de 10 ohms entre C-R y 10 ohms entre C-S. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["El motor es de alta eficiencia.","El motor est\xE1 da\xF1ado (devanados cortocircuitados), ya que el arranque (S) siempre debe ser mayor que la marcha (R).","Es un motor trif\xE1sico.","Falta el capacitor."],respuesta_correcta:1,explicacion:"En compresores monof\xE1sicos de refrigeraci\xF3n, las bobinas nunca son iguales. Una lectura id\xE9ntica indica un fallo interno en el esmaltado del cobre.",question:"You measure a domestic compressor and find 10 ohms between C-R and 10 ohms between C-S. What is the diagnosis?",options:["The motor is high efficiency.","The motor is damaged (shorted windings), since the start winding (S) must always have higher resistance than the run winding (R).","It is a three-phase motor.","The capacitor is missing."],explanation:"In single-phase refrigeration compressors, the windings are never equal. An identical reading indicates an internal fault in the copper enamel insulation."},{id:"refri_43",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema Inverter, \xBFc\xF3mo se logra variar la capacidad de enfriamiento?",opciones:["Encendiendo y apagando el compresor r\xE1pido.","Variando la frecuencia (Hz) de la corriente para cambiar las RPM del motor del compresor.","Cerrando el capilar.","Cambiando el tipo de gas."],respuesta_correcta:1,explicacion:"A diferencia del sistema On/Off, el Inverter ajusta la velocidad para igualar exactamente la carga t\xE9rmica, ahorrando mucha energ\xEDa.",question:"In an inverter system, how is the cooling capacity varied?",options:["By rapidly cycling the compressor on and off.","By varying the frequency (Hz) of the electrical current to change the compressor motor RPM.","By closing the capillary tube.","By changing the type of refrigerant."],explanation:"Unlike a conventional on/off system, the inverter adjusts motor speed to precisely match the thermal load, saving significant energy."},{id:"refri_44",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una fuga en el evaporador de aluminio. \xBFPor qu\xE9 es dif\xEDcil de soldar?",opciones:["Porque el aluminio se quema con el ox\xEDgeno.","Debido a la capa de \xF3xido de aluminio que se forma instant\xE1neamente y requiere fundentes y t\xE9cnicas especiales de temperatura.","Porque el aluminio es magn\xE9tico.","No es dif\xEDcil, se suelda igual que el cobre."],respuesta_correcta:1,explicacion:"El aluminio tiene un punto de fusi\xF3n muy cercano a la temperatura de trabajo del soplete; un descuido de un segundo y se derrite el tubo.",question:"A domestic refrigerator has a leak in the aluminum evaporator. Why is it difficult to repair?",options:["Because aluminum burns with oxygen.","Due to the aluminum oxide layer that forms instantly, requiring special fluxes and brazing techniques at precise temperatures.","Because aluminum is magnetic.","It is not difficult; it brazes the same as copper."],explanation:"Aluminum has a melting point very close to the working temperature of the torch; a one-second lapse can melt the tube."},{id:"refri_45",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 sucede si el ventilador del condensador de un refrigerador est\xE1 bloqueado por suciedad?",opciones:["La presi\xF3n de succi\xF3n baja.","La presi\xF3n de descarga sube, el compresor se sobrecalienta y el protector t\xE9rmico se dispara.","El equipo enfr\xEDa m\xE1s r\xE1pido.","El aceite se vuelve m\xE1s l\xEDquido."],respuesta_correcta:1,explicacion:"El calor no puede salir; el sistema se satura t\xE9rmicamente y el motor sufre por exceso de carga el\xE9ctrica.",question:"What happens if the condenser fan on a refrigerator is blocked by dirt?",options:["Suction pressure drops.","Discharge pressure rises, the compressor overheats, and the thermal overload trips.","The unit cools faster.","The oil becomes more fluid."],explanation:"Heat cannot escape; the system becomes thermally saturated and the motor suffers from excessive electrical load."},{id:"refri_46",categoria:"REFRI_DOMESTICA",pregunta:"Al cargar un refrigerador con R-600a, \xBFpor qu\xE9 es indispensable usar una b\xE1scula de precisi\xF3n?",opciones:["Porque el gas es muy caro.","Porque la carga total suele ser de apenas 40 a 60 gramos; un error de 5 gramos cambia totalmente el rendimiento.","Para que el cliente vea que eres profesional.","Para evitar que el tanque flote."],respuesta_correcta:1,explicacion:"Los sistemas de hidrocarburos son extremadamente sensibles a la masa del refrigerante; el exceso causa inundaci\xF3n inmediata.",question:"When charging a refrigerator with R-600a, why is it essential to use a precision scale?",options:["Because the gas is very expensive.","Because the total charge is typically only 40 to 60 grams; an error of 5 grams drastically changes system performance.","To appear professional to the customer.","To prevent the cylinder from floating."],explanation:"Hydrocarbon systems are extremely sensitive to refrigerant mass; an overcharge causes immediate liquid floodback."},{id:"refri_47",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador 'No Frost' tiene hielo bloqueando los ductos de aire pero el evaporador est\xE1 limpio. \xBFQu\xE9 falla?",opciones:["El sistema de deshielo.","Infiltraci\xF3n de aire por sellos (gaskets) de puerta da\xF1ados o damper trabado.","Falta de refrigerante.","El ventilador gira al rev\xE9s."],respuesta_correcta:1,explicacion:"Si entra aire h\xFAmedo del exterior constantemente, la humedad se condensa y congela en los ductos antes de llegar al evaporador.",question:"A No-Frost refrigerator has ice blocking the air ducts but the evaporator itself is clean. What is wrong?",options:["The defrost system.","Air infiltration through damaged door gaskets or a stuck-open air damper.","Low refrigerant charge.","The fan is spinning in reverse."],explanation:"If warm humid air from outside enters continuously, the moisture condenses and freezes in the ducts before reaching the evaporator."},{id:"refri_48",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador usa una 'Resistencia de Marco' (Perimeter Heater). \xBFCu\xE1l es su prop\xF3sito?",opciones:["Enfriar la puerta.","Calentar el borde del gabinete para evitar que la humedad ambiente se condense y se peguen los sellos de hule.","Calentar la comida.","Reducir el ruido."],respuesta_correcta:1,explicacion:"Sin este calor, el sudor del gabinete oxidar\xEDa el metal y romper\xEDa los empaques magn\xE9ticos por congelamiento.",question:"A domestic refrigerator uses a perimeter heater (mullion heater). What is its purpose?",options:["To cool the door.","To warm the cabinet edge to prevent ambient moisture from condensing and causing the door gaskets to stick.","To warm the food.","To reduce noise."],explanation:"Without this heat, condensation on the cabinet would cause metal corrosion and freeze the magnetic gaskets in place."},{id:"refri_49",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 sucede si se carga un sistema de R-134a con un refrigerante de mezcla (serie 400) sin limpiar el aceite POE?",opciones:["Enfr\xEDa mejor.","Riesgo de incompatibilidad qu\xEDmica y problemas de retorno de aceite debido a la diferencia de polaridad.","El motor se vuelve m\xE1s silencioso.","Nada, son compatibles."],respuesta_correcta:1,explicacion:"El aceite POE es extremadamente sensible. Cambiar el tipo de gas sin verificar la solubilidad del aceite destruye el compresor.",question:"What happens if a system designed for R-134a is recharged with a 400-series blend refrigerant without flushing the POE oil?",options:["It cools better.","Risk of chemical incompatibility and oil return problems due to the difference in polarity.","The motor becomes quieter.","Nothing; they are compatible."],explanation:"POE oil is extremely sensitive. Changing the refrigerant type without verifying oil solubility will destroy the compressor."},{id:"refri_50",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema con capilar, si se hace un vac\xEDo profundo y luego se carga, pero el capilar se tapa a los 10 minutos. \xBFQu\xE9 pas\xF3?",opciones:["Fallo el compresor.","Humedad remanente o suciedad desprendida por el nuevo refrigerante que se acumul\xF3 en la restricci\xF3n.","El gas estaba vencido.","La bomba de vac\xEDo estaba sucia."],respuesta_correcta:1,explicacion:"El capilar es el punto m\xE1s estrecho; cualquier impureza que circule terminar\xE1 alojada ah\xED.",question:"In a capillary tube system, if a deep vacuum is pulled and the system is then charged, but the capillary tube clogs after 10 minutes, what happened?",options:["Compressor failure.","Residual moisture or debris dislodged by the new refrigerant flow that accumulated at the restriction.","The refrigerant was expired.","The vacuum pump was dirty."],explanation:"The capillary tube is the narrowest point in the system; any circulating impurity will eventually lodge there."},{id:"refri_51",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Acumulador de calor' en un refrigerador de absorci\xF3n?",opciones:["Enfriar el agua.","Mantener la soluci\xF3n de amon\xEDaco/agua caliente para facilitar la separaci\xF3n de vapores.","No existe tal componente.","Guardar hielo."],respuesta_correcta:1,explicacion:"Es el coraz\xF3n t\xE9rmico del sistema que permite el movimiento del refrigerante sin bomba el\xE9ctrica.",question:"What is the function of the heat accumulator in an absorption refrigerator?",options:["To cool the water.","To keep the ammonia/water solution hot to facilitate the separation of vapors.","No such component exists.","To store ice."],explanation:"It is the thermal heart of the system that enables refrigerant movement without an electric pump."},{id:"refri_52",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta una temperatura de 55\xB0F en el conservador y -10\xB0F en el congelador. El ventilador funciona. \xBFQu\xE9 sospecha?",opciones:["Falta de gas.","Damper (puerta de aire) trabado en posici\xF3n cerrada o ductos de retorno obstruidos.","Compresor agotado.","Termostato de congelador da\xF1ado."],respuesta_correcta:1,explicacion:"Si el congelador est\xE1 perfecto pero el refrigerador no, el problema es de distribuci\xF3n de aire, no de generaci\xF3n de fr\xEDo.",question:"A domestic refrigerator shows 55 degrees F in the fresh food compartment and -10 degrees F in the freezer. The fan works. What do you suspect?",options:["Low refrigerant charge.","Air damper stuck in the closed position or blocked return air ducts.","Worn-out compressor.","Faulty freezer thermostat."],explanation:"If the freezer is perfect but the fresh food section is not, the problem is air distribution, not refrigeration capacity."},{id:"refri_53",categoria:"REFRI_DOMESTICA",pregunta:"Al realizar una carga de R-134a en un refrigerador, \xBFpor qu\xE9 es importante no sobrecargar el sistema?",opciones:["Para ahorrar gas.","Porque el exceso de l\xEDquido llenar\xE1 el evaporador y terminar\xE1 llegando al compresor, pudiendo causar rotura de v\xE1lvulas.","Porque el motor gira m\xE1s lento.","Porque el condensador se enfr\xEDa demasiado."],respuesta_correcta:1,explicacion:"Los sistemas dom\xE9sticos no tienen acumuladores de succi\xF3n grandes; el margen de error es de apenas unos pocos gramos.",question:"When charging a refrigerator with R-134a, why is it important not to overcharge the system?",options:["To save gas.","Because excess liquid will fill the evaporator and eventually reach the compressor, potentially breaking the valves due to liquid slugging.","Because the motor spins slower.","Because the condenser gets too cold."],explanation:"Domestic systems do not have large suction accumulators; the margin of error is only a few grams."},{id:"refri_54",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Capacitor de Marcha' (Run Capacitor) en un compresor de refrigerador?",opciones:["Ayudar solo en el arranque.","Mejorar el factor de potencia y la eficiencia del motor mientras est\xE1 funcionando, reduciendo el consumo de corriente.","Aumentar las RPM del motor.","Proteger contra rayos."],respuesta_correcta:1,explicacion:"A diferencia del de arranque, este capacitor permanece conectado, permitiendo que el motor trabaje de forma m\xE1s suave y econ\xF3mica.",question:"What is the function of the run capacitor in a domestic refrigerator compressor?",options:["To assist only during startup.","To improve the power factor and motor efficiency while running, reducing current draw.","To increase motor RPM.","To protect against lightning."],explanation:"Unlike a start capacitor, the run capacitor stays connected, allowing the motor to operate more smoothly and efficiently."},{id:"refri_55",categoria:"REFRI_DOMESTICA",pregunta:"Si mides continuidad entre los tres terminales de un compresor (C, R, S) pero no hay continuidad hacia tierra, y aun as\xED no arranca, \xBFqu\xE9 pruebas?",opciones:["Cambiar el compresor.","Verificar el sistema de arranque (Relay/PTC) y el capacitor si lo tiene.","A\xF1adir gas.","Verificar la presi\xF3n de alta."],respuesta_correcta:1,explicacion:"Un motor puede estar el\xE9ctricamente sano pero no arrancar por una falla externa en los componentes de arranque.",question:"If you measure continuity between all three terminals of a compressor (C, R, S) but there is no continuity to ground, and it still does not start, what do you check?",options:["Replace the compressor.","Verify the starting components (relay/PTC) and the capacitor if equipped.","Add refrigerant.","Check the high-side pressure."],explanation:"A motor can be electrically healthy but fail to start due to an external fault in the starting components."},{id:"refri_56",categoria:"REFRI_DOMESTICA",pregunta:"Si el tubo capilar de un refrigerador est\xE1 soldado muy cerca de la salida del compresor, \xBFqu\xE9 pasar\xE1?",opciones:["Enfriar\xE1 m\xE1s r\xE1pido.","El calor de la descarga har\xE1 que el refrigerante entre muy caliente al evaporador, reduciendo dr\xE1sticamente la capacidad de enfriamiento.","El compresor consumir\xE1 menos.","La presi\xF3n de baja subir\xE1."],respuesta_correcta:1,explicacion:"El capilar debe entrar al evaporador con el l\xEDquido lo m\xE1s fr\xEDo posible para aprovechar el efecto refrigerante.",question:"If the capillary tube of a refrigerator is brazed too close to the compressor discharge, what will happen?",options:["It will cool faster.","The discharge heat will cause refrigerant to enter the evaporator too hot, drastically reducing cooling capacity.","The compressor will consume less power.","The suction pressure will rise."],explanation:"The capillary tube should deliver liquid to the evaporator as cold as possible to maximize the refrigeration effect."},{id:"refri_57",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador con R-600a, \xBFpor qu\xE9 no se debe usar una bomba de vac\xEDo est\xE1ndar sin verificar su seguridad?",opciones:["Porque el R-600a da\xF1a el aceite de la bomba.","Debido al riesgo de que los interruptores internos de la bomba generen una chispa si hay una fuga de gas inflamable.","Porque la bomba es muy potente.","Porque el vac\xEDo es diferente."],respuesta_correcta:1,explicacion:"Se requieren herramientas certificadas 'Spark-free' para trabajar con hidrocarburos.",question:"In a refrigerator using R-600a, why should a standard vacuum pump not be used without verifying its safety rating?",options:["Because R-600a damages the pump oil.","Because the pump's internal switches may produce a spark if flammable gas leaks into the pump.","Because the pump is too powerful.","Because the vacuum level is different."],explanation:"Spark-free certified tools are required when working with hydrocarbon refrigerants."},{id:"refri_58",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene la pared trasera caliente y los laterales fr\xEDos. El compresor no para. \xBFDiagn\xF3stico?",opciones:["Falta parcial de refrigerante o compresor con baja eficiencia.","Exceso de carga.","Termostato da\xF1ado en corto.","Bombilla interna encendida siempre."],respuesta_correcta:0,explicacion:"Si no hay suficiente calor en el condensador (pared trasera) pero el compresor trabaja, no hay suficiente bombeo de calor desde el interior.",question:"A domestic refrigerator has a warm back wall and cold side walls. The compressor runs nonstop. What is the diagnosis?",options:["Partial loss of refrigerant charge or a compressor with low efficiency.","Overcharge.","Thermostat stuck closed.","Interior light always on."],explanation:"If there is not enough heat at the condenser (back wall) while the compressor is running, there is not enough heat being pumped from the interior."},{id:"refri_59",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico hace un ruido de 'borboteo' o agua fluyendo despu\xE9s de que el compresor apaga. \xBFEs normal?",opciones:["No, indica fuga de gas.","S\xED, es el sonido del refrigerante igualando presiones a trav\xE9s del tubo capilar.","No, el aceite se est\xE1 saliendo.","Es el drenaje tapado."],respuesta_correcta:1,explicacion:"Al no haber v\xE1lvulas de retenci\xF3n, el gas fluye desde el lado de alta al de baja hasta equilibrarse; es un proceso est\xE1ndar.",question:"A domestic refrigerator makes a bubbling or flowing-water sound after the compressor shuts off. Is this normal?",options:["No, it indicates a refrigerant leak.","Yes, it is the sound of refrigerant equalizing pressures through the capillary tube.","No, oil is leaking out.","It is a clogged drain."],explanation:"Since there are no check valves, refrigerant flows from the high side to the low side until pressures equalize; this is a standard process."},{id:"refri_60",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la causa m\xE1s com\xFAn de que un refrigerador No-Frost se bloquee de hielo?",opciones:["Dejar la puerta abierta.","Falla en el sistema de desescarche (Timer, resistencia o bimetal).","Compresor muy potente.","Bombilla interna fundida."],respuesta_correcta:1,explicacion:"Si el ciclo de deshielo no ocurre, el hielo acumulado bloquea el paso del aire hacia el conservador.",question:"What is the most common cause of a No-Frost refrigerator becoming blocked with ice?",options:["Leaving the door open.","A failure in the defrost system (timer, heater, or bimetal thermostat).","An overpowered compressor.","A burned-out interior light bulb."],explanation:"If the defrost cycle does not occur, accumulated ice blocks the airflow path to the fresh food compartment."},{id:"refri_61",categoria:"REFRI_DOMESTICA",pregunta:"Al cambiar un compresor dom\xE9stico, \xBFpor qu\xE9 se debe usar nitr\xF3geno para soldar?",opciones:["Para enfriar los tubos.","Para desplazar el ox\xEDgeno y evitar la formaci\xF3n de holl\xEDn (cascarilla) dentro de las tuber\xEDas que tapar\xEDa el capilar.","Para detectar fugas mientras sueldas.","Para ahorrar plata."],respuesta_correcta:1,explicacion:"La cascarilla de \xF3xido de cobre es el enemigo n\xFAmero uno de los tubos capilares.",question:"When replacing a domestic compressor, why must nitrogen be used during brazing?",options:["To cool the tubing.","To displace oxygen and prevent the formation of copper oxide scale inside the tubing, which would clog the capillary tube.","To detect leaks while brazing.","To save silver alloy."],explanation:"Copper oxide scale is the number one enemy of capillary tubes."},{id:"refri_62",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una succi\xF3n de 5 PSI y una descarga de 180 PSI (R-134a). El tubo de retorno tiene escarcha hasta el compresor. \xBFQu\xE9 sospecha?",opciones:["Falta de gas.","Exceso de carga de refrigerante; el l\xEDquido no termina de evaporarse y sale del evaporador.","Capilar tapado.","Compresor muy potente."],respuesta_correcta:1,explicacion:"La escarcha en la succi\xF3n fuera del gabinete es el signo inequ\xEDvoco de sobrecarga en sistemas capilares.",question:"A domestic refrigerator using R-134a has a suction pressure of 5 PSI and a discharge pressure of 180 PSI. The suction line has frost all the way to the compressor. What do you suspect?",options:["Low refrigerant charge.","Overcharge of refrigerant; liquid is not fully evaporating and exits the evaporator.","Clogged capillary tube.","Oversized compressor."],explanation:"Frost on the suction line outside the cabinet is the unmistakable sign of overcharge in capillary tube systems."},{id:"refri_63",categoria:"REFRI_DOMESTICA",pregunta:"En un compresor de refrigerador, \xBFqu\xE9 significa el t\xE9rmino 'Eficiencia Volum\xE9trica'?",opciones:["El tama\xF1o del compresor.","La relaci\xF3n entre el volumen real de gas succionado y el volumen desplazado te\xF3ricamente por el pist\xF3n.","La velocidad del motor.","La cantidad de aceite que usa."],respuesta_correcta:1,explicacion:"A mayor presi\xF3n de descarga, menor eficiencia volum\xE9trica, ya que el gas en el espacio muerto se expande y ocupa espacio de nueva succi\xF3n.",question:"In a refrigerator compressor, what does the term 'Volumetric Efficiency' mean?",options:["The physical size of the compressor.","The ratio between the actual volume of gas drawn in and the theoretical volume displaced by the piston.","The motor speed.","The amount of oil it uses."],explanation:"As discharge pressure increases, volumetric efficiency decreases because the gas remaining in the clearance volume re-expands and occupies space that should be filled with new suction gas."},{id:"refri_64",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico usa R-600a. Al medir amperaje, la pinza marca 0.6A. La placa dice 1.2A. \xBFDiagn\xF3stico?",opciones:["Falta de gas (el compresor no tiene carga de trabajo).","Exceso de gas.","Compresor muy eficiente.","Bajo voltaje."],respuesta_correcta:0,explicacion:"Al no haber masa de refrigerante que comprimir, el motor el\xE9ctrico consume mucha menos energ\xEDa.",question:"A domestic refrigerator uses R-600a. The clamp meter reads 0.6A. The nameplate says 1.2A. What is the diagnosis?",options:["Low refrigerant charge (the compressor has no work load).","Overcharge of refrigerant.","Highly efficient compressor.","Low voltage."],explanation:"With no refrigerant mass to compress, the electric motor consumes much less energy."},{id:"refri_65",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador de dos puertas, el separador entre el congelador y el conservador est\xE1 muy caliente. \xBFEs una falla?",opciones:["S\xED, hay un corto circuito.","No, es el paso de la tuber\xEDa de alta presi\xF3n para evitar la condensaci\xF3n de humedad en el marco de la puerta.","S\xED, falta gas.","No, es el calor del foco."],respuesta_correcta:1,explicacion:"Es el dise\xF1o 'anti-sudor' que aprovecha el calor del refrigerante en lugar de una resistencia el\xE9ctrica.",question:"In a two-door refrigerator, the mullion (divider between the freezer and fresh food section) is very hot. Is this a fault?",options:["Yes, there is a short circuit.","No, it is the hot-gas discharge line routed through the mullion to prevent moisture condensation on the door frame.","Yes, it is low on refrigerant.","No, it is heat from the light bulb."],explanation:"This is the anti-sweat design that uses the heat of the refrigerant instead of a separate electric heater."},{id:"refri_66",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una fuga interna en la tuber\xEDa inyectada. \xBFCu\xE1l es la soluci\xF3n m\xE1s t\xE9cnica recomendada?",opciones:["Echar sellador de fugas.","Instalar un evaporador y condensador externos (adaptaci\xF3n) si el valor del equipo lo justifica, o descartar el gabinete.","Pintar la fuga.","Aumentar la presi\xF3n de carga."],respuesta_correcta:1,explicacion:"Las fugas en tuber\xEDa inyectada son inaccesibles; el sellador suele tapar el capilar en sistemas tan peque\xF1os.",question:"A domestic refrigerator has an internal leak in the foam-embedded tubing. What is the most technically recommended solution?",options:["Add leak sealant.","Install an external evaporator and condenser (retrofit) if the unit's value justifies it, or scrap the cabinet.","Paint over the leak.","Increase the charge pressure."],explanation:"Leaks in foam-embedded tubing are inaccessible; leak sealant typically clogs the capillary tube in such small systems."},{id:"refri_67",categoria:"REFRI_DOMESTICA",pregunta:"Al cambiar un termostato dom\xE9stico, \xBFqu\xE9 precauci\xF3n se debe tener con el 'capilar' del sensor?",opciones:["Se debe cortar para que encaje.","No se debe doblar bruscamente ni quebrar, ya que contiene un gas que acciona el interruptor.","Se debe pintar de rojo.","Se debe calentar antes de instalar."],respuesta_correcta:1,explicacion:"Si el capilar se rompe o se pincha, el termostato queda in\xFAtil instant\xE1neamente.",question:"When replacing a domestic thermostat, what precaution must be taken with the sensor capillary tube?",options:["It should be cut to fit.","It must not be sharply bent or kinked, as it contains a gas charge that operates the switch.","It should be painted red.","It should be heated before installing."],explanation:"If the capillary tube is broken or punctured, the thermostat becomes instantly useless."},{id:"refri_68",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta sudoraci\xF3n en el exterior del gabinete. \xBFCausa probable?",opciones:["Falta de gas.","Aislamiento t\xE9rmico degradado o saturado de agua, o humedad ambiental extremadamente alta (>80%).","Luz interna prendida.","Motor muy caliente."],respuesta_correcta:1,explicacion:"Si el fr\xEDo atraviesa la pared del refrigerador debido a un mal aislamiento, el punto de roc\xEDo se alcanza en la pared externa.",question:"A domestic refrigerator shows sweating (condensation) on the exterior of the cabinet. What is the probable cause?",options:["Low refrigerant charge.","Degraded or water-saturated thermal insulation, or extremely high ambient humidity (above 80%).","Interior light left on.","Motor too hot."],explanation:"If the cold penetrates through the refrigerator wall due to poor insulation, the dew point is reached on the external surface."},{id:"refri_69",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 un refrigerador de absorci\xF3n debe estar perfectamente nivelado?",opciones:["Por est\xE9tica.","Porque el movimiento del refrigerante (amon\xEDaco/hidr\xF3geno/agua) depende de la gravedad y la convecci\xF3n t\xE9rmica sin bombas.","Para que el hielo no se caiga.","Para que la puerta cierre sola."],respuesta_correcta:1,explicacion:"Un desnivel de pocos grados detiene el ciclo qu\xEDmico y el equipo deja de enfriar.",question:"Why must an absorption refrigerator be perfectly level?",options:["For aesthetics.","Because the movement of the refrigerant (ammonia/hydrogen/water) depends on gravity and thermal convection without any pumps.","So the ice does not fall out.","So the door closes by itself."],explanation:"A tilt of just a few degrees can stop the chemical cycle and the unit stops cooling."},{id:"refri_70",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene el condensador interno (en las paredes laterales). Si un lado est\xE1 caliente y el otro fr\xEDo, \xBFqu\xE9 indica?",opciones:["Funcionamiento normal.","Obstrucci\xF3n parcial o falta de refrigerante, ya que el calor deber\xEDa distribuirse uniformemente por todo el recorrido del condensador.","El ventilador est\xE1 soplando mal.","Termostato roto."],respuesta_correcta:1,explicacion:"Es una se\xF1al temprana de que el sistema no est\xE1 moviendo la masa de refrigerante necesaria.",question:"A domestic refrigerator has a wall-embedded condenser (in the side panels). If one side is hot and the other is cold, what does it indicate?",options:["Normal operation.","Partial obstruction or low refrigerant charge, since heat should be distributed evenly along the entire condenser path.","The fan is blowing incorrectly.","Broken thermostat."],explanation:"This is an early warning sign that the system is not circulating the required mass of refrigerant."},{id:"refri_71",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador con R-600a, \xBFpor qu\xE9 no se deben usar v\xE1lvulas de pinchar (piercing valves) permanentemente?",opciones:["Porque son feas.","Porque tienden a fugar con el tiempo; en sistemas con tan poco gas, una microfuga es fatal.","Porque tapan el capilar.","Porque el gas las corroe."],respuesta_correcta:1,explicacion:"Solo deben usarse para diagn\xF3stico y luego soldar una v\xE1lvula de servicio o sellar el tubo.",question:"In a refrigerator using R-600a, why should piercing valves not be left installed permanently?",options:["Because they are unsightly.","Because they tend to leak over time; in systems with such a small charge, even a micro-leak is fatal.","Because they clog the capillary tube.","Because the gas corrodes them."],explanation:"They should only be used for diagnostics and then replaced by brazing on a proper service valve or sealing the tube."},{id:"refri_72",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta una presi\xF3n de succi\xF3n de 20 PSI y una descarga de 150 PSI (R-134a). \xBFEst\xE1 operando correctamente para un conservador?",opciones:["S\xED, son presiones est\xE1ndar.","No, la presi\xF3n de succi\xF3n es demasiado alta (saturaci\xF3n a 22\xB0F); deber\xEDa estar cerca de los 2-10 PSI.","No, la presi\xF3n de descarga es muy baja.","Falta gas."],respuesta_correcta:1,explicacion:"Para refrigeraci\xF3n dom\xE9stica, el evaporador debe estar a unos 10-20\xB0F (aprox. 5-12 PSI). 20 PSI es una temperatura de evaporaci\xF3n demasiado alta para enfriar bien.",question:"A domestic refrigerator using R-134a has a suction pressure of 20 PSI and a discharge of 150 PSI. Is it operating correctly for a fresh food compartment?",options:["Yes, those are standard pressures.","No, the suction pressure is too high (saturates at 22 degrees F); it should be near 2-10 PSI.","No, the discharge pressure is too low.","Low on refrigerant."],explanation:"For domestic refrigeration, the evaporator should be at about 10-20 degrees F (approximately 5-12 PSI). 20 PSI gives a saturation temperature that is too high to cool effectively."},{id:"refri_73",categoria:"REFRI_DOMESTICA",pregunta:"Si un refrigerador dom\xE9stico tiene el condensador pegado a la pared trasera y se llena de pelusa, \xBFqu\xE9 s\xEDntoma presentar\xE1?",opciones:["Baja presi\xF3n de succi\xF3n.","Ciclos de trabajo m\xE1s largos y menor eficiencia de enfriamiento.","Se congela el evaporador.","El motor se enfr\xEDa m\xE1s."],respuesta_correcta:1,explicacion:"El calor no puede salir; la presi\xF3n de alta sube, el compresor rinde menos y debe trabajar m\xE1s tiempo para lograr la temperatura.",question:"If the condenser on the back wall of a domestic refrigerator is clogged with lint, what symptom will it show?",options:["Low suction pressure.","Longer run cycles and reduced cooling efficiency.","The evaporator freezes up.","The motor runs cooler."],explanation:"Heat cannot leave the system; the high-side pressure rises, the compressor becomes less efficient, and it must run longer to reach the set temperature."},{id:"refri_74",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 no se debe usar un soplete de propano para soldar tuber\xEDas de refrigeraci\xF3n con varilla de plata al 15%?",opciones:["Porque es muy caro.","Porque el propano no alcanza la temperatura necesaria de manera eficiente; se requiere oxi-acetileno o MAP-Pro para una soldadura fuerte (brazing) de calidad.","Porque el propano ensucia el cobre.","Porque el propano es ilegal."],respuesta_correcta:1,explicacion:"La soldadura fuerte requiere calentar el tubo a un rojo cereza que el aire-propano rara vez logra de forma puntual y r\xE1pida.",question:"Why should a propane torch not be used to braze refrigeration tubing with 15% silver brazing alloy?",options:["Because it is too expensive.","Because propane does not reach the required temperature efficiently; oxy-acetylene or MAP-Pro is needed for quality brazing.","Because propane dirties the copper.","Because propane is illegal."],explanation:"Brazing requires heating the tube to a cherry-red color, which an air-propane torch rarely achieves quickly and precisely."},{id:"refri_75",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador No-Frost, el compresor funciona pero el ventilador del evaporador no. \xBFCu\xE1l ser\xE1 la lectura de amperaje del compresor despu\xE9s de 1 hora?",opciones:["M\xE1s alta de lo normal.","M\xE1s baja de lo normal debido a la ca\xEDda en la presi\xF3n de succi\xF3n por falta de carga t\xE9rmica.","Igual a la de placa.","Cero."],respuesta_correcta:1,explicacion:"Al no haber aire, el refrigerante no absorbe calor. La presi\xF3n de succi\xF3n baja, el gas es menos denso y el compresor hace menos trabajo f\xEDsico.",question:"In a No-Frost refrigerator, the compressor runs but the evaporator fan does not. What will the compressor amperage reading be after 1 hour?",options:["Higher than normal.","Lower than normal due to the drop in suction pressure from lack of heat load.","Same as the nameplate rating.","Zero."],explanation:"Without air, the refrigerant does not absorb heat. The suction pressure drops, the gas becomes less dense, and the compressor does less physical work."},{id:"refri_76",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una succi\xF3n de 30 PSI (R-134a) y el compresor est\xE1 muy caliente. \xBFQu\xE9 sospecha?",opciones:["Falta de gas.","V\xE1lvulas de succi\xF3n del compresor da\xF1adas (no bombea, solo recircula gas internamente).","Filtro tapado.","Ventilador del condensador muy r\xE1pido."],respuesta_correcta:1,explicacion:"Si el compresor no puede bajar la presi\xF3n de succi\xF3n y se calienta, es porque mec\xE1nicamente ha perdido su capacidad de compresi\xF3n.",question:"A domestic refrigerator has a suction pressure of 30 PSI (R-134a) and the compressor is very hot. What do you suspect?",options:["Low refrigerant charge.","Damaged compressor suction valves (not pumping, only recirculating gas internally).","Clogged filter.","Condenser fan running too fast."],explanation:"If the compressor cannot pull down the suction pressure and it overheats, it has mechanically lost its compression capacity."},{id:"refri_77",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema con R-600a, \xBFcu\xE1l es el peligro de una fuga en el lado de baja presi\xF3n (succi\xF3n)?",opciones:["Ninguno, el gas no es t\xF3xico.","Que el sistema succione aire hacia adentro, creando una mezcla explosiva dentro del compresor.","Que el aceite se vuelva s\xF3lido.","Que el evaporador explote."],respuesta_correcta:1,explicacion:"Al trabajar en vac\xEDo, cualquier fuga permite la entrada de ox\xEDgeno, el cual se mezcla con el hidrocarburo inflamable bajo compresi\xF3n.",question:"In a system using R-600a, what is the danger of a leak on the low-pressure (suction) side?",options:["None; the gas is not toxic.","The system may draw air inward, creating an explosive mixture inside the compressor.","The oil will solidify.","The evaporator will explode."],explanation:"When operating in a vacuum, any leak allows oxygen to enter, which mixes with the flammable hydrocarbon under compression."},{id:"refri_78",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene el condensador interno (en las paredes laterales). Si un lado est\xE1 caliente y el otro fr\xEDo, \xBFqu\xE9 indica?",opciones:["Funcionamiento normal.","Obstrucci\xF3n parcial o falta de refrigerante, ya que el calor deber\xEDa distribuirse uniformemente por todo el recorrido del condensador.","El ventilador est\xE1 soplando mal.","Termostato roto."],respuesta_correcta:1,explicacion:"Es una se\xF1al temprana de que el sistema no est\xE1 moviendo la masa de refrigerante necesaria.",question:"A domestic refrigerator has a wall-embedded condenser (in the side panels). If one side is hot and the other is cold, what does this indicate?",options:["Normal operation.","Partial obstruction or low refrigerant charge, since heat should be distributed evenly along the entire condenser path.","The fan is blowing incorrectly.","Broken thermostat."],explanation:"This is an early warning sign that the system is not circulating the required mass of refrigerant."},{id:"refri_79",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador con R-600a, \xBFpor qu\xE9 no se deben usar v\xE1lvulas de pinchar (piercing valves) permanentemente?",opciones:["Porque son feas.","Porque tienden a fugar con el tiempo; en sistemas con tan poco gas, una microfuga es fatal.","Porque tapan el capilar.","Porque el gas las corroe."],respuesta_correcta:1,explicacion:"Solo deben usarse para diagn\xF3stico y luego soldar una v\xE1lvula de servicio o sellar el tubo.",question:"In a refrigerator using R-600a, why should piercing valves not be left installed permanently?",options:["Because they are unsightly.","Because they tend to leak over time; in systems with such a small charge, even a micro-leak is fatal.","Because they clog the capillary tube.","Because the gas corrodes them."],explanation:"They should only be used for diagnostics and then replaced by brazing on a proper service valve or sealing the tube."},{id:"refri_80",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador de absorci\xF3n, el calor se utiliza para separar el refrigerante de qu\xE9 sustancia?",opciones:["Del aceite.","Del absorbente (com\xFAnmente agua en sistemas de amon\xEDaco).","Del nitr\xF3geno.","Del aire ambiental."],respuesta_correcta:1,explicacion:"El generador usa calor para 'hervir' el amon\xEDaco y separarlo del agua, permitiendo que el ciclo contin\xFAe.",question:"In an absorption refrigerator, heat is used to separate the refrigerant from what substance?",options:["From the oil.","From the absorbent (commonly water in ammonia systems).","From the nitrogen.","From the ambient air."],explanation:"The generator uses heat to boil the ammonia and separate it from the water, allowing the cycle to continue."},{id:"refri_81",categoria:"REFRI_DOMESTICA",pregunta:"Si el drenaje del refrigerador se tapa, \xBFd\xF3nde aparecer\xE1 el agua usualmente?",opciones:["Dentro del motor.","En el piso del compartimento de alimentos frescos (abajo de los cajones de verduras).","En el condensador.","En la l\xEDnea de succi\xF3n."],respuesta_correcta:1,explicacion:"El agua del deshielo no tiene por d\xF3nde salir y se desborda desde el canal del evaporador hacia el interior del gabinete.",question:"If the drain line of a refrigerator gets clogged, where will the water typically appear?",options:["Inside the motor.","On the floor of the fresh food compartment (under the vegetable crisper drawers).","In the condenser.","On the suction line."],explanation:"The defrost water has nowhere to go and overflows from the evaporator drain channel into the cabinet interior."},{id:"refri_82",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una succi\xF3n de 0 PSI y el filtro deshidratador est\xE1 cubierto de escarcha. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Falta de gas.","Filtro deshidratador obstruido parcial o totalmente.","Compresor agotado.","Exceso de carga."],respuesta_correcta:1,explicacion:"Si el filtro tiene escarcha, est\xE1 actuando como un dispositivo de expansi\xF3n debido a una restricci\xF3n interna (ca\xEDda de presi\xF3n brusca).",question:"A domestic refrigerator has a suction pressure of 0 PSI and the filter drier is covered in frost. What is the diagnosis?",options:["Low refrigerant charge.","Partially or totally obstructed filter drier.","Worn-out compressor.","Overcharge."],explanation:"If the filter drier has frost on it, it is acting as an expansion device due to an internal restriction (sudden pressure drop)."},{id:"refri_83",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 los refrigeradores con R-600a no suelen usar ventilador en el condensador?",opciones:["Porque el gas no se calienta.","Porque las cargas son tan peque\xF1as y las presiones tan bajas que la convecci\xF3n natural es suficiente y se ahorra energ\xEDa.","Porque el ventilador causar\xEDa explosiones.","Porque el condensador es de pl\xE1stico."],respuesta_correcta:1,explicacion:"La eficiencia del isobutano permite dise\xF1os m\xE1s simples y silenciosos en baja capacidad.",question:"Why do refrigerators using R-600a typically not have a condenser fan?",options:["Because the gas does not heat up.","Because the charges are so small and the pressures so low that natural convection is sufficient, saving energy.","Because a fan would cause explosions.","Because the condenser is made of plastic."],explanation:"The efficiency of isobutane allows for simpler and quieter designs at low capacity."},{id:"refri_84",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta una succi\xF3n de 30 PSI (R-134a) pero el evaporador no enfr\xEDa nada y el compresor hace poco ruido. \xBFQu\xE9 sucede?",opciones:["Falta de gas.","Compresor con v\xE1lvulas rotas (no hay diferencia de presi\xF3n real).","Filtro tapado.","Exceso de gas."],respuesta_correcta:1,explicacion:"Sin compresi\xF3n mec\xE1nica, la presi\xF3n de baja sube hasta igualarse casi con la de alta (presi\xF3n de equilibrio).",question:"A domestic refrigerator has a suction pressure of 30 PSI (R-134a) but the evaporator is not cooling at all and the compressor makes little noise. What is happening?",options:["Low refrigerant charge.","Compressor with broken valves (no real pressure differential exists).","Clogged filter.","Overcharge."],explanation:"Without mechanical compression, the low-side pressure rises until it nearly equals the high side (equalized pressure)."},{id:"refri_85",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador No-Frost, \xBFqu\xE9 componente activa la resistencia de deshielo?",opciones:["El termostato de ambiente.","El Timer o reloj de deshielo (o la tarjeta electr\xF3nica).","El compresor.","El sensor de la puerta."],respuesta_correcta:1,explicacion:"Es el cerebro que decide cu\xE1ndo detener el fr\xEDo para eliminar la escarcha del evaporador.",question:"In a No-Frost refrigerator, which component activates the defrost heater?",options:["The room thermostat.","The defrost timer or the electronic control board.","The compressor.","The door sensor."],explanation:"It is the controller that decides when to stop cooling in order to remove frost from the evaporator."},{id:"refri_86",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene el condensador empotrado en los laterales. Si un lateral est\xE1 caliente y el otro fr\xEDo, \xBFqu\xE9 indica?",opciones:["Falla del ventilador interno.","Obstrucci\xF3n parcial o falta de gas (el refrigerante no completa el recorrido del condensador).","El equipo es de alta eficiencia.","Termostato roto."],respuesta_correcta:1,explicacion:"El calor debe distribuirse por todo el condensador; una diferencia marcada indica un flujo de masa pobre.",question:"A domestic refrigerator has a wall-embedded condenser in the side panels. If one side is hot and the other is cold, what does this indicate?",options:["Internal fan failure.","Partial obstruction or low charge (the refrigerant is not completing the full condenser circuit).","The unit is high-efficiency.","Broken thermostat."],explanation:"Heat should be distributed throughout the entire condenser; a noticeable difference indicates poor refrigerant mass flow."},{id:"refri_87",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la carga de refrigerante t\xEDpica de un refrigerador dom\xE9stico con R-600a?",opciones:["1 a 2 kilogramos.","40 a 70 gramos.","500 a 800 gramos.","2 a 3 libras."],respuesta_correcta:1,explicacion:"El isobutano es tan eficiente que requiere cargas m\xEDnimas, lo cual tambi\xE9n es una medida de seguridad.",question:"What is the typical refrigerant charge for a domestic refrigerator using R-600a?",options:["1 to 2 kilograms.","40 to 70 grams.","500 to 800 grams.","2 to 3 pounds."],explanation:"Isobutane is so efficient that it requires minimal charges, which is also a safety measure."},{id:"refri_88",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador No-Frost tiene el bimetal de deshielo quemado (siempre abierto). \xBFQu\xE9 s\xEDntoma tendr\xE1?",opciones:["El compresor no arranca.","El evaporador se bloquea de hielo y deja de enfriar el conservador tras unos d\xEDas.","La resistencia se queda prendida siempre.","El ventilador gira muy r\xE1pido."],respuesta_correcta:1,explicacion:"Sin el bimetal cerrado, la resistencia nunca recibe energ\xEDa, por lo que el hielo nunca se derrite.",question:"A No-Frost refrigerator has a burned-out (always open) defrost bimetal thermostat. What symptom will it have?",options:["The compressor will not start.","The evaporator will become blocked with ice and stop cooling the fresh food section after a few days.","The heater will stay on all the time.","The fan will spin very fast."],explanation:"With the bimetal permanently open, the heater never receives power, so the ice never melts."},{id:"refri_89",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 se utiliza un 'Tubo Capilar' en lugar de una TXV en refrigeradores dom\xE9sticos?",opciones:["Porque es m\xE1s eficiente.","Por su bajo costo, simplicidad y porque permite la igualaci\xF3n de presiones durante el apagado, facilitando el arranque del motor.","Porque aguanta m\xE1s presi\xF3n.","Porque no se tapa nunca."],respuesta_correcta:1,explicacion:"El capilar es un control pasivo ideal para sistemas de carga cr\xEDtica y motores de bajo torque de arranque.",question:"Why is a capillary tube used instead of a TXV in domestic refrigerators?",options:["Because it is more efficient.","Due to its low cost, simplicity, and because it allows pressure equalization during the off cycle, making motor startup easier.","Because it handles more pressure.","Because it never clogs."],explanation:"The capillary tube is an ideal passive control for critical-charge systems and low-starting-torque motors."},{id:"refri_90",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una succi\xF3n de 5 PSI (R-134a) pero el condensador est\xE1 fr\xEDo. \xBFDiagn\xF3stico?",opciones:["Exceso de gas.","Falta de refrigerante o compresor que no bombea (aunque la presi\xF3n parezca normal, no hay masa circulando).","Termostato roto.","Filtro deshidratador nuevo."],respuesta_correcta:1,explicacion:"Si no hay calor en el condensador, no hay energ\xEDa siendo extra\xEDda del interior.",question:"A domestic refrigerator has a suction pressure of 5 PSI (R-134a) but the condenser is cold. What is the diagnosis?",options:["Overcharge.","Low refrigerant charge or a compressor that is not pumping (even though the pressure appears normal, no mass is circulating).","Broken thermostat.","New filter drier."],explanation:"If there is no heat at the condenser, no energy is being extracted from the interior."},{id:"refri_91",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Acumulador de calor' en un refrigerador de absorci\xF3n?",opciones:["Enfriar el agua.","Mantener la soluci\xF3n caliente para facilitar la separaci\xF3n del amon\xEDaco.","No existe tal componente.","Guardar hielo."],respuesta_correcta:1,explicacion:"Mantiene la estabilidad t\xE9rmica del ciclo qu\xEDmico.",question:"What is the function of the heat accumulator in an absorption refrigerator?",options:["To cool the water.","To keep the solution hot to facilitate the separation of ammonia.","No such component exists.","To store ice."],explanation:"It maintains the thermal stability of the chemical cycle."},{id:"refri_92",categoria:"REFRI_DOMESTICA",pregunta:"Mides un compresor dom\xE9stico con el mult\xEDmetro. Entre C-R da 4 ohms, entre C-S da 12 ohms y entre R-S da 16 ohms. No hay continuidad a tierra. \xBFEstado del motor?",opciones:["Quemado.","El\xE9ctricamente sano (la suma de los devanados coincide y el aislamiento es correcto).","En cortocircuito interno.","Aterrizado."],respuesta_correcta:1,explicacion:"C-R (Com\xFAn-Run) + C-S (Com\xFAn-Start) = R-S (Run-Start). 4 + 12 = 16. Es un motor en buen estado.",question:"You measure a domestic compressor with a multimeter. Between C-R you get 4 ohms, between C-S you get 12 ohms, and between R-S you get 16 ohms. There is no continuity to ground. What is the motor's condition?",options:["Burned out.","Electrically healthy (the winding resistances add up correctly and the insulation is intact).","Internal short circuit.","Grounded."],explanation:"C-R (Common-Run) + C-S (Common-Start) = R-S (Run-Start). 4 + 12 = 16. This motor is in good condition."},{id:"refri_93",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Damper Electr\xF3nico' en un refrigerador Side-by-Side?",opciones:["Regular el voltaje del motor.","Controlar mec\xE1nicamente el paso de aire fr\xEDo desde el evaporador hacia el compartimento de alimentos frescos.","Encender la f\xE1brica de hielos.","Aumentar la presi\xF3n de succi\xF3n."],respuesta_correcta:1,explicacion:"Es la compuerta que abre o cierra seg\xFAn lo que pida el sensor de temperatura del refrigerador.",question:"What is the function of the electronic damper in a side-by-side refrigerator?",options:["To regulate motor voltage.","To mechanically control the flow of cold air from the evaporator to the fresh food compartment.","To turn on the ice maker.","To increase suction pressure."],explanation:"It is the gate that opens or closes based on the temperature sensor reading in the fresh food section."},{id:"refri_94",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 los compresores Inverter dom\xE9sticos usan aceite POE incluso con refrigerante R-600a en algunos casos?",opciones:["Porque es m\xE1s barato.","Por su excelente estabilidad t\xE9rmica y propiedades de lubricaci\xF3n a velocidades variables de rotaci\xF3n.","Porque el R-600a oxida el aceite mineral.","Para que el motor haga menos ruido."],respuesta_correcta:1,explicacion:"El control de velocidad del Inverter requiere un lubricante que mantenga la viscosidad perfecta tanto a 1500 como a 4500 RPM.",question:"Why do some domestic inverter compressors use POE oil even with R-600a refrigerant?",options:["Because it is cheaper.","Due to its excellent thermal stability and lubrication properties at variable rotation speeds.","Because R-600a oxidizes mineral oil.","To make the motor quieter."],explanation:"Inverter speed control requires a lubricant that maintains perfect viscosity across a wide RPM range, from 1,500 to 4,500 RPM."},{id:"refri_95",categoria:"REFRI_DOMESTICA",pregunta:"En un sistema con R-600a, \xBFcu\xE1l es el procedimiento correcto para cambiar el filtro deshidratador?",opciones:["Desoldar con soplete directamente.","Cortar con cortatubos para evitar la ignici\xF3n de residuos de gas y usar uniones mec\xE1nicas o soldar tras limpieza con nitr\xF3geno.","Lijar y pegar con ep\xF3xico.","No es necesario cambiarlo."],respuesta_correcta:1,explicacion:"La seguridad contra explosi\xF3n es la regla #1 con hidrocarburos.",question:"In a system using R-600a, what is the correct procedure for replacing the filter drier?",options:["Debraze directly with a torch.","Cut with a tube cutter to avoid igniting residual gas, then use mechanical fittings or braze after flushing with nitrogen.","Sand and glue with epoxy.","It does not need to be replaced."],explanation:"Explosion safety is the number one rule when working with hydrocarbon refrigerants."},{id:"refri_96",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta hielo solo en la entrada del evaporador (primeras vueltas). El resto est\xE1 seco. \xBFCausa?",opciones:["Filtro tapado.","Falta parcial de refrigerante; el l\xEDquido se evapora totalmente antes de recorrer todo el serpent\xEDn.","Compresor muy potente.","Exceso de gas."],respuesta_correcta:1,explicacion:"Es el s\xEDntoma cl\xE1sico de una fuga lenta de gas.",question:"A domestic refrigerator has frost only at the inlet of the evaporator (first few passes). The rest is dry. What is the cause?",options:["Clogged filter.","Partial loss of refrigerant charge; the liquid evaporates completely before traveling through the entire coil.","Oversized compressor.","Overcharge."],explanation:"This is the classic symptom of a slow refrigerant leak."},{id:"refri_97",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 gas se usa para presurizar y buscar fugas en refrigeraci\xF3n dom\xE9stica por su seguridad y sequedad?",opciones:["Ox\xEDgeno.","Nitr\xF3geno seco (OFN).","Aire de llantas.","Gas propano."],respuesta_correcta:1,explicacion:"El nitr\xF3geno es inerte, no explota con el aceite y no introduce humedad al sistema.",question:"What gas is used to pressurize and leak-test domestic refrigeration systems due to its safety and dryness?",options:["Oxygen.","Dry nitrogen (OFN - Oxygen Free Nitrogen).","Tire air.","Propane gas."],explanation:"Nitrogen is inert, does not react with oil, and does not introduce moisture into the system."},{id:"refri_98",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico usa R-600a. Al medir amperaje, la pinza marca 0.6A. La placa dice 1.2A. \xBFDiagn\xF3stico?",opciones:["Falta de gas (el compresor no tiene carga de trabajo).","Exceso de gas.","Compresor muy eficiente.","Bajo voltaje."],respuesta_correcta:0,explicacion:"Al no haber masa de refrigerante que comprimir, el motor el\xE9ctrico consume mucha menos energ\xEDa.",question:"A domestic refrigerator uses R-600a. The clamp meter reads 0.6A. The nameplate says 1.2A. What is the diagnosis?",options:["Low refrigerant charge (the compressor has no work load).","Overcharge of refrigerant.","Highly efficient compressor.","Low voltage."],explanation:"With no refrigerant mass to compress, the electric motor consumes much less energy."},{id:"refri_99",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador de dos puertas, el separador entre el congelador y el conservador est\xE1 muy caliente. \xBFEs una falla?",opciones:["S\xED, hay un corto circuito.","No, es el paso de la tuber\xEDa de alta presi\xF3n para evitar la condensaci\xF3n de humedad en el marco de la puerta.","S\xED, falta gas.","No, es el calor del foco."],respuesta_correcta:1,explicacion:"Es el dise\xF1o 'anti-sudor' que aprovecha el calor del refrigerante en lugar de una resistencia el\xE9ctrica.",question:"In a two-door refrigerator, the mullion (divider between the freezer and fresh food section) is very hot. Is this a fault?",options:["Yes, there is a short circuit.","No, it is the hot-gas discharge line routed through the mullion to prevent moisture condensation on the door frame.","Yes, it is low on refrigerant.","No, it is heat from the light bulb."],explanation:"This is the anti-sweat design that uses the heat of the refrigerant instead of a separate electric heater."},{id:"refri_100",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una fuga interna en la tuber\xEDa inyectada. \xBFCu\xE1l es la soluci\xF3n m\xE1s t\xE9cnica recomendada?",opciones:["Echar sellador de fugas.","Instalar un evaporador y condensador externos (adaptaci\xF3n) si el valor del equipo lo justifica, o descartar el gabinete.","Pintar la fuga.","Aumentar la presi\xF3n de carga."],respuesta_correcta:1,explicacion:"Las fugas en tuber\xEDa inyectada son inaccesibles; el sellador suele tapar el capilar en sistemas tan peque\xF1os.",question:"A domestic refrigerator has an internal leak in the foam-embedded tubing. What is the most technically recommended solution?",options:["Add leak sealant.","Install an external evaporator and condenser (retrofit) if the unit's value justifies it, or scrap the cabinet.","Paint over the leak.","Increase the charge pressure."],explanation:"Leaks in foam-embedded tubing are inaccessible; leak sealant typically clogs the capillary tube in such small systems."},{id:"refri_101",categoria:"REFRI_DOMESTICA",pregunta:"Al cambiar un termostato dom\xE9stico, \xBFqu\xE9 precauci\xF3n se debe tener con el 'capilar' del sensor?",opciones:["Se debe cortar para que encaje.","No se debe doblar bruscamente ni quebrar, ya que contiene un gas que acciona el interruptor.","Se debe pintar de rojo.","Se debe calentar antes de instalar."],respuesta_correcta:1,explicacion:"Si el capilar se rompe o se pincha, el termostato queda in\xFAtil instant\xE1neamente.",question:"When replacing a domestic thermostat, what precaution must be taken with the sensor capillary tube?",options:["It should be cut to fit.","It must not be sharply bent or kinked, as it contains a gas charge that operates the switch.","It should be painted red.","It should be heated before installing."],explanation:"If the capillary tube is broken or punctured, the thermostat becomes instantly useless."},{id:"refri_102",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador Inverter tiene el compresor funcionando a 4500 RPM constantes pero no baja la temperatura. Al revisar, la succi\xF3n est\xE1 en 30 PSI (R-600a). \xBFDiagn\xF3stico?",opciones:["Falta de gas.","Compresor con eficiencia mec\xE1nica perdida (desgaste de biela o v\xE1lvulas).","Filtro tapado.","Tarjeta electr\xF3nica da\xF1ada."],respuesta_correcta:1,explicacion:"A m\xE1xima velocidad, la presi\xF3n de succi\xF3n de R-600a deber\xEDa ser cercana a 0 o negativa. 30 PSI indica que el compresor no est\xE1 comprimiendo.",question:"An inverter refrigerator has the compressor running at 4,500 RPM constantly but the temperature will not come down. Upon inspection, suction pressure is 30 PSI (R-600a). What is the diagnosis?",options:["Low refrigerant charge.","Loss of mechanical efficiency in the compressor (worn connecting rod or valves).","Clogged filter.","Damaged electronic control board."],explanation:"At maximum speed, R-600a suction pressure should be near 0 or in a vacuum. 30 PSI indicates the compressor is not compressing."},{id:"refri_103",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n de la 'Resistencia de Deshielo' en un sistema No-Frost?",opciones:["Calentar la comida.","Derretir la escarcha acumulada en las aletas del evaporador durante el ciclo de refrigeraci\xF3n.","Calentar el aceite del compresor.","Evitar que la puerta se pegue."],respuesta_correcta:1,explicacion:"Convierte energ\xEDa el\xE9ctrica en calor para limpiar el serpent\xEDn y permitir que el aire vuelva a circular.",question:"What is the function of the defrost heater in a No-Frost system?",options:["To heat the food.","To melt the frost accumulated on the evaporator fins during the refrigeration cycle.","To heat the compressor oil.","To prevent the door from sticking."],explanation:"It converts electrical energy into heat to clear the coil and allow air to circulate again."},{id:"refri_104",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene el compresor 'zumbando' y el ventilador del condensador no gira. Al girar el ventilador con la mano, este arranca. \xBFQu\xE9 falla?",opciones:["El motor del ventilador est\xE1 quemado.","Capacitor del ventilador defectuoso o bujes resecos con falta de lubricaci\xF3n.","Termostato da\xF1ado.","Falta de gas."],respuesta_correcta:1,explicacion:"Si necesita ayuda para arrancar pero luego gira, el torque de arranque es insuficiente por falla el\xE9ctrica o fricci\xF3n mec\xE1nica inicial.",question:"A domestic refrigerator has the compressor humming and the condenser fan is not spinning. When the fan blade is turned by hand, it starts running. What is the fault?",options:["The fan motor is burned out.","A defective fan capacitor or dry bushings causing lack of lubrication.","Faulty thermostat.","Low refrigerant charge."],explanation:"If the motor needs a manual push to start but then runs, the starting torque is insufficient due to an electrical fault or initial mechanical friction."},{id:"refri_105",categoria:"REFRI_DOMESTICA",pregunta:"Al cambiar un evaporador de aluminio en un refrigerador, \xBFqu\xE9 t\xE9cnica se prefiere para unirlo al cobre de succi\xF3n?",opciones:["Soldadura de plata 45%.","Uniones mec\xE1nicas tipo Lokring o soldadura especial aluminio-cobre con fundente espec\xEDfico.","Pegamento ep\xF3xico.","Cinta aislante."],respuesta_correcta:1,explicacion:"La uni\xF3n aluminio-cobre es galv\xE1nicamente activa y dif\xEDcil de soldar; las uniones mec\xE1nicas son el est\xE1ndar de f\xE1brica por confiabilidad.",question:"When replacing an aluminum evaporator in a refrigerator, what technique is preferred for joining it to the copper suction line?",options:["45% silver brazing alloy.","Mechanical fittings such as Lokring or special aluminum-to-copper brazing with a specific flux.","Epoxy adhesive.","Electrical tape."],explanation:"The aluminum-to-copper joint is galvanically active and difficult to braze; mechanical fittings are the factory standard for reliability."},{id:"refri_106",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico usa R-600a. Al medir amperaje, la pinza marca 0.6A. La placa dice 1.2A. \xBFDiagn\xF3stico?",opciones:["Falta de gas (el compresor no tiene carga de trabajo).","Exceso de gas.","Compresor muy eficiente.","Bajo voltaje."],respuesta_correcta:0,explicacion:"Al no haber masa de refrigerante que comprimir, el motor el\xE9ctrico consume mucha menos energ\xEDa.",question:"A domestic refrigerator uses R-600a. The clamp meter reads 0.6A. The nameplate says 1.2A. What is the diagnosis?",options:["Low refrigerant charge (the compressor has no work load).","Overcharge of refrigerant.","Highly efficient compressor.","Low voltage."],explanation:"With no refrigerant mass to compress, the electric motor consumes much less energy."},{id:"refri_107",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador de dos puertas, el separador entre el congelador y el conservador est\xE1 muy caliente. \xBFEs una falla?",opciones:["S\xED, hay un corto circuito.","No, es el paso de la tuber\xEDa de alta presi\xF3n para evitar la condensaci\xF3n de humedad en el marco de la puerta.","S\xED, falta gas.","No, es el calor del foco."],respuesta_correcta:1,explicacion:"Es el dise\xF1o 'anti-sudor' que aprovecha el calor del refrigerante en lugar de una resistencia el\xE9ctrica.",question:"In a two-door refrigerator, the mullion (divider between the freezer and fresh food section) is very hot. Is this a fault?",options:["Yes, there is a short circuit.","No, it is the hot-gas discharge line routed through the mullion to prevent moisture condensation on the door frame.","Yes, it is low on refrigerant.","No, it is heat from the light bulb."],explanation:"This is the anti-sweat design that uses the heat of the refrigerant instead of a separate electric heater."},{id:"refri_108",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una fuga interna en la tuber\xEDa inyectada. \xBFCu\xE1l es la soluci\xF3n m\xE1s t\xE9cnica recomendada?",opciones:["Echar sellador de fugas.","Instalar un evaporador y condensador externos (adaptaci\xF3n) si el valor del equipo lo justifica, o descartar el gabinete.","Pintar la fuga.","Aumentar la presi\xF3n de carga."],respuesta_correcta:1,explicacion:"Las fugas en tuber\xEDa inyectada son inaccesibles; el sellador suele tapar el capilar en sistemas tan peque\xF1os.",question:"A domestic refrigerator has an internal leak in the foam-embedded tubing. What is the most technically recommended solution?",options:["Add leak sealant.","Install an external evaporator and condenser (retrofit) if the unit's value justifies it, or scrap the cabinet.","Paint over the leak.","Increase the charge pressure."],explanation:"Leaks in foam-embedded tubing are inaccessible; leak sealant typically clogs the capillary tube in such small systems."},{id:"refri_109",categoria:"REFRI_DOMESTICA",pregunta:"Al cambiar un termostato dom\xE9stico, \xBFqu\xE9 precauci\xF3n se debe tener con el 'capilar' del sensor?",opciones:["Se debe cortar para que encaje.","No se debe doblar bruscamente ni quebrar, ya que contiene un gas que acciona el interruptor.","Se debe pintar de rojo.","Se debe calentar antes de instalar."],respuesta_correcta:1,explicacion:"Si el capilar se rompe o se pincha, el termostato queda in\xFAtil instant\xE1neamente.",question:"When replacing a domestic thermostat, what precaution must be taken with the sensor capillary tube?",options:["It should be cut to fit.","It must not be sharply bent or kinked, as it contains a gas charge that operates the switch.","It should be painted red.","It should be heated before installing."],explanation:"If the capillary tube is broken or punctured, the thermostat becomes instantly useless."},{id:"refri_110",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta sudoraci\xF3n en el exterior del gabinete. \xBFCausa probable?",opciones:["Falta de gas.","Aislamiento t\xE9rmico degradado o saturado de agua, o humedad ambiental extremadamente alta (>80%).","Luz interna prendida.","Motor muy caliente."],respuesta_correcta:1,explicacion:"Si el fr\xEDo atraviesa la pared del refrigerador debido a un mal aislamiento, el punto de roc\xEDo se alcanza en la pared externa.",question:"A domestic refrigerator shows sweating (condensation) on the exterior of the cabinet. What is the probable cause?",options:["Low refrigerant charge.","Degraded or water-saturated thermal insulation, or extremely high ambient humidity (above 80%).","Interior light left on.","Motor too hot."],explanation:"If the cold penetrates through the refrigerator wall due to poor insulation, the dew point is reached on the external surface."},{id:"refri_111",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 un refrigerador de absorci\xF3n debe estar perfectamente nivelado?",opciones:["Por est\xE9tica.","Porque el movimiento del refrigerante (amon\xEDaco/hidr\xF3geno/agua) depende de la gravedad y la convecci\xF3n t\xE9rmica sin bombas.","Para que el hielo no se caiga.","Para que la puerta cierre sola."],respuesta_correcta:1,explicacion:"Un desnivel de pocos grados detiene el ciclo qu\xEDmico y el equipo deja de enfriar.",question:"Why must an absorption refrigerator be perfectly level?",options:["For aesthetics.","Because the movement of the refrigerant (ammonia/hydrogen/water) depends on gravity and thermal convection without any pumps.","So the ice does not fall out.","So the door closes by itself."],explanation:"A tilt of just a few degrees can stop the chemical cycle and the unit stops cooling."},{id:"refri_112",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene una fuga en el condensador din\xE1mico (el que tiene ventilador). El t\xE9cnico decide anularlo y poner uno est\xE1tico exterior. \xBFQu\xE9 debe calcular?",opciones:["Solo el color del condensador.","El \xE1rea de transferencia de calor debe ser equivalente para no elevar la presi\xF3n de descarga y da\xF1ar el compresor.","Nada, todos los condensadores son iguales.","El peso del compresor."],respuesta_correcta:1,explicacion:"Si el nuevo condensador es m\xE1s peque\xF1o, el equipo trabajar\xE1 a presiones muy altas, acortando la vida \xFAtil del motor.",question:"A domestic refrigerator has a leak in the forced-air condenser (the one with a fan). The technician decides to bypass it and install a static external condenser. What must be calculated?",options:["Only the color of the condenser.","The heat transfer surface area must be equivalent to avoid raising discharge pressure and damaging the compressor.","Nothing; all condensers are the same.","The weight of the compressor."],explanation:"If the replacement condenser is smaller, the unit will operate at very high pressures, shortening the motor's service life."},{id:"refri_113",categoria:"REFRI_DOMESTICA",pregunta:"Al realizar un vac\xEDo en un refrigerador dom\xE9stico, el vacu\xF3metro se queda clavado en 2000 micrones y no baja m\xE1s. \xBFQu\xE9 indica?",opciones:["Vac\xEDo perfecto.","Presencia de humedad atrapada en el aceite o una microfuga en el sistema.","La bomba es muy potente.","El refrigerante est\xE1 saliendo."],respuesta_correcta:1,explicacion:"Un vac\xEDo aceptable debe bajar de 500 micrones. Quedarse en 2000 es se\xF1al de contaminaci\xF3n o entrada de aire.",question:"While pulling a vacuum on a domestic refrigerator, the micron gauge stalls at 2,000 microns and will not go lower. What does this indicate?",options:["A perfect vacuum.","Moisture trapped in the oil or a micro-leak in the system.","The pump is too powerful.","Refrigerant is escaping."],explanation:"An acceptable vacuum must reach below 500 microns. Stalling at 2,000 is a sign of contamination or air ingress."},{id:"refri_114",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador 'No-Frost' tiene el evaporador bloqueado de hielo, pero la resistencia y el bimetal est\xE1n bien. \xBFQu\xE9 componente revisas ahora?",opciones:["El compresor.","El Timer (reloj de deshielo) o los sensores de la tarjeta electr\xF3nica.","El ventilador del condensador.","La carga de gas."],respuesta_correcta:1,explicacion:"Si los ejecutores (resistencia) funcionan, el problema est\xE1 en el cerebro que manda la orden del ciclo.",question:"A No-Frost refrigerator has the evaporator blocked with ice, but the heater and bimetal thermostat are both good. What component do you check next?",options:["The compressor.","The defrost timer or the electronic control board sensors.","The condenser fan.","The refrigerant charge."],explanation:"If the actuators (heater) work, the problem lies in the controller that gives the command for the defrost cycle."},{id:"refri_115",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 sucede si se carga un sistema de R-600a usando una manguera de servicio muy larga y sin purgar?",opciones:["Enfr\xEDa m\xE1s r\xE1pido.","Se introduce una cantidad significativa de aire (no condensables) y humedad, alterando la carga cr\xEDtica que es muy peque\xF1a.","El motor se vuelve silencioso.","No pasa nada."],respuesta_correcta:1,explicacion:"En sistemas con cargas de 40-60g, el aire dentro de una manguera de 1 metro es suficiente para arruinar el rendimiento.",question:"What happens if an R-600a system is charged using a very long, unpurged service hose?",options:["It cools faster.","A significant amount of air (non-condensables) and moisture is introduced, altering the very small critical charge.","The motor becomes quieter.","Nothing happens."],explanation:"In systems with a 40-60 gram charge, the air trapped inside a one-meter hose is enough to ruin system performance."},{id:"refri_116",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta una temperatura de 32\xB0F en el conservador (congela las verduras). \xBFQu\xE9 componente falla?",opciones:["El compresor.","El termostato o sensor de temperatura de ambiente (descalibrado o pegado).","Falta de gas.","El foco interno."],respuesta_correcta:1,explicacion:"Si el equipo enfr\xEDa de m\xE1s, es porque el control no sabe cu\xE1ndo detener el ciclo.",question:"A domestic refrigerator shows a fresh food compartment temperature of 32 degrees F (freezing the vegetables). Which component is at fault?",options:["The compressor.","The thermostat or temperature sensor (out of calibration or stuck).","Low refrigerant charge.","The interior light."],explanation:"If the unit overcools, the control system does not know when to stop the cycle."},{id:"refri_117",categoria:"REFRI_DOMESTICA",pregunta:"\xBFQu\xE9 s\xEDntoma indica que el 'Tubo Capilar' est\xE1 parcialmente obstruido?",opciones:["Alta presi\xF3n de succi\xF3n.","Baja presi\xF3n de succi\xF3n, alto sobrecalentamiento y el evaporador solo se congela al inicio.","El compresor no arranca.","La luz no prende."],respuesta_correcta:1,explicacion:"La restricci\xF3n impide que pase la masa de refrigerante necesaria para llenar todo el evaporador.",question:"What symptom indicates that the capillary tube is partially obstructed?",options:["High suction pressure.","Low suction pressure, high superheat, and frost only at the beginning of the evaporator.","The compressor will not start.","The light does not turn on."],explanation:"The restriction prevents enough refrigerant mass from passing through to fill the entire evaporator."},{id:"refri_118",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene la pared trasera caliente y los laterales fr\xEDos. El compresor no para. \xBFDiagn\xF3stico?",opciones:["Falta parcial de refrigerante o compresor con baja eficiencia.","Exceso de carga.","Termostato da\xF1ado en corto.","Bombilla interna encendida siempre."],respuesta_correcta:0,explicacion:"Si no hay suficiente calor en el condensador (pared trasera) pero el compresor trabaja, no hay suficiente bombeo de calor desde el interior.",question:"A domestic refrigerator has a warm back wall and cold side walls. The compressor runs nonstop. What is the diagnosis?",options:["Partial loss of refrigerant charge or a compressor with low efficiency.","Overcharge.","Thermostat stuck closed.","Interior light always on."],explanation:"If there is not enough heat at the condenser (back wall) while the compressor is running, there is not enough heat being pumped from the interior."},{id:"refri_119",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico hace un ruido de 'borboteo' o agua fluyendo despu\xE9s de que el compresor apaga. \xBFEs normal?",opciones:["No, indica fuga de gas.","S\xED, es el sonido del refrigerante igualando presiones a trav\xE9s del tubo capilar.","No, el aceite se est\xE1 saliendo.","Es el drenaje tapado."],respuesta_correcta:1,explicacion:"Al no haber v\xE1lvulas de retenci\xF3n, el gas fluye desde el lado de alta al de baja hasta equilibrarse; es un proceso est\xE1ndar.",question:"A domestic refrigerator makes a bubbling or flowing-water sound after the compressor shuts off. Is this normal?",options:["No, it indicates a refrigerant leak.","Yes, it is the sound of refrigerant equalizing pressures through the capillary tube.","No, oil is leaking out.","It is a clogged drain."],explanation:"Since there are no check valves, refrigerant flows from the high side to the low side until pressures equalize; this is a standard process."},{id:"refri_120",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la causa m\xE1s com\xFAn de que un refrigerador No-Frost se bloquee de hielo?",opciones:["Dejar la puerta abierta.","Falla en el sistema de desescarche (Timer, resistencia o bimetal).","Compresor muy potente.","Bombilla interna fundida."],respuesta_correcta:1,explicacion:"Si el ciclo de deshielo no ocurre, el hielo acumulado bloquea el paso del aire hacia el conservador.",question:"What is the most common cause of a No-Frost refrigerator becoming blocked with ice?",options:["Leaving the door open.","A failure in the defrost system (timer, heater, or bimetal thermostat).","An overpowered compressor.","A burned-out interior light bulb."],explanation:"If the defrost cycle does not occur, accumulated ice blocks the airflow path to the fresh food compartment."},{id:"refri_121",categoria:"REFRI_DOMESTICA",pregunta:"Al cambiar un compresor dom\xE9stico, \xBFpor qu\xE9 se debe usar nitr\xF3geno para soldar?",opciones:["Para enfriar los tubos.","Para desplazar el ox\xEDgeno y evitar la formaci\xF3n de holl\xEDn (cascarilla) dentro de las tuber\xEDas que tapar\xEDa el capilar.","Para detectar fugas mientras sueldas.","Para ahorrar plata."],respuesta_correcta:1,explicacion:"La cascarilla de \xF3xido de cobre es el enemigo n\xFAmero uno de los tubos capilares.",question:"When replacing a domestic compressor, why must nitrogen be used during brazing?",options:["To cool the tubing.","To displace oxygen and prevent the formation of copper oxide scale inside the tubing, which would clog the capillary tube.","To detect leaks while brazing.","To save silver alloy."],explanation:"Copper oxide scale is the number one enemy of capillary tubes."},{id:"refri_122",categoria:"REFRI_DOMESTICA",pregunta:"En un refrigerador con R-600a, si el t\xE9cnico debe soldar cerca del compresor, \xBFqu\xE9 paso es obligatorio?",opciones:["Usar mucha soldadura.","Evacuar el sistema y realizar un barrido con nitr\xF3geno para desplazar cualquier residuo inflamable antes de aplicar llama.","Mojar el compresor con agua.","Soldar lo m\xE1s r\xE1pido posible."],respuesta_correcta:1,explicacion:"La seguridad contra explosi\xF3n es la prioridad absoluta al trabajar con hidrocarburos.",question:"In a refrigerator using R-600a, if the technician must braze near the compressor, what step is mandatory?",options:["Use plenty of brazing alloy.","Evacuate the system and perform a nitrogen purge to displace any flammable residue before applying a flame.","Wet the compressor with water.","Braze as fast as possible."],explanation:"Explosion safety is the absolute priority when working with hydrocarbon refrigerants."},{id:"refri_123",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico presenta condensaci\xF3n de agua en el separador de puertas. \xBFQu\xE9 resistencia est\xE1 fallando?",opciones:["La resistencia de deshielo.","La resistencia anti-condensaci\xF3n (malla t\xE9rmica o heater de marco).","La resistencia del compresor.","No usa resistencias."],respuesta_correcta:1,explicacion:"Esta resistencia mantiene el marco por encima del punto de roc\xEDo para evitar el 'sudor' externo.",question:"A domestic refrigerator shows condensation on the door mullion (divider between doors). Which heater is failing?",options:["The defrost heater.","The anti-condensation heater (mullion heater or frame heater).","The compressor heater.","It does not use heaters."],explanation:"This heater keeps the frame above the dew point to prevent external sweating."},{id:"refri_124",categoria:"REFRI_DOMESTICA",pregunta:"Un refrigerador dom\xE9stico tiene el compresor funcionando pero el ventilador del evaporador est\xE1 trabado. \xBFC\xF3mo estar\xE1 la presi\xF3n de succi\xF3n?",opciones:["M\xE1s alta de lo normal.","M\xE1s baja de lo normal y el serpent\xEDn se llenar\xE1 de hielo r\xE1pidamente.","Igual a la de la placa.","En vac\xEDo total."],respuesta_correcta:1,explicacion:"Sin flujo de aire, el refrigerante no tiene calor que absorber, por lo que la presi\xF3n de saturaci\xF3n cae.",question:"A domestic refrigerator has the compressor running but the evaporator fan is stuck. How will the suction pressure behave?",options:["Higher than normal.","Lower than normal, and the coil will ice up rapidly.","Same as the nameplate rating.","Full vacuum."],explanation:"Without airflow, the refrigerant has no heat to absorb, so the saturation pressure drops."},{id:"refri_125",categoria:"REFRI_DOMESTICA",pregunta:"Al realizar una carga de R-134a, \xBFpor qu\xE9 no se debe invertir el cilindro si el sistema est\xE1 encendido?",opciones:["Para no gastar gas.","Para evitar que entre l\xEDquido al compresor por la succi\xF3n y cause un da\xF1o mec\xE1nico inmediato por incompresibilidad.","Porque el cilindro se congela.","Porque el man\xF3metro se rompe."],respuesta_correcta:1,explicacion:"El compresor es una bomba de vapor; el l\xEDquido es su enemigo mortal.",question:"When charging R-134a, why should the cylinder not be inverted while the system is running?",options:["To save gas.","To prevent liquid from entering the compressor through the suction port, which would cause immediate mechanical damage from liquid slugging.","Because the cylinder freezes.","Because the gauge will break."],explanation:"The compressor is a vapor pump; liquid is its worst enemy."},{id:"refri_126",categoria:"REFRI_DOMESTICA",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Condensador de Pared' en refrigeradores modernos?",opciones:["Adornar el equipo.","Disipar el calor a trav\xE9s de las paredes met\xE1licas del gabinete, eliminando la necesidad de rejillas traseras y ventiladores.","Calentar el interior.","Enfriar el motor."],respuesta_correcta:1,explicacion:"Hace el sistema m\xE1s limpio est\xE9ticamente y utiliza la superficie total para el intercambio.",question:"What is the function of a wall-type condenser in modern refrigerators?",options:["To decorate the unit.","To dissipate heat through the metal walls of the cabinet, eliminating the need for rear grilles and fans.","To heat the interior.","To cool the motor."],explanation:"It makes the system aesthetically cleaner and uses the entire cabinet surface for heat exchange."},{id:"refri_127",categoria:"REFRI_DOMESTICA",pregunta:"\xBFPor qu\xE9 se dice que el R-600a es 'Respetuoso con el Clima'?",opciones:["Porque huele a flores.","Porque tiene un GWP (Potencial de Calentamiento Global) de 3 y un ODP (Da\xF1o a la capa de ozono) de 0.","Porque es barato.","Porque no usa compresor."],respuesta_correcta:1,explicacion:"Es el est\xE1ndar ecol\xF3gico mundial para refrigeraci\xF3n dom\xE9stica actual.",question:"Why is R-600a considered 'climate-friendly'?",options:["Because it smells like flowers.","Because it has a GWP (Global Warming Potential) of 3 and an ODP (Ozone Depletion Potential) of 0.","Because it is cheap.","Because it does not use a compressor."],explanation:"It is the current worldwide environmental standard for domestic refrigeration."},{id:"refri_128",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A y TXV, el visor de l\xEDquido muestra burbujas constantes, pero el subenfriamiento a la salida del condensador es de 15\xB0F. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Falta de carga de refrigerante.","Restricci\xF3n en el filtro deshidratador.","Presencia de gases no condensables en el sistema.","Flash gas causado por una ca\xEDda de presi\xF3n excesiva en la l\xEDnea de l\xEDquido."],respuesta_correcta:3,explicacion:"Si hay subenfriamiento alto (15\xB0F) pero burbujas en el visor, no falta refrigerante. Las burbujas se deben a la ca\xEDda de presi\xF3n en la l\xEDnea de l\xEDquido antes del visor, creando 'flash gas'.",question:"In a system using R-404A with a TXV, the sight glass shows constant bubbles, but the subcooling at the condenser outlet is 15 degrees F. What is the diagnosis?",options:["Low refrigerant charge.","Restriction in the filter drier.","Non-condensable gases in the system.","Flash gas caused by an excessive pressure drop in the liquid line."],explanation:"If subcooling is high (15 degrees F) but there are bubbles in the sight glass, the system is not low on charge. The bubbles are caused by the pressure drop in the liquid line before the sight glass, creating flash gas."},{id:"refri_129",categoria:"REFRI_COMERCIAL",pregunta:"Si una TXV tiene el bulbo suelto y no hace contacto con la tuber\xEDa, \xBFc\xF3mo afectar\xE1 esto a las presiones del sistema?",opciones:["Presi\xF3n de succi\xF3n baja y sobrecalentamiento alto.","Presi\xF3n de succi\xF3n alta y sobrecalentamiento bajo.","Presi\xF3n de descarga extremadamente alta.","No afecta la presi\xF3n, solo la temperatura de descarga."],respuesta_correcta:1,explicacion:"Al no sentir el fr\xEDo de la tuber\xEDa, el bulbo se calienta con el aire ambiente, abriendo la TXV al m\xE1ximo (inundando el evaporador), lo que sube la succi\xF3n y baja el superheat.",question:"If a TXV has a loose sensing bulb that is not making contact with the suction line, how will this affect system pressures?",options:["Suction pressure low and superheat high.","Suction pressure high and superheat low.","Extremely high discharge pressure.","No effect on pressure, only on discharge temperature."],explanation:"Without sensing the cold suction line, the bulb warms up with the ambient air, opening the TXV to maximum (flooding the evaporator), which raises suction pressure and lowers superheat."},{id:"refri_130",categoria:"REFRI_COMERCIAL",pregunta:"Un enfriador de botellas usa tubo capilar. Si el t\xE9cnico corta 12 pulgadas del capilar original para 'limpiarlo', \xBFqu\xE9 efecto tendr\xE1 en el sistema?",opciones:["Aumentar\xE1 la capacidad de enfriamiento.","Aumentar\xE1 la presi\xF3n de succi\xF3n y disminuir\xE1 el sobrecalentamiento.","Disminuir\xE1 el flujo de refrigerante.","El compresor consumir\xE1 menos amperaje."],respuesta_correcta:1,explicacion:"Al acortar el capilar se reduce la resistencia al flujo, lo que aumenta la presi\xF3n de succi\xF3n y puede causar retorno de l\xEDquido al compresor.",question:"A bottle cooler uses a capillary tube. If the technician cuts 12 inches off the original capillary tube to 'clean it,' what effect will this have on the system?",options:["Increased cooling capacity.","Increased suction pressure and decreased superheat.","Decreased refrigerant flow.","Lower compressor amperage."],explanation:"Shortening the capillary tube reduces its flow restriction, which increases suction pressure and can cause liquid floodback to the compressor."},{id:"refri_131",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la ca\xEDda de presi\xF3n m\xE1xima aceptable en una l\xEDnea de succi\xF3n para evitar p\xE9rdida significativa de capacidad?",opciones:["Equivalente a 2\xB0F de cambio en la temperatura de saturaci\xF3n.","10 PSI constantes.","5% de la presi\xF3n de descarga.","No importa mientras el compresor sea grande."],respuesta_correcta:0,explicacion:"Las reglas de dise\xF1o de ASHRAE y manuales t\xE9cnicos sugieren no exceder una ca\xEDda de presi\xF3n equivalente a 2\xB0F (1.1\xB0C) para mantener la eficiencia.",question:"What is the maximum acceptable pressure drop in a suction line to avoid significant capacity loss?",options:["Equivalent to a 2 degrees F change in saturation temperature.","A constant 10 PSI.","5% of the discharge pressure.","It does not matter as long as the compressor is large enough."],explanation:"ASHRAE design guidelines and technical manuals recommend not exceeding a pressure drop equivalent to 2 degrees F (1.1 degrees C) to maintain efficiency."},{id:"refri_132",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede con la capacidad de un condensador enfriado por aire si la altitud de la instalaci\xF3n aumenta (ej. de nivel del mar a 2,500 metros)?",opciones:["La capacidad aumenta porque el aire es m\xE1s fr\xEDo.","La capacidad disminuye porque el aire es menos denso y transporta menos calor.","La capacidad se mantiene igual.","La presi\xF3n de condensaci\xF3n baja autom\xE1ticamente."],respuesta_correcta:1,explicacion:"A mayor altitud, el aire es menos denso. Al haber menos masa de aire pasando por las aletas, la transferencia de calor es menos eficiente.",question:"What happens to the capacity of an air-cooled condenser if the installation altitude increases (e.g., from sea level to 8,200 feet)?",options:["Capacity increases because the air is cooler.","Capacity decreases because the air is less dense and carries less heat.","Capacity stays the same.","Condensing pressure drops automatically."],explanation:"At higher altitude, the air is less dense. With less air mass passing over the fins, heat transfer is less efficient."},{id:"refri_133",categoria:"REFRI_COMERCIAL",pregunta:"En una TXV con igualaci\xF3n interna, \xBFd\xF3nde 'lee' la v\xE1lvula la presi\xF3n que se opone a la apertura?",opciones:["A trav\xE9s de un capilar conectado a la salida del evaporador.","Directamente en la salida de la propia v\xE1lvula (orificio).","En el domo del compresor.","En la l\xEDnea de l\xEDquido."],respuesta_correcta:1,explicacion:"Las v\xE1lvulas de igualaci\xF3n interna asumen que la presi\xF3n en la entrada del evaporador es la misma que a la salida, lo cual es falso en evaporadores grandes.",question:"In a TXV with internal equalization, where does the valve sense the pressure that opposes opening?",options:["Through a capillary tube connected to the evaporator outlet.","Directly at the valve's own outlet (orifice).","At the compressor dome.","In the liquid line."],explanation:"Internally equalized valves assume that the pressure at the evaporator inlet is the same as at the outlet, which is false in large evaporators."},{id:"refri_134",categoria:"REFRI_COMERCIAL",pregunta:"Un enfriador de bebidas tiene condensador sucio. \xBFQu\xE9 efecto tiene esto sobre el aceite del compresor?",opciones:["Lo hace m\xE1s viscoso.","Produce carbonizaci\xF3n y acidez debido a las altas temperaturas de descarga.","Ayuda a que el aceite regrese m\xE1s r\xE1pido.","No afecta al aceite, solo al consumo el\xE9ctrico."],respuesta_correcta:1,explicacion:"El calor extremo degrada el aceite POE/Mineral, creando lodos y \xE1cidos que atacan el barniz del motor.",question:"A beverage cooler has a dirty condenser. What effect does this have on the compressor oil?",options:["It makes the oil more viscous.","It causes carbonization and acidity due to excessively high discharge temperatures.","It helps the oil return faster.","It does not affect the oil, only the electrical consumption."],explanation:"Extreme heat degrades POE or mineral oil, creating sludge and acids that attack the motor winding varnish."},{id:"refri_135",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la temperatura t\xEDpica de dise\xF1o de un evaporador para un 'Walk-in Freezer' que debe estar a -10\xB0F?",opciones:["-10\xB0F","0\xB0F","-20\xB0F","20\xB0F"],respuesta_correcta:2,explicacion:"Se suele dise\xF1ar con un TD (Temperature Difference) de 10\xB0F. Para que el aire est\xE9 a -10\xB0F, el serpent\xEDn debe estar a -20\xB0F.",question:"What is the typical design temperature for an evaporator in a walk-in freezer that must maintain -10 degrees F?",options:["-10 degrees F","0 degrees F","-20 degrees F","20 degrees F"],explanation:"The standard design uses a 10 degrees F TD (Temperature Difference). For the air to be at -10 degrees F, the coil must be at -20 degrees F."},{id:"refri_136",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con capilar, si agregas demasiado refrigerante, \xBFqu\xE9 parte del sistema sufrir\xE1 primero?",opciones:["El condensador.","El compresor (por golpe de l\xEDquido).","El evaporador (se congela).","El filtro deshidratador."],respuesta_correcta:1,explicacion:"Los sistemas capilares son cr\xEDticos en carga. El exceso de l\xEDquido llena el evaporador y termina llegando al compresor en forma l\xEDquida.",question:"In a capillary tube system, if you add too much refrigerant, which part of the system will suffer first?",options:["The condenser.","The compressor (from liquid slugging).","The evaporator (it freezes up).","The filter drier."],explanation:"Capillary tube systems are critical-charge systems. Excess liquid fills the evaporator and ends up reaching the compressor in liquid form."},{id:"refri_137",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n principal de un receptor de l\xEDquido?",opciones:["Almacenar el refrigerante que no se necesita en el evaporador durante bajas cargas t\xE9rmicas.","Separar el aceite del gas.","Enfriar el gas de descarga.","Actuar como filtro de part\xEDculas."],respuesta_correcta:0,explicacion:"Asegura que solo llegue l\xEDquido 100% a la v\xE1lvula de expansi\xF3n, independientemente de la carga del sistema.",question:"What is the primary function of a liquid receiver?",options:["To store refrigerant that is not needed in the evaporator during low thermal loads.","To separate oil from the refrigerant gas.","To cool the discharge gas.","To act as a particle filter."],explanation:"It ensures that only 100% liquid reaches the expansion valve, regardless of the system's load condition."},{id:"refri_138",categoria:"REFRI_COMERCIAL",pregunta:"En una vitrina refrigerada (Display Case), \xBFqu\xE9 causa que el aire soplado por los ventiladores se sienta 'h\xFAmedo' y el producto no enfr\xEDe, aunque el evaporador no tenga hielo?",opciones:["Falta de refrigerante.","Velocidad de aire demasiado alta (no da tiempo al intercambio).","Serpent\xEDn del evaporador sucio por grasa/polvo obstruyendo el intercambio t\xE9rmico.","Compresor con v\xE1lvulas da\xF1adas."],respuesta_correcta:2,explicacion:"La suciedad act\xFAa como aislante. El aire pasa pero no cede calor al refrigerante, resultando en aire h\xFAmedo y producto caliente.",question:"In a refrigerated display case, what causes the air blown by the fans to feel humid and the product not to cool, even though the evaporator has no ice?",options:["Low refrigerant charge.","Air velocity too high (not enough time for heat exchange).","Evaporator coil fouled with grease/dust, blocking heat transfer.","Compressor with damaged valves."],explanation:"Dirt acts as an insulator. Air passes through but does not give up heat to the refrigerant, resulting in humid air and warm product."},{id:"refri_139",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema de deshielo por gas caliente, \xBFqu\xE9 componente regula la presi\xF3n del gas que entra al evaporador para evitar da\xF1os mec\xE1nicos?",opciones:["La v\xE1lvula de expansi\xF3n.","La v\xE1lvula reguladora de presi\xF3n de desescarche (Check Valve con orificio o reguladora).","El presostato de alta.","El termostato de ambiente."],respuesta_correcta:1,explicacion:"Inyectar gas a plena presi\xF3n de descarga podr\xEDa da\xF1ar el evaporador o causar golpes de ariete.",question:"In a hot-gas defrost system, which component regulates the pressure of the gas entering the evaporator to prevent mechanical damage?",options:["The expansion valve.","The defrost pressure regulating valve (check valve with orifice or regulator).","The high-pressure switch.","The room thermostat."],explanation:"Injecting gas at full discharge pressure could damage the evaporator or cause water hammer."},{id:"refri_140",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la causa m\xE1s com\xFAn de que un compresor de un Reach-in queme sus bobinas por calor (Burnout) si el amperaje era normal?",opciones:["Falta de ventilaci\xF3n en el \xE1rea de la unidad condensadora.","Termostato ajustado muy bajo.","Puertas abiertas mucho tiempo.","Uso de refrigerante virgen."],respuesta_correcta:0,explicacion:"Si el aire no circula por el condensador, el calor no se rechaza. El gas de succi\xF3n llega muy caliente y no enfr\xEDa las bobinas del motor semi-herm\xE9tico o herm\xE9tico.",question:"What is the most common cause of a reach-in compressor suffering a winding burnout from heat, even though the amperage was normal?",options:["Inadequate ventilation around the condensing unit.","Thermostat set too low.","Doors left open too long.","Use of virgin refrigerant."],explanation:"If air does not circulate over the condenser, heat is not rejected. The suction gas arrives too hot and does not adequately cool the motor windings of the hermetic or semi-hermetic compressor."},{id:"refri_141",categoria:"REFRI_COMERCIAL",pregunta:"Si el evaporador est\xE1 a 20\xB0F y el aire que sale de \xE9l est\xE1 a 30\xB0F, \xBFcu\xE1l es el 'Evaporator TD'?",opciones:["50\xB0F","10\xB0F","-10\xB0F","25\xB0F"],respuesta_correcta:1,explicacion:"TD = Temp. Aire Entrada (o salida en ciertos contextos de dise\xF1o) - Temp. Saturaci\xF3n. 30 - 20 = 10.",question:"If the evaporator is at 20 degrees F and the air leaving it is at 30 degrees F, what is the evaporator TD?",options:["50 degrees F","10 degrees F","-10 degrees F","25 degrees F"],explanation:"TD = Air Temperature - Saturation Temperature. 30 - 20 = 10."},{id:"refri_142",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema de refrigeraci\xF3n comercial, \xBFqu\xE9 indica un visor de l\xEDquido con el indicador de color en amarillo?",opciones:["El sistema est\xE1 operando a alta temperatura.","Presencia de humedad en el refrigerante por encima de los niveles permitidos.","El aceite est\xE1 sucio.","Falta de refrigerante en el sistema."],respuesta_correcta:1,explicacion:"El indicador qu\xEDmico del visor reacciona a la humedad. Amarillo significa peligro (\xE1cido/hielo), verde significa seco.",question:"In a commercial refrigeration system, what does a yellow color indicator in the sight glass mean?",options:["The system is operating at high temperature.","Moisture content in the refrigerant is above the allowable level.","The oil is dirty.","The system is low on refrigerant."],explanation:"The chemical indicator in the sight glass reacts to moisture. Yellow means danger (acid/ice risk); green means dry."},{id:"refri_143",categoria:"REFRI_COMERCIAL",pregunta:"Un 'Ice Machine' (m\xE1quina de hielo) produce cubos muy delgados y el tiempo de cosecha es muy largo. \xBFCu\xE1l es el problema m\xE1s probable?",opciones:["Entrada de agua demasiado fr\xEDa.","Sensores de espesor desajustados o falta de gas.","Mucho hielo en el dep\xF3sito.","Ventilador del condensador muy r\xE1pido."],respuesta_correcta:1,explicacion:"Si falta gas, la temperatura del evaporador no baja lo suficiente para formar el grosor del cubo en el tiempo previsto.",question:"An ice machine produces very thin cubes and the harvest cycle is excessively long. What is the most probable problem?",options:["Incoming water too cold.","Thickness sensors out of adjustment or low refrigerant charge.","Too much ice in the storage bin.","Condenser fan running too fast."],explanation:"If the charge is low, the evaporator plate temperature does not drop enough to build the proper cube thickness in the allotted time."},{id:"refri_144",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, si el sobrecalentamiento (Superheat) en la salida del evaporador es de 2\xB0F y en la entrada del compresor es de 25\xB0F, \xBFqu\xE9 indica esta diferencia?",opciones:["El sistema funciona perfectamente.","Hay una ganancia de calor excesiva en la l\xEDnea de succi\xF3n o falta de aislamiento.","La TXV est\xE1 inundando el evaporador.","El compresor est\xE1 perdiendo eficiencia."],respuesta_correcta:1,explicacion:"Un superheat muy bajo en el evaporador indica que est\xE1 casi inundado, pero si llega alto al compresor, el gas se est\xE1 calentando en el trayecto, lo que reduce la densidad del gas y la capacidad del compresor.",question:"In a system using R-404A, the superheat at the evaporator outlet is 2 degrees F and the superheat at the compressor inlet is 25 degrees F. What does this difference indicate?",options:["The system is operating perfectly.","Excessive heat gain in the suction line or lack of insulation.","The TXV is flooding the evaporator.","The compressor is losing efficiency."],explanation:"Very low superheat at the evaporator means it is nearly flooded, but if superheat is high at the compressor, the gas is picking up heat along the suction line, reducing gas density and compressor capacity."},{id:"refri_145",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 ocurre si se instala un filtro deshidratador de la l\xEDnea de l\xEDquido en sentido contrario a la flecha de flujo?",opciones:["El refrigerante no pasa.","El filtro puede soltar el desecante hacia la v\xE1lvula de expansi\xF3n o aumentar la ca\xEDda de presi\xF3n excesivamente.","El sistema enfr\xEDa m\xE1s r\xE1pido.","Se rompe el compresor por alta presi\xF3n."],respuesta_correcta:1,explicacion:"Los filtros est\xE1n dise\xF1ados para retener part\xEDculas y desecante en una estructura interna espec\xEDfica que solo es eficiente en una direcci\xF3n.",question:"What happens if a liquid-line filter drier is installed backwards (against the flow arrow)?",options:["The refrigerant will not pass.","The filter may release desiccant particles toward the expansion valve or cause an excessive pressure drop.","The system will cool faster.","The compressor will fail on high pressure."],explanation:"Filter driers are designed to retain particles and desiccant in an internal structure that is only effective in one direction of flow."},{id:"refri_146",categoria:"REFRI_COMERCIAL",pregunta:"Si el 'Sling' (lazo de aceite) en la descarga de un compresor est\xE1 mal dise\xF1ado y permite el retorno de aceite l\xEDquido al plato de v\xE1lvulas en la parada, \xBFqu\xE9 ruido se escuchar\xE1 al arrancar?",opciones:["Un silbido constante.","Un golpe met\xE1lico fuerte (Slugging) debido a la incompresibilidad del aceite.","No se escuchar\xE1 nada.","Un zumbido el\xE9ctrico."],respuesta_correcta:1,explicacion:"Los l\xEDquidos no se pueden comprimir. Si el aceite llena el espacio muerto del cilindro, el pist\xF3n chocar\xE1 contra \xE9l, pudiendo romper las v\xE1lvulas o la biela.",question:"If the oil trap (oil loop) in the discharge line of a compressor is poorly designed and allows liquid oil to flow back to the valve plate during shutdown, what noise will be heard at startup?",options:["A constant whistling.","A loud metallic bang (slugging) caused by the incompressibility of the oil.","Nothing will be heard.","An electrical hum."],explanation:"Liquids cannot be compressed. If oil fills the cylinder clearance volume, the piston will slam into it, potentially breaking the valves or connecting rod."},{id:"refri_147",categoria:"REFRI_COMERCIAL",pregunta:"Mides una presi\xF3n de succi\xF3n de 30 PSI en un sistema con R-134a, pero la temperatura del evaporador medida con term\xF3metro es de 45\xB0F. \xBFQu\xE9 sucede?",opciones:["El sistema est\xE1 perfecto.","Hay una gran ca\xEDda de presi\xF3n entre el evaporador y el punto de medici\xF3n.","El refrigerante est\xE1 contaminado.","El term\xF3metro est\xE1 mal calibrado."],respuesta_correcta:1,explicacion:"A 30 PSI el R-134a satura a 35\xB0F. Si el metal est\xE1 a 45\xB0F, hay un diferencial que indica falta de eficiencia o error de flujo.",question:"You measure a suction pressure of 30 PSI on a system using R-134a, but the evaporator temperature measured with a thermometer is 45 degrees F. What is happening?",options:["The system is perfect.","There is a large pressure drop between the evaporator and the measurement point.","The refrigerant is contaminated.","The thermometer is out of calibration."],explanation:"At 30 PSI, R-134a saturates at 35 degrees F. If the metal reads 45 degrees F, there is a differential indicating poor efficiency or flow issues."},{id:"refri_148",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 efecto tiene el exceso de aceite en el evaporador sobre el sobrecalentamiento?",opciones:["Lo hace m\xE1s estable.","Causa fluctuaciones (Hunting) y reduce la transferencia de calor, elevando el sobrecalentamiento real.","No tiene ning\xFAn efecto.","Baja la temperatura de saturaci\xF3n."],respuesta_correcta:1,explicacion:"El aceite crea una pel\xEDcula aislante. El refrigerante no puede absorber calor eficientemente, lo que confunde a la TXV.",question:"What effect does excess oil in the evaporator have on superheat?",options:["It makes superheat more stable.","It causes fluctuations (hunting) and reduces heat transfer, raising the actual superheat.","It has no effect.","It lowers the saturation temperature."],explanation:"Oil creates an insulating film. The refrigerant cannot absorb heat efficiently, which confuses the TXV."},{id:"refri_149",categoria:"REFRI_COMERCIAL",pregunta:"En un condensador enfriado por aire, el 'Delta T' del aire (salida menos entrada) es muy bajo (ej. 3\xB0F), pero la presi\xF3n de alta es muy elevada. \xBFCu\xE1l es el problema?",opciones:["Falta de gas.","Recirculaci\xF3n del aire caliente o bypass de aire alrededor del serpent\xEDn.","El ventilador est\xE1 demasiado r\xE1pido.","El condensador es demasiado grande."],respuesta_correcta:1,explicacion:"Si el aire no atraviesa el serpent\xEDn y solo 'rebota' o rodea el condensador, no absorbe calor, resultando en un delta T bajo y alta presi\xF3n por falta de condensaci\xF3n.",question:"In an air-cooled condenser, the air delta T (outlet minus inlet) is very low (e.g., 3 degrees F), but the high-side pressure is very elevated. What is the problem?",options:["Low refrigerant charge.","Recirculation of hot discharge air or air bypassing around the coil.","The fan is running too fast.","The condenser is oversized."],explanation:"If the air does not actually pass through the coil and merely bounces off or goes around the condenser, it does not absorb heat, resulting in a low delta T and high head pressure from lack of condensation."},{id:"refri_150",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico nota que la l\xEDnea de l\xEDquido est\xE1 'fr\xEDa' al tacto despu\xE9s del filtro deshidratador. \xBFQu\xE9 significa?",opciones:["El sistema es muy eficiente.","El filtro est\xE1 parcialmente obstruido y est\xE1 actuando como un dispositivo de expansi\xF3n.","Falta gas.","El condensador est\xE1 demasiado fr\xEDo."],respuesta_correcta:1,explicacion:"Cualquier diferencia de temperatura a trav\xE9s de un componente que deber\xEDa ser solo de paso indica una ca\xEDda de presi\xF3n y, por ende, una obstrucci\xF3n.",question:"A technician notices that the liquid line feels cold to the touch after the filter drier. What does this mean?",options:["The system is very efficient.","The filter drier is partially obstructed and is acting as an expansion device.","Low on refrigerant.","The condenser is too cold."],explanation:"Any temperature difference across a component that should be just a pass-through indicates a pressure drop and, therefore, an obstruction."},{id:"refri_151",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-22 convertido a R-407C, el t\xE9cnico no cambi\xF3 el aceite mineral por POE. \xBFQu\xE9 falla ocurrir\xE1 primero?",opciones:["El compresor se quemar\xE1 por alto amperaje.","Falla de lubricaci\xF3n porque el aceite mineral se quedar\xE1 atrapado en el evaporador.","La presi\xF3n de alta bajar\xE1.","El termostato dejar\xE1 de funcionar."],respuesta_correcta:1,explicacion:"Los HFC como el 407C no transportan el aceite mineral de regreso al compresor. El c\xE1rter se quedar\xE1 vac\xEDo y el evaporador se llenar\xE1 de aceite.",question:"In a system converted from R-22 to R-407C, the technician did not change the mineral oil to POE. What failure will occur first?",options:["The compressor will burn out from high amperage.","Lubrication failure because the mineral oil will become trapped in the evaporator.","The high-side pressure will drop.","The thermostat will stop working."],explanation:"HFC refrigerants like R-407C do not transport mineral oil back to the compressor. The crankcase will run dry and the evaporator will fill with oil."},{id:"refri_152",categoria:"REFRI_COMERCIAL",pregunta:"\xBFPara qu\xE9 sirve el puerto de 'Ecualizaci\xF3n Externa' en una TXV?",opciones:["Para cargar gas por ah\xED.","Para compensar la ca\xEDda de presi\xF3n interna del evaporador y que la v\xE1lvula cierre/abra correctamente.","Para medir la temperatura de entrada.","Para purgar el aire."],respuesta_correcta:1,explicacion:"Si el evaporador tiene una ca\xEDda de presi\xF3n mayor a 2-3 PSI, una TXV con igualaci\xF3n interna dar\xE1 un sobrecalentamiento falso y err\xE1tico.",question:"What is the purpose of the external equalization port on a TXV?",options:["To charge refrigerant through it.","To compensate for the internal pressure drop of the evaporator so that the valve opens and closes correctly.","To measure the inlet temperature.","To purge air."],explanation:"If the evaporator has a pressure drop greater than 2-3 PSI, an internally equalized TXV will give a false and erratic superheat reading."},{id:"refri_153",categoria:"REFRI_COMERCIAL",pregunta:"Si un t\xE9cnico encuentra que el sobrecalentamiento total (en el compresor) es de solo 2\xB0F, \xBFcu\xE1l es el riesgo?",opciones:["Que el equipo no enfr\xEDe.","Golpe de l\xEDquido o diluci\xF3n del aceite, lo que destruye el compresor.","Consumo excesivo de energ\xEDa.","Que el condensador explote."],respuesta_correcta:1,explicacion:"Un sobrecalentamiento tan bajo indica que el refrigerante est\xE1 entrando al compresor casi en estado l\xEDquido.",question:"If a technician finds that the total superheat (at the compressor) is only 2 degrees F, what is the risk?",options:["The unit will not cool.","Liquid slugging or oil dilution, which will destroy the compressor.","Excessive energy consumption.","The condenser will burst."],explanation:"Such low superheat indicates that the refrigerant is entering the compressor in a nearly liquid state."},{id:"refri_154",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede con la relaci\xF3n de compresi\xF3n si la presi\xF3n de succi\xF3n baja debido a un filtro de aire sucio?",opciones:["La relaci\xF3n de compresi\xF3n disminuye.","La relaci\xF3n de compresi\xF3n aumenta.","Se mantiene igual.","La presi\xF3n de descarga baja proporcionalmente."],respuesta_correcta:1,explicacion:"Al bajar la presi\xF3n de succi\xF3n, el divisor en la f\xF3rmula ($P_{alta} / P_{baja}$) es menor, lo que da un resultado mayor. Esto calienta m\xE1s al compresor.",question:"What happens to the compression ratio if the suction pressure drops due to a dirty air filter?",options:["The compression ratio decreases.","The compression ratio increases.","It stays the same.","The discharge pressure drops proportionally."],explanation:"When suction pressure drops, the denominator in the formula (P-high / P-low) becomes smaller, producing a larger result. This causes the compressor to run hotter."},{id:"refri_155",categoria:"REFRI_COMERCIAL",pregunta:"\xBFD\xF3nde debe colocarse el bulbo sensor de la TXV en una l\xEDnea de succi\xF3n horizontal de 7/8'?",opciones:["En la parte inferior (a las 6 en punto).","A las 4 o las 8 en punto para evitar lecturas falsas por el aceite.","En la parte superior (a las 12 en punto).","Antes del evaporador."],respuesta_correcta:1,explicacion:"En tuber\xEDas de menos de 7/8 se puede usar a las 12, pero en medidas est\xE1ndar se recomienda a los lados para sentir la temperatura del gas y no del aceite estancado abajo.",question:"Where should the TXV sensing bulb be mounted on a 7/8-inch horizontal suction line?",options:["At the bottom (6 o'clock position).","At the 4 o'clock or 8 o'clock position to avoid false readings caused by oil.","At the top (12 o'clock position).","Before the evaporator."],explanation:"On tubing smaller than 7/8 inch, the 12 o'clock position may be used, but on standard sizes the bulb should be on the side to sense gas temperature, not the temperature of stagnant oil at the bottom."},{id:"refri_156",categoria:"REFRI_COMERCIAL",pregunta:"Si una v\xE1lvula solenoide de la l\xEDnea de l\xEDquido no cierra herm\xE9ticamente durante el Pump Down, \xBFqu\xE9 s\xEDntoma presentar\xE1 el compresor?",opciones:["Alta presi\xF3n de descarga.","Ciclado corto (Short cycling) por el control de baja presi\xF3n durante el periodo de apagado.","El compresor no arrancar\xE1 nunca.","Bajo amperaje."],respuesta_correcta:1,explicacion:"El gas se filtra al lado de baja, subiendo la presi\xF3n hasta que el presostato arranca el compresor de nuevo para volver a vaciarlo.",question:"If a liquid-line solenoid valve does not close tightly during a pump-down cycle, what symptom will the compressor exhibit?",options:["High discharge pressure.","Short cycling on the low-pressure control during the off period.","The compressor will never start.","Low amperage."],explanation:"Gas leaks past the solenoid to the low side, raising the pressure until the low-pressure switch starts the compressor again to re-evacuate it."},{id:"refri_157",categoria:"REFRI_COMERCIAL",pregunta:"Al usar nitr\xF3geno para presurizar, \xBFpor qu\xE9 es indispensable usar un regulador de presi\xF3n?",opciones:["Para no gastar mucho nitr\xF3geno.","Porque los tanques de nitr\xF3geno tienen presiones de hasta 2500 PSI, lo que destruir\xEDa las tuber\xEDas de cobre instant\xE1neamente.","Para filtrar el nitr\xF3geno.","Para que el nitr\xF3geno no se congele."],respuesta_correcta:1,explicacion:"La seguridad es primero. Un tanque sin regulador es b\xE1sicamente una bomba de presi\xF3n incontrolable.",question:"When using nitrogen to pressurize a system, why is a pressure regulator absolutely essential?",options:["To conserve nitrogen.","Because nitrogen cylinders contain pressures up to 2,500 PSI, which would instantly rupture copper tubing.","To filter the nitrogen.","To keep the nitrogen from freezing."],explanation:"Safety comes first. An unregulated cylinder is essentially an uncontrollable pressure bomb."},{id:"refri_158",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el subenfriamiento es de 0\xB0F y hay burbujas en el visor. La presi\xF3n de alta es baja. \xBFDiagn\xF3stico?",opciones:["Obstrucci\xF3n en el filtro.","Falta de refrigerante.","Exceso de carga.","Condensador sucio."],respuesta_correcta:1,explicacion:"Si no hay subenfriamiento, significa que el refrigerante no se est\xE1 terminando de condensar. Es la se\xF1al m\xE1s clara de carga baja.",question:"A technician finds that the subcooling is 0 degrees F and there are bubbles in the sight glass. The high-side pressure is low. What is the diagnosis?",options:["Obstruction in the filter drier.","Low refrigerant charge.","Overcharge.","Dirty condenser."],explanation:"If there is no subcooling, the refrigerant is not fully condensing. This is the clearest sign of a low charge."},{id:"refri_159",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la principal desventaja de usar una v\xE1lvula de expansi\xF3n de orificio fijo (capilar o pist\xF3n) comparada con una TXV?",opciones:["Es m\xE1s cara.","No puede ajustar el flujo ante cambios de carga t\xE9rmica, arriesgando el retorno de l\xEDquido al compresor.","Se tapa m\xE1s f\xE1cil.","Solo sirve para aire acondicionado."],respuesta_correcta:1,explicacion:"El orificio fijo es reactivo solo a la diferencia de presi\xF3n. Si la carga sube, el superheat se dispara; si baja, inunda el compresor.",question:"What is the main disadvantage of using a fixed-orifice expansion device (capillary tube or piston) compared to a TXV?",options:["It is more expensive.","It cannot adjust flow in response to changes in thermal load, risking liquid floodback to the compressor.","It clogs more easily.","It only works for air conditioning."],explanation:"A fixed orifice reacts only to the pressure differential. If the load increases, superheat spikes; if it decreases, the evaporator floods."},{id:"refri_160",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 significa un 'Compresor Fraccionado'?",opciones:["Que est\xE1 roto en pedazos.","Que su potencia es menor a 1 HP (ej. 1/3 HP, 1/2 HP).","Que usa dos tipos de gas.","Que es trif\xE1sico."],respuesta_correcta:1,explicacion:"T\xE9rmino com\xFAn para compresores peque\xF1os usados en refrigeraci\xF3n comercial ligera y dom\xE9stica.",question:"What does 'fractional horsepower compressor' mean?",options:["It is broken into pieces.","Its power rating is less than 1 HP (e.g., 1/3 HP, 1/2 HP).","It uses two types of refrigerant.","It is three-phase."],explanation:"A common term for small compressors used in light commercial refrigeration and domestic applications."},{id:"refri_161",categoria:"REFRI_COMERCIAL",pregunta:"Un visor de l\xEDquido ubicado DESPU\xC9S del receptor muestra burbujas, pero ANTES del receptor el l\xEDquido es claro. \xBFQu\xE9 sucede?",opciones:["Falta gas.","El receptor est\xE1 actuando como un acumulador de calor o hay una restricci\xF3n a la salida del mismo.","El condensador est\xE1 inundado.","Es normal."],respuesta_correcta:1,explicacion:"El receptor debe entregar l\xEDquido puro. Si salen burbujas, hay una ca\xEDda de presi\xF3n interna o el refrigerante se est\xE1 calentando dentro del tanque.",question:"A sight glass located AFTER the liquid receiver shows bubbles, but the sight glass BEFORE the receiver shows clear liquid. What is happening?",options:["Low charge.","The receiver is acting as a heat accumulator or there is a restriction at its outlet.","The condenser is flooded.","This is normal."],explanation:"The receiver should deliver pure liquid. If bubbles appear at its outlet, there is an internal pressure drop or the refrigerant is picking up heat inside the tank."},{id:"refri_162",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula de retenci\xF3n (Check Valve) en la l\xEDnea de descarga de un sistema m\xFAltiple?",opciones:["Aumentar la presi\xF3n.","Evitar que el refrigerante de los compresores activos migre hacia un compresor apagado.","Filtrar el aceite.","Regular el flujo."],respuesta_correcta:1,explicacion:"Sin ella, el gas caliente se condensar\xEDa en el compresor m\xE1s fr\xEDo (el apagado), causando un arranque con golpe de l\xEDquido.",question:"What is the function of a check valve in the discharge line of a multiplex (parallel) compressor system?",options:["To increase pressure.","To prevent refrigerant from active compressors from migrating to a compressor that is off.","To filter oil.","To regulate flow."],explanation:"Without it, hot gas would condense in the coldest compressor (the one that is off), causing a liquid slug at the next startup."},{id:"refri_163",categoria:"REFRI_COMERCIAL",pregunta:"Si el ventilador del condensador falla y la presi\xF3n de alta sube, \xBFqu\xE9 sucede con la temperatura de descarga del compresor?",opciones:["Baja.","Sube dr\xE1sticamente debido al aumento en la relaci\xF3n de compresi\xF3n.","Se mantiene igual.","Baja porque el motor se esfuerza menos."],respuesta_correcta:1,explicacion:"Al compresor le cuesta m\xE1s 'empujar' el gas contra una presi\xF3n mayor, lo que genera m\xE1s calor interno por fricci\xF3n y compresi\xF3n.",question:"If the condenser fan fails and the high-side pressure rises, what happens to the compressor discharge temperature?",options:["It drops.","It rises dramatically due to the increase in the compression ratio.","It stays the same.","It drops because the motor works less."],explanation:"The compressor must work harder to push gas against a higher pressure, generating more internal heat from friction and compression."},{id:"refri_164",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Subenfriamiento' (Subcooling)?",opciones:["La temperatura del evaporador.","La diferencia entre la temperatura de saturaci\xF3n en el condensador y la temperatura real del l\xEDquido a la salida.","El fr\xEDo que hace afuera.","La temperatura de la succi\xF3n."],respuesta_correcta:1,explicacion:"Es la medida de cu\xE1nto calor se le quit\xF3 al l\xEDquido despu\xE9s de haberse condensado. Asegura que llegue l\xEDquido puro a la TXV.",question:"What is subcooling?",options:["The evaporator temperature.","The difference between the saturation temperature at the condenser and the actual temperature of the liquid at its outlet.","The outdoor temperature.","The suction temperature."],explanation:"It measures how much heat has been removed from the liquid after it has condensed. It ensures that pure liquid reaches the TXV."},{id:"refri_165",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 0\xB0F y un subenfriamiento de 20\xB0F?",opciones:["Falta de gas.","Exceso de carga de refrigerante inundando el evaporador y el condensador.","Filtro tapado.","Compresor muy eficiente."],respuesta_correcta:1,explicacion:"Mucho l\xEDquido en el condensador (subcooling alto) y l\xEDquido saliendo del evaporador (superheat 0) es signo cl\xE1sico de sobrecarga.",question:"What do a superheat of 0 degrees F and a subcooling of 20 degrees F indicate?",options:["Low refrigerant charge.","Overcharge of refrigerant, flooding both the evaporator and the condenser.","Clogged filter.","Highly efficient compressor."],explanation:"High liquid in the condenser (high subcooling) combined with liquid exiting the evaporator (0 superheat) is the classic sign of an overcharge."},{id:"refri_166",categoria:"REFRI_COMERCIAL",pregunta:"Si el evaporador est\xE1 muy sucio, \xBFc\xF3mo se comportar\xE1 la presi\xF3n de succi\xF3n?",opciones:["Subir\xE1.","Bajar\xE1 debido a la falta de carga t\xE9rmica (el refrigerante no tiene qu\xE9 absorber).","Se mantendr\xE1 igual.","Subir\xE1 la descarga."],respuesta_correcta:1,explicacion:"Al no haber intercambio, el refrigerante no hierve a la velocidad normal, bajando la presi\xF3n de saturaci\xF3n.",question:"If the evaporator is very dirty, how will the suction pressure behave?",options:["It will rise.","It will drop due to the lack of heat load (the refrigerant has nothing to absorb).","It will stay the same.","Discharge pressure will rise."],explanation:"Without proper heat exchange, the refrigerant does not boil at the normal rate, which lowers the saturation pressure."},{id:"refri_167",categoria:"REFRI_COMERCIAL",pregunta:"\xBFPor qu\xE9 se usa una 'Trampa de Inversi\xF3n' en la l\xEDnea de succi\xF3n cuando el evaporador est\xE1 m\xE1s alto que el compresor?",opciones:["Para que el gas no se escape.","Para evitar que el refrigerante l\xEDquido migre al compresor por gravedad durante las paradas.","Para aumentar la velocidad del gas.","Para que el aceite no suba."],respuesta_correcta:1,explicacion:"La trampa evita que el compresor reciba un ba\xF1o de l\xEDquido apenas arranque.",question:"Why is a P-trap (inverted trap) used in the suction line when the evaporator is located above the compressor?",options:["To prevent refrigerant gas from escaping.","To prevent liquid refrigerant from migrating to the compressor by gravity during off cycles.","To increase gas velocity.","To keep oil from rising."],explanation:"The trap prevents the compressor from receiving a slug of liquid refrigerant the moment it starts up."},{id:"refri_168",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el aceite del compresor est\xE1 negro y huele a quemado (\xE1cido). \xBFCu\xE1l es la prueba de campo obligatoria?",opciones:["Prueba de color.","Prueba de acidez con un kit qu\xEDmico.","Manejarlo con las manos.","Echarle m\xE1s aceite nuevo."],respuesta_correcta:1,explicacion:"La prueba de acidez confirma si el sistema requiere una limpieza profunda con filtros de succi\xF3n especiales antes de quemar otro compresor.",question:"A technician finds that the compressor oil is black and smells burnt (acidic). What is the mandatory field test?",options:["A color test.","An acid test using a chemical test kit.","Handle it with bare hands.","Just add fresh oil."],explanation:"The acid test confirms whether the system requires a thorough cleanup with special suction-line filter driers before another compressor burns out."},{id:"refri_169",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, \xBFqu\xE9 sucede con el Glide t\xE9rmico si se carga el sistema \xFAnicamente con vapor desde un cilindro nuevo?",opciones:["El glide se mantiene igual.","Ocurre fraccionamiento; los componentes m\xE1s vol\xE1tiles salen primero, alterando la composici\xF3n y el rendimiento del refrigerante en el sistema.","El sistema enfr\xEDa m\xE1s r\xE1pido.","El aceite se vuelve m\xE1s denso."],respuesta_correcta:1,explicacion:"Las mezclas serie 400 deben cargarse siempre en estado l\xEDquido. Si se carga vapor, la proporci\xF3n de gases cambia, invalidando la tabla P-T y afectando la eficiencia.",question:"In a system using R-404A, what happens to the temperature glide if the system is charged with vapor only from a new cylinder?",options:["The glide remains the same.","Fractionation occurs; the more volatile components escape first, altering the composition and performance of the refrigerant in the system.","The system cools faster.","The oil becomes denser."],explanation:"400-series blends must always be charged as liquid. Vapor charging changes the gas proportions, invalidating the P-T chart and reducing efficiency."},{id:"refri_170",categoria:"REFRI_COMERCIAL",pregunta:"Al realizar un cambio de compresor, \xBFpor qu\xE9 es cr\xEDtico realizar un triple vac\xEDo con nitr\xF3geno entre cada etapa?",opciones:["Para limpiar las tuber\xEDas de cobre por fuera.","Para arrastrar la humedad y los no condensables de manera m\xE1s efectiva mediante el proceso de diluci\xF3n.","Para que el sistema pese menos.","Para aumentar la presi\xF3n de aceite."],respuesta_correcta:1,explicacion:"El nitr\xF3geno es seco y ayuda a 'empujar' las mol\xE9culas de agua hacia la bomba de vac\xEDo en el siguiente ciclo, logrando niveles de micrones m\xE1s bajos.",question:"When performing a compressor changeout, why is it critical to do a triple evacuation with nitrogen breaks between each stage?",options:["To clean the outside of the copper tubing.","To sweep moisture and non-condensables more effectively through a dilution process.","To make the system lighter.","To increase oil pressure."],explanation:"Dry nitrogen helps push water molecules toward the vacuum pump during the next pull-down, achieving lower micron levels."},{id:"refri_171",categoria:"REFRI_COMERCIAL",pregunta:"Si un t\xE9cnico observa burbujas en el visor de l\xEDquido solo durante los primeros 5 minutos de arranque y luego desaparecen, \xBFqu\xE9 indica?",opciones:["Falta de gas.","Es una condici\xF3n normal de estabilizaci\xF3n mientras la TXV regula y el subenfriamiento se establece.","Filtro deshidratador obstruido.","El compresor est\xE1 perdiendo compresi\xF3n."],respuesta_correcta:1,explicacion:"Al arrancar, las presiones fluct\xFAan. Mientras el condensador no se llene y el l\xEDquido no se enfr\xEDe lo suficiente, es com\xFAn ver burbujas temporales.",question:"If a technician observes bubbles in the sight glass only during the first 5 minutes after startup and they then disappear, what does this indicate?",options:["Low refrigerant charge.","A normal stabilization condition while the TXV regulates and subcooling is established.","Obstructed filter drier.","The compressor is losing compression."],explanation:"During startup, pressures fluctuate. Until the condenser fills and the liquid cools sufficiently, temporary bubbles are common."},{id:"refri_172",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema de media temperatura con R-134a, \xBFcu\xE1l es el sobrecalentamiento ideal medido en la salida del evaporador?",opciones:["0\xB0F a 2\xB0F","8\xB0F a 12\xB0F","20\xB0F a 30\xB0F","40\xB0F a 50\xB0F"],respuesta_correcta:1,explicacion:"Un rango de 8-12\xB0F asegura que el evaporador est\xE9 bien aprovechado sin arriesgar el retorno de l\xEDquido al compresor.",question:"In a medium-temperature system using R-134a, what is the ideal superheat measured at the evaporator outlet?",options:["0 to 2 degrees F","8 to 12 degrees F","20 to 30 degrees F","40 to 50 degrees F"],explanation:"A range of 8-12 degrees F ensures that the evaporator is well utilized without risking liquid return to the compressor."},{id:"refri_173",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de alta es normal, pero la de succi\xF3n es muy alta (ej. 100 PSI para R-404A en congelaci\xF3n) y el compresor no enfr\xEDa. \xBFDiagn\xF3stico?",opciones:["Falta de gas.","Compresor con v\xE1lvulas internas rotas o bypass de platos de v\xE1lvulas.","TXV cerrada.","Condensador muy limpio."],respuesta_correcta:1,explicacion:"Si el compresor no puede crear un diferencial de presi\xF3n (succi\xF3n alta y descarga que no sube), es porque mec\xE1nicamente no est\xE1 bombeando.",question:"A technician finds normal high-side pressure, but the suction pressure is very high (e.g., 100 PSI for R-404A in a freezer application) and the compressor does not cool. What is the diagnosis?",options:["Low refrigerant charge.","Compressor with broken internal valves or a bypassing valve plate.","TXV closed.","Very clean condenser."],explanation:"If the compressor cannot create a pressure differential (high suction and discharge that will not rise), it is not pumping mechanically."},{id:"refri_174",categoria:"REFRI_COMERCIAL",pregunta:"\xBFC\xF3mo afecta una tuber\xEDa de succi\xF3n demasiado grande al sistema?",opciones:["Mejora la eficiencia dr\xE1sticamente.","Reduce la velocidad del gas, impidiendo el retorno correcto del aceite al compresor.","Aumenta la presi\xF3n de descarga.","El compresor consume menos energ\xEDa."],respuesta_correcta:1,explicacion:"La velocidad del gas debe ser suficiente (aprox. 500-700 fpm en tramos horizontales) para arrastrar el aceite. Si el tubo es muy ancho, el aceite se estanca.",question:"How does an oversized suction line affect the system?",options:["It drastically improves efficiency.","It reduces gas velocity, preventing proper oil return to the compressor.","It increases discharge pressure.","The compressor consumes less energy."],explanation:"Gas velocity must be sufficient (approximately 500-700 FPM in horizontal runs) to carry oil along. If the pipe is too large, oil stagnates."},{id:"refri_175",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de la 'V\xE1lvula de Recubrimiento de Aceite' (Oil Regulator) en un sistema m\xFAltiple?",opciones:["Medir la viscosidad del aceite.","Mantener el nivel de aceite correcto en cada c\xE1rter de compresor de forma individual.","Filtrar el aceite sucio.","Enfriar el aceite."],respuesta_correcta:1,explicacion:"Cada compresor tiene necesidades distintas; el regulador abre o cierra la entrada desde el reservorio central seg\xFAn el flotador interno.",question:"What is the function of an oil level regulator in a multiplex (rack) system?",options:["To measure oil viscosity.","To maintain the correct oil level in each compressor crankcase individually.","To filter dirty oil.","To cool the oil."],explanation:"Each compressor has different needs; the regulator opens or closes the inlet from the central oil reservoir based on its internal float level."},{id:"refri_176",categoria:"REFRI_COMERCIAL",pregunta:"Si una v\xE1lvula de expansi\xF3n est\xE1 'sobre-dimensionada' para la carga t\xE9rmica, \xBFqu\xE9 s\xEDntoma presentar\xE1 el sistema?",opciones:["Baja presi\xF3n de succi\xF3n constante.","Hunting (oscilaci\xF3n violenta del sobrecalentamiento y la presi\xF3n de succi\xF3n).","Alta presi\xF3n de descarga.","El compresor no arrancar\xE1."],respuesta_correcta:1,explicacion:"La v\xE1lvula abre demasiado, inunda, luego cierra bruscamente para compensar, y repite el ciclo, sin estabilizarse nunca.",question:"If an expansion valve is oversized for the thermal load, what symptom will the system show?",options:["Consistently low suction pressure.","Hunting (violent oscillation of superheat and suction pressure).","High discharge pressure.","The compressor will not start."],explanation:"The valve opens too much, floods the evaporator, then closes abruptly to compensate, and repeats the cycle without ever stabilizing."},{id:"refri_177",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema de refrigeraci\xF3n, \xBFcu\xE1l es el prop\xF3sito de la 'L\xEDnea de Equilibrio' en un receptor de l\xEDquido?",opciones:["Para que el refrigerante no se mueva.","Para igualar la presi\xF3n entre el condensador y el receptor, facilitando que el l\xEDquido fluya por gravedad.","Para calentar el refrigerante.","Para filtrar el gas."],respuesta_correcta:1,explicacion:"Evita el bloqueo por vapor (vapor lock) en el receptor, asegurando que el l\xEDquido baje libremente desde el condensador.",question:"In a refrigeration system, what is the purpose of the equalizer line on a liquid receiver?",options:["To keep the refrigerant from moving.","To equalize the pressure between the condenser and the receiver so that liquid flows by gravity.","To heat the refrigerant.","To filter the gas."],explanation:"It prevents a vapor lock in the receiver, ensuring that liquid drains freely from the condenser."},{id:"refri_178",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico instala un compresor de 1 HP en un sistema dise\xF1ado para 1/2 HP. \xBFQu\xE9 suceder\xE1?",opciones:["El sistema ser\xE1 m\xE1s eficiente.","La presi\xF3n de succi\xF3n bajar\xE1 demasiado, el evaporador se congelar\xE1 y el compresor podr\xEDa da\xF1arse por bajo flujo de gas.","El condensador se enfriar\xE1 m\xE1s.","No pasa nada, el termostato lo controla."],respuesta_correcta:1,explicacion:"El evaporador no tiene suficiente superficie para alimentar a un compresor tan grande; el equilibrio del sistema se rompe.",question:"A technician installs a 1 HP compressor in a system designed for 1/2 HP. What will happen?",options:["The system will be more efficient.","Suction pressure will drop too low, the evaporator will freeze up, and the compressor may be damaged from low gas flow.","The condenser will run cooler.","Nothing will happen; the thermostat controls everything."],explanation:"The evaporator does not have enough surface area to feed a compressor that large; the system balance is broken."},{id:"refri_179",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema de refrigeraci\xF3n comercial presenta 'Acidez' en el aceite. \xBFCu\xE1l es el procedimiento de correcci\xF3n?",opciones:["Solo cambiar el aceite.","Cambiar aceite, instalar filtros deshidratadores de succi\xF3n de alta capacidad (anti-\xE1cido) y realizar pruebas peri\xF3dicas hasta que sea neutro.","A\xF1adir agua destilada.","Subir la temperatura de descarga."],respuesta_correcta:1,explicacion:"El \xE1cido se queda atrapado en todo el sistema. Los filtros de succi\xF3n son vitales para proteger el compresor nuevo de los residuos que circulan.",question:"A commercial refrigeration system has acidic oil. What is the corrective procedure?",options:["Just change the oil.","Change the oil, install high-capacity suction-line filter driers (acid-removing type), and perform periodic acid tests until the oil is neutral.","Add distilled water.","Increase the discharge temperature."],explanation:"Acid remains trapped throughout the entire system. Suction-line filter driers are essential to protect the new compressor from circulating residues."},{id:"refri_180",categoria:"REFRI_COMERCIAL",pregunta:"Un evaporador de tiro forzado (con ventilador) tiene las aletas dobladas en un 50% de su superficie. \xBFCu\xE1l es el efecto?",opciones:["Aumenta la velocidad del aire.","Reduce dr\xE1sticamente la transferencia de calor y causa una ca\xEDda de presi\xF3n excesiva del lado del aire.","Enfr\xEDa mejor por turbulencia.","No afecta si el ventilador es potente."],respuesta_correcta:1,explicacion:"El aire no puede pasar a trav\xE9s de las aletas dobladas; el \xE1rea de intercambio efectiva se reduce a la mitad.",question:"A forced-air evaporator has bent fins over 50% of its surface. What is the effect?",options:["Air velocity increases.","Heat transfer is drastically reduced and excessive air-side pressure drop occurs.","It cools better due to turbulence.","It does not matter if the fan is powerful."],explanation:"Air cannot pass through the bent fins; the effective heat exchange area is reduced by half."},{id:"refri_181",categoria:"REFRI_COMERCIAL",pregunta:"Si la v\xE1lvula de expansi\xF3n est\xE1 ajustada con un sobrecalentamiento muy alto (ej. 25\xB0F en el evaporador), \xBFqu\xE9 sucede con la capacidad del sistema?",opciones:["La capacidad aumenta.","La capacidad disminuye porque gran parte del evaporador se usa para calentar gas en lugar de evaporar l\xEDquido.","La capacidad es la misma pero ahorra energ\xEDa.","La presi\xF3n de succi\xF3n sube."],respuesta_correcta:1,explicacion:"Un superheat alto significa que el evaporador est\xE1 'hambriento' (starved). Menos superficie h\xFAmeda equivale a menos extracci\xF3n de calor.",question:"If the expansion valve is adjusted with a very high superheat (e.g., 25 degrees F at the evaporator), what happens to system capacity?",options:["Capacity increases.","Capacity decreases because a large portion of the evaporator is used for superheating gas instead of evaporating liquid.","Capacity stays the same but energy is saved.","Suction pressure rises."],explanation:"High superheat means the evaporator is starved. Less wetted surface equals less heat extraction."},{id:"refri_182",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-22, la presi\xF3n de descarga es 250 PSI y la temperatura de la tuber\xEDa de l\xEDquido es 105\xB0F. \xBFCu\xE1l es el subenfriamiento? (Dato: R-22 a 250 PSI = 117\xB0F)",opciones:["0\xB0F","12\xB0F","117\xB0F","250\xB0F"],respuesta_correcta:1,explicacion:"Subcooling = Temp. Saturaci\xF3n (117) - Temp. L\xEDquido (105) = 12\xB0F.",question:"In a system using R-22, the discharge pressure is 250 PSI and the liquid line temperature is 105 degrees F. What is the subcooling? (Given: R-22 at 250 PSI = 117 degrees F)",options:["0 degrees F","12 degrees F","117 degrees F","250 degrees F"],explanation:"Subcooling = Saturation Temperature (117) - Liquid Temperature (105) = 12 degrees F."},{id:"refri_183",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el compresor est\xE1 muy caliente y el gas de succi\xF3n llega a 80\xB0F en un sistema de baja temperatura. \xBFCu\xE1l es la causa?",opciones:["Exceso de gas.","Falta de aislamiento en la l\xEDnea de succi\xF3n o tuber\xEDa demasiado larga expuesta al calor.","Evaporador congelado.","Filtro de aire sucio."],respuesta_correcta:1,explicacion:"El gas de succi\xF3n es lo que enfr\xEDa el motor del compresor. Si llega muy caliente, el motor se sobrecalienta y el protector t\xE9rmico se dispara.",question:"A technician finds that the compressor is very hot and the suction gas arrives at 80 degrees F in a low-temperature system. What is the cause?",options:["Overcharge.","Lack of insulation on the suction line or excessively long tubing exposed to heat.","Frozen evaporator.","Dirty air filter."],explanation:"The suction gas is what cools the compressor motor. If it arrives too hot, the motor overheats and the thermal overload trips."},{id:"refri_184",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR)?",opciones:["Mantener la presi\xF3n del c\xE1rter alta.","Evitar que el motor del compresor se sobrecargue durante un arranque en caliente limitando la presi\xF3n de succi\xF3n m\xE1xima.","Aumentar el flujo de aceite.","Controlar el desescarche."],respuesta_correcta:1,explicacion:"Al arrancar despu\xE9s de un defrost, la presi\xF3n es muy alta. La CPR se cierra para que el compresor no 'coma' m\xE1s gas del que su motor puede manejar.",question:"What is the function of a crankcase pressure regulator (CPR)?",options:["To keep crankcase pressure high.","To prevent motor overload during a hot startup by limiting the maximum suction pressure.","To increase oil flow.","To control defrost."],explanation:"When starting after a defrost cycle, the evaporator pressure is very high. The CPR throttles back so the compressor does not draw more gas than its motor can handle."},{id:"refri_185",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico mide una ca\xEDda de presi\xF3n de 15 PSI a trav\xE9s de un filtro deshidratador. \xBFQu\xE9 debe hacer?",opciones:["Nada, es normal.","Reemplazar el filtro inmediatamente ya que est\xE1 obstruido.","Aumentar la carga de gas.","Limpiar el condensador."],respuesta_correcta:1,explicacion:"Una ca\xEDda de presi\xF3n tan alta indica suciedad acumulada. Esto genera flash gas y p\xE9rdida de eficiencia total.",question:"A technician measures a 15 PSI pressure drop across a filter drier. What should be done?",options:["Nothing; that is normal.","Replace the filter drier immediately, as it is obstructed.","Add more refrigerant.","Clean the condenser."],explanation:"Such a high pressure drop indicates accumulated debris. This creates flash gas and total loss of efficiency."},{id:"refri_186",categoria:"REFRI_COMERCIAL",pregunta:"Si el aceite POE se deja expuesto al aire por m\xE1s de 15 minutos, \xBFqu\xE9 sucede?",opciones:["Se evapora.","Absorbe humedad del aire (higroscop\xEDa) y crea una uni\xF3n qu\xEDmica que no se puede eliminar solo con vac\xEDo.","Se vuelve negro.","Se vuelve m\xE1s eficiente."],respuesta_correcta:1,explicacion:"El aceite POE reacciona con el agua formando \xE1cidos y alcoholes. Una vez contaminado, suele requerir el cambio total del aceite.",question:"If POE oil is left exposed to the open air for more than 15 minutes, what happens?",options:["It evaporates.","It absorbs moisture from the air (hygroscopy), forming a chemical bond that cannot be removed by vacuum alone.","It turns black.","It becomes more efficient."],explanation:"POE oil reacts with water to form acids and alcohols. Once contaminated, a complete oil change is usually required."},{id:"refri_187",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Espaciado de Aletas' (Fins per inch) y por qu\xE9 es menor en evaporadores de baja temperatura?",opciones:["Para que se vean mejor.","Para permitir que el hielo se acumule por m\xE1s tiempo sin bloquear el flujo de aire entre desescarches.","Para ahorrar aluminio.","Para que el aire pase m\xE1s r\xE1pido."],respuesta_correcta:1,explicacion:"Un evaporador de congelados con aletas muy juntas se bloquear\xEDa de escarcha en pocos minutos.",question:"What is fin spacing (fins per inch) and why is it wider in low-temperature evaporators?",options:["For appearance.","To allow frost to accumulate for a longer time without blocking airflow between defrost cycles.","To save aluminum.","To move air faster."],explanation:"A freezer evaporator with closely spaced fins would become blocked with frost within minutes."},{id:"refri_188",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico utiliza un soplete para calentar un cilindro de refrigerante y aumentar la presi\xF3n de carga. \xBFEs esto aceptable?",opciones:["S\xED, si tiene prisa.","No, es extremadamente peligroso y puede causar la explosi\xF3n del cilindro; se debe usar una manta t\xE9rmica o agua tibia.","S\xED, pero solo si el cilindro es nuevo.","Solo si el gas es R-22."],respuesta_correcta:1,explicacion:"El calor directo debilita el metal del cilindro y crea presiones localizadas que superan la v\xE1lvula de seguridad.",question:"A technician uses a torch to heat a refrigerant cylinder to increase charging pressure. Is this acceptable?",options:["Yes, if in a hurry.","No, it is extremely dangerous and can cause the cylinder to explode; a heating blanket or warm water should be used instead.","Yes, but only if the cylinder is new.","Only if the refrigerant is R-22."],explanation:"Direct heat weakens the cylinder metal and creates localized pressures that can exceed the relief valve capacity."},{id:"refri_189",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 30\xB0F en la salida del evaporador de un congelador?",opciones:["Exceso de gas.","Falta de refrigerante o TXV muy cerrada (evaporador hambriento).","Termostato roto.","Compresor muy fr\xEDo."],respuesta_correcta:1,explicacion:"El refrigerante se evapora muy pronto y el resto del serpent\xEDn solo calienta el gas, perdiendo capacidad de enfriamiento.",question:"What does a superheat of 30 degrees F at the evaporator outlet of a freezer indicate?",options:["Overcharge.","Low refrigerant charge or a TXV that is too restricted (starved evaporator).","Broken thermostat.","Compressor too cold."],explanation:"The refrigerant evaporates too early and the remainder of the coil only superheats gas, losing cooling capacity."},{id:"refri_190",categoria:"REFRI_COMERCIAL",pregunta:"Un condensador tiene aire atrapado. \xBFC\xF3mo afecta esto a la eficiencia energ\xE9tica (COP)?",opciones:["Lo aumenta.","Lo disminuye dr\xE1sticamente ya que el compresor trabaja m\xE1s contra una presi\xF3n de alta mayor.","No lo afecta.","El COP no depende de la presi\xF3n."],respuesta_correcta:1,explicacion:"A mayor presi\xF3n de descarga, mayor trabajo del motor y menor efecto refrigerante; el COP cae.",question:"A condenser has trapped air (non-condensables). How does this affect the energy efficiency (COP)?",options:["It increases it.","It decreases it drastically because the compressor must work harder against a higher head pressure.","It does not affect it.","COP does not depend on pressure."],explanation:"Higher discharge pressure means more compressor work and less net refrigerating effect; the COP drops."},{id:"refri_191",categoria:"REFRI_COMERCIAL",pregunta:"Si el motor del ventilador del evaporador gira m\xE1s lento de lo debido por un capacitor gastado, \xBFqu\xE9 sucede?",opciones:["La presi\xF3n de succi\xF3n sube.","La presi\xF3n de succi\xF3n baja y el evaporador puede congelarse.","La presi\xF3n de descarga sube.","El compresor consume menos amperaje."],respuesta_correcta:1,explicacion:"Menos aire significa menos calor entregado al refrigerante. La presi\xF3n cae y el hielo empieza a formarse.",question:"If the evaporator fan motor runs slower than rated because of a weak capacitor, what happens?",options:["Suction pressure rises.","Suction pressure drops and the evaporator may freeze up.","Discharge pressure rises.","The compressor draws less amperage."],explanation:"Less air means less heat delivered to the refrigerant. The pressure drops and ice starts to form."},{id:"refri_192",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula 'KVR' (Reguladora de Presi\xF3n de Condensaci\xF3n)?",opciones:["Evitar que la presi\xF3n de alta suba mucho.","Mantener una presi\xF3n m\xEDnima de condensaci\xF3n en climas fr\xEDos para que la TXV funcione correctamente.","Controlar la velocidad del ventilador.","Separar el aceite."],respuesta_correcta:1,explicacion:"En invierno, el condensador enfr\xEDa demasiado. La KVR restringe el flujo para inundar el condensador y subir la presi\xF3n artificialmente.",question:"What is the function of a head pressure control valve (KVR - Condenser Pressure Regulator)?",options:["To prevent high-side pressure from rising too much.","To maintain a minimum condensing pressure in cold climates so the TXV operates correctly.","To control fan speed.","To separate oil."],explanation:"In winter, the condenser overcools. The KVR restricts flow to flood the condenser and artificially raise the head pressure."},{id:"refri_193",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el acumulador de succi\xF3n est\xE1 cubierto de escarcha gruesa. \xBFQu\xE9 indica?",opciones:["Funcionamiento perfecto.","Retorno masivo de l\xEDquido desde el evaporador (Floodback).","Falta de gas.","Ambiente muy h\xFAmedo."],respuesta_correcta:1,explicacion:"El acumulador est\xE1 hirviendo el l\xEDquido sobrante para proteger al compresor. Es una se\xF1al de que la TXV o el sistema de expansi\xF3n est\xE1 fallando.",question:"A technician finds that the suction accumulator is covered in heavy frost. What does this indicate?",options:["Perfect operation.","Massive liquid floodback from the evaporator.","Low refrigerant charge.","Very humid ambient conditions."],explanation:"The accumulator is boiling off excess liquid to protect the compressor. This is a sign that the TXV or expansion device is malfunctioning."},{id:"refri_194",categoria:"REFRI_COMERCIAL",pregunta:"En un compresor Scroll, \xBFcu\xE1l es la funci\xF3n de la v\xE1lvula check interna ubicada en la descarga?",opciones:["Regular el flujo de aceite.","Evitar que el compresor gire en reversa al apagarse debido al diferencial de presi\xF3n.","Aumentar la presi\xF3n de succi\xF3n.","Filtrar impurezas met\xE1licas."],respuesta_correcta:1,explicacion:"Sin esta v\xE1lvula, el gas de alta presi\xF3n regresar\xEDa a las espirales al apagar el motor, haciendo que el Scroll gire hacia atr\xE1s, lo que puede causar ruido y da\xF1os mec\xE1nicos.",question:"In a scroll compressor, what is the function of the internal check valve at the discharge?",options:["To regulate oil flow.","To prevent the compressor from spinning in reverse when it shuts off due to the pressure differential.","To increase suction pressure.","To filter metallic debris."],explanation:"Without this valve, high-pressure gas would flow back into the scrolls when the motor stops, causing the scroll to spin backwards, which can produce noise and mechanical damage."},{id:"refri_195",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la principal ventaja de un condensador microcanal (Microchannel) sobre uno de tubo y aleta?",opciones:["Es m\xE1s f\xE1cil de reparar.","Requiere una carga de refrigerante significativamente menor (hasta un 40% menos) y ofrece mejor transferencia de calor.","No se ensucia nunca.","Es m\xE1s pesado y resistente."],respuesta_correcta:1,explicacion:"El dise\xF1o de canales planos y peque\xF1os aumenta la superficie de contacto y reduce el volumen interno muerto del sistema.",question:"What is the primary advantage of a microchannel condenser over a conventional tube-and-fin condenser?",options:["It is easier to repair.","It requires a significantly smaller refrigerant charge (up to 40% less) and offers better heat transfer.","It never gets dirty.","It is heavier and more rugged."],explanation:"The flat, small-channel design increases the contact surface and reduces the internal dead volume of the system."},{id:"refri_196",categoria:"REFRI_COMERCIAL",pregunta:"Si el ventilador del evaporador est\xE1 invertido (sopla hacia atr\xE1s), \xBFqu\xE9 sucede con el sobrecalentamiento?",opciones:["Se mantiene estable.","Aumenta debido a que el flujo de aire es ineficiente y no hay carga t\xE9rmica suficiente en las aletas.","Disminuye dr\xE1sticamente, arriesgando el retorno de l\xEDquido.","La TXV se cierra sola."],respuesta_correcta:2,explicacion:"Al no pasar aire correctamente por el serpent\xEDn, el refrigerante no se evapora del todo. El superheat cae y el l\xEDquido llega al compresor.",question:"If the evaporator fan is wired in reverse (blowing backwards), what happens to the superheat?",options:["It stays stable.","It increases because the airflow is inefficient and there is not enough heat load on the fins.","It drops drastically, risking liquid floodback to the compressor.","The TXV closes on its own."],explanation:"Without proper air passing over the coil, the refrigerant does not fully evaporate. Superheat drops and liquid reaches the compressor."},{id:"refri_197",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el compresor vibra excesivamente pero las presiones son normales. Los resortes internos del compresor herm\xE9tico podr\xEDan estar rotos. \xBFC\xF3mo se confirma?",opciones:["Midiendo el amperaje.","Por el sonido met\xE1lico de impacto al apagar el equipo (clunk) y la vibraci\xF3n f\xEDsica externa.","A\xF1adiendo aceite.","Cambiando el capacitor."],respuesta_correcta:1,explicacion:"Si el bloque motor se desprende de sus resortes internos, golpea contra la carcasa met\xE1lica, especialmente en los arranques y paradas.",question:"A technician finds that the compressor vibrates excessively but pressures are normal. The internal springs of the hermetic compressor may be broken. How is this confirmed?",options:["By measuring amperage.","By the metallic clunk sound when the unit shuts off and the physical vibration transmitted externally.","By adding oil.","By changing the capacitor."],explanation:"If the motor block detaches from its internal springs, it bangs against the metal shell, especially during starts and stops."},{id:"refri_198",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico instala una TXV de R-22 en un sistema con R-404A. \xBFQu\xE9 suceder\xE1?",opciones:["Funcionar\xE1 pero consumir\xE1 m\xE1s luz.","La TXV no controlar\xE1 correctamente (inundar\xE1 o cerrar\xE1 de m\xE1s) porque la presi\xF3n del elemento de poder no coincide con la presi\xF3n del refrigerante.","Se quemar\xE1 el compresor instant\xE1neamente.","El filtro se tapar\xE1."],respuesta_correcta:1,explicacion:"Cada TXV est\xE1 calibrada para una curva P-T espec\xEDfica. Usar una v\xE1lvula de otro gas destruye el control del sobrecalentamiento.",question:"A technician installs a TXV designed for R-22 on a system using R-404A. What will happen?",options:["It will work but consume more electricity.","The TXV will not control properly (it will either flood or starve) because the power element charge does not match the refrigerant's P-T curve.","The compressor will burn out instantly.","The filter will clog."],explanation:"Each TXV is calibrated for a specific P-T curve. Using a valve meant for a different gas destroys superheat control."},{id:"refri_199",categoria:"REFRI_COMERCIAL",pregunta:"Mides un subenfriamiento de 25\xB0F en un sistema comercial. \xBFCu\xE1l es el problema?",opciones:["Falta de refrigerante.","Exceso de refrigerante; el l\xEDquido est\xE1 'respaldado' en el condensador ocupando espacio de intercambio.","Compresor muy eficiente.","Ventilador del condensador muy lento."],respuesta_correcta:1,explicacion:"Un subcooling normal es de 5-12\xB0F. 25\xB0F indica que el condensador est\xE1 lleno de l\xEDquido, lo que sube la presi\xF3n de descarga innecesariamente.",question:"You measure a subcooling of 25 degrees F in a commercial system. What is the problem?",options:["Low refrigerant charge.","Overcharge of refrigerant; liquid is backed up in the condenser, occupying heat exchange area.","Highly efficient compressor.","Condenser fan running too slowly."],explanation:"Normal subcooling is 5-12 degrees F. A reading of 25 degrees F indicates the condenser is full of liquid, which unnecessarily raises the discharge pressure."},{id:"refri_200",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con receptor de l\xEDquido, \xBFc\xF3mo se asegura el t\xE9cnico de que el sistema tiene la carga correcta?",opciones:["Por sobrecalentamiento solamente.","Asegurando que el visor de l\xEDquido est\xE9 claro (sin burbujas) y que el receptor tenga un nivel adecuado (aprox 20-30% en carga completa).","Por el amperaje del motor.","Pesando el cilindro y metiendo lo que diga la placa."],respuesta_correcta:1,explicacion:"En sistemas con receptor, el subcooling no es un indicador confiable porque el receptor 'esconde' el exceso de gas.",question:"In a system with a liquid receiver, how does the technician verify that the system has the correct charge?",options:["By superheat only.","By confirming that the sight glass is clear (no bubbles) and the receiver has an adequate level (approximately 20-30% at full load).","By the motor amperage.","By weighing the cylinder and charging the nameplate amount."],explanation:"In systems with a receiver, subcooling is not a reliable indicator because the receiver masks excess charge."},{id:"refri_201",categoria:"REFRI_COMERCIAL",pregunta:"Un compresor de baja temperatura (Freezer) tiene la culata (head) extremadamente caliente, pero la tuber\xEDa de succi\xF3n est\xE1 fresca. \xBFCausa probable?",opciones:["Bajo sobrecalentamiento.","Alta relaci\xF3n de compresi\xF3n debido a una presi\xF3n de descarga muy alta o succi\xF3n muy baja.","Falta de aceite.","Demasiado gas."],respuesta_correcta:1,explicacion:"El calor de la compresi\xF3n es excesivo. Esto sucede cuando el compresor tiene que 'esforzarse' demasiado para subir la presi\xF3n desde un nivel muy bajo.",question:"A low-temperature (freezer) compressor has an extremely hot cylinder head, but the suction line is cool. What is the probable cause?",options:["Low superheat.","High compression ratio due to very high discharge pressure or very low suction pressure.","Low oil level.","Overcharge."],explanation:"The heat of compression is excessive. This happens when the compressor must work too hard to raise the pressure from a very low suction level."},{id:"refri_202",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, si el sobrecalentamiento es de 15\xB0F pero el evaporador est\xE1 lleno de escarcha, \xBFqu\xE9 sucede?",opciones:["Falta de gas.","Falla en el flujo de aire o ciclo de deshielo deficiente; la escarcha act\xFAa como aislante y enga\xF1a a la TXV.","TXV muy abierta.","Compresor muy grande."],respuesta_correcta:1,explicacion:"El hielo impide que el calor del aire llegue al refrigerante. La TXV trata de ajustar, pero el sistema pierde eficiencia totalmente.",question:"In a system using R-404A, the superheat is 15 degrees F but the evaporator is heavily frosted. What is happening?",options:["Low refrigerant charge.","Airflow failure or deficient defrost cycle; the frost acts as an insulator and misleads the TXV.","TXV too far open.","Oversized compressor."],explanation:"Ice prevents the heat in the air from reaching the refrigerant. The TXV tries to compensate, but the system loses efficiency entirely."},{id:"refri_203",categoria:"REFRI_COMERCIAL",pregunta:"Un controlador digital marca 'HiP' (High Pressure). El t\xE9cnico limpia el condensador pero el error sigue. Al revisar, el ventilador del condensador gira lento. \xBFQu\xE9 mide para confirmar?",opciones:["El amperaje del motor.","La capacitancia del capacitor del ventilador y el voltaje de alimentaci\xF3n.","La presi\xF3n de succi\xF3n.","La temperatura del evaporador."],respuesta_correcta:1,explicacion:"Un capacitor d\xE9bil hace que el motor pierda RPM, bajando el flujo de aire y subiendo la presi\xF3n de alta.",question:"A digital controller displays a 'HiP' (High Pressure) alarm. The technician cleans the condenser but the alarm persists. Upon inspection, the condenser fan is spinning slowly. What should be measured to confirm?",options:["The motor amperage.","The capacitance of the fan motor capacitor and the supply voltage.","The suction pressure.","The evaporator temperature."],explanation:"A weak capacitor causes the motor to lose RPM, reducing airflow and raising the high-side pressure."},{id:"refri_204",categoria:"REFRI_COMERCIAL",pregunta:"Si una TXV con igualaci\xF3n externa no tiene conectada la l\xEDnea de igualaci\xF3n (est\xE1 tapada), \xBFqu\xE9 har\xE1 la v\xE1lvula?",opciones:["Se quedar\xE1 abierta al 100%.","Tender\xE1 a cerrarse casi por completo, matando de hambre (starving) al evaporador.","No afecta en nada.","Explotar\xE1 por presi\xF3n."],respuesta_correcta:1,explicacion:"La presi\xF3n debajo del diafragma ser\xE1 la de entrada (alta) en lugar de la de salida (baja), empujando la aguja hacia la posici\xF3n cerrada.",question:"If a TXV with external equalization does not have the equalization line connected (it is capped off), what will the valve do?",options:["It will stay 100% open.","It will tend to close almost completely, starving the evaporator.","It will not be affected at all.","It will burst from pressure."],explanation:"The pressure under the diaphragm will be the inlet (high) pressure instead of the outlet (low) pressure, pushing the needle toward the closed position."},{id:"refri_205",categoria:"REFRI_COMERCIAL",pregunta:"Al cargar un sistema por la l\xEDnea de succi\xF3n (compresor encendido), \xBFpor qu\xE9 se debe hacer lentamente?",opciones:["Para no gastar gas.","Para evitar que el l\xEDquido llegue a los cilindros del compresor y cause da\xF1os mec\xE1nicos por incompresibilidad.","Para que el filtro no se congele.","Para que el motor no se esfuerce."],respuesta_correcta:1,explicacion:"El compresor es una bomba de vapor. Si le entra l\xEDquido de golpe, las v\xE1lvulas o los pistones se rompen.",question:"When charging a system through the suction line (compressor running), why must it be done slowly?",options:["To conserve gas.","To prevent liquid from reaching the compressor cylinders and causing mechanical damage from liquid slugging.","To keep the filter from freezing.","To reduce motor strain."],explanation:"The compressor is a vapor pump. If liquid enters suddenly, the valves or pistons can break."},{id:"refri_206",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 efecto tiene una v\xE1lvula de expansi\xF3n demasiado peque\xF1a para el sistema?",opciones:["Bajo sobrecalentamiento.","Alto sobrecalentamiento constante y baja presi\xF3n de succi\xF3n (evaporador hambriento).","Alta presi\xF3n de descarga.","Bajo amperaje del ventilador."],respuesta_correcta:1,explicacion:"La v\xE1lvula no puede proveer suficiente refrigerante para llenar el evaporador, limitando la capacidad de enfriamiento.",question:"What effect does an undersized expansion valve have on the system?",options:["Low superheat.","Consistently high superheat and low suction pressure (starved evaporator).","High discharge pressure.","Low fan motor amperage."],explanation:"The valve cannot supply enough refrigerant to fill the evaporator, limiting the cooling capacity."},{id:"refri_207",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 significa un 'Sistema Inundado' en refrigeraci\xF3n comercial?",opciones:["Que se llen\xF3 de agua de lluvia.","Un sistema donde el evaporador est\xE1 lleno de refrigerante l\xEDquido y el control de nivel regula la entrada.","Un sistema con exceso de carga.","Un sistema que gotea aceite."],respuesta_correcta:1,explicacion:"Se usa para maximizar la eficiencia en sistemas grandes, manteniendo mojada toda la superficie de intercambio.",question:"What does a 'flooded system' mean in commercial refrigeration?",options:["The system filled with rainwater.","A system where the evaporator is full of liquid refrigerant and a level control regulates the feed.","A system with excess charge.","A system that leaks oil."],explanation:"It is used to maximize efficiency in large systems by keeping the entire heat exchange surface wetted."},{id:"refri_208",categoria:"REFRI_COMERCIAL",pregunta:"Si un t\xE9cnico encuentra que el aceite en el visor del compresor tiene espuma excesiva durante el funcionamiento, \xBFqu\xE9 sospecha?",opciones:["Que el aceite es de buena calidad.","Presencia de refrigerante l\xEDquido mezclado con el aceite (migraci\xF3n o inundaci\xF3n).","Que el filtro de aceite est\xE1 tapado.","Baja presi\xF3n de succi\xF3n."],respuesta_correcta:1,explicacion:"Al bajar la presi\xF3n en el c\xE1rter, el refrigerante disuelto en el aceite hierve bruscamente, creando espuma que no lubrica bien.",question:"If a technician observes excessive foaming in the compressor oil sight glass during operation, what is the concern?",options:["The oil is of good quality.","Liquid refrigerant is mixed with the oil (migration or flooding).","The oil filter is clogged.","Low suction pressure."],explanation:"As crankcase pressure drops, the refrigerant dissolved in the oil boils violently, creating foam that does not lubricate properly."},{id:"refri_209",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema tiene una temperatura de saturaci\xF3n en el condensador de 110\xB0F y la temperatura ambiente es de 95\xB0F. \xBFEs este un 'Split' de condensador normal?",opciones:["No, es muy bajo.","S\xED, un split de 10-30\xB0F sobre la temperatura ambiente es est\xE1ndar en sistemas enfriados por aire.","No, la presi\xF3n deber\xEDa ser mayor.","Depende de la humedad."],respuesta_correcta:1,explicacion:"El split (TD del condensador) indica qu\xE9 tan bien se est\xE1 rechazando el calor. 15\xB0F sobre el ambiente es un valor saludable.",question:"A system has a condensing saturation temperature of 110 degrees F and the ambient temperature is 95 degrees F. Is this a normal condenser split?",options:["No, it is too low.","Yes, a split of 10-30 degrees F above ambient is standard for air-cooled systems.","No, the pressure should be higher.","It depends on humidity."],explanation:"The split (condenser TD) indicates how well heat is being rejected. 15 degrees F above ambient is a healthy value."},{id:"refri_210",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede con la capacidad de un compresor si la temperatura de succi\xF3n aumenta (gas m\xE1s caliente/menos denso)?",opciones:["La capacidad aumenta.","La capacidad disminuye porque el compresor mueve menos masa de refrigerante por cada embolada.","Se mantiene igual.","El compresor enfr\xEDa m\xE1s el aceite."],respuesta_correcta:1,explicacion:"La refrigeraci\xF3n es un juego de masa, no de volumen. Gas caliente ocupa m\xE1s espacio pero pesa menos; el compresor rinde menos.",question:"What happens to compressor capacity if the suction temperature increases (hotter, less dense gas)?",options:["Capacity increases.","Capacity decreases because the compressor moves less refrigerant mass per stroke.","It stays the same.","The compressor cools its oil better."],explanation:"Refrigeration is a game of mass, not volume. Hot gas occupies more space but weighs less; the compressor delivers less."},{id:"refri_211",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema de refrigeraci\xF3n usa R-448A. \xBFC\xF3mo se debe leer el sobrecalentamiento?",opciones:["Usando el punto de burbuja (Bubble point).","Usando el punto de roc\xEDo (Dew point) debido al deslizamiento t\xE9rmico (glide).","No importa, la tabla es una sola.","Solo con el term\xF3metro de succi\xF3n."],respuesta_correcta:1,explicacion:"En mezclas con glide, el sobrecalentamiento se calcula con la temperatura de roc\xEDo (vapor saturado).",question:"A system uses R-448A. How should the superheat be read?",options:["Using the bubble point.","Using the dew point due to the temperature glide.","It does not matter; there is only one chart.","Only with the suction thermometer."],explanation:"In blends with glide, superheat is calculated using the dew point temperature (saturated vapor)."},{id:"refri_212",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de evaporaci\xF3n (EPR)?",opciones:["Aumentar la presi\xF3n de descarga.","Mantener una presi\xF3n m\xEDnima en un evaporador espec\xEDfico dentro de un sistema con varios evaporadores a distintas temperaturas.","Controlar el subenfriamiento.","Detener el compresor."],respuesta_correcta:1,explicacion:"Evita que un evaporador de media temperatura (ej. verduras) se congele cuando el rack trabaja para un evaporador de baja (ej. helados).",question:"What is the function of an evaporator pressure regulator (EPR)?",options:["To increase discharge pressure.","To maintain a minimum pressure in a specific evaporator within a system that has multiple evaporators at different temperatures.","To control subcooling.","To stop the compressor."],explanation:"It prevents a medium-temperature evaporator (e.g., produce) from freezing when the rack is pulling down for a low-temperature evaporator (e.g., ice cream)."},{id:"refri_213",categoria:"REFRI_COMERCIAL",pregunta:"Si el aceite del c\xE1rter est\xE1 muy fr\xEDo, el refrigerante se condensa en \xE9l. Al arrancar, \xBFqu\xE9 fen\xF3meno ocurre?",opciones:["Arranque suave.","Efervescencia (Foaming) que puede causar que la bomba de aceite succione vapor en lugar de l\xEDquido, fallando la lubricaci\xF3n.","El compresor enfr\xEDa m\xE1s r\xE1pido.","Se limpia el filtro de succi\xF3n."],respuesta_correcta:1,explicacion:"El refrigerante l\xEDquido al fondo del c\xE1rter se evapora explosivamente al bajar la presi\xF3n del arranque, creando espuma que no lubrica.",question:"If the crankcase oil is very cold, refrigerant condenses into it. When the compressor starts, what phenomenon occurs?",options:["A smooth start.","Foaming (effervescence) that can cause the oil pump to draw vapor instead of liquid, resulting in lubrication failure.","The compressor cools faster.","The suction-line filter cleans itself."],explanation:"The liquid refrigerant at the bottom of the crankcase boils explosively when the pressure drops at startup, creating foam that cannot lubricate."},{id:"refri_214",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede si el bulbo de la TXV se instala en un tramo de tuber\xEDa donde el aceite se acumula (trampa)?",opciones:["La v\xE1lvula lee la temperatura exacta.","La lectura ser\xE1 err\xE1tica y lenta, ya que el aceite act\xFAa como un aislante t\xE9rmico entre el gas y el bulbo.","La v\xE1lvula se abre al 100% siempre.","La v\xE1lvula se rompe."],respuesta_correcta:1,explicacion:"El bulbo debe sentir la temperatura del gas de succi\xF3n; el aceite estancado tiene una inercia t\xE9rmica que falsea el control.",question:"What happens if the TXV sensing bulb is installed at a point where oil accumulates (in a trap)?",options:["The valve reads the exact temperature.","The reading will be erratic and slow because the oil acts as a thermal insulator between the gas and the bulb.","The valve will open 100% at all times.","The valve will break."],explanation:"The bulb must sense the suction gas temperature; stagnant oil has thermal inertia that distorts the control signal."},{id:"refri_215",categoria:"REFRI_COMERCIAL",pregunta:"Si el visor de l\xEDquido muestra un color 'verde' pero hay burbujas constantes, el t\xE9cnico debe:",opciones:["Cambiar el filtro.","A\xF1adir refrigerante; el verde indica que no hay humedad, pero las burbujas indican falta de carga o flash gas.","A\xF1adir aceite.","Limpiar el evaporador."],respuesta_correcta:1,explicacion:"El color solo mide humedad. El estado f\xEDsico (burbujas) mide la calidad de la condensaci\xF3n o la cantidad de gas.",question:"If the sight glass shows a green color but has constant bubbles, the technician should:",options:["Change the filter.","Add refrigerant; the green color means there is no moisture, but the bubbles indicate a low charge or flash gas.","Add oil.","Clean the evaporator."],explanation:"The color only measures moisture. The physical state (bubbles) indicates the quality of condensation or the amount of charge."},{id:"refri_216",categoria:"REFRI_COMERCIAL",pregunta:"\xBFC\xF3mo se calcula el sobrecalentamiento total (Total Superheat)?",opciones:["Temp. entrada evaporador - Temp. salida evaporador.","Temp. tuber\xEDa de succi\xF3n (a 6' del compresor) - Temp. de saturaci\xF3n de baja.","Presi\xF3n de alta - Presi\xF3n de baja.","Amperaje / Voltaje."],respuesta_correcta:1,explicacion:"Mide cu\xE1nto calor gan\xF3 el gas desde el evaporador hasta el compresor; es vital para asegurar que el motor se enfr\xEDe y no reciba l\xEDquido.",question:"How is total superheat calculated?",options:["Evaporator inlet temperature minus evaporator outlet temperature.","Suction line temperature (measured 6 inches from the compressor) minus the low-side saturation temperature.","High pressure minus low pressure.","Amperage divided by voltage."],explanation:"It measures how much heat the gas gained from the evaporator to the compressor; it is vital for ensuring the motor is cooled and no liquid enters."},{id:"refri_217",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es un 'Intercambiador de Placas' y por qu\xE9 se usa en refrigeraci\xF3n comercial?",opciones:["Un tipo de filtro.","Un intercambiador muy compacto y eficiente que usa placas met\xE1licas soldadas para transferir calor entre dos fluidos.","Una placa de hielo.","Un control de presi\xF3n."],respuesta_correcta:1,explicacion:"Ofrece una transferencia t\xE9rmica superior en un espacio muy reducido, ideal para enfriadores de leche o sistemas de glicol.",question:"What is a plate heat exchanger and why is it used in commercial refrigeration?",options:["A type of filter.","A very compact and efficient exchanger that uses brazed metal plates to transfer heat between two fluids.","A plate of ice.","A pressure control."],explanation:"It delivers superior heat transfer in a very small footprint, ideal for milk coolers or glycol chiller systems."},{id:"refri_218",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de descarga fluct\xFAa r\xEDtmicamente (agujas vibrando). \xBFQu\xE9 sospecha?",opciones:["Falta de aceite.","V\xE1lvulas de descarga del compresor da\xF1adas o presencia de aire en el sistema.","Termostato defectuoso.","Voltaje bajo."],respuesta_correcta:1,explicacion:"Si las v\xE1lvulas no sellan bien, hay un retorno de gas en cada embolada que causa pulsaciones en el man\xF3metro.",question:"A technician finds that the discharge pressure fluctuates rhythmically (gauge needles vibrating). What is suspected?",options:["Low oil level.","Damaged compressor discharge valves or the presence of air (non-condensables) in the system.","Faulty thermostat.","Low voltage."],explanation:"If the valves do not seal properly, there is a back-flow of gas on each stroke that causes pulsations visible on the gauge."},{id:"refri_219",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, si el sobrecalentamiento en el evaporador es de 8\xB0F pero el gas llega al compresor a 65\xB0F (estando el cuarto a 35\xB0F), \xBFqu\xE9 problema t\xE9rmico existe?",opciones:["Falta de refrigerante.","Ganancia de calor excesiva en la l\xEDnea de succi\xF3n por falta de aislamiento o tuber\xEDa mal ubicada.","La TXV est\xE1 fallando.","El compresor est\xE1 perdiendo eficiencia."],respuesta_correcta:1,explicacion:"Un gas de succi\xF3n demasiado caliente reduce la densidad del refrigerante, disminuye la capacidad de enfriamiento del motor y eleva peligrosamente la temperatura de descarga.",question:"In a system using R-404A, the evaporator superheat is 8 degrees F but the gas arrives at the compressor at 65 degrees F (room temperature is 35 degrees F). What thermal problem exists?",options:["Low refrigerant charge.","Excessive heat gain in the suction line due to lack of insulation or poorly routed tubing.","The TXV is failing.","The compressor is losing efficiency."],explanation:"Excessively hot suction gas reduces refrigerant density, decreases the motor cooling capacity, and dangerously raises the discharge temperature."},{id:"refri_220",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Total Heat of Rejection' (THR)?",opciones:["El fr\xEDo que genera el evaporador.","La suma del calor absorbido en el evaporador m\xE1s el calor generado por el trabajo de compresi\xF3n.","La presi\xF3n de descarga.","El calor que sale por el drenaje."],respuesta_correcta:1,explicacion:"El condensador debe ser capaz de eliminar toda la energ\xEDa del sistema: la carga t\xE9rmica del cliente y el calor el\xE9ctrico/mec\xE1nico del compresor.",question:"What is the Total Heat of Rejection (THR)?",options:["The cooling produced by the evaporator.","The sum of the heat absorbed in the evaporator plus the heat generated by the work of compression.","The discharge pressure.","The heat that exits through the drain."],explanation:"The condenser must be capable of rejecting all the energy in the system: the customer's heat load plus the electrical/mechanical heat from the compressor."},{id:"refri_221",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema de baja temperatura tiene una TXV con 'MOP' (Maximum Operating Pressure). \xBFCu\xE1l es su funci\xF3n?",opciones:["Aumentar la presi\xF3n de descarga.","Limitar la presi\xF3n de succi\xF3n durante el arranque para proteger al motor de sobrecargas.","Abrir la v\xE1lvula al 100% siempre.","Evitar que el aceite se congele."],respuesta_correcta:1,explicacion:"La carga del bulbo MOP est\xE1 dise\xF1ada para que la v\xE1lvula no abra m\xE1s all\xE1 de una presi\xF3n espec\xEDfica, evitando que el compresor 'se ahogue' al arrancar caliente.",question:"A low-temperature system has a TXV with MOP (Maximum Operating Pressure). What is its function?",options:["To increase discharge pressure.","To limit the suction pressure during startup in order to protect the motor from overloading.","To keep the valve open 100% at all times.","To prevent oil from freezing."],explanation:"The MOP bulb charge is designed so that the valve will not open beyond a specific pressure, preventing the compressor from being overwhelmed when starting under a warm load."},{id:"refri_222",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un visor de l\xEDquido que est\xE1 'claro' pero la l\xEDnea de l\xEDquido est\xE1 muy caliente al tacto?",opciones:["Falta de refrigerante.","Condensador sucio o incondensables; hay l\xEDquido pero a una temperatura/presi\xF3n demasiado alta.","Filtro tapado.","Funcionamiento \xF3ptimo."],respuesta_correcta:1,explicacion:"Si el l\xEDquido sale muy caliente del condensador, el subenfriamiento es bajo o nulo, lo que reduce la eficiencia del evaporador.",question:"What does a clear sight glass indicate if the liquid line is very hot to the touch?",options:["Low refrigerant charge.","Dirty condenser or non-condensables; there is liquid but at excessively high temperature/pressure.","Clogged filter.","Optimal operation."],explanation:"If the liquid leaving the condenser is too hot, subcooling is low or nonexistent, which reduces the efficiency of the evaporator."},{id:"refri_223",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el compresor de un congelador arranca cada 30 segundos y se apaga (Short Cycling). Las presiones son normales. \xBFQu\xE9 sospecha?",opciones:["Falta de gas.","Diferencial del presostato de baja muy estrecho o bulbo del termostato mal ubicado.","Motor quemado.","Filtro obstruido."],respuesta_correcta:1,explicacion:"Si el rango entre encendido y apagado es muy peque\xF1o, cualquier cambio de presi\xF3n har\xE1 que el equipo cicle constantemente, da\xF1ando el contactor y el motor.",question:"A technician finds that a freezer compressor starts every 30 seconds and shuts off (short cycling). Pressures are normal. What is suspected?",options:["Low refrigerant charge.","The low-pressure switch differential is set too narrow, or the thermostat bulb is poorly positioned.","Burned motor.","Obstructed filter."],explanation:"If the range between cut-in and cut-out is too small, any minor pressure change will cause the unit to cycle constantly, damaging the contactor and motor."},{id:"refri_224",categoria:"REFRI_COMERCIAL",pregunta:"\xBFC\xF3mo afecta la humedad interna a una TXV de tipo orificio intercambiable?",opciones:["La hace enfriar m\xE1s.","Se forma hielo en el orificio peque\xF1o de la v\xE1lvula, bloqueando el flujo de refrigerante de manera intermitente.","Limpia el aceite.","Aumenta la presi\xF3n de alta."],respuesta_correcta:1,explicacion:"La ca\xEDda de temperatura en la expansi\xF3n es tan brusca que cualquier rastro de agua se convierte en un tap\xF3n de hielo instant\xE1neo.",question:"How does internal moisture affect a TXV with an interchangeable orifice?",options:["It makes it cool better.","Ice forms in the small orifice of the valve, intermittently blocking refrigerant flow.","It cleans the oil.","It increases high-side pressure."],explanation:"The temperature drop during expansion is so sudden that any trace of water instantly turns into an ice plug."},{id:"refri_225",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite' en la l\xEDnea de descarga?",opciones:["Enfriar el refrigerante.","Capturar el aceite que sale del compresor y devolverlo al c\xE1rter antes de que entre al condensador.","Aumentar la presi\xF3n de baja.","Filtrar la humedad."],respuesta_correcta:1,explicacion:"Mantiene el aceite donde debe estar (lubricando) y evita que act\xFAe como aislante t\xE9rmico en el evaporador.",question:"What is the function of an oil separator in the discharge line?",options:["To cool the refrigerant.","To capture oil leaving the compressor and return it to the crankcase before it enters the condenser.","To increase low-side pressure.","To filter moisture."],explanation:"It keeps the oil where it belongs (lubricating) and prevents it from acting as a thermal insulator in the evaporator."},{id:"refri_226",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico mide una ca\xEDda de presi\xF3n de 5 PSI en un filtro deshidratador de la l\xEDnea de l\xEDquido. \xBFEs aceptable?",opciones:["S\xED, hasta 10 PSI est\xE1 bien.","No, una ca\xEDda de m\xE1s de 2-3 PSI indica que el filtro est\xE1 obstruido y debe cambiarse.","S\xED, ayuda a la expansi\xF3n.","Depende del tipo de aceite."],respuesta_correcta:1,explicacion:"Cualquier restricci\xF3n en la l\xEDnea de l\xEDquido causa flash gas prematuro, reduciendo la capacidad de la v\xE1lvula de expansi\xF3n.",question:"A technician measures a 5 PSI pressure drop across a liquid-line filter drier. Is this acceptable?",options:["Yes, up to 10 PSI is fine.","No, a drop greater than 2-3 PSI indicates the filter is obstructed and must be replaced.","Yes, it helps with expansion.","It depends on the oil type."],explanation:"Any restriction in the liquid line causes premature flash gas, reducing the capacity of the expansion valve."},{id:"refri_227",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de evaporaci\xF3n (EPR)?",opciones:["Mantener el evaporador a una presi\xF3n constante, evitando que baje de un punto determinado aunque la succi\xF3n del rack sea menor.","Aumentar la eficiencia del condensador.","Regular el flujo de aceite.","Controlar la velocidad del ventilador."],respuesta_correcta:0,explicacion:"Se usa para mantener diferentes temperaturas en un sistema m\xFAltiple (ej. carnes y verduras conectados al mismo compresor).",question:"What is the function of an evaporator pressure regulator (EPR)?",options:["To maintain the evaporator at a constant pressure, preventing it from dropping below a set point even when the rack suction pressure is lower.","To increase condenser efficiency.","To regulate oil flow.","To control fan speed."],explanation:"It is used to maintain different temperatures in a multiplex system (e.g., meat and produce cases connected to the same compressor rack)."},{id:"refri_228",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema de refrigeraci\xF3n comercial presenta 'Acidez' en el aceite. \xBFCu\xE1l es el procedimiento de correcci\xF3n?",opciones:["Cambiar el aceite, instalar filtros deshidratadores de succi\xF3n de alta capacidad y realizar un triple vac\xEDo.","A\xF1adir bicarbonato al aceite.","Subir la presi\xF3n de alta.","Solo cambiar el refrigerante."],respuesta_correcta:0,explicacion:"La acidez destruye el barniz del motor. Requiere una limpieza qu\xEDmica profunda y monitoreo constante.",question:"A commercial refrigeration system has acidic oil. What is the corrective procedure?",options:["Change the oil, install high-capacity suction-line filter driers, and perform a triple evacuation.","Add baking soda to the oil.","Raise the high-side pressure.","Just replace the refrigerant."],explanation:"Acidity destroys the motor winding varnish. A thorough chemical cleanup and constant monitoring are required."},{id:"refri_229",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Efecto de Hist\xE9resis' en un termostato mec\xE1nico?",opciones:["El tiempo que tarda en quemarse.","La diferencia entre la temperatura de encendido (cut-in) y la de apagado (cut-out).","La precisi\xF3n del sensor.","El retraso del compresor."],respuesta_correcta:1,explicacion:"Sin este diferencial, el equipo encender\xEDa y apagar\xEDa ante el m\xE1s m\xEDnimo cambio de temperatura, destruy\xE9ndose por ciclados cortos.",question:"What is the hysteresis effect in a mechanical thermostat?",options:["The time it takes to burn out.","The difference between the cut-in temperature (on) and the cut-out temperature (off).","The precision of the sensor.","The compressor delay."],explanation:"Without this differential, the unit would cycle on and off at the slightest temperature change, destroying itself from short cycling."},{id:"refri_230",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Acumulador de Succi\xF3n'?",opciones:["Almacenar l\xEDquido antes de la TXV.","Evitar que el refrigerante l\xEDquido llegue a la succi\xF3n del compresor durante fluctuaciones de carga.","Aumentar la presi\xF3n de descarga.","Enfriar el aceite."],respuesta_correcta:1,explicacion:"Es la \xFAltima l\xEDnea de defensa para evitar el 'slugging' (golpe de l\xEDquido) que rompe los platos de v\xE1lvulas.",question:"What is the function of a suction accumulator?",options:["To store liquid before the TXV.","To prevent liquid refrigerant from reaching the compressor suction during load fluctuations.","To increase discharge pressure.","To cool the oil."],explanation:"It is the last line of defense against liquid slugging that can break valve plates."},{id:"refri_231",categoria:"REFRI_COMERCIAL",pregunta:"Si una v\xE1lvula de expansi\xF3n est\xE1 'cazando' (hunting) constantemente, \xBFcu\xE1l es la causa m\xE1s probable?",opciones:["Falta de gas.","V\xE1lvula sobredimensionada o bulbo mal ubicado/sin contacto firme.","Presi\xF3n de alta muy baja.","Compresor muy peque\xF1o."],respuesta_correcta:1,explicacion:"La v\xE1lvula abre de m\xE1s, siente el fr\xEDo, cierra de m\xE1s, y se repite la oscilaci\xF3n sin lograr el equilibrio t\xE9rmico.",question:"If an expansion valve is constantly hunting, what is the most probable cause?",options:["Low refrigerant charge.","Oversized valve or a sensing bulb that is poorly positioned or not firmly attached.","Low high-side pressure.","Undersized compressor."],explanation:"The valve opens too much, senses the cold, closes too much, and repeats the oscillation without achieving thermal equilibrium."},{id:"refri_232",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 significa un 'Compresor Semi-herm\xE9tico'?",opciones:["Que no se puede abrir.","Que el motor y el compresor est\xE1n en la misma carcasa pero unidos por tornillos, permitiendo su apertura para reparaci\xF3n.","Que es mitad aire acondicionado, mitad refrigeraci\xF3n.","Que usa aceite mineral solamente."],respuesta_correcta:1,explicacion:"A diferencia de los herm\xE9ticos (sellados), estos permiten cambiar platos de v\xE1lvulas, bobinas o bielas.",question:"What does 'semi-hermetic compressor' mean?",options:["It cannot be opened.","The motor and compressor are in the same housing but joined by bolts, allowing the unit to be opened for repair.","It is half air conditioning, half refrigeration.","It uses mineral oil only."],explanation:"Unlike hermetic (welded-shut) compressors, semi-hermetics allow replacement of valve plates, windings, or connecting rods."},{id:"refri_233",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico instala un compresor de 208V en una l\xEDnea de 240V. \xBFQu\xE9 suceder\xE1?",opciones:["Funcionar\xE1 con m\xE1s potencia.","El motor se sobrecalentar\xE1, consumir\xE1 m\xE1s amperaje de lo normal y su vida \xFAtil se reducir\xE1 dr\xE1sticamente.","No arrancar\xE1.","El capacitor explotar\xE1."],respuesta_correcta:1,explicacion:"El exceso de voltaje satura el n\xFAcleo magn\xE9tico del motor, generando calor residual que termina quemando el esmalte de las bobinas.",question:"A technician installs a 208V compressor on a 240V power supply. What will happen?",options:["It will run with more power.","The motor will overheat, draw higher-than-normal amperage, and its service life will be drastically shortened.","It will not start.","The capacitor will explode."],explanation:"Excess voltage saturates the magnetic core of the motor, generating residual heat that eventually burns the winding enamel."},{id:"refri_234",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la diferencia entre el sobrecalentamiento del evaporador y el sobrecalentamiento total?",opciones:["No hay diferencia.","El del evaporador se mide a la salida del mismo; el total se mide en la succi\xF3n del compresor.","Uno es con term\xF3metro y otro con man\xF3metro.","El total incluye la presi\xF3n de descarga."],respuesta_correcta:1,explicacion:"El total nos dice si el gas que llega al motor tiene la temperatura adecuada para enfriarlo sin da\xF1arlo.",question:"What is the difference between evaporator superheat and total superheat?",options:["There is no difference.","Evaporator superheat is measured at the evaporator outlet; total superheat is measured at the compressor suction inlet.","One uses a thermometer and the other uses a gauge.","Total superheat includes discharge pressure."],explanation:"Total superheat tells us whether the gas reaching the motor is at the right temperature to cool it without causing damage."},{id:"refri_235",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 0\xB0F?",opciones:["Evaporador perfecto.","Inundaci\xF3n total; est\xE1 entrando refrigerante l\xEDquido al compresor.","Falta de gas.","Condensador tapado."],respuesta_correcta:1,explicacion:"Si no hay superheat, el gas no es gas, es l\xEDquido saturado. Es el escenario m\xE1s peligroso para la mec\xE1nica del sistema.",question:"What does a superheat of 0 degrees F indicate?",options:["A perfectly performing evaporator.","Total flooding; liquid refrigerant is entering the compressor.","Low refrigerant charge.","Clogged condenser."],explanation:"If there is no superheat, the gas is not gas but saturated liquid. This is the most dangerous scenario for the mechanical integrity of the system."},{id:"refri_236",categoria:"REFRI_COMERCIAL",pregunta:"Un condensador evaporativo tiene dep\xF3sitos de minerales (sarro) en los tubos. \xBFC\xF3mo afecta esto a la presi\xF3n de descarga?",opciones:["La baja.","La sube dr\xE1sticamente al actuar como un aislante t\xE9rmico que impide que el agua enfr\xEDe el refrigerante.","No la afecta.","Limpia el refrigerante."],respuesta_correcta:1,explicacion:"El sarro tiene una conductividad t\xE9rmica baj\xEDsima; el compresor debe trabajar mucho m\xE1s para compensar.",question:"An evaporative condenser has mineral scale deposits on the tubes. How does this affect the discharge pressure?",options:["It lowers it.","It raises it drastically by acting as a thermal insulator that prevents the water from cooling the refrigerant.","It has no effect.","It cleans the refrigerant."],explanation:"Scale has extremely low thermal conductivity; the compressor must work much harder to compensate."},{id:"refri_237",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de condensaci\xF3n (KVR)?",opciones:["Bajar la presi\xF3n de alta.","Mantener una presi\xF3n m\xEDnima de descarga en climas fr\xEDos para que la TXV reciba suficiente presi\xF3n para operar.","Ahorrar agua.","Detener el ventilador."],respuesta_correcta:1,explicacion:"En invierno, el fr\xEDo externo hace que la presi\xF3n de alta caiga tanto que la v\xE1lvula de expansi\xF3n deja de alimentar el evaporador.",question:"What is the function of a condenser pressure regulating valve (KVR)?",options:["To lower the high-side pressure.","To maintain a minimum discharge pressure in cold climates so the TXV receives enough pressure to operate.","To save water.","To stop the fan."],explanation:"In winter, the extreme outdoor cold causes the head pressure to drop so low that the expansion valve can no longer feed the evaporator."},{id:"refri_238",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el compresor est\xE1 cubierto de hielo. \xBFQu\xE9 est\xE1 pasando?",opciones:["Falta de gas.","Retorno de l\xEDquido (Floodback) severo, probablemente por una TXV trabada abierta o ventilador de evaporador quemado.","Funcionamiento normal en congelaci\xF3n.","El filtro est\xE1 tapado."],respuesta_correcta:1,explicacion:"Si el compresor se congela por fuera, el refrigerante l\xEDquido est\xE1 llegando al c\xE1rter y robando calor del ambiente para hervir ah\xED mismo.",question:"A technician finds that the compressor is covered in ice. What is happening?",options:["Low refrigerant charge.","Severe liquid floodback, likely caused by a TXV stuck open or a burned-out evaporator fan motor.","Normal operation in a freezer application.","The filter is clogged."],explanation:"If the compressor is icing up on the outside, liquid refrigerant is reaching the crankcase and absorbing ambient heat to boil off right there."},{id:"refri_239",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 componente se encarga de evitar que el refrigerante migre al compresor durante las paradas largas?",opciones:["El separador de aceite.","El calentador de c\xE1rter (Crankcase Heater).","La v\xE1lvula de expansi\xF3n.","El presostato de alta."],respuesta_correcta:1,explicacion:"Mantiene el aceite caliente para que el refrigerante prefiera quedarse en las partes m\xE1s fr\xEDas del sistema y no se diluya en el c\xE1rter.",question:"Which component prevents refrigerant from migrating to the compressor during long off cycles?",options:["The oil separator.","The crankcase heater.","The expansion valve.","The high-pressure switch."],explanation:"It keeps the oil warm so that refrigerant prefers to stay in the colder parts of the system rather than dissolving into the crankcase."},{id:"refri_240",categoria:"REFRI_COMERCIAL",pregunta:"\xBFPara qu\xE9 sirve un 'Aceite Alquilbenceno' (AB)?",opciones:["Para sistemas de R-410A.","Para sistemas de R-22 y mezclas (HCFC) donde el aceite mineral no tiene buena solubilidad a bajas temperaturas.","Es un aceite de cocina.","Para sistemas de amon\xEDaco solamente."],respuesta_correcta:1,explicacion:"Fue la soluci\xF3n intermedia para mejorar el retorno de aceite en sistemas comerciales que migraron de R-12 o R-502.",question:"What is alkylbenzene (AB) oil used for?",options:["For R-410A systems.","For R-22 and HCFC blend systems where mineral oil does not have adequate solubility at low temperatures.","It is a cooking oil.","For ammonia systems only."],explanation:"It was the intermediate solution to improve oil return in commercial systems that transitioned from R-12 or R-502."},{id:"refri_241",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica una diferencia de temperatura (TD) muy alta en el evaporador?",opciones:["Flujo de aire excesivo.","Evaporador muy peque\xF1o para la carga o ventilador fallando (poco flujo de aire).","Demasiado gas.","El compresor est\xE1 fr\xEDo."],respuesta_correcta:1,explicacion:"Si el aire no circula bien, el serpent\xEDn se enfr\xEDa demasiado comparado con el aire del cuarto, lo que deshumidifica en exceso y baja la eficiencia.",question:"What does a very high temperature difference (TD) across the evaporator indicate?",options:["Excessive airflow.","Evaporator too small for the load or fan failing (insufficient airflow).","Too much refrigerant.","The compressor is cold."],explanation:"If air does not circulate well, the coil becomes too cold compared to the room air, causing excessive dehumidification and reduced efficiency."},{id:"refri_242",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es un 'Sistema en Cascada'?",opciones:["Un sistema con agua cayendo.","Dos sistemas independientes conectados por un intercambiador donde el evaporador de uno enfr\xEDa el condensador del otro.","Un rack de compresores en serie.","Un sistema de aire acondicionado central."],respuesta_correcta:1,explicacion:"Se utiliza para alcanzar temperaturas ultra-bajas (-80\xB0F) que un solo refrigerante no podr\xEDa lograr eficientemente.",question:"What is a 'Cascade System'?",options:["A system with falling water.","Two independent systems connected by a heat exchanger where the evaporator of one cools the condenser of the other.","A rack of compressors in series.","A central air conditioning system."],explanation:"It is used to achieve ultra-low temperatures (-80\xB0F) that a single refrigerant could not reach efficiently."},{id:"refri_243",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el compresor semi-herm\xE9tico 'golpea' r\xEDtmicamente al arrancar. \xBFCausa m\xE1s probable?",opciones:["Falta de gas.","Migraci\xF3n de refrigerante l\xEDquido al c\xE1rter durante el periodo de apagado.","El ventilador est\xE1 flojo.","Filtro tapado."],respuesta_correcta:1,explicacion:"Al arrancar, el l\xEDquido en el c\xE1rter se mezcla con el aceite y es succionado por los pistones, causando el golpe hidr\xE1ulico.",question:"A technician finds that a semi-hermetic compressor 'knocks' rhythmically at startup. What is the most likely cause?",options:["Low refrigerant charge.","Liquid refrigerant migration to the crankcase during the off cycle.","The fan is loose.","Clogged filter."],explanation:"On startup, the liquid in the crankcase mixes with the oil and is drawn in by the pistons, causing hydraulic slugging."},{id:"refri_244",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula de retenci\xF3n (Check Valve) instalada en la l\xEDnea de descarga de un compresor en un sistema m\xFAltiple?",opciones:["Aumentar la presi\xF3n de descarga.","Evitar que el refrigerante de los compresores activos migre hacia el compresor apagado y se condense en su c\xE1rter.","Regular el flujo de aceite.","Filtrar el refrigerante gaseoso."],respuesta_correcta:1,explicacion:"Sin esta v\xE1lvula, el gas caliente buscar\xEDa el punto m\xE1s fr\xEDo (el compresor apagado), causando un arranque con golpe de l\xEDquido y diluci\xF3n de aceite.",question:"What is the function of a check valve installed in the discharge line of a compressor in a multiplex system?",options:["To increase discharge pressure.","To prevent refrigerant from active compressors from migrating to the off compressor and condensing in its crankcase.","To regulate oil flow.","To filter gaseous refrigerant."],explanation:"Without this valve, the hot gas would seek the coldest point (the off compressor), causing a startup with liquid slugging and oil dilution."},{id:"refri_245",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede con el sobrecalentamiento si la carga t\xE9rmica en el evaporador aumenta repentinamente?",opciones:["El sobrecalentamiento disminuye.","El sobrecalentamiento aumenta, haciendo que la TXV se abra para admitir m\xE1s refrigerante.","Se mantiene igual.","La presi\xF3n de descarga baja."],respuesta_correcta:1,explicacion:"M\xE1s calor evapora el l\xEDquido m\xE1s r\xE1pido, dejando m\xE1s tramo de tuber\xEDa para calentar el gas; la TXV responde a este aumento abriendo el puerto.",question:"What happens to superheat if the thermal load on the evaporator increases suddenly?",options:["Superheat decreases.","Superheat increases, causing the TXV to open to admit more refrigerant.","It stays the same.","Discharge pressure drops."],explanation:"More heat evaporates the liquid faster, leaving more tubing length to heat the vapor; the TXV responds to this increase by opening the port."},{id:"refri_246",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un 'Oil Safety Switch' (Presostato de aceite) que se dispara despu\xE9s de 120 segundos?",opciones:["Que el aceite est\xE1 muy caliente.","Que la diferencia entre la presi\xF3n de la bomba de aceite y la presi\xF3n del c\xE1rter es insuficiente para garantizar la lubricaci\xF3n.","Que el compresor tiene mucho aceite.","Que el filtro de succi\xF3n est\xE1 tapado."],respuesta_correcta:1,explicacion:"El timer de 120 segundos permite que el compresor establezca presi\xF3n en el arranque; si no lo logra, corta para evitar que los cojinetes se fundan.",question:"What does an Oil Safety Switch (oil pressure safety control) that trips after 120 seconds indicate?",options:["That the oil is too hot.","That the difference between the oil pump pressure and crankcase pressure is insufficient to ensure lubrication.","That the compressor has too much oil.","That the suction filter is clogged."],explanation:"The 120-second timer allows the compressor to build pressure on startup; if it fails to do so, it shuts down to prevent bearing failure."},{id:"refri_247",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, si el visor de l\xEDquido muestra burbujas pero el subenfriamiento es de 10\xB0F, \xBFcu\xE1l es el problema?",opciones:["Falta de refrigerante.","Restricci\xF3n en la l\xEDnea de l\xEDquido (posiblemente filtro deshidratador) causando una ca\xEDda de presi\xF3n local.","Exceso de aceite.","Condensador sucio."],respuesta_correcta:1,explicacion:"Si hay subenfriamiento, el condensador hizo su trabajo. Las burbujas despu\xE9s del filtro indican que el l\xEDquido 'hirvi\xF3' por la ca\xEDda de presi\xF3n en la obstrucci\xF3n.",question:"In an R-404A system, if the liquid sight glass shows bubbles but subcooling is 10\xB0F, what is the problem?",options:["Low refrigerant charge.","A restriction in the liquid line (possibly the filter drier) causing a localized pressure drop.","Excess oil.","Dirty condenser."],explanation:"If there is subcooling, the condenser did its job. Bubbles after the filter indicate the liquid 'flashed' due to the pressure drop across the restriction."},{id:"refri_248",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el compresor de una m\xE1quina de hielo est\xE1 muy caliente y corta por t\xE9rmico. El condensador est\xE1 limpio. \xBFQu\xE9 otra cosa revisa?",opciones:["La temperatura del agua de entrada.","El funcionamiento del ventilador del condensador y la posible presencia de gases no condensables (aire).","El nivel de hielo en el dep\xF3sito.","El grosor del cubo de hielo."],respuesta_correcta:1,explicacion:"Si hay aire en el sistema, la presi\xF3n de descarga sube al infinito, sobrecalentando el motor hasta que el protector act\xFAa.",question:"A technician finds that a compressor on an ice machine is very hot and trips on thermal overload. The condenser is clean. What else should be checked?",options:["The inlet water temperature.","The condenser fan operation and the possible presence of non-condensable gases (air).","The ice level in the bin.","The ice cube thickness."],explanation:"If there is air in the system, the discharge pressure rises excessively, overheating the motor until the protector trips."},{id:"refri_249",categoria:"REFRI_COMERCIAL",pregunta:"Si una TXV con carga de 'Gas Cruzado' (Cross Charge) falla, \xBFc\xF3mo se comporta el sobrecalentamiento?",opciones:["Se mantiene constante.","Se vuelve extremadamente err\xE1tico, ya que la v\xE1lvula pierde su capacidad de compensar las variaciones de presi\xF3n.","La v\xE1lvula se cierra permanentemente.","El sistema enfr\xEDa m\xE1s."],respuesta_correcta:1,explicacion:"Las cargas cruzadas est\xE1n dise\xF1adas para mantener un superheat estable en un rango amplio de temperaturas. Al fallar, la v\xE1lvula pierde su 'inteligencia' mec\xE1nica.",question:"If a TXV with a 'Cross Charge' fails, how does the superheat behave?",options:["It remains constant.","It becomes extremely erratic, as the valve loses its ability to compensate for pressure variations.","The valve closes permanently.","The system cools more."],explanation:"Cross charges are designed to maintain stable superheat over a wide temperature range. When they fail, the valve loses its mechanical 'intelligence'."},{id:"refri_250",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de succi\xF3n es muy baja, pero el sobrecalentamiento en el evaporador es de 2\xB0F. \xBFDiagn\xF3stico?",opciones:["Falta de gas.","Poco flujo de aire a trav\xE9s del evaporador (ventilador malo o serpent\xEDn sucio/congelado).","TXV muy abierta.","Compresor muy grande."],respuesta_correcta:1,explicacion:"Si el superheat es bajo, el evaporador est\xE1 lleno de l\xEDquido, pero si la presi\xF3n es baja, significa que el l\xEDquido no puede absorber calor por falta de aire.",question:"A technician finds that suction pressure is very low, but the evaporator superheat is 2\xB0F. What is the diagnosis?",options:["Low refrigerant charge.","Poor airflow across the evaporator (bad fan motor or dirty/iced coil).","TXV too far open.","Oversized compressor."],explanation:"If superheat is low, the evaporator is full of liquid, but if pressure is low, it means the liquid cannot absorb heat due to lack of airflow."},{id:"refri_251",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-22 convertido a R-407C, el t\xE9cnico nota que el evaporador se congela. Las presiones est\xE1n bien seg\xFAn la tabla. \xBFQu\xE9 olvid\xF3?",opciones:["Cargar m\xE1s gas.","Ajustar la TXV para compensar el deslizamiento t\xE9rmico (glide) del nuevo refrigerante.","Cambiar el ventilador.","Limpiar el condensador."],respuesta_correcta:1,explicacion:"El glide del 407C hace que la temperatura cambie durante la evaporaci\xF3n; si no se ajusta el superheat, el sistema puede operar fuera de rango.",question:"In a system converted from R-22 to R-407C, the technician notices the evaporator is freezing up. Pressures look correct on the chart. What was forgotten?",options:["Add more refrigerant.","Adjust the TXV to compensate for the temperature glide of the new refrigerant.","Replace the fan.","Clean the condenser."],explanation:"The glide of R-407C causes the temperature to change during evaporation; if superheat is not adjusted, the system may operate out of range."},{id:"refri_252",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un 'Control de Baja Presi\xF3n' (LPS) de tipo autom\xE1tico?",opciones:["Detener el compresor si hay una fuga de gas o si la presi\xF3n de succi\xF3n cae peligrosamente por debajo del punto de congelaci\xF3n.","Aumentar la presi\xF3n de descarga.","Regular la velocidad del ventilador.","Encender la luz de alarma solamente."],respuesta_correcta:0,explicacion:"Es una protecci\xF3n vital para evitar que el compresor trabaje en vac\xEDo o con evaporadores congelados.",question:"What is the purpose of an automatic-type Low Pressure Safety (LPS) control?",options:["To shut down the compressor if there is a refrigerant leak or if suction pressure drops dangerously below the freezing point.","To increase discharge pressure.","To regulate fan speed.","To activate the alarm light only."],explanation:"It is a vital protection to prevent the compressor from operating in a vacuum or with frozen evaporators."},{id:"refri_253",categoria:"REFRI_COMERCIAL",pregunta:"Un rack de compresores tiene una 'V\xE1lvula Diferencial de Aceite'. \xBFPara qu\xE9 sirve?",opciones:["Para mezclar aceites.","Para mantener una presi\xF3n de aceite constante en el colector, independientemente de cu\xE1ntos compresores est\xE9n funcionando.","Para filtrar el aceite sucio.","Para calentar el aceite."],respuesta_correcta:1,explicacion:"Asegura que el suministro de aceite a cada compresor sea uniforme y confiable en todo el rack.",question:"A compressor rack has an 'Oil Differential Valve.' What is it for?",options:["To mix oils.","To maintain a constant oil pressure in the header, regardless of how many compressors are running.","To filter dirty oil.","To heat the oil."],explanation:"It ensures that the oil supply to each compressor is uniform and reliable across the entire rack."},{id:"refri_254",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 efecto tiene una tuber\xEDa de succi\xF3n con demasiadas vueltas y codos?",opciones:["Mejora el retorno de aceite.","Causa una ca\xEDda de presi\xF3n excesiva, reduciendo la capacidad del compresor y aumentando el consumo el\xE9ctrico.","Ayuda a enfriar el gas.","No afecta en nada."],respuesta_correcta:1,explicacion:"Cada codo suma 'longitud equivalente'. Demasiada fricci\xF3n hace que la presi\xF3n en el compresor sea menor que en el evaporador, perdiendo eficiencia.",question:"What effect does a suction line with too many bends and elbows have?",options:["It improves oil return.","It causes excessive pressure drop, reducing compressor capacity and increasing electrical consumption.","It helps cool the gas.","It has no effect."],explanation:"Each elbow adds 'equivalent length.' Too much friction makes the pressure at the compressor lower than at the evaporator, losing efficiency."},{id:"refri_255",categoria:"REFRI_COMERCIAL",pregunta:"Al usar un detector de fugas de luz ultravioleta (tinte fluorescente), \xBFcu\xE1l es la mayor precauci\xF3n?",opciones:["No usarlo en sistemas nuevos.","Asegurarse de que el tinte sea compatible con el aceite del sistema y no usarlo en exceso para no alterar las propiedades de lubricaci\xF3n.","No mirar la luz sin lentes.","B y C son correctas."],respuesta_correcta:3,explicacion:"La seguridad ocular es b\xE1sica, y el exceso de tinte puede degradar el aceite POE o mineral.",question:"When using a UV leak detector (fluorescent dye), what is the greatest precaution?",options:["Do not use it on new systems.","Make sure the dye is compatible with the system oil and do not use too much to avoid altering lubrication properties.","Do not look at the light without glasses.","Both B and C are correct."],explanation:"Eye safety is essential, and excessive dye can degrade POE or mineral oil."},{id:"refri_256",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 45\xB0F en el compresor de un sistema de baja temperatura?",opciones:["Funcionamiento normal.","Riesgo inminente de quemadura del motor por falta de enfriamiento; el gas llega demasiado caliente para retirar el calor de las bobinas.","Falta de aceite.","Evaporador inundado."],respuesta_correcta:1,explicacion:"El gas de succi\xF3n es la vida del compresor herm\xE9tico. Si el superheat es muy alto, el motor se 'cocina' internamente.",question:"What does a superheat of 45\xB0F at the compressor of a low-temperature system indicate?",options:["Normal operation.","Imminent risk of motor burnout from lack of cooling; the gas arrives too hot to remove heat from the windings.","Low oil.","Flooded evaporator."],explanation:"Suction gas is the lifeline of a hermetic compressor. If superheat is very high, the motor 'cooks' internally."},{id:"refri_257",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de succi\xF3n (EPR) en un sistema de supermercado?",opciones:["Bajar la presi\xF3n de descarga.","Mantener una temperatura m\xE1s alta en un evaporador espec\xEDfico (ej. l\xE1cteos) que la succi\xF3n general del rack (ej. carnes).","Controlar el aceite.","Evitar el desescarche."],respuesta_correcta:1,explicacion:"Permite manejar m\xFAltiples temperaturas con un solo grupo de compresores de forma eficiente.",question:"What is the function of a suction pressure regulator (EPR) valve in a supermarket system?",options:["To lower discharge pressure.","To maintain a higher temperature in a specific evaporator (e.g., dairy) than the general suction of the rack (e.g., meats).","To control the oil.","To prevent defrost."],explanation:"It allows managing multiple temperatures with a single group of compressors efficiently."},{id:"refri_258",categoria:"REFRI_COMERCIAL",pregunta:"Si el ventilador del evaporador se detiene en un sistema de media temperatura, \xBFqu\xE9 pasar\xE1 con el subenfriamiento?",opciones:["Aumentar\xE1 dr\xE1sticamente.","Disminuir\xE1 ligeramente debido a la ca\xEDda de la presi\xF3n de descarga al haber menos carga t\xE9rmica en el sistema.","Se mantendr\xE1 igual.","Subir\xE1 la presi\xF3n de succi\xF3n."],respuesta_correcta:1,explicacion:"Menos calor absorbido significa menos calor a rechazar; la presi\xF3n de alta baja y el subcooling se ve afectado por el nuevo equilibrio de masas.",question:"If the evaporator fan stops in a medium-temperature system, what will happen to subcooling?",options:["It will increase drastically.","It will decrease slightly due to the drop in discharge pressure from reduced thermal load on the system.","It will stay the same.","Suction pressure will rise."],explanation:"Less heat absorbed means less heat to reject; discharge pressure drops and subcooling is affected by the new mass balance."},{id:"refri_259",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Glide' (deslizamiento) en una mezcla de refrigerantes serie 400?",opciones:["La velocidad a la que fluye el gas.","La diferencia entre la temperatura de burbuja y la de roc\xEDo a una presi\xF3n constante durante el cambio de fase.","El tiempo que tarda en evaporarse.","La mezcla del aceite con el gas."],respuesta_correcta:1,explicacion:"Como los componentes hierven a temperaturas distintas, la mezcla cambia su temperatura mientras se evapora o condensa.",question:"What is 'glide' in a 400-series refrigerant blend?",options:["The speed at which the gas flows.","The difference between the bubble point temperature and the dew point temperature at a constant pressure during the phase change.","The time it takes to evaporate.","The mixing of oil with the gas."],explanation:"Because the components boil at different temperatures, the blend changes its temperature as it evaporates or condenses."},{id:"refri_260",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n principal de la v\xE1lvula solenoide en la l\xEDnea de l\xEDquido?",opciones:["Regular el sobrecalentamiento.","Cortar el flujo de refrigerante para permitir el ciclo de 'Pump Down' o durante el desescarche.","Proteger contra altas presiones.","Medir el flujo de gas."],respuesta_correcta:1,explicacion:"Es el interruptor principal del flujo de l\xEDquido controlado por el termostato o el reloj de deshielo.",question:"What is the primary function of the liquid line solenoid valve?",options:["To regulate superheat.","To shut off refrigerant flow to allow the pump-down cycle or during defrost.","To protect against high pressures.","To measure gas flow."],explanation:"It is the main liquid flow switch controlled by the thermostat or the defrost timer."},{id:"refri_261",categoria:"REFRI_COMERCIAL",pregunta:"Si el bulbo de la TXV pierde su carga termost\xE1tica, \xBFqu\xE9 posici\xF3n tomar\xE1 la v\xE1lvula?",opciones:["Totalmente abierta.","Totalmente cerrada (o casi cerrada) por la fuerza del resorte y la presi\xF3n de evaporaci\xF3n.","Se quedar\xE1 a la mitad.","Fluctuar\xE1 constantemente."],respuesta_correcta:1,explicacion:"La presi\xF3n del bulbo es la que abre la v\xE1lvula; sin ella, el resorte gana la batalla y cierra el puerto.",question:"If the sensing bulb of a TXV loses its thermostatic charge, what position will the valve take?",options:["Fully open.","Fully closed (or nearly closed) due to the force of the spring and evaporator pressure.","It will stay at midpoint.","It will fluctuate constantly."],explanation:"The bulb pressure is what opens the valve; without it, the spring wins and closes the port."},{id:"refri_262",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica una temperatura de descarga del compresor superior a 225\xB0F?",opciones:["Alta eficiencia.","Degradaci\xF3n inminente del aceite y posible formaci\xF3n de lodos y carb\xF3n en los platos de v\xE1lvulas.","Falta de aceite.","Baja presi\xF3n de alta."],respuesta_correcta:1,explicacion:"A partir de esa temperatura, la estabilidad qu\xEDmica del aceite se rompe, comprometiendo la vida del compresor.",question:"What does a compressor discharge temperature above 225\xB0F indicate?",options:["High efficiency.","Imminent oil degradation and possible formation of sludge and carbon on the valve plates.","Low oil.","Low head pressure."],explanation:"Above that temperature, the chemical stability of the oil breaks down, compromising the life of the compressor."},{id:"refri_263",categoria:"REFRI_COMERCIAL",pregunta:"Si el aceite del c\xE1rter est\xE1 espumando excesivamente en el visor durante el arranque, \xBFqu\xE9 debe hacer el t\xE9cnico?",opciones:["A\xF1adir m\xE1s aceite.","Verificar el calentador de c\xE1rter; el refrigerante l\xEDquido se ha mezclado con el aceite durante la parada.","Cambiar el compresor.","Subir la presi\xF3n de alta."],respuesta_correcta:1,explicacion:"La espuma indica que el refrigerante est\xE1 'hirviendo' fuera del aceite, lo que puede causar fallas de lubricaci\xF3n.",question:"If the crankcase oil is foaming excessively in the sight glass during startup, what should the technician do?",options:["Add more oil.","Check the crankcase heater; liquid refrigerant has mixed with the oil during the off period.","Replace the compressor.","Raise the head pressure."],explanation:"Foaming indicates that the refrigerant is 'boiling out' of the oil, which can cause lubrication failure."},{id:"refri_264",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, \xBFqu\xE9 significa un sobrecalentamiento de 30\xB0F en el evaporador?",opciones:["Que est\xE1 perfecto.","Que el evaporador est\xE1 'hambriento' de refrigerante, probablemente por una TXV mal ajustada o cerrada.","Que tiene exceso de gas.","Que el ventilador est\xE1 muy r\xE1pido."],respuesta_correcta:1,explicacion:"Un superheat alto significa que el refrigerante se evapora muy pronto y el resto del serpent\xEDn no est\xE1 enfriando efectivamente.",question:"In an R-404A system, what does a superheat of 30\xB0F at the evaporator outlet mean?",options:["It is perfect.","The evaporator is 'starved' of refrigerant, likely due to a poorly adjusted or closed TXV.","There is excess refrigerant.","The fan is running too fast."],explanation:"High superheat means the refrigerant evaporates too early and the rest of the coil is not effectively cooling."},{id:"refri_265",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un subenfriamiento de 0\xB0F y burbujas en el visor?",opciones:["Condensador perfecto.","Falta de refrigerante; el gas no se termina de condensar en el lado de alta.","Exceso de carga.","Filtro tapado."],respuesta_correcta:1,explicacion:"Sin subcooling, no tienes garant\xEDa de que el refrigerante llegue l\xEDquido a la v\xE1lvula de expansi\xF3n.",question:"What does a subcooling of 0\xB0F and bubbles in the sight glass indicate?",options:["Perfect condenser.","Low refrigerant charge; the gas is not fully condensing on the high side.","Excess charge.","Clogged filter."],explanation:"Without subcooling, there is no guarantee that the refrigerant arrives as liquid at the expansion valve."},{id:"refri_266",categoria:"REFRI_COMERCIAL",pregunta:"Si el ventilador del condensador falla y la presi\xF3n de alta sube, \xBFqu\xE9 pasa con el amperaje del compresor?",opciones:["Disminuye.","Aumenta debido al incremento del trabajo requerido para comprimir el gas contra una presi\xF3n mayor.","Se mantiene igual.","El motor gira m\xE1s r\xE1pido."],respuesta_correcta:1,explicacion:"A mayor presi\xF3n de descarga, mayor torque requerido del motor el\xE9ctrico, subiendo el consumo.",question:"If the condenser fan fails and head pressure rises, what happens to compressor amperage?",options:["It decreases.","It increases due to the greater work required to compress gas against a higher pressure.","It stays the same.","The motor spins faster."],explanation:"Higher discharge pressure means greater torque required from the electric motor, increasing power consumption."},{id:"refri_267",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite' en la l\xEDnea de descarga?",opciones:["Enfriar el refrigerante.","Capturar el aceite que sale del compresor y devolverlo al c\xE1rter antes de que entre al condensador.","Aumentar la presi\xF3n de baja.","Filtrar la humedad."],respuesta_correcta:1,explicacion:"Mantiene el aceite donde debe estar (lubricando) y evita que act\xFAe como aislante t\xE9rmico en el evaporador.",question:"What is the function of the oil separator in the discharge line?",options:["To cool the refrigerant.","To capture oil leaving the compressor and return it to the crankcase before it enters the condenser.","To increase suction pressure.","To filter moisture."],explanation:"It keeps the oil where it belongs (lubricating) and prevents it from acting as a thermal insulator in the evaporator."},{id:"refri_268",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de descarga fluct\xFAa r\xEDtmicamente. \xBFQu\xE9 sospecha?",opciones:["Falta de aceite.","V\xE1lvulas de descarga del compresor da\xF1adas o presencia de aire en el sistema.","Termostato defectuoso.","Voltaje bajo."],respuesta_correcta:1,explicacion:"Si las v\xE1lvulas no cierran bien, hay un retorno de gas en cada embolada que causa pulsaciones en el man\xF3metro.",question:"A technician finds that discharge pressure fluctuates rhythmically. What is suspected?",options:["Low oil.","Damaged compressor discharge valves or the presence of air in the system.","Defective thermostat.","Low voltage."],explanation:"If the valves do not seal properly, gas returns on each stroke, causing pulsations on the gauge."},{id:"refri_269",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema de refrigeraci\xF3n comercial, \xBFqu\xE9 indica un 'Approach' de condensador (Temp. l\xEDquido - Temp. aire entrada) menor a 5\xB0F?",opciones:["Condensador extremadamente eficiente.","Condensador sobredimensionado para la carga actual o carga de refrigerante insuficiente.","Falta de aceite.","Ventilador muy lento."],respuesta_correcta:1,explicacion:"Un approach demasiado bajo suele indicar que no hay suficiente intercambio ocurriendo, ya sea porque no hay gas que condensar o porque el equipo es demasiado grande para el calor que est\xE1 manejando.",question:"In a commercial refrigeration system, what does a condenser 'approach' (liquid temp minus entering air temp) of less than 5\xB0F indicate?",options:["An extremely efficient condenser.","An oversized condenser for the current load or insufficient refrigerant charge.","Low oil.","Slow fan."],explanation:"A very low approach usually indicates insufficient heat exchange is occurring, either because there is not enough gas to condense or because the equipment is oversized for the heat being handled."},{id:"refri_270",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 efecto tiene el 'Calor Sensible' en el aire que pasa por un evaporador?",opciones:["Cambia la humedad del aire.","Baja la temperatura del aire sin cambiar su estado f\xEDsico (de 45\xB0F a 35\xB0F, por ejemplo).","Condensa el agua en las aletas.","Aumenta la presi\xF3n del gas."],respuesta_correcta:1,explicacion:"El calor sensible es el que se refleja directamente en el cambio de lectura del term\xF3metro.",question:"What effect does 'sensible heat' have on the air passing through an evaporator?",options:["It changes the humidity of the air.","It lowers the air temperature without changing its physical state (from 45\xB0F to 35\xB0F, for example).","It condenses water on the fins.","It increases gas pressure."],explanation:"Sensible heat is directly reflected in the change in thermometer reading."},{id:"refri_271",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema comercial usa una TXV con igualaci\xF3n externa. Si la l\xEDnea de igualaci\xF3n se rompe y se tapa, \xBFqu\xE9 har\xE1 la v\xE1lvula?",opciones:["Se abre totalmente.","Se cierra casi por completo (Starving) porque la presi\xF3n debajo del diafragma ser\xE1 mayor a la de salida del evaporador.","No pasa nada.","El compresor se apaga por alta presi\xF3n."],respuesta_correcta:1,explicacion:"La v\xE1lvula 'cree' que la presi\xF3n en el evaporador es mucho m\xE1s alta de lo que realmente es, intentando compensar cerrando el flujo.",question:"A commercial system uses a TXV with external equalization. If the equalizer line breaks and becomes plugged, what will the valve do?",options:["It opens fully.","It closes almost completely (starving) because the pressure below the diaphragm will be higher than the actual evaporator outlet pressure.","Nothing happens.","The compressor shuts down on high pressure."],explanation:"The valve 'thinks' the evaporator pressure is much higher than it actually is, and tries to compensate by closing off flow."},{id:"refri_272",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra lodo gris/negro en el visor de aceite de un compresor semi-herm\xE9tico. \xBFQu\xE9 indica?",opciones:["El aceite es nuevo.","Desgaste mec\xE1nico severo de los cojinetes de biela o presencia de humedad que ha reaccionado con el aceite.","Falta de refrigerante.","Exceso de carga."],respuesta_correcta:1,explicacion:"La 'sopa de metal' es el paso previo a que el compresor se 'amarre' o se clave mec\xE1nicamente.",question:"A technician finds gray/black sludge in the oil sight glass of a semi-hermetic compressor. What does this indicate?",options:["The oil is new.","Severe mechanical wear of the connecting rod bearings or the presence of moisture that has reacted with the oil.","Low refrigerant charge.","Excess charge."],explanation:"The 'metal soup' is the precursor to the compressor seizing up mechanically."},{id:"refri_273",categoria:"REFRI_COMERCIAL",pregunta:"Un controlador digital de un Reach-in muestra la temperatura en 40\xB0F pero el compresor no enciende. El setpoint es 35\xB0F. \xBFQu\xE9 es lo primero que revisa?",opciones:["El capacitor del compresor.","El estado del rel\xE9 de salida del controlador y los retardos de tiempo (Anti-short cycle).","La presi\xF3n de alta.","La bombilla interna."],respuesta_correcta:1,explicacion:"Muchos controladores tienen un retraso de 3 a 5 minutos antes de enviar la se\xF1al al compresor para protegerlo.",question:"A digital controller on a reach-in cooler shows a temperature of 40\xB0F but the compressor does not start. The setpoint is 35\xB0F. What is checked first?",options:["The compressor capacitor.","The status of the controller output relay and the time delays (anti-short cycle).","The head pressure.","The internal light bulb."],explanation:"Many controllers have a 3- to 5-minute delay before sending the signal to the compressor to protect it."},{id:"refri_274",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Subenfriamiento L\xEDquido' (Liquid Subcooling) y por qu\xE9 es vital antes de la TXV?",opciones:["Es enfriar el gas.","Es asegurar que el refrigerante sea 100% l\xEDquido para evitar 'flash gas' en la l\xEDnea de l\xEDquido, lo que reducir\xEDa la capacidad de la v\xE1lvula.","Es calentar el aceite.","Es bajar la presi\xF3n de descarga."],respuesta_correcta:1,explicacion:"Sin subenfriamiento, cualquier ca\xEDda de presi\xF3n peque\xF1a convierte el l\xEDquido en vapor, haciendo que la TXV trabaje de forma err\xE1tica.",question:"What is 'Liquid Subcooling' and why is it vital before the TXV?",options:["It is cooling the gas.","It is ensuring the refrigerant is 100% liquid to prevent flash gas in the liquid line, which would reduce valve capacity.","It is heating the oil.","It is lowering the discharge pressure."],explanation:"Without subcooling, any small pressure drop converts liquid into vapor, causing the TXV to work erratically."},{id:"refri_275",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Acumulador de Succi\xF3n' en un sistema con deshielo por gas caliente?",opciones:["Guardar aceite.","Proteger al compresor atrapando el refrigerante l\xEDquido condensado en el evaporador durante el ciclo de calor.","Aumentar la presi\xF3n de succi\xF3n.","Filtrar la humedad."],respuesta_correcta:1,explicacion:"Durante el gas caliente, el evaporador act\xFAa como condensador; al volver al modo fr\xEDo, hay mucho l\xEDquido que podr\xEDa matar al compresor.",question:"What is the function of the suction accumulator in a system with hot gas defrost?",options:["To store oil.","To protect the compressor by trapping liquid refrigerant that condensed in the evaporator during the hot gas cycle.","To increase suction pressure.","To filter moisture."],explanation:"During hot gas defrost, the evaporator acts as a condenser; when switching back to cooling mode, there is a large amount of liquid that could destroy the compressor."},{id:"refri_276",categoria:"REFRI_COMERCIAL",pregunta:"Si un evaporador de congelados tiene el 'Termostato de terminaci\xF3n de deshielo' (Klixon) mal calibrado y abre a 80\xB0F, \xBFqu\xE9 sucede?",opciones:["El equipo enfr\xEDa mejor.","El gabinete se calienta demasiado durante el deshielo, pudiendo da\xF1ar productos o deformar pl\xE1sticos.","El hielo nunca se derrite.","El compresor no arranca."],respuesta_correcta:1,explicacion:"Normalmente corta a 45-55\xB0F. Dejarlo hasta 80\xB0F es desperdicio de energ\xEDa y riesgo t\xE9rmico innecesario.",question:"If a freezer evaporator has a defrost termination thermostat (Klixon) miscalibrated to open at 80\xB0F, what happens?",options:["The unit cools better.","The cabinet heats up excessively during defrost, potentially damaging products or warping plastics.","The ice never melts.","The compressor does not start."],explanation:"It normally cuts out at 45-55\xB0F. Letting it run to 80\xB0F is a waste of energy and an unnecessary thermal risk."},{id:"refri_277",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Presi\xF3n de saturaci\xF3n'?",opciones:["La presi\xF3n m\xE1xima que aguanta el tubo.","La presi\xF3n a la cual un refrigerante cambia de estado (de l\xEDquido a vapor o viceversa) a una temperatura dada.","La presi\xF3n del aceite.","La presi\xF3n atmosf\xE9rica."],respuesta_correcta:1,explicacion:"Es el concepto fundamental para usar la tabla P-T y diagnosticar cualquier sistema.",question:"What is 'saturation pressure'?",options:["The maximum pressure the tubing can withstand.","The pressure at which a refrigerant changes state (from liquid to vapor or vice versa) at a given temperature.","The oil pressure.","Atmospheric pressure."],explanation:"It is the fundamental concept for using the P-T chart and diagnosing any system."},{id:"refri_278",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el sobrecalentamiento es de 35\xB0F. Al intentar ajustar la TXV, esta no responde. \xBFQu\xE9 sucede?",opciones:["La v\xE1lvula est\xE1 perfecta.","El orificio de la v\xE1lvula est\xE1 obstruido o el elemento de poder ha perdido su carga termost\xE1tica.","Falta aceite.","El compresor est\xE1 muy fr\xEDo."],respuesta_correcta:1,explicacion:"Si la v\xE1lvula no abre m\xE1s por m\xE1s que se gire el v\xE1stago, mec\xE1nicamente est\xE1 inoperante o bloqueada.",question:"A technician finds that superheat is 35\xB0F. When attempting to adjust the TXV, it does not respond. What is happening?",options:["The valve is fine.","The valve orifice is blocked or the power element has lost its thermostatic charge.","Low oil.","The compressor is too cold."],explanation:"If the valve will not open further no matter how much the stem is turned, it is mechanically inoperative or blocked."},{id:"refri_279",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, el visor de l\xEDquido muestra burbujas constantes, pero el subenfriamiento a la salida del condensador es de 15\xB0F. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Falta de refrigerante.","Presencia de gases no condensables (aire) en el sistema.","Restricci\xF3n en la l\xEDnea de l\xEDquido o ca\xEDda de presi\xF3n excesiva.","El compresor tiene v\xE1lvulas da\xF1adas."],respuesta_correcta:2,explicacion:"Un subenfriamiento alto (15\xB0F) indica que hay suficiente l\xEDquido. Si hay burbujas despu\xE9s de eso, el l\xEDquido se est\xE1 'evaporando' por una ca\xEDda de presi\xF3n en el filtro o tuber\xEDa.",question:"In an R-404A system, the liquid sight glass shows constant bubbles, but subcooling at the condenser outlet is 15\xB0F. What is the diagnosis?",options:["Low refrigerant charge.","Presence of non-condensable gases (air) in the system.","Restriction in the liquid line or excessive pressure drop.","The compressor has damaged valves."],explanation:"High subcooling (15\xB0F) indicates there is enough liquid. If bubbles appear after that point, the liquid is 'flashing' due to a pressure drop in the filter or piping."},{id:"refri_280",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 mide un 'Man\xF3metro de Compuesto'?",opciones:["Solo presiones altas.","Presiones por encima y por debajo (vac\xEDo) de la presi\xF3n atmosf\xE9rica.","La pureza del gas.","La velocidad del aceite."],respuesta_correcta:1,explicacion:"Es el man\xF3metro de baja (azul), esencial para ver si el sistema est\xE1 operando en vac\xEDo.",question:"What does a 'compound gauge' measure?",options:["Only high pressures.","Pressures above and below (vacuum) atmospheric pressure.","Gas purity.","Oil velocity."],explanation:"It is the low-side gauge (blue), essential for determining if the system is operating in a vacuum."},{id:"refri_281",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 s\xEDntoma provoca una TXV con el bulbo sensor suelto (sin contacto)?",opciones:["Baja presi\xF3n de succi\xF3n.","Inundaci\xF3n del evaporador (Floodback) y presi\xF3n de succi\xF3n alta, ya que la v\xE1lvula 'cree' que el gas est\xE1 caliente y abre totalmente.","Falta de gas.","El condensador se congela."],respuesta_correcta:1,explicacion:"Al sentir la temperatura ambiente, el bulbo ordena m\xE1xima apertura, enviando l\xEDquido al compresor.",question:"What symptom does a TXV with a loose sensing bulb (no contact) cause?",options:["Low suction pressure.","Evaporator flooding (floodback) and high suction pressure, as the valve 'thinks' the gas is hot and opens fully.","Low refrigerant charge.","The condenser freezes."],explanation:"Sensing ambient temperature, the bulb commands maximum opening, sending liquid to the compressor."},{id:"refri_282",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de la 'V\xE1lvula de Retenci\xF3n' (Check Valve) en el drenaje de aceite de un evaporador?",opciones:["Aumentar la presi\xF3n.","Evitar que el refrigerante l\xEDquido regrese al separador de aceite cuando el sistema est\xE1 en reposo.","Enfriar el aceite.","Filtrar el gas."],respuesta_correcta:1,explicacion:"Asegura el flujo en una sola direcci\xF3n hacia el c\xE1rter o reservorio.",question:"What is the function of a check valve in the oil drain of an evaporator?",options:["To increase pressure.","To prevent liquid refrigerant from flowing back to the oil separator when the system is at rest.","To cool the oil.","To filter the gas."],explanation:"It ensures flow in only one direction toward the crankcase or reservoir."},{id:"refri_283",categoria:"REFRI_COMERCIAL",pregunta:"Si un compresor tiene un amperaje de 10A y un voltaje de 220V, y el factor de potencia es 0.9, \xBFcu\xE1ntos Watts reales consume?",opciones:["2200W","1980W","2444W","1100W"],respuesta_correcta:1,explicacion:"$Watts = V 	imes I 	imes PF$. Entonces $220 	imes 10 	imes 0.9 = 1980W$.",question:"If a compressor draws 10A at 220V with a power factor of 0.9, how many actual watts does it consume?",options:["2200W","1980W","2444W","1100W"],explanation:"Watts = V x I x PF. Therefore, 220 x 10 x 0.9 = 1980W."},{id:"refri_284",categoria:"REFRI_COMERCIAL",pregunta:"\xBFC\xF3mo afecta un filtro de aire de evaporador tapado al funcionamiento de la TXV?",opciones:["La hace abrir m\xE1s.","La hace cerrar (Starve), ya que la temperatura del gas de succi\xF3n baja al no haber intercambio de calor.","No la afecta.","La rompe mec\xE1nicamente."],respuesta_correcta:1,explicacion:"Menos calor = gas m\xE1s fr\xEDo saliendo = la TXV cierra para evitar que el l\xEDquido llegue al compresor.",question:"How does a clogged evaporator air filter affect TXV operation?",options:["It makes it open more.","It causes the valve to close (starve), since the suction gas temperature drops due to lack of heat exchange.","It has no effect.","It breaks it mechanically."],explanation:"Less heat = cooler gas leaving = the TXV closes to prevent liquid from reaching the compressor."},{id:"refri_285",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR)?",opciones:["Subir la presi\xF3n de alta.","Evitar la sobrecarga del motor del compresor durante el arranque o tras un deshielo, limitando la presi\xF3n de succi\xF3n m\xE1xima.","Medir el aceite.","Enfriar el evaporador."],respuesta_correcta:1,explicacion:"Act\xFAa como un 'limitador' para que el motor no consuma m\xE1s amperaje del que puede soportar.",question:"What is the function of a crankcase pressure regulator (CPR) valve?",options:["To raise head pressure.","To prevent motor overload on the compressor during startup or after defrost by limiting maximum suction pressure.","To measure oil.","To cool the evaporator."],explanation:"It acts as a 'limiter' so the motor does not draw more amperage than it can handle."},{id:"refri_286",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema comercial tiene el condensador ubicado a 20 metros de altura sobre el compresor. \xBFQu\xE9 componente es OBLIGATORIO?",opciones:["Una TXV m\xE1s grande.","Trampas de aceite (P-traps) cada 6 metros en la l\xEDnea de descarga vertical para asegurar el retorno de lubricante.","Un filtro de succi\xF3n.","Un ventilador extra."],respuesta_correcta:1,explicacion:"Sin trampas, el aceite nunca vencer\xEDa la gravedad en el tramo ascendente, matando al compresor por falta de lubricaci\xF3n.",question:"A commercial system has the condenser located 65 feet above the compressor. What component is MANDATORY?",options:["A larger TXV.","Oil traps (P-traps) every 20 feet on the vertical discharge line to ensure lubricant return.","A suction filter.","An extra fan."],explanation:"Without traps, the oil would never overcome gravity on the vertical rise, killing the compressor from lack of lubrication."},{id:"refri_287",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 2\xB0F en el compresor?",opciones:["Compresor muy eficiente.","Riesgo de golpe de l\xEDquido (Floodback), ya que el refrigerante est\xE1 muy cerca de su punto de saturaci\xF3n.","Falta de gas.","Filtro tapado."],respuesta_correcta:1,explicacion:"Idealmente, el compresor debe recibir gas a 20-30\xB0F de sobrecalentamiento total para estar seguro.",question:"What does a superheat of 2\xB0F at the compressor indicate?",options:["A very efficient compressor.","Risk of liquid slugging (floodback), as the refrigerant is very close to its saturation point.","Low refrigerant charge.","Clogged filter."],explanation:"Ideally, the compressor should receive gas at 20-30\xB0F of total superheat to be safe."},{id:"refri_288",categoria:"REFRI_COMERCIAL",pregunta:"Si la bobina de una v\xE1lvula solenoide est\xE1 quemada, \xBFqu\xE9 s\xEDntomas presenta el sistema?",opciones:["Alta presi\xF3n de succi\xF3n.","Presi\xF3n de succi\xF3n en vac\xEDo y el compresor se detiene por el control de baja (Pump Down).","El ventilador no prende.","Fuga de gas."],respuesta_correcta:1,explicacion:"Al no abrirse, el refrigerante no pasa al evaporador; el compresor succiona lo que queda y se apaga.",question:"If the coil of a solenoid valve is burned out, what symptoms does the system exhibit?",options:["High suction pressure.","Suction pressure in a vacuum and the compressor shuts down on the low-pressure control (pump down).","The fan does not turn on.","Refrigerant leak."],explanation:"Since the valve cannot open, refrigerant does not flow to the evaporator; the compressor pulls down what remains and shuts off."},{id:"refri_289",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula EPR (Evaporator Pressure Regulator)?",opciones:["Bajar la presi\xF3n de descarga.","Mantener una presi\xF3n m\xEDnima en el evaporador para controlar la temperatura del producto (ej. evitar que se congelen las verduras).","Regular el nivel de aceite.","Aumentar el flujo de gas."],respuesta_correcta:1,explicacion:"Se instala en la l\xEDnea de succi\xF3n a la salida de evaporadores que requieren temperaturas m\xE1s altas que el resto del sistema.",question:"What is the function of an EPR (Evaporator Pressure Regulator) valve?",options:["To lower discharge pressure.","To maintain a minimum evaporator pressure to control product temperature (e.g., to prevent vegetables from freezing).","To regulate oil level.","To increase gas flow."],explanation:"It is installed in the suction line at the outlet of evaporators that require higher temperatures than the rest of the system."},{id:"refri_290",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un subenfriamiento de 30\xB0F?",opciones:["Falta de gas.","Exceso de carga de refrigerante, lo que inunda el condensador y reduce su capacidad de intercambio.","Compresor muy eficiente.","Filtro limpio."],respuesta_correcta:1,explicacion:"Subenfriamientos normales rondan los 10\xB0F. 30\xB0F es una se\xF1al clara de sobrecarga.",question:"What does a subcooling of 30\xB0F indicate?",options:["Low refrigerant charge.","Excess refrigerant charge, which floods the condenser and reduces its heat exchange capacity.","Very efficient compressor.","Clean filter."],explanation:"Normal subcooling is around 10\xB0F. A reading of 30\xB0F is a clear sign of overcharge."},{id:"refri_291",categoria:"REFRI_COMERCIAL",pregunta:"Un compresor Scroll hace un ruido fuerte met\xE1lico al apagarse. \xBFQu\xE9 falla?",opciones:["Falta de aceite.","V\xE1lvula check de descarga interna da\xF1ada, permitiendo que el compresor gire en reversa.","Los resortes est\xE1n rotos.","Bajo voltaje."],respuesta_correcta:1,explicacion:"El gas a alta presi\xF3n regresa por las espirales, haci\xE9ndolas girar al rev\xE9s a alta velocidad.",question:"A Scroll compressor makes a loud metallic noise when shutting off. What is the fault?",options:["Low oil.","Damaged internal discharge check valve, allowing the compressor to spin in reverse.","Broken springs.","Low voltage."],explanation:"High-pressure gas flows back through the scrolls, spinning them in reverse at high speed."},{id:"refri_292",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Trampa de Aceite' y d\xF3nde se pone?",opciones:["Un filtro en la l\xEDnea de l\xEDquido.","Un sif\xF3n en la l\xEDnea de succi\xF3n vertical (ascendente) para ayudar al retorno de aceite al compresor.","Un tanque despu\xE9s del condensador.","Una v\xE1lvula de seguridad."],respuesta_correcta:1,explicacion:"Recoge el aceite hasta que el flujo de gas tiene la velocidad suficiente para empujarlo hacia arriba.",question:"What is an 'oil trap' and where is it installed?",options:["A filter in the liquid line.","A siphon (P-trap) in a vertical (rising) suction line to assist oil return to the compressor.","A tank after the condenser.","A safety valve."],explanation:"It collects oil until the gas flow has enough velocity to push it upward."},{id:"refri_293",categoria:"REFRI_COMERCIAL",pregunta:"Si mides un capacitor de marcha y te da un 20% menos de su valor nominal, \xBFqu\xE9 haces?",opciones:["Lo dejas, todav\xEDa sirve.","Lo reemplazas; una p\xE9rdida mayor al 10% aumenta el consumo y calienta el devanado de arranque del motor.","Le pones otro en serie.","Lo limpias con solvente."],respuesta_correcta:1,explicacion:"La salud del capacitor es la salud del compresor a largo plazo.",question:"If you test a run capacitor and it reads 20% below its rated value, what do you do?",options:["Leave it, it still works.","Replace it; a loss greater than 10% increases power consumption and overheats the motor start winding.","Put another one in series.","Clean it with solvent."],explanation:"The health of the capacitor is the long-term health of the compressor."},{id:"refri_294",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, si el sobrecalentamiento en el evaporador es de 8\xB0F pero el gas llega al compresor a 65\xB0F (estando el cuarto a 35\xB0F), \xBFqu\xE9 problema t\xE9rmico existe?",opciones:["Falta de refrigerante.","Ganancia de calor excesiva en la l\xEDnea de succi\xF3n por falta de aislamiento o tuber\xEDa mal ubicada.","La TXV est\xE1 fallando.","El compresor est\xE1 perdiendo eficiencia."],respuesta_correcta:1,explicacion:"Un gas de succi\xF3n demasiado caliente reduce la densidad del refrigerante, disminuye la capacidad de enfriamiento del motor y eleva peligrosamente la temperatura de descarga.",question:"In an R-404A system, if the evaporator superheat is 8\xB0F but the gas arrives at the compressor at 65\xB0F (with the box at 35\xB0F), what thermal problem exists?",options:["Low refrigerant charge.","Excessive heat gain in the suction line due to missing insulation or poorly routed piping.","The TXV is failing.","The compressor is losing efficiency."],explanation:"Suction gas that is too hot reduces refrigerant density, decreases the motor's cooling capacity, and dangerously raises discharge temperature."},{id:"refri_295",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede con la capacidad de un compresor si la temperatura de succi\xF3n aumenta (gas m\xE1s caliente/menos denso)?",opciones:["La capacidad aumenta.","La capacidad disminuye porque el compresor mueve menos masa de refrigerante por cada embolada.","Se mantiene igual.","El compresor enfr\xEDa m\xE1s el aceite."],respuesta_correcta:1,explicacion:"La refrigeraci\xF3n es un juego de masa, no de volumen. Gas caliente ocupa m\xE1s espacio pero pesa menos; el compresor rinde menos.",question:"What happens to compressor capacity if suction temperature increases (hotter/less dense gas)?",options:["Capacity increases.","Capacity decreases because the compressor moves less refrigerant mass per stroke.","It stays the same.","The compressor cools the oil more."],explanation:"Refrigeration is a mass game, not a volume game. Hot gas takes up more space but weighs less; the compressor delivers less."},{id:"refri_296",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema de refrigeraci\xF3n usa R-448A. \xBFC\xF3mo se debe leer el sobrecalentamiento?",opciones:["Usando el punto de burbuja (Bubble point).","Usando el punto de roc\xEDo (Dew point) debido al deslizamiento t\xE9rmico (glide).","No importa, la tabla es una sola.","Solo con el term\xF3metro de succi\xF3n."],respuesta_correcta:1,explicacion:"En mezclas con glide, el sobrecalentamiento se calcula con la temperatura de roc\xEDo (vapor saturado).",question:"A refrigeration system uses R-448A. How should superheat be read?",options:["Using the bubble point.","Using the dew point due to temperature glide.","It does not matter, the chart is the same.","Only with the suction thermometer."],explanation:"For blends with glide, superheat is calculated using the dew point temperature (saturated vapor)."},{id:"refri_297",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de evaporaci\xF3n (EPR)?",opciones:["Aumentar la presi\xF3n de descarga.","Mantener una presi\xF3n m\xEDnima en un evaporador espec\xEDfico dentro de un sistema con varios evaporadores a distintas temperaturas.","Controlar el subenfriamiento.","Detener el compresor."],respuesta_correcta:1,explicacion:"Evita que un evaporador de media temperatura (ej. verduras) se congele cuando el rack trabaja para un evaporador de baja (ej. helados).",question:"What is the function of an evaporator pressure regulator (EPR) valve?",options:["To increase discharge pressure.","To maintain a minimum pressure in a specific evaporator within a system with multiple evaporators at different temperatures.","To control subcooling.","To stop the compressor."],explanation:"It prevents a medium-temperature evaporator (e.g., produce) from freezing when the rack is running for a low-temperature evaporator (e.g., ice cream)."},{id:"refri_298",categoria:"REFRI_COMERCIAL",pregunta:"Si el aceite del c\xE1rter est\xE1 muy fr\xEDo, el refrigerante se condensa en \xE9l. Al arrancar, \xBFqu\xE9 fen\xF3meno ocurre?",opciones:["Arranque suave.","Efervescencia (Foaming) que puede causar que la bomba de aceite succione vapor en lugar de l\xEDquido, fallando la lubricaci\xF3n.","El compresor enfr\xEDa m\xE1s r\xE1pido.","Se limpia el filtro de succi\xF3n."],respuesta_correcta:1,explicacion:"El refrigerante l\xEDquido al fondo del c\xE1rter se evapora explosivamente al bajar la presi\xF3n del arranque, creando espuma que no lubrica.",question:"If the crankcase oil is very cold, refrigerant condenses in it. What phenomenon occurs at startup?",options:["A smooth startup.","Foaming (effervescence) that can cause the oil pump to draw vapor instead of liquid, resulting in lubrication failure.","The compressor cools faster.","The suction filter gets cleaned."],explanation:"The liquid refrigerant at the bottom of the crankcase boils off explosively when pressure drops on startup, creating foam that cannot lubricate."},{id:"refri_299",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede si el bulbo de la TXV se instala en un tramo de tuber\xEDa donde el aceite se acumula (trampa)?",opciones:["La v\xE1lvula lee la temperatura exacta.","La lectura ser\xE1 err\xE1tica y lenta, ya que el aceite act\xFAa como un aislante t\xE9rmico entre el gas y el bulbo.","La v\xE1lvula se abre al 100% siempre.","La v\xE1lvula se rompe."],respuesta_correcta:1,explicacion:"El bulbo debe sentir la temperatura del gas de succi\xF3n; el aceite estancado tiene una inercia t\xE9rmica que falsea el control.",question:"What happens if the TXV sensing bulb is installed on a section of tubing where oil accumulates (trap)?",options:["The valve reads the exact temperature.","The reading will be erratic and sluggish, as the oil acts as a thermal insulator between the gas and the bulb.","The valve opens 100% at all times.","The valve breaks."],explanation:"The bulb must sense the suction gas temperature; stagnant oil has a thermal lag that falsifies the control signal."},{id:"refri_300",categoria:"REFRI_COMERCIAL",pregunta:"Si el visor de l\xEDquido muestra un color 'verde' pero hay burbujas constantes, el t\xE9cnico debe:",opciones:["Cambiar el filtro.","A\xF1adir refrigerante; el verde indica que no hay humedad, pero las burbujas indican falta de carga o flash gas.","A\xF1adir aceite.","Limpiar el evaporador."],respuesta_correcta:1,explicacion:"El color solo mide humedad. El estado f\xEDsico (burbujas) mide la calidad de la condensaci\xF3n o la cantidad de gas.",question:"If the liquid sight glass shows a 'green' color but there are constant bubbles, the technician should:",options:["Replace the filter.","Add refrigerant; green indicates no moisture, but bubbles indicate low charge or flash gas.","Add oil.","Clean the evaporator."],explanation:"The color only measures moisture. The physical state (bubbles) indicates the quality of condensation or the amount of refrigerant."},{id:"refri_301",categoria:"REFRI_COMERCIAL",pregunta:"\xBFC\xF3mo se calcula el sobrecalentamiento total (Total Superheat)?",opciones:["Temp. entrada evaporador - Temp. salida evaporador.","Temp. tuber\xEDa de succi\xF3n (a 6' del compresor) - Temp. de saturaci\xF3n de baja.","Presi\xF3n de alta - Presi\xF3n de baja.","Amperaje / Voltaje."],respuesta_correcta:1,explicacion:"Mide cu\xE1nto calor gan\xF3 el gas desde el evaporador hasta el compresor; es vital para asegurar que el motor se enfr\xEDe y no reciba l\xEDquido.",question:"How is total superheat calculated?",options:["Evaporator inlet temp minus evaporator outlet temp.","Suction line temperature (6 inches from the compressor) minus low-side saturation temperature.","High pressure minus low pressure.","Amperage divided by voltage."],explanation:"It measures how much heat the gas gained from the evaporator to the compressor; it is vital to ensure the motor is cooled and does not receive liquid."},{id:"refri_302",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es un 'Intercambiador de Placas' y por qu\xE9 se usa en refrigeraci\xF3n comercial?",opciones:["Un tipo de filtro.","Un intercambiador muy compacto y eficiente que usa placas met\xE1licas soldadas para transferir calor entre dos fluidos.","Una placa de hielo.","Un control de presi\xF3n."],respuesta_correcta:1,explicacion:"Ofrece una transferencia t\xE9rmica superior en un espacio muy reducido, ideal para enfriadores de leche o sistemas de glicol.",question:"What is a 'Plate Heat Exchanger' and why is it used in commercial refrigeration?",options:["A type of filter.","A very compact and efficient heat exchanger that uses brazed metal plates to transfer heat between two fluids.","An ice plate.","A pressure control."],explanation:"It offers superior heat transfer in a very small footprint, ideal for milk coolers or glycol systems."},{id:"refri_303",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de descarga fluct\xFAa r\xEDtmicamente (agujas vibrando). \xBFQu\xE9 sospecha?",opciones:["Falta de aceite.","V\xE1lvulas de descarga del compresor da\xF1adas o presencia de aire en el sistema.","Termostato defectuoso.","Voltaje bajo."],respuesta_correcta:1,explicacion:"Si las v\xE1lvulas no cierran bien, hay un retorno de gas en cada embolada que causa pulsaciones en el man\xF3metro.",question:"A technician finds that discharge pressure fluctuates rhythmically (gauge needles vibrating). What is suspected?",options:["Low oil.","Damaged compressor discharge valves or the presence of air in the system.","Defective thermostat.","Low voltage."],explanation:"If the valves do not seal properly, gas returns on each stroke causing pulsations on the gauge."},{id:"refri_304",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema de refrigeraci\xF3n comercial usa una TXV. Si el subenfriamiento es de 12\xB0F y el sobrecalentamiento es de 25\xB0F con presiones bajas, \xBFcu\xE1l es el problema?",opciones:["Falta de carga.","Restricci\xF3n en el lado de alta o TXV cerrada en exceso.","Condensador sucio.","Exceso de carga."],respuesta_correcta:1,explicacion:"Si hay subenfriamiento, el condensador tiene l\xEDquido. Si el sobrecalentamiento es alto y la succi\xF3n baja, el gas no est\xE1 pasando al evaporador.",question:"A commercial refrigeration system uses a TXV. If subcooling is 12\xB0F and superheat is 25\xB0F with low pressures, what is the problem?",options:["Low refrigerant charge.","Restriction on the high side or TXV closed excessively.","Dirty condenser.","Excess charge."],explanation:"If there is subcooling, the condenser has liquid. If superheat is high and suction is low, the refrigerant is not passing into the evaporator."},{id:"refri_305",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR)?",opciones:["Subir la presi\xF3n de alta.","Evitar la sobrecarga del motor del compresor durante el arranque o tras un deshielo, limitando la presi\xF3n de succi\xF3n m\xE1xima.","Medir el aceite.","Enfriar el evaporador."],respuesta_correcta:1,explicacion:"Act\xFAa como un 'limitador' para que el motor no consuma m\xE1s amperaje del que puede soportar.",question:"What is the function of a crankcase pressure regulator (CPR) valve?",options:["To raise head pressure.","To prevent compressor motor overload during startup or after defrost by limiting maximum suction pressure.","To measure oil.","To cool the evaporator."],explanation:"It acts as a 'limiter' so the motor does not draw more amperage than it can handle."},{id:"refri_306",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de aceite neta es de 10 PSI. La presi\xF3n de succi\xF3n es de 40 PSI. \xBFCu\xE1l es la presi\xF3n de la bomba de aceite?",opciones:["10 PSI","30 PSI","50 PSI","400 PSI"],respuesta_correcta:2,explicacion:"Presi\xF3n neta = Presi\xF3n de Bomba - Presi\xF3n de C\xE1rter (Succi\xF3n). Entonces, 10 = X - 40; X = 50 PSI.",question:"A technician finds that net oil pressure is 10 PSI. Suction pressure is 40 PSI. What is the oil pump pressure?",options:["10 PSI","30 PSI","50 PSI","400 PSI"],explanation:"Net pressure = Pump Pressure - Crankcase (Suction) Pressure. Therefore, 10 = X - 40; X = 50 PSI."},{id:"refri_307",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 2\xB0F en el compresor?",opciones:["Compresor muy eficiente.","Riesgo de golpe de l\xEDquido (Floodback), ya que el refrigerante est\xE1 muy cerca de su punto de saturaci\xF3n.","Falta de gas.","Filtro tapado."],respuesta_correcta:1,explicacion:"Idealmente, el compresor debe recibir gas a 20-30\xB0F de sobrecalentamiento total para estar seguro.",question:"What does a superheat of 2\xB0F at the compressor indicate?",options:["A very efficient compressor.","Risk of liquid slugging (floodback), as the refrigerant is very close to its saturation point.","Low refrigerant charge.","Clogged filter."],explanation:"Ideally, the compressor should receive gas at 20-30\xB0F of total superheat to be safe."},{id:"refri_308",categoria:"REFRI_COMERCIAL",pregunta:"Si la bobina de una v\xE1lvula solenoide est\xE1 quemada, \xBFqu\xE9 s\xEDntomas presenta el sistema?",opciones:["Alta presi\xF3n de succi\xF3n.","Presi\xF3n de succi\xF3n en vac\xEDo y el compresor se detiene por el control de baja (Pump Down).","El ventilador no prende.","Fuga de gas."],respuesta_correcta:1,explicacion:"Al no abrirse, el refrigerante no pasa al evaporador; el compresor succiona lo que queda y se apaga.",question:"If the coil of a solenoid valve is burned out, what symptoms does the system exhibit?",options:["High suction pressure.","Suction pressure drops to a vacuum and the compressor shuts down on the low-pressure control (pump down).","The fan does not turn on.","Refrigerant leak."],explanation:"Since the valve cannot open, refrigerant does not flow to the evaporator; the compressor pulls down what remains and shuts off."},{id:"refri_309",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula EPR (Evaporator Pressure Regulator)?",opciones:["Bajar la presi\xF3n de descarga.","Mantener una presi\xF3n m\xEDnima en el evaporador para controlar la temperatura del producto (ej. evitar que se congelen las verduras).","Regular el nivel de aceite.","Aumentar el flujo de gas."],respuesta_correcta:1,explicacion:"Se instala en la l\xEDnea de succi\xF3n a la salida de evaporadores que requieren temperaturas m\xE1s altas que el resto del sistema.",question:"What is the function of an EPR (Evaporator Pressure Regulator) valve?",options:["To lower discharge pressure.","To maintain a minimum evaporator pressure to control product temperature (e.g., to prevent vegetables from freezing).","To regulate oil level.","To increase gas flow."],explanation:"It is installed in the suction line at the outlet of evaporators that require higher temperatures than the rest of the system."},{id:"refri_310",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un subenfriamiento de 30\xB0F?",opciones:["Falta de gas.","Exceso de carga de refrigerante, lo que inunda el condensador y reduce su capacidad de intercambio.","Compresor muy eficiente.","Filtro limpio."],respuesta_correcta:1,explicacion:"Subenfriamientos normales rondan los 10\xB0F. 30\xB0F es una se\xF1al clara de sobrecarga.",question:"What does a subcooling of 30\xB0F indicate?",options:["Low refrigerant charge.","Excess refrigerant charge, which floods the condenser and reduces its heat exchange capacity.","Very efficient compressor.","Clean filter."],explanation:"Normal subcooling is around 10\xB0F. A reading of 30\xB0F is a clear sign of overcharge."},{id:"refri_311",categoria:"REFRI_COMERCIAL",pregunta:"Un compresor Scroll hace un ruido fuerte met\xE1lico al apagarse. \xBFQu\xE9 falla?",opciones:["Falta de aceite.","V\xE1lvula check de descarga interna da\xF1ada, permitiendo que el compresor gire en reversa.","Los resortes est\xE1n rotos.","Bajo voltaje."],respuesta_correcta:1,explicacion:"El gas a alta presi\xF3n regresa por las espirales, haci\xE9ndolas girar al rev\xE9s a alta velocidad.",question:"A Scroll compressor makes a loud metallic noise when shutting off. What is the fault?",options:["Low oil.","Damaged internal discharge check valve, allowing the compressor to spin in reverse.","Broken springs.","Low voltage."],explanation:"High-pressure gas flows back through the scrolls, spinning them in reverse at high speed."},{id:"refri_312",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Trampa de Aceite' y d\xF3nde se pone?",opciones:["Un filtro en la l\xEDnea de l\xEDquido.","Un sif\xF3n en la l\xEDnea de succi\xF3n vertical (ascendente) para ayudar al retorno de aceite al compresor.","Un tanque despu\xE9s del condensador.","Una v\xE1lvula de seguridad."],respuesta_correcta:1,explicacion:"Recoge el aceite hasta que el flujo de gas tiene la velocidad suficiente para empujarlo hacia arriba.",question:"What is an 'oil trap' and where is it installed?",options:["A filter in the liquid line.","A siphon (P-trap) in a vertical (rising) suction line to assist oil return to the compressor.","A tank after the condenser.","A safety valve."],explanation:"It collects oil until the gas flow has enough velocity to push it upward."},{id:"refri_313",categoria:"REFRI_COMERCIAL",pregunta:"Si mides un capacitor de marcha y te da un 20% menos de su valor nominal, \xBFqu\xE9 haces?",opciones:["Lo dejas, todav\xEDa sirve.","Lo reemplazas; una p\xE9rdida mayor al 10% aumenta el consumo y calienta el devanado de arranque del motor.","Le pones otro en serie.","Lo limpias con solvente."],respuesta_correcta:1,explicacion:"La salud del capacitor es la salud del compresor a largo plazo.",question:"If you test a run capacitor and it reads 20% below its rated value, what do you do?",options:["Leave it, it still works.","Replace it; a loss greater than 10% increases power consumption and overheats the motor start winding.","Put another one in series.","Clean it with solvent."],explanation:"The health of the capacitor is the long-term health of the compressor."},{id:"refri_314",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema tiene una temperatura de saturaci\xF3n en el condensador de 110\xB0F y la temperatura ambiente es de 95\xB0F. \xBFEs este un 'Split' de condensador normal?",opciones:["No, es muy bajo.","S\xED, un split de 10-30\xB0F sobre la temperatura ambiente es est\xE1ndar en sistemas enfriados por aire.","No, la presi\xF3n deber\xEDa ser mayor.","Depende de la humedad."],respuesta_correcta:1,explicacion:"El split (TD del condensador) indica qu\xE9 tan bien se est\xE1 rechazando el calor.",question:"A system has a condensing saturation temperature of 110\xB0F and the ambient temperature is 95\xB0F. Is this a normal condenser 'split'?",options:["No, it is too low.","Yes, a split of 10-30\xB0F above ambient temperature is standard for air-cooled systems.","No, the pressure should be higher.","It depends on the humidity."],explanation:"The condenser split (TD) indicates how well the system is rejecting heat."},{id:"refri_315",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 ocurre si el orificio de la TXV est\xE1 parcialmente obstruido?",opciones:["Alta presi\xF3n de succi\xF3n.","Baja presi\xF3n de succi\xF3n y sobrecalentamiento muy alto.","El compresor consume m\xE1s amperaje.","Se congela la l\xEDnea de descarga."],respuesta_correcta:1,explicacion:"Al no entrar suficiente gas al evaporador, la presi\xF3n cae y el gas restante se calienta excesivamente.",question:"What happens if the orifice of the TXV is partially blocked?",options:["High suction pressure.","Low suction pressure and very high superheat.","The compressor draws more amperage.","The discharge line freezes."],explanation:"Without enough refrigerant entering the evaporator, pressure drops and the remaining gas becomes excessively superheated."},{id:"refri_316",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Desecante' dentro de un filtro deshidratador?",opciones:["Separar el aceite.","Atrapar la humedad y los \xE1cidos presentes en el refrigerante.","Reducir la presi\xF3n del gas.","Limpia las aletas del condensador."],respuesta_correcta:1,explicacion:"La humedad causa corrosi\xF3n y congelamiento en las v\xE1lvulas; el desecante (zeolita/al\xFAmina) la retiene.",question:"What is the function of the 'desiccant' inside a filter drier?",options:["To separate the oil.","To trap moisture and acids present in the refrigerant.","To reduce gas pressure.","To clean the condenser fins."],explanation:"Moisture causes corrosion and freezing in valves; the desiccant (zeolite/alumina) retains it."},{id:"refri_317",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 significa un 'Sistema Inundado' en refrigeraci\xF3n comercial?",opciones:["Que se llen\xF3 de agua de lluvia.","Un sistema donde el evaporador est\xE1 lleno de refrigerante l\xEDquido y el control de nivel regula la entrada.","Un sistema con exceso de carga.","Un sistema que gotea aceite."],respuesta_correcta:1,explicacion:"Se usa para maximizar la eficiencia en sistemas grandes, manteniendo mojada toda la superficie de intercambio.",question:"What does a 'flooded system' mean in commercial refrigeration?",options:["That it filled with rainwater.","A system where the evaporator is full of liquid refrigerant and a level control regulates the inlet.","A system with excess charge.","A system that leaks oil."],explanation:"It is used to maximize efficiency in large systems by keeping the entire heat exchange surface wetted."},{id:"refri_318",categoria:"REFRI_COMERCIAL",pregunta:"Si un t\xE9cnico encuentra que el aceite en el visor del compresor tiene espuma excesiva durante el funcionamiento, \xBFqu\xE9 sospecha?",opciones:["Que el aceite es de buena calidad.","Presencia de refrigerante l\xEDquido mezclado con el aceite (migraci\xF3n o inundaci\xF3n).","Que el filtro de aceite est\xE1 tapado.","Baja presi\xF3n de succi\xF3n."],respuesta_correcta:1,explicacion:"Al bajar la presi\xF3n en el c\xE1rter, el refrigerante disuelto en el aceite hierve bruscamente, creando espuma que no lubrica bien.",question:"If a technician finds that the oil in the compressor sight glass has excessive foam during operation, what is suspected?",options:["The oil is of good quality.","Liquid refrigerant mixed with the oil (migration or flooding).","The oil filter is clogged.","Low suction pressure."],explanation:"As pressure drops in the crankcase, refrigerant dissolved in the oil boils off violently, creating foam that provides poor lubrication."},{id:"refri_319",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-448A (mezcla con alto glide), \xBFc\xF3mo se debe ajustar el sobrecalentamiento de la TXV correctamente?",opciones:["Usando el promedio entre el punto de roc\xEDo y burbuja.","Restando la temperatura de tuber\xEDa menos la temperatura de roc\xEDo (Dew Point) a esa presi\xF3n.","Usando solo la temperatura de burbuja.","No se puede ajustar, viene fijo de f\xE1brica."],respuesta_correcta:1,explicacion:"Para calcular el sobrecalentamiento en mezclas zeotr\xF3picas, siempre se utiliza el valor de 'Dew Point' (Roc\xEDo) porque representa el estado 100% vapor.",question:"In a system using R-448A (blend with high glide), how should TXV superheat be adjusted correctly?",options:["Using the average between the dew point and bubble point.","By subtracting the pipe temperature minus the dew point temperature at that pressure.","Using only the bubble point temperature.","It cannot be adjusted; it is factory set."],explanation:"To calculate superheat in zeotropic blends, the dew point value is always used because it represents the 100% vapor state."},{id:"refri_320",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula 'KVP' instalada antes de la succi\xF3n de un evaporador?",opciones:["Aumentar la presi\xF3n de descarga.","Evitar que la presi\xF3n de evaporaci\xF3n caiga por debajo de un punto ajustado para evitar congelamiento de producto delicado.","Regular el flujo de aceite.","Detener el compresor por alta presi\xF3n."],respuesta_correcta:1,explicacion:"La KVP (Reguladora de Presi\xF3n de Evaporaci\xF3n) mantiene una temperatura m\xEDnima en el serpent\xEDn independientemente de la succi\xF3n del rack.",question:"What is the function of a 'KVP' valve installed before the suction of an evaporator?",options:["To increase discharge pressure.","To prevent evaporator pressure from dropping below a set point to avoid freezing of delicate products.","To regulate oil flow.","To shut down the compressor on high pressure."],explanation:"The KVP (Evaporator Pressure Regulator) maintains a minimum coil temperature regardless of the rack suction pressure."},{id:"refri_321",categoria:"REFRI_COMERCIAL",pregunta:"Mides un compresor semi-herm\xE9tico y el amperaje en las tres fases es: L1: 15A, L2: 15A, L3: 28A. \xBFQu\xE9 sospechas?",opciones:["Funcionamiento normal.","Falla inminente del devanado en la fase L3 o un desequilibrio de voltaje grave en la alimentaci\xF3n.","Que el capacitor de marcha est\xE1 fallando.","Que el compresor es de dos etapas."],respuesta_correcta:1,explicacion:"Un desequilibrio de corriente mayor al 10% indica problemas el\xE9ctricos serios que quemar\xE1n el motor por calor localizado.",question:"You measure a semi-hermetic compressor and the amperage on the three phases is: L1: 15A, L2: 15A, L3: 28A. What do you suspect?",options:["Normal operation.","Imminent winding failure on phase L3 or a severe voltage imbalance in the power supply.","The run capacitor is failing.","The compressor is two-stage."],explanation:"A current imbalance greater than 10% indicates serious electrical problems that will burn the motor from localized heat."},{id:"refri_322",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 40\xB0F medido a la entrada del compresor?",opciones:["Compresor muy seguro.","Peligro de sobrecalentamiento del motor (motor overheating) debido a que el gas llega demasiado caliente para retirar el calor de las bobinas.","Falta de aceite.","Exceso de refrigerante."],respuesta_correcta:1,explicacion:"El gas de succi\xF3n debe entrar 'fresco' para enfriar el motor herm\xE9tico/semi-herm\xE9tico. 40\xB0F de superheat total es excesivo.",question:"What does a superheat of 40\xB0F measured at the compressor inlet indicate?",options:["A very safe compressor.","Risk of motor overheating because the gas arrives too hot to remove heat from the windings.","Low oil.","Excess refrigerant."],explanation:"The suction gas must enter 'cool' to remove heat from the hermetic/semi-hermetic motor. A total superheat of 40\xB0F is excessive."},{id:"refri_323",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de alta es normal pero el visor de l\xEDquido est\xE1 vac\xEDo. Al revisar, el receptor de l\xEDquido est\xE1 lleno. \xBFQu\xE9 falla?",opciones:["Falta de gas.","V\xE1lvula de salida del receptor (King Valve) cerrada o filtro de salida del receptor obstruido.","Compresor sin fuerza.","Condensador muy limpio."],respuesta_correcta:1,explicacion:"Si el l\xEDquido est\xE1 en el tanque pero no llega al visor, hay un bloqueo mec\xE1nico entre ambos.",question:"A technician finds that head pressure is normal but the liquid sight glass is empty. Upon inspection, the liquid receiver is full. What is the fault?",options:["Low refrigerant charge.","The receiver outlet valve (King Valve) is closed or the receiver outlet filter is blocked.","Weak compressor.","Very clean condenser."],explanation:"If the liquid is in the tank but is not reaching the sight glass, there is a mechanical blockage between the two."},{id:"refri_324",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Subenfriamiento' y c\xF3mo se mide?",opciones:["Temp. succi\xF3n - Temp. saturaci\xF3n baja.","Temp. saturaci\xF3n alta (man\xF3metro) - Temp. real de la l\xEDnea de l\xEDquido (term\xF3metro).","Presi\xF3n alta / Presi\xF3n baja.","Amperaje del condensador."],respuesta_correcta:1,explicacion:"Es la medida de cu\xE1nto calor se le quit\xF3 al l\xEDquido despu\xE9s de condensarse. Vital para diagnosticar la carga en sistemas con TXV.",question:"What is 'subcooling' and how is it measured?",options:["Suction temp minus low-side saturation temp.","High-side saturation temperature (from the gauge) minus the actual liquid line temperature (from a thermometer).","High pressure divided by low pressure.","Condenser amperage."],explanation:"It is a measure of how much heat was removed from the liquid after it condensed. It is vital for diagnosing charge on TXV systems."},{id:"refri_325",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un 'Acumulador de Succi\xF3n'?",opciones:["Almacenar l\xEDquido para la TXV.","Atrapar refrigerante l\xEDquido y permitir que se evapore antes de entrar al compresor, evitando golpes de l\xEDquido.","Filtrar el aceite sucio.","Enfriar el gas de descarga."],respuesta_correcta:1,explicacion:"Es un recipiente de seguridad esencial en sistemas comerciales propensos a variaciones de carga t\xE9rmica.",question:"What is the purpose of a suction accumulator?",options:["To store liquid for the TXV.","To trap liquid refrigerant and allow it to evaporate before entering the compressor, preventing liquid slugging.","To filter dirty oil.","To cool the discharge gas."],explanation:"It is an essential safety vessel in commercial systems prone to thermal load variations."},{id:"refri_326",categoria:"REFRI_COMERCIAL",pregunta:"Si una TXV est\xE1 'Cazando' (Hunting) constantemente, \xBFcu\xE1l es el ajuste inicial para estabilizarla?",opciones:["Cerrar la v\xE1lvula totalmente.","Aumentar el sobrecalentamiento (girar v\xE1stago a la derecha) para ralentizar la respuesta de la v\xE1lvula.","Abrir la v\xE1lvula al m\xE1ximo.","Cambiar el gas."],respuesta_correcta:1,explicacion:"Al aumentar el superheat, la v\xE1lvula se vuelve menos sensible a cambios peque\xF1os, estabilizando el flujo.",question:"If a TXV is constantly 'hunting,' what is the initial adjustment to stabilize it?",options:["Close the valve completely.","Increase the superheat setting (turn the stem clockwise) to slow down the valve's response.","Open the valve to maximum.","Change the refrigerant."],explanation:"By increasing superheat, the valve becomes less sensitive to small changes, stabilizing the flow."},{id:"refri_327",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica una presi\xF3n de descarga extremadamente alta y un condensador limpio?",opciones:["Falta de refrigerante.","Presencia de gases no condensables (aire) o exceso de carga de refrigerante.","V\xE1lvulas de compresor rotas.","Filtro deshidratador nuevo."],respuesta_correcta:1,explicacion:"El aire se acumula en el condensador y no se condensa, ocupando espacio y disparando la presi\xF3n por ley de presiones parciales.",question:"What does extremely high discharge pressure with a clean condenser indicate?",options:["Low refrigerant charge.","Presence of non-condensable gases (air) or excess refrigerant charge.","Broken compressor valves.","New filter drier."],explanation:"Air accumulates in the condenser and does not condense, taking up space and driving up pressure according to Dalton's law of partial pressures."},{id:"refri_328",categoria:"REFRI_COMERCIAL",pregunta:"Mides 0 ohms entre los terminales de un compresor y la carcasa de tierra. \xBFQu\xE9 significa?",opciones:["El motor tiene excelente conexi\xF3n el\xE9ctrica.","El motor est\xE1 aterrizado (quemado a tierra) y es un peligro de electrocuci\xF3n.","Es normal en sistemas trif\xE1sicos.","El mult\xEDmetro est\xE1 mal configurado."],respuesta_correcta:1,explicacion:"Nunca debe haber continuidad entre los devanados internos y el chasis del equipo.",question:"You measure 0 ohms between the compressor terminals and the ground casing. What does this mean?",options:["The motor has an excellent electrical connection.","The motor is grounded (shorted to ground) and is an electrocution hazard.","This is normal in three-phase systems.","The multimeter is misconfigured."],explanation:"There should never be continuity between the internal windings and the equipment chassis."},{id:"refri_329",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la ca\xEDda de presi\xF3n m\xE1xima permitida en una l\xEDnea de succi\xF3n de larga distancia?",opciones:["10 PSI constantes.","La equivalente a una ca\xEDda de 2\xB0F en la temperatura de saturaci\xF3n del refrigerante.","50% de la presi\xF3n total.","No hay l\xEDmite."],respuesta_correcta:1,explicacion:"Exceder esta ca\xEDda reduce dr\xE1sticamente la capacidad del compresor y su eficiencia (COP).",question:"What is the maximum allowable pressure drop in a long-run suction line?",options:["A constant 10 PSI.","The equivalent of a 2\xB0F drop in the refrigerant saturation temperature.","50% of the total pressure.","There is no limit."],explanation:"Exceeding this drop drastically reduces compressor capacity and efficiency (COP)."},{id:"refri_330",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula 'KVR'?",opciones:["Controlar la presi\xF3n del evaporador.","Mantener una presi\xF3n m\xEDnima de condensaci\xF3n en climas fr\xEDos inundando el condensador con l\xEDquido.","Regular el flujo de aceite.","Limitar la presi\xF3n de succi\xF3n."],respuesta_correcta:1,explicacion:"Asegura que la TXV siempre tenga suficiente diferencial de presi\xF3n para alimentar el evaporador en invierno.",question:"What is the function of a 'KVR' valve?",options:["To control evaporator pressure.","To maintain a minimum condensing pressure in cold climates by flooding the condenser with liquid.","To regulate oil flow.","To limit suction pressure."],explanation:"It ensures the TXV always has sufficient pressure differential to feed the evaporator in winter."},{id:"refri_331",categoria:"REFRI_COMERCIAL",pregunta:"Si el aceite POE se vuelve oscuro y tiene olor picante, \xBFcu\xE1l es el siguiente paso?",opciones:["A\xF1adir m\xE1s aceite nuevo.","Realizar una prueba de acidez; el aceite probablemente se ha descompuesto por humedad.","Cambiar el refrigerante solamente.","No hacer nada, es normal con el tiempo."],respuesta_correcta:1,explicacion:"El aceite POE \xE1cido destruir\xE1 el esmalte del motor, provocando un cortocircuito (burnout).",question:"If POE oil turns dark and has a pungent smell, what is the next step?",options:["Add more fresh oil.","Perform an acid test; the oil has likely broken down due to moisture.","Change the refrigerant only.","Do nothing, it is normal over time."],explanation:"Acidic POE oil will destroy the motor winding enamel, leading to a short circuit (burnout)."},{id:"refri_332",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 0\xB0F y una succi\xF3n normal?",opciones:["Evaporador perfecto.","Retorno de l\xEDquido al compresor (Floodback).","Falta de gas.","Filtro tapado."],respuesta_correcta:1,explicacion:"Significa que el refrigerante no gan\xF3 nada de calor tras evaporarse, por lo que sigue siendo l\xEDquido saturado.",question:"What does a superheat of 0\xB0F with normal suction pressure indicate?",options:["A perfect evaporator.","Liquid returning to the compressor (floodback).","Low refrigerant charge.","Clogged filter."],explanation:"It means the refrigerant gained no heat after evaporating, so it is still saturated liquid."},{id:"refri_333",categoria:"REFRI_COMERCIAL",pregunta:"Un compresor arranca pero se detiene por el protector t\xE9rmico a los 10 segundos. El amperaje es 5 veces el nominal. \xBFQu\xE9 falla?",opciones:["Falta de gas.","Motor trabado mec\xE1nicamente o capacitor de arranque da\xF1ado.","Termostato roto.","Bajo voltaje en la l\xEDnea."],respuesta_correcta:1,explicacion:"El motor consume el amperaje de rotor bloqueado (LRA) al no poder romper la inercia inicial.",question:"A compressor starts but shuts down on the thermal protector after 10 seconds. Amperage is 5 times the rated value. What is the fault?",options:["Low refrigerant charge.","Mechanically seized motor or damaged start capacitor.","Broken thermostat.","Low line voltage."],explanation:"The motor draws locked rotor amperage (LRA) when it cannot overcome the initial inertia."},{id:"refri_334",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Efecto Flash Gas'?",opciones:["Gas que brilla en el visor.","La evaporaci\xF3n instant\xE1nea de parte del refrigerante l\xEDquido al pasar por la v\xE1lvula de expansi\xF3n debido a la ca\xEDda de presi\xF3n.","Un escape de gas por la v\xE1lvula de seguridad.","Cuando el compresor arranca muy r\xE1pido."],respuesta_correcta:1,explicacion:"Este gas no enfr\xEDa; el dise\xF1o busca minimizarlo mediante el subenfriamiento.",question:"What is the 'flash gas effect'?",options:["Gas that glows in the sight glass.","The instantaneous evaporation of part of the liquid refrigerant as it passes through the expansion valve due to the pressure drop.","A gas escape through the relief valve.","When the compressor starts too quickly."],explanation:"This gas does not provide cooling; system design aims to minimize it through subcooling."},{id:"refri_335",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de succi\xF3n (EPR)?",opciones:["Aumentar la presi\xF3n de descarga.","Mantener una presi\xF3n m\xEDnima en el evaporador para evitar que el producto se congele o se deshidrate en exceso.","Controlar la velocidad del motor.","Cerrar el paso de aceite."],respuesta_correcta:1,explicacion:"Mantiene el evaporador a una temperatura constante aunque la succi\xF3n del rack sea m\xE1s baja.",question:"What is the function of a suction pressure regulator (EPR) valve?",options:["To increase discharge pressure.","To maintain a minimum evaporator pressure to prevent the product from freezing or dehydrating excessively.","To control motor speed.","To shut off oil flow."],explanation:"It holds the evaporator at a constant temperature even though the rack suction is lower."},{id:"refri_336",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el sobrecalentamiento es de 2\xB0F y el subenfriamiento de 25\xB0F. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Falta de refrigerante.","Exceso de refrigerante (Sistema sobrecargado).","TXV muy cerrada.","Condensador muy limpio."],respuesta_correcta:1,explicacion:"Mucho l\xEDquido en el condensador (subcooling alto) y l\xEDquido saliendo del evaporador (superheat casi nulo) es se\xF1al clara de sobrecarga.",question:"A technician finds that superheat is 2\xB0F and subcooling is 25\xB0F. What is the diagnosis?",options:["Low refrigerant charge.","Excess refrigerant charge (overcharged system).","TXV too closed.","Very clean condenser."],explanation:"A large amount of liquid in the condenser (high subcooling) and liquid leaving the evaporator (near-zero superheat) is a clear sign of overcharge."},{id:"refri_337",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica una temperatura de descarga superior a 225\xB0F en un compresor comercial?",opciones:["Alta eficiencia t\xE9rmica.","Degradaci\xF3n del aceite y formaci\xF3n de \xE1cidos y carb\xF3n en los platos de v\xE1lvulas.","Que el ventilador del condensador es muy potente.","Que el refrigerante es nuevo."],respuesta_correcta:1,explicacion:"Es el l\xEDmite de seguridad para la vida \xFAtil del aceite y la mec\xE1nica interna del compresor.",question:"What does a discharge temperature above 225\xB0F on a commercial compressor indicate?",options:["High thermal efficiency.","Oil degradation and formation of acids and carbon deposits on the valve plates.","The condenser fan is very powerful.","The refrigerant is new."],explanation:"This is the safety limit for oil life and the internal mechanics of the compressor."},{id:"refri_338",categoria:"REFRI_COMERCIAL",pregunta:"Si el ventilador del evaporador gira al rev\xE9s, \xBFc\xF3mo se afecta el sistema?",opciones:["Enfr\xEDa m\xE1s r\xE1pido.","Baja dr\xE1sticamente el flujo de aire, disminuyendo la presi\xF3n de succi\xF3n y arriesgando el retorno de l\xEDquido.","Aumenta la presi\xF3n de alta.","El compresor consume menos energ\xEDa."],respuesta_correcta:1,explicacion:"Las aspas est\xE1n dise\xF1adas para un sentido; el giro inverso apenas mueve aire, matando la transferencia de calor.",question:"If the evaporator fan spins in reverse, how is the system affected?",options:["It cools faster.","Airflow drops drastically, lowering suction pressure and risking liquid return to the compressor.","Head pressure increases.","The compressor uses less energy."],explanation:"The blades are designed for one direction; reverse rotation barely moves air, killing heat transfer."},{id:"refri_339",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Recuperaci\xF3n de Calor' en un sistema de supermercado?",opciones:["Poner el compresor cerca del horno.","Usar el gas de descarga caliente para calentar agua o el aire de la tienda a trav\xE9s de un serpent\xEDn adicional.","Guardar el gas en tanques calientes.","No existe tal sistema."],respuesta_correcta:1,explicacion:"Aprovecha la energ\xEDa desperdiciada en el condensador para mejorar la eficiencia del edificio.",question:"What is 'heat reclaim' in a supermarket system?",options:["Placing the compressor near the oven.","Using the hot discharge gas to heat water or store air through an additional coil.","Storing gas in hot tanks.","No such system exists."],explanation:"It leverages the energy wasted in the condenser to improve the overall building efficiency."},{id:"refri_340",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 mide un 'Vacu\xF3metro Micr\xF3nico'?",opciones:["La presi\xF3n de descarga.","El nivel de vac\xEDo absoluto en micrones para asegurar la eliminaci\xF3n de aire y humedad.","La velocidad del refrigerante.","La cantidad de aceite en el sistema."],respuesta_correcta:1,explicacion:"Es la \xFAnica herramienta confiable para saber si un sistema est\xE1 realmente seco y sin fugas antes de cargar.",question:"What does a 'micron gauge' measure?",options:["Discharge pressure.","The absolute vacuum level in microns to ensure the removal of air and moisture.","Refrigerant velocity.","The amount of oil in the system."],explanation:"It is the only reliable tool for knowing if a system is truly dry and leak-free before charging."},{id:"refri_341",categoria:"REFRI_COMERCIAL",pregunta:"Si el bulbo de la TXV se instala despu\xE9s de una trampa de aceite, \xBFqu\xE9 sucede?",opciones:["Lee mejor la temperatura.","La lectura ser\xE1 err\xE1tica y falsa debido a la masa de aceite fr\xEDo estancado, causando hunting.","La v\xE1lvula se cierra siempre.","No afecta en nada."],respuesta_correcta:1,explicacion:"El bulbo debe sentir solo la temperatura del gas de succi\xF3n que sale del evaporador.",question:"If the TXV sensing bulb is installed after an oil trap, what happens?",options:["It reads the temperature better.","The reading will be erratic and false due to the mass of cold stagnant oil, causing hunting.","The valve always closes.","It has no effect."],explanation:"The bulb must sense only the temperature of the suction gas leaving the evaporator."},{id:"refri_342",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es un 'Sistema en Cascada'?",opciones:["Un sistema con agua cayendo.","Dos sistemas independientes conectados por un intercambiador donde el evaporador de uno enfr\xEDa el condensador del otro.","Un rack de compresores en serie.","Un sistema de aire acondicionado central."],respuesta_correcta:1,explicacion:"Se utiliza para alcanzar temperaturas ultra-bajas de forma eficiente.",question:"What is a 'cascade system'?",options:["A system with falling water.","Two independent systems connected by a heat exchanger where the evaporator of one cools the condenser of the other.","A rack of compressors in series.","A central air conditioning system."],explanation:"It is used to achieve ultra-low temperatures efficiently."},{id:"refri_343",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de succi\xF3n es baja, pero el sobrecalentamiento es de 2\xB0F. \xBFCausa probable?",opciones:["Falta de gas.","Falla en el flujo de aire del evaporador (serpent\xEDn bloqueado o ventilador parado).","TXV muy cerrada.","Condensador sucio."],respuesta_correcta:1,explicacion:"Si no hay aire pasando por el evaporador, el refrigerante l\xEDquido no puede absorber calor, por lo que sale l\xEDquido (superheat bajo) y a baja presi\xF3n.",question:"A technician finds that suction pressure is low, but superheat is 2\xB0F. What is the probable cause?",options:["Low refrigerant charge.","Airflow failure at the evaporator (blocked coil or stopped fan).","TXV too closed.","Dirty condenser."],explanation:"If no air passes over the evaporator, the liquid refrigerant cannot absorb heat, so it exits as liquid (low superheat) and at low pressure."},{id:"refri_344",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, si el sobrecalentamiento en el evaporador es de 2\xB0F y en la entrada del compresor es de 45\xB0F, \xBFqu\xE9 problema t\xE9cnico se presenta?",opciones:["Falta de refrigerante.","Aislamiento de la l\xEDnea de succi\xF3n deficiente o inexistente (ganancia de calor excesiva).","La TXV est\xE1 inundando el compresor.","El condensador est\xE1 demasiado limpio."],respuesta_correcta:1,explicacion:"Un superheat bajo en el evaporador indica que est\xE1 casi inundado, pero si llega muy alto al compresor, el gas se calent\xF3 en el trayecto, perdiendo densidad y enfriamiento para el motor.",question:"In a system with R-404A, if evaporator superheat is 2\xB0F and compressor inlet superheat is 45\xB0F, what technical problem is present?",options:["Low refrigerant charge.","Deficient or missing suction line insulation (excessive heat gain).","The TXV is flooding the compressor.","The condenser is too clean."],explanation:"Low superheat at the evaporator indicates it is nearly flooded, but if it arrives very high at the compressor, the gas heated up along the way, losing density and motor cooling ability."},{id:"refri_345",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Entalp\xEDa' en el ciclo de refrigeraci\xF3n?",opciones:["La presi\xF3n del gas.","La cantidad total de energ\xEDa t\xE9rmica (calor) contenida en una libra de refrigerante a una presi\xF3n y temperatura dadas.","La velocidad del compresor.","La humedad del aire."],respuesta_correcta:1,explicacion:"Es el valor clave en el diagrama de Mollier para calcular cu\xE1nto calor se est\xE1 moviendo realmente.",question:"What is 'enthalpy' in the refrigeration cycle?",options:["Gas pressure.","The total amount of thermal energy (heat) contained in one pound of refrigerant at a given pressure and temperature.","Compressor speed.","Air humidity."],explanation:"It is the key value on the Mollier diagram for calculating how much heat is actually being moved."},{id:"refri_346",categoria:"REFRI_COMERCIAL",pregunta:"Un controlador de rack muestra una alarma de 'Diferencial de Aceite Bajo'. El t\xE9cnico encuentra que el filtro de aceite est\xE1 fr\xEDo. \xBFQu\xE9 indica?",opciones:["Falta de gas.","El filtro de aceite est\xE1 obstruido (ca\xEDda de presi\xF3n), impidiendo que el aceite llegue a los compresores.","El aceite es nuevo.","El calentador de c\xE1rter fall\xF3."],respuesta_correcta:1,explicacion:"Si el filtro est\xE1 fr\xEDo comparado con la l\xEDnea de entrada, hay una restricci\xF3n que provoca una expansi\xF3n local de cualquier rastro de gas.",question:"A rack controller shows a 'Low Oil Differential' alarm. The technician finds the oil filter is cold. What does this indicate?",options:["Low refrigerant charge.","The oil filter is blocked (pressure drop), preventing oil from reaching the compressors.","The oil is new.","The crankcase heater failed."],explanation:"If the filter is cold compared to the inlet line, there is a restriction causing localized expansion of any trace gas."},{id:"refri_347",categoria:"REFRI_COMERCIAL",pregunta:"En un condensador enfriado por aire, \xBFqu\xE9 indica un 'Split' de temperatura (Temp. Saturaci\xF3n - Temp. Ambiente) de 40\xB0F?",opciones:["Condensador perfecto.","Condensador sucio o ventilador fallando; el calor no est\xE1 saliendo del sistema de forma eficiente.","Falta de gas.","Compresor muy peque\xF1o."],respuesta_correcta:1,explicacion:"Un split normal es de 10-25\xB0F. 40\xB0F significa que la presi\xF3n de alta est\xE1 volando porque el calor no tiene por d\xF3nde escapar.",question:"On an air-cooled condenser, what does a temperature 'split' (saturation temp minus ambient temp) of 40\xB0F indicate?",options:["A perfect condenser.","A dirty condenser or failing fan; heat is not leaving the system efficiently.","Low refrigerant charge.","Undersized compressor."],explanation:"A normal split is 10-25\xB0F. A reading of 40\xB0F means head pressure is very high because the heat has no way to escape."},{id:"refri_348",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de baja es de 5 PSI (R-404A) y la TXV est\xE1 cubierta de hielo. El ventilador del evaporador est\xE1 apagado. \xBFQu\xE9 hace primero?",opciones:["Cargar m\xE1s gas.","Verificar el motor del ventilador y el capacitor; la falta de aire causa el congelamiento.","Cambiar la TXV.","Lavar el condensador."],respuesta_correcta:1,explicacion:"Sin flujo de aire, el l\xEDquido no se evapora. La presi\xF3n cae y el poco calor que absorbe viene de congelar la humedad ambiente sobre el metal.",question:"A technician finds that low-side pressure is 5 PSI (R-404A) and the TXV is covered in ice. The evaporator fan is off. What is done first?",options:["Add more refrigerant.","Check the fan motor and capacitor; the lack of airflow is causing the freeze-up.","Replace the TXV.","Wash the condenser."],explanation:"Without airflow, the liquid does not evaporate. Pressure drops and the small amount of heat absorbed comes from freezing ambient moisture onto the metal."},{id:"refri_349",categoria:"REFRI_COMERCIAL",pregunta:"Si una v\xE1lvula de expansi\xF3n electr\xF3nica (EEV) pierde energ\xEDa, \xBFen qu\xE9 posici\xF3n suele quedar?",opciones:["Totalmente abierta.","En la posici\xF3n en que se encontraba (no tiene resorte de retorno a diferencia de la solenoide).","Totalmente cerrada.","En modo bypass."],respuesta_correcta:1,explicacion:"Las EEV usan motores a pasos. Si pierden corriente, el v\xE1stago se queda quieto, lo que puede causar inundaci\xF3n o vac\xEDo seg\xFAn d\xF3nde se par\xF3.",question:"If an electronic expansion valve (EEV) loses power, what position does it typically remain in?",options:["Fully open.","In whatever position it was in (it has no return spring unlike a solenoid).","Fully closed.","In bypass mode."],explanation:"EEVs use stepper motors. If they lose power, the pin stays put, which can cause flooding or vacuum depending on where it stopped."},{id:"refri_350",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 0\xB0F y un amperaje de compresor normal?",opciones:["Funcionamiento \xF3ptimo.","Retorno de l\xEDquido (Floodback); el compresor est\xE1 comprimiendo vapor saturado y gotas de l\xEDquido.","Falta de gas.","Condensador bloqueado."],respuesta_correcta:1,explicacion:"Es el asesino silencioso; el l\xEDquido diluye el aceite y desgasta los pistones/scroll antes de causar un golpe hidr\xE1ulico final.",question:"What does a superheat of 0\xB0F with normal compressor amperage indicate?",options:["Optimal operation.","Liquid return (floodback); the compressor is compressing saturated vapor and liquid droplets.","Low refrigerant charge.","Blocked condenser."],explanation:"It is the silent killer; liquid dilutes the oil and wears pistons/scrolls before causing a final hydraulic slug."},{id:"refri_351",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el subenfriamiento es de 2\xB0F y las burbujas en el visor no paran. La presi\xF3n de alta es baja. \xBFDiagn\xF3stico?",opciones:["Exceso de carga.","Falta de refrigerante; no hay suficiente l\xEDquido 'respaldado' en el condensador para enfriarse.","Filtro tapado.","Compresor muy eficiente."],respuesta_correcta:1,explicacion:"Sin suficiente refrigerante, el condensador solo alcanza a 'medio condensar' el gas, entregando una mezcla burbujeante.",question:"A technician finds that subcooling is 2\xB0F and the bubbles in the sight glass won't stop. Head pressure is low. What is the diagnosis?",options:["Excess charge.","Low refrigerant charge; there is not enough liquid 'backed up' in the condenser to cool down.","Clogged filter.","Very efficient compressor."],explanation:"Without enough refrigerant, the condenser can only partially condense the gas, delivering a bubbly mixture."},{id:"refri_352",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Reloj de Deshielo' (Defrost Timer)?",opciones:["Controlar la luz del cuarto fr\xEDo.","Interrumpir el ciclo de refrigeraci\xF3n y activar las resistencias o gas caliente para eliminar el hielo del evaporador peri\xF3dicamente.","Medir el consumo el\xE9ctrico.","Regular el sobrecalentamiento."],respuesta_correcta:1,explicacion:"Sin \xE9l, el evaporador se convertir\xEDa en un bloque de hielo s\xF3lido en menos de 24 horas.",question:"What is the function of the defrost timer?",options:["To control the walk-in cooler light.","To interrupt the refrigeration cycle and activate heaters or hot gas to periodically remove ice from the evaporator.","To measure electrical consumption.","To regulate superheat."],explanation:"Without it, the evaporator would become a solid block of ice in less than 24 hours."},{id:"refri_353",categoria:"REFRI_COMERCIAL",pregunta:"Un compresor de baja temperatura tiene una temperatura de descarga de 245\xB0F. \xBFQu\xE9 riesgo hay?",opciones:["Ninguno, est\xE1 operando normal.","Carbonizaci\xF3n del aceite y falla de lubricaci\xF3n; el aceite se descompone por encima de los 225\xB0F-250\xB0F.","Que el gas se congele.","Que el motor gire m\xE1s r\xE1pido."],respuesta_correcta:1,explicacion:"El calor extremo es el enemigo mortal de los sellos y el lubricante qu\xEDmico.",question:"A low-temperature compressor has a discharge temperature of 245\xB0F. What is the risk?",options:["None, it is operating normally.","Oil carbonization and lubrication failure; oil breaks down above 225-250\xB0F.","The gas will freeze.","The motor will spin faster."],explanation:"Extreme heat is the mortal enemy of seals and chemical lubricant."},{id:"refri_354",categoria:"REFRI_COMERCIAL",pregunta:"\xBFC\xF3mo se calcula el sobrecalentamiento total (Total Superheat)?",opciones:["Temp. salida evaporador - Temp. saturaci\xF3n.","Temp. tuber\xEDa de succi\xF3n (a 15-20cm del compresor) - Temp. saturaci\xF3n de baja.","Presi\xF3n alta - Presi\xF3n baja.","Voltaje x Amperaje."],respuesta_correcta:1,explicacion:"Nos dice cu\xE1nta protecci\xF3n tiene el compresor contra el l\xEDquido y si el motor se est\xE1 enfriando correctamente.",question:"How is total superheat calculated?",options:["Evaporator outlet temp minus saturation temp.","Suction line temperature (6-8 inches from the compressor) minus low-side saturation temperature.","High pressure minus low pressure.","Voltage times amperage."],explanation:"It tells us how much protection the compressor has against liquid and whether the motor is being cooled properly."},{id:"refri_355",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite'?",opciones:["Enfriar el refrigerante.","Capturar el aceite de la descarga y devolverlo al compresor para evitar que se acumule en el evaporador.","Filtrar la humedad.","Aumentar la presi\xF3n de alta."],respuesta_correcta:1,explicacion:"Mantiene el aceite en el motor y deja las tuber\xEDas libres para el intercambio de calor eficiente.",question:"What is the function of the oil separator?",options:["To cool the refrigerant.","To capture oil from the discharge and return it to the compressor to prevent it from accumulating in the evaporator.","To filter moisture.","To increase head pressure."],explanation:"It keeps the oil in the motor and leaves the piping clear for efficient heat exchange."},{id:"refri_356",categoria:"REFRI_COMERCIAL",pregunta:"Si una TXV tiene el bulbo sensor suelto y le da el aire caliente del cuarto, \xBFqu\xE9 pasar\xE1?",opciones:["La v\xE1lvula se cierra.","La v\xE1lvula se abre al m\xE1ximo, inundando el evaporador y arriesgando el compresor.","El ventilador se apaga.","La presi\xF3n de descarga baja."],respuesta_correcta:1,explicacion:"El bulbo 'cree' que el gas est\xE1 muy caliente y ordena abrir el flujo de par en par.",question:"If a TXV has a loose sensing bulb and it is exposed to the warm air of the room, what will happen?",options:["The valve closes.","The valve opens fully, flooding the evaporator and endangering the compressor.","The fan shuts off.","Discharge pressure drops."],explanation:"The bulb 'believes' the gas is very hot and commands the valve to open the flow wide open."},{id:"refri_357",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un visor de l\xEDquido con el indicador en color amarillo?",opciones:["Sistema operando bien.","Humedad excesiva en el sistema; el filtro deshidratador est\xE1 saturado.","Falta de aceite.","Presi\xF3n de alta muy baja."],respuesta_correcta:1,explicacion:"El color amarillo es la alerta de que hay agua circulando, lo que puede formar \xE1cidos o hielo en la TXV.",question:"What does a liquid sight glass with a yellow moisture indicator mean?",options:["System is operating well.","Excessive moisture in the system; the filter drier is saturated.","Low oil.","Very low head pressure."],explanation:"Yellow is the alert that water is circulating, which can form acids or ice in the TXV."},{id:"refri_358",categoria:"REFRI_COMERCIAL",pregunta:"Un compresor hace un ruido de 'zumbido' pero no arranca. Al medir, el voltaje cae de 220V a 160V en el intento. \xBFDiagn\xF3stico?",opciones:["Falta de gas.","Ca\xEDda de tensi\xF3n excesiva debido a cables delgados o conexiones flojas; el motor no tiene torque suficiente.","Capacitor nuevo da\xF1ado.","Termostato al rev\xE9s."],respuesta_correcta:1,explicacion:"Sin el voltaje adecuado, el motor no puede vencer la inercia y se queda 'pegado' consumiendo corriente.",question:"A compressor 'hums' but does not start. When measured, voltage drops from 220V to 160V on the attempt. What is the diagnosis?",options:["Low refrigerant charge.","Excessive voltage drop due to undersized wiring or loose connections; the motor lacks sufficient starting torque.","New capacitor is damaged.","Thermostat is wired backwards."],explanation:"Without adequate voltage, the motor cannot overcome inertia and remains 'stuck,' drawing excessive current."},{id:"refri_359",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Subenfriamiento L\xEDquido' (Liquid Subcooling) y por qu\xE9 es vital antes de la TXV?",opciones:["Es enfriar el gas.","Es asegurar que el refrigerante sea 100% l\xEDquido para evitar 'flash gas' en la l\xEDnea de l\xEDquido, lo que reducir\xEDa la capacidad de la v\xE1lvula.","Es calentar el aceite.","Es bajar la presi\xF3n de descarga."],respuesta_correcta:1,explicacion:"Sin subenfriamiento, cualquier ca\xEDda de presi\xF3n peque\xF1a convierte el l\xEDquido en vapor, haciendo que la TXV trabaje de forma err\xE1tica.",question:"What is 'liquid subcooling' and why is it vital before the TXV?",options:["It is cooling the gas.","It is ensuring that the refrigerant is 100% liquid to prevent flash gas in the liquid line, which would reduce valve capacity.","It is heating the oil.","It is lowering discharge pressure."],explanation:"Without subcooling, any small pressure drop converts liquid into vapor, causing the TXV to work erratically."},{id:"refri_360",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Acumulador de Succi\xF3n' en un sistema con deshielo por gas caliente?",opciones:["Guardar aceite.","Proteger al compresor atrapando el refrigerante l\xEDquido condensado en el evaporador durante el ciclo de calor.","Aumentar la presi\xF3n de succi\xF3n.","Filtrar la humedad."],respuesta_correcta:1,explicacion:"Durante el gas caliente, el evaporador act\xFAa como condensador; al volver al modo fr\xEDo, hay mucho l\xEDquido que podr\xEDa matar al compresor.",question:"What is the function of the suction accumulator in a system with hot gas defrost?",options:["To store oil.","To protect the compressor by trapping liquid refrigerant that condensed in the evaporator during the hot gas cycle.","To increase suction pressure.","To filter moisture."],explanation:"During hot gas defrost, the evaporator acts as a condenser; when switching back to cooling mode, a large amount of liquid could destroy the compressor."},{id:"refri_361",categoria:"REFRI_COMERCIAL",pregunta:"Si un evaporador de congelados tiene el 'Termostato de terminaci\xF3n de deshielo' (Klixon) mal calibrado y abre a 80\xB0F, \xBFqu\xE9 sucede?",opciones:["El equipo enfr\xEDa mejor.","El gabinete se calienta demasiado durante el deshielo, pudiendo da\xF1ar productos o deformar pl\xE1sticos.","El hielo nunca se derrite.","El compresor no arranca."],respuesta_correcta:1,explicacion:"Normalmente corta a 45-55\xB0F. Dejarlo hasta 80\xB0F es desperdicio de energ\xEDa y riesgo t\xE9rmico innecesario.",question:"If a freezer evaporator has a defrost termination thermostat (Klixon) miscalibrated to open at 80\xB0F, what happens?",options:["The unit cools better.","The cabinet overheats during defrost, potentially damaging products or warping plastics.","The ice never melts.","The compressor does not start."],explanation:"It normally cuts out at 45-55\xB0F. Letting it reach 80\xB0F is a waste of energy and an unnecessary thermal risk."},{id:"refri_362",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Presi\xF3n de saturaci\xF3n'?",opciones:["La presi\xF3n m\xE1xima que aguanta el tubo.","La presi\xF3n a la cual un refrigerante cambia de estado (de l\xEDquido a vapor o viceversa) a una temperatura dada.","La presi\xF3n del aceite.","La presi\xF3n atmosf\xE9rica."],respuesta_correcta:1,explicacion:"Es el concepto fundamental para usar la tabla P-T y diagnosticar cualquier sistema.",question:"What is 'saturation pressure'?",options:["The maximum pressure the tubing can withstand.","The pressure at which a refrigerant changes state (from liquid to vapor or vice versa) at a given temperature.","The oil pressure.","Atmospheric pressure."],explanation:"It is the fundamental concept for using the P-T chart and diagnosing any system."},{id:"refri_363",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el sobrecalentamiento es de 35\xB0F. Al intentar ajustar la TXV, esta no responde. \xBFQu\xE9 sucede?",opciones:["La v\xE1lvula est\xE1 perfecta.","El orificio de la v\xE1lvula est\xE1 obstruido o el elemento de poder ha perdido su carga termost\xE1tica.","Falta aceite.","El compresor est\xE1 muy fr\xEDo."],respuesta_correcta:1,explicacion:"Si la v\xE1lvula no abre m\xE1s por m\xE1s que se gire el v\xE1stago, mec\xE1nicamente est\xE1 inoperante o bloqueada.",question:"A technician finds that superheat is 35\xB0F. When attempting to adjust the TXV, it does not respond. What is happening?",options:["The valve is fine.","The valve orifice is blocked or the power element has lost its thermostatic charge.","Low oil.","The compressor is too cold."],explanation:"If the valve will not open further no matter how much the stem is turned, it is mechanically inoperative or blocked."},{id:"refri_364",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, el visor de l\xEDquido muestra burbujas constantes, pero el subenfriamiento a la salida del condensador es de 15\xB0F. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Falta de refrigerante.","Presencia de gases no condensables (aire) en el sistema.","Restricci\xF3n en la l\xEDnea de l\xEDquido o ca\xEDda de presi\xF3n excesiva.","El compresor tiene v\xE1lvulas da\xF1adas."],respuesta_correcta:2,explicacion:"Un subenfriamiento alto (15\xB0F) indica que hay suficiente l\xEDquido. Si hay burbujas despu\xE9s de eso, el l\xEDquido se est\xE1 'evaporando' por una ca\xEDda de presi\xF3n en el filtro o tuber\xEDa.",question:"In an R-404A system, the liquid sight glass shows constant bubbles, but subcooling at the condenser outlet is 15\xB0F. What is the diagnosis?",options:["Low refrigerant charge.","Presence of non-condensable gases (air) in the system.","Restriction in the liquid line or excessive pressure drop.","The compressor has damaged valves."],explanation:"High subcooling (15\xB0F) indicates there is enough liquid. If bubbles appear after that point, the liquid is flashing due to a pressure drop in the filter or piping."},{id:"refri_365",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 mide un 'Man\xF3metro de Compuesto'?",opciones:["Solo presiones altas.","Presiones por encima y por debajo (vac\xEDo) de la presi\xF3n atmosf\xE9rica.","La pureza del gas.","La velocidad del aceite."],respuesta_correcta:1,explicacion:"Es el man\xF3metro de baja (azul), esencial para ver si el sistema est\xE1 operando en vac\xEDo.",question:"What does a 'compound gauge' measure?",options:["Only high pressures.","Pressures above and below (vacuum) atmospheric pressure.","Gas purity.","Oil velocity."],explanation:"It is the low-side gauge (blue), essential for determining if the system is operating in a vacuum."},{id:"refri_366",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 s\xEDntoma provoca una TXV con el bulbo sensor suelto (sin contacto)?",opciones:["Baja presi\xF3n de succi\xF3n.","Inundaci\xF3n del evaporador (Floodback) y presi\xF3n de succi\xF3n alta, ya que la v\xE1lvula 'cree' que el gas est\xE1 caliente y abre totalmente.","Falta de gas.","El condensador se congela."],respuesta_correcta:1,explicacion:"Al sentir la temperatura ambiente, el bulbo ordena m\xE1xima apertura, enviando l\xEDquido al compresor.",question:"What symptom does a TXV with a loose sensing bulb (no contact) cause?",options:["Low suction pressure.","Evaporator flooding (floodback) and high suction pressure, as the valve 'thinks' the gas is hot and opens fully.","Low refrigerant charge.","The condenser freezes."],explanation:"Sensing ambient temperature, the bulb commands maximum opening, sending liquid to the compressor."},{id:"refri_367",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de la 'V\xE1lvula de Retenci\xF3n' (Check Valve) en el drenaje de aceite de un evaporador?",opciones:["Aumentar la presi\xF3n.","Evitar que el refrigerante l\xEDquido regrese al separador de aceite cuando el sistema est\xE1 en reposo.","Enfriar el aceite.","Filtrar el gas."],respuesta_correcta:1,explicacion:"Asegura el flujo en una sola direcci\xF3n hacia el c\xE1rter o reservorio.",question:"What is the function of a check valve in the oil drain of an evaporator?",options:["To increase pressure.","To prevent liquid refrigerant from flowing back to the oil separator when the system is at rest.","To cool the oil.","To filter the gas."],explanation:"It ensures flow in only one direction toward the crankcase or reservoir."},{id:"refri_368",categoria:"REFRI_COMERCIAL",pregunta:"Si un compresor tiene un amperaje de 10A y un voltaje de 220V, y el factor de potencia es 0.9, \xBFcu\xE1ntos Watts reales consume?",opciones:["2200W","1980W","2444W","1100W"],respuesta_correcta:1,explicacion:"Watts = V x I x PF. Entonces 220 x 10 x 0.9 = 1980W.",question:"If a compressor draws 10A at 220V with a power factor of 0.9, how many actual watts does it consume?",options:["2200W","1980W","2444W","1100W"],explanation:"Watts = V x I x PF. Therefore, 220 x 10 x 0.9 = 1980W."},{id:"refri_369",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-454B (A2L), \xBFcu\xE1l es la principal diferencia operativa en la recuperaci\xF3n de refrigerante comparado con un HFC est\xE1ndar?",opciones:["No se puede recuperar.","Se requiere una recuperadora certificada para gases inflamables con motores sin chispas y ventilaci\xF3n forzada.","Se recupera solo en estado gaseoso.","Se debe mezclar con nitr\xF3geno antes de recuperar."],respuesta_correcta:1,explicacion:"Los refrigerantes A2L son ligeramente inflamables; el equipo de servicio debe estar dise\xF1ado para evitar cualquier fuente de ignici\xF3n interna.",question:"In a system with R-454B (A2L), what is the main operational difference in refrigerant recovery compared to a standard HFC?",options:["It cannot be recovered.","A recovery unit certified for flammable gases with sparkless motors and forced ventilation is required.","It can only be recovered in a gaseous state.","It must be mixed with nitrogen before recovery."],explanation:"A2L refrigerants are mildly flammable; service equipment must be designed to avoid any internal ignition source."},{id:"refri_370",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Differential' (Diferencial) en un control de temperatura y cu\xE1l es su importancia?",opciones:["Es el precio del control.","El rango entre la temperatura de encendido y apagado que evita el ciclado corto del compresor.","La diferencia entre alta y baja presi\xF3n.","La precisi\xF3n del sensor NTC."],respuesta_correcta:1,explicacion:"Sin diferencial, el equipo arrancar\xEDa y parar\xEDa con variaciones de 0.1 grados, quemando el contactor en horas.",question:"What is the 'differential' on a temperature control and why is it important?",options:["It is the price of the control.","The range between the cut-in and cut-out temperatures that prevents short cycling of the compressor.","The difference between high and low pressure.","The accuracy of the NTC sensor."],explanation:"Without a differential, the equipment would start and stop with 0.1-degree variations, burning out the contactor in hours."},{id:"refri_371",categoria:"REFRI_COMERCIAL",pregunta:"Mides un sobrecalentamiento de 15\xB0F en la salida del evaporador y 18\xB0F en la entrada del compresor. \xBFQu\xE9 indica esto sobre el aislamiento de la succi\xF3n?",opciones:["Que el aislamiento es perfecto.","Que hay una ganancia de calor aceptable (3\xB0F) a lo largo de la l\xEDnea de succi\xF3n.","Que el aislamiento est\xE1 totalmente destruido.","Que la TXV est\xE1 muy cerrada."],respuesta_correcta:1,explicacion:"Una diferencia de 3 a 5 grados entre el evaporador y el compresor es el est\xE1ndar de una instalaci\xF3n bien aislada.",question:"You measure a superheat of 15\xB0F at the evaporator outlet and 18\xB0F at the compressor inlet. What does this indicate about the suction line insulation?",options:["The insulation is perfect.","There is an acceptable heat gain (3\xB0F) along the suction line.","The insulation is completely destroyed.","The TXV is too closed."],explanation:"A difference of 3 to 5 degrees between the evaporator and the compressor is the standard for a well-insulated installation."},{id:"refri_372",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de alta es de 350 PSI para R-404A en un d\xEDa de 70\xB0F. El condensador est\xE1 limpio. \xBFQu\xE9 sospecha?",opciones:["Falta de gas.","Presencia de gases no condensables (aire) en el lado de alta presi\xF3n.","Filtro tapado.","Compresor muy eficiente."],respuesta_correcta:1,explicacion:"A 70\xB0F ambiente, la presi\xF3n deber\xEDa estar rondando los 160-200 PSI. 350 PSI es signo de aire atrapado que no se condensa.",question:"A technician finds that head pressure is 350 PSI for R-404A on a 70\xB0F day. The condenser is clean. What is suspected?",options:["Low refrigerant charge.","Presence of non-condensable gases (air) on the high-pressure side.","Clogged filter.","Very efficient compressor."],explanation:"At 70\xB0F ambient, the pressure should be around 160-200 PSI. A reading of 350 PSI is a sign of trapped air that does not condense."},{id:"refri_373",categoria:"REFRI_COMERCIAL",pregunta:"Un equipo de refrigeraci\xF3n de transporte (Thermo King/Carrier) se apaga por 'Baja Presi\xF3n de Aceite'. El nivel est\xE1 bien. \xBFQu\xE9 revisa?",opciones:["El sensor de temperatura.","La bomba de aceite mec\xE1nica y el filtro de malla interno del c\xE1rter que podr\xEDa estar obstruido.","La presi\xF3n de descarga.","El alternador del motor."],respuesta_correcta:1,explicacion:"El desgaste de la bomba o suciedad en el c\xE1rter impiden que la presi\xF3n neta de lubricaci\xF3n sea la adecuada.",question:"A transport refrigeration unit (Thermo King/Carrier) shuts down on 'Low Oil Pressure.' The oil level is fine. What is checked?",options:["The temperature sensor.","The mechanical oil pump and the internal crankcase screen filter that may be clogged.","The discharge pressure.","The engine alternator."],explanation:"Pump wear or dirt in the crankcase prevents the net oil pressure from reaching the required level."},{id:"refri_374",categoria:"REFRI_COMERCIAL",pregunta:"Si una v\xE1lvula de expansi\xF3n electr\xF3nica (EEV) est\xE1 marcando '0 pasos' en el controlador pero el evaporador sigue inund\xE1ndose, \xBFqu\xE9 falla?",opciones:["El controlador est\xE1 loco.","Falla mec\xE1nica de la v\xE1lvula (asiento da\xF1ado o basura que impide el cierre total).","Falta de gas.","Sensor de presi\xF3n roto."],respuesta_correcta:1,explicacion:"Si el software ordena cerrar pero el flujo sigue, el problema es una fuga f\xEDsica a trav\xE9s del obturador de la v\xE1lvula.",question:"If an electronic expansion valve (EEV) is showing '0 steps' on the controller but the evaporator is still flooding, what is the fault?",options:["The controller is malfunctioning.","Mechanical failure of the valve (damaged seat or debris preventing full closure).","Low refrigerant charge.","Broken pressure sensor."],explanation:"If the software commands full close but flow continues, the problem is a physical leak through the valve seat."},{id:"refri_375",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Acumulador de Succi\xF3n' en sistemas de baja temperatura?",opciones:["Aumentar la presi\xF3n de baja.","Prevenir el golpe de l\xEDquido atrapando refrigerante l\xEDquido que no se evapor\xF3 debido a bajas cargas t\xE9rmicas.","Enfriar el aceite.","Separar el aire."],respuesta_correcta:1,explicacion:"Es la protecci\xF3n final contra el 'slugging' que destruir\xEDa los pistones.",question:"What is the function of the suction accumulator in low-temperature systems?",options:["To increase suction pressure.","To prevent liquid slugging by trapping liquid refrigerant that did not evaporate due to low thermal loads.","To cool the oil.","To separate air."],explanation:"It is the final protection against slugging that would destroy the pistons."},{id:"refri_376",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de succi\xF3n es normal, pero el sobrecalentamiento es de 35\xB0F. \xBFQu\xE9 sucede?",opciones:["Exceso de carga.","La TXV est\xE1 restringiendo demasiado el flujo o el bulbo perdi\xF3 contacto t\xE9rmico parcial.","El ventilador est\xE1 parado.","Compresor muy fr\xEDo."],respuesta_correcta:1,explicacion:"Un superheat alto con succi\xF3n normal indica un evaporador 'hambriento' que no est\xE1 aprovechando su superficie de intercambio.",question:"A technician finds that suction pressure is normal, but superheat is 35\xB0F. What is happening?",options:["Excess charge.","The TXV is restricting flow too much or the bulb has partially lost thermal contact.","The fan is stopped.","The compressor is too cold."],explanation:"High superheat with normal suction pressure indicates a 'starved' evaporator not utilizing its heat exchange surface."},{id:"refri_377",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un amperaje de compresor un 20% por debajo de la placa pero presiones normales?",opciones:["Compresor de alta eficiencia.","Baja densidad del gas de succi\xF3n (posiblemente sobrecalentamiento muy alto) o compresor con desgaste moderado.","Falta de aceite.","Exceso de gas."],respuesta_correcta:1,explicacion:"Si el gas llega muy 'ligero' (caliente), el compresor hace menos trabajo de masa, consumiendo menos energ\xEDa pero enfriando menos.",question:"What does compressor amperage 20% below nameplate with normal pressures indicate?",options:["A high-efficiency compressor.","Low suction gas density (possibly very high superheat) or moderate compressor wear.","Low oil.","Excess refrigerant."],explanation:"If the gas arrives very 'light' (hot), the compressor does less mass work, consuming less energy but also providing less cooling."},{id:"refri_378",categoria:"REFRI_COMERCIAL",pregunta:"Un cliente reporta que su congelador de helados no baja de 10\xB0F. El t\xE9cnico encuentra 0\xB0F de sobrecalentamiento. \xBFQu\xE9 est\xE1 pasando?",opciones:["Falta de gas.","Inundaci\xF3n del evaporador; la TXV est\xE1 abierta de m\xE1s o el orificio es muy grande, impidiendo una evaporaci\xF3n eficiente.","Condensador sucio.","Filtro tapado."],respuesta_correcta:1,explicacion:"Si no hay superheat, el refrigerante sale l\xEDquido; el sistema pierde su capacidad de absorber calor sensible y arriesga al compresor.",question:"A customer reports that their ice cream freezer won't go below 10\xB0F. The technician finds 0\xB0F superheat. What is going on?",options:["Low refrigerant charge.","Evaporator flooding; the TXV is open too far or the orifice is oversized, preventing efficient evaporation.","Dirty condenser.","Clogged filter."],explanation:"If there is no superheat, the refrigerant exits as liquid; the system loses its ability to absorb sensible heat and puts the compressor at risk."},{id:"refri_379",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Subenfriamiento L\xEDquido' (Liquid Subcooling) y por qu\xE9 es vital antes de la TXV?",opciones:["Es enfriar el gas.","Es asegurar que el refrigerante sea 100% l\xEDquido para evitar 'flash gas' en la l\xEDnea de l\xEDquido, lo que reducir\xEDa la capacidad de la v\xE1lvula.","Es calentar el aceite.","Es bajar la presi\xF3n de descarga."],respuesta_correcta:1,explicacion:"Sin subenfriamiento, cualquier ca\xEDda de presi\xF3n peque\xF1a convierte el l\xEDquido en vapor, haciendo que la TXV trabaje de forma err\xE1tica.",question:"What is 'liquid subcooling' and why is it vital before the TXV?",options:["It is cooling the gas.","It is ensuring that the refrigerant is 100% liquid to prevent flash gas in the liquid line, which would reduce valve capacity.","It is heating the oil.","It is lowering discharge pressure."],explanation:"Without subcooling, any small pressure drop converts liquid into vapor, causing the TXV to work erratically."},{id:"refri_380",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Acumulador de Succi\xF3n' en un sistema con deshielo por gas caliente?",opciones:["Guardar aceite.","Proteger al compresor atrapando el refrigerante l\xEDquido condensado en el evaporador durante el ciclo de calor.","Aumentar la presi\xF3n de succi\xF3n.","Filtrar la humedad."],respuesta_correcta:1,explicacion:"Durante el gas caliente, el evaporador act\xFAa como condensador; al volver al modo fr\xEDo, hay mucho l\xEDquido que podr\xEDa matar al compresor.",question:"What is the function of the suction accumulator in a system with hot gas defrost?",options:["To store oil.","To protect the compressor by trapping liquid refrigerant that condensed in the evaporator during the hot gas cycle.","To increase suction pressure.","To filter moisture."],explanation:"During hot gas defrost, the evaporator acts as a condenser; when switching back to cooling mode, a large amount of liquid could destroy the compressor."},{id:"refri_381",categoria:"REFRI_COMERCIAL",pregunta:"Si un evaporador de congelados tiene el 'Termostato de terminaci\xF3n de deshielo' (Klixon) mal calibrado y abre a 80\xB0F, \xBFqu\xE9 sucede?",opciones:["El equipo enfr\xEDa mejor.","El gabinete se calienta demasiado durante el deshielo, pudiendo da\xF1ar productos o deformar pl\xE1sticos.","El hielo nunca se derrite.","El compresor no arranca."],respuesta_correcta:1,explicacion:"Normalmente corta a 45-55\xB0F. Dejarlo hasta 80\xB0F es desperdicio de energ\xEDa y riesgo t\xE9rmico innecesario.",question:"If a freezer evaporator has a defrost termination thermostat (Klixon) miscalibrated to open at 80\xB0F, what happens?",options:["The unit cools better.","The cabinet overheats during defrost, potentially damaging products or warping plastics.","The ice never melts.","The compressor does not start."],explanation:"It normally cuts out at 45-55\xB0F. Letting it reach 80\xB0F is a waste of energy and an unnecessary thermal risk."},{id:"refri_382",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Presi\xF3n de saturaci\xF3n'?",opciones:["La presi\xF3n m\xE1xima que aguanta el tubo.","La presi\xF3n a la cual un refrigerante cambia de estado (de l\xEDquido a vapor o viceversa) a una temperatura dada.","La presi\xF3n del aceite.","La presi\xF3n atmosf\xE9rica."],respuesta_correcta:1,explicacion:"Es el concepto fundamental para usar la tabla P-T y diagnosticar cualquier sistema.",question:"What is 'saturation pressure'?",options:["The maximum pressure the tubing can withstand.","The pressure at which a refrigerant changes state (from liquid to vapor or vice versa) at a given temperature.","The oil pressure.","Atmospheric pressure."],explanation:"It is the fundamental concept for using the P-T chart and diagnosing any system."},{id:"refri_383",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el sobrecalentamiento es de 35\xB0F. Al intentar ajustar la TXV, esta no responde. \xBFQu\xE9 sucede?",opciones:["La v\xE1lvula est\xE1 perfecta.","El orificio de la v\xE1lvula est\xE1 obstruido o el elemento de poder ha perdido su carga termost\xE1tica.","Falta aceite.","El compresor est\xE1 muy fr\xEDo."],respuesta_correcta:1,explicacion:"Si la v\xE1lvula no abre m\xE1s por m\xE1s que se gire el v\xE1stago, mec\xE1nicamente est\xE1 inoperante o bloqueada.",question:"A technician finds that superheat is 35\xB0F. When attempting to adjust the TXV, it does not respond. What is happening?",options:["The valve is fine.","The valve orifice is blocked or the power element has lost its thermostatic charge.","Low oil.","The compressor is too cold."],explanation:"If the valve will not open further no matter how much the stem is turned, it is mechanically inoperative or blocked."},{id:"refri_384",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, el visor de l\xEDquido muestra burbujas constantes, pero el subenfriamiento a la salida del condensador es de 15\xB0F. \xBFCu\xE1l es el diagn\xF3stico?",opciones:["Falta de refrigerante.","Presencia de gases no condensables (aire) en el sistema.","Restricci\xF3n en la l\xEDnea de l\xEDquido o ca\xEDda de presi\xF3n excesiva.","El compresor tiene v\xE1lvulas da\xF1adas."],respuesta_correcta:2,explicacion:"Un subenfriamiento alto (15\xB0F) indica que hay suficiente l\xEDquido. Si hay burbujas despu\xE9s de eso, el l\xEDquido se est\xE1 'evaporando' por una ca\xEDda de presi\xF3n en el filtro o tuber\xEDa.",question:"In an R-404A system, the liquid sight glass shows constant bubbles, but subcooling at the condenser outlet is 15\xB0F. What is the diagnosis?",options:["Low refrigerant charge.","Presence of non-condensable gases (air) in the system.","Restriction in the liquid line or excessive pressure drop.","The compressor has damaged valves."],explanation:"High subcooling (15\xB0F) indicates there is enough liquid. If bubbles appear after that point, the liquid is flashing due to a pressure drop in the filter or piping."},{id:"refri_385",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 mide un 'Man\xF3metro de Compuesto'?",opciones:["Solo presiones altas.","Presiones por encima y por debajo (vac\xEDo) de la presi\xF3n atmosf\xE9rica.","La pureza del gas.","La velocidad del aceite."],respuesta_correcta:1,explicacion:"Es el man\xF3metro de baja (azul), esencial para ver si el sistema est\xE1 operando en vac\xEDo.",question:"What does a 'compound gauge' measure?",options:["Only high pressures.","Pressures above and below (vacuum) atmospheric pressure.","Gas purity.","Oil velocity."],explanation:"It is the low-side gauge (blue), essential for determining if the system is operating in a vacuum."},{id:"refri_386",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 s\xEDntoma provoca una TXV con el bulbo sensor suelto (sin contacto)?",opciones:["Baja presi\xF3n de succi\xF3n.","Inundaci\xF3n del evaporador (Floodback) y presi\xF3n de succi\xF3n alta, ya que la v\xE1lvula 'cree' que el gas est\xE1 caliente y abre totalmente.","Falta de gas.","El condensador se congela."],respuesta_correcta:1,explicacion:"Al sentir la temperatura ambiente, el bulbo ordena m\xE1xima apertura, enviando l\xEDquido al compresor.",question:"What symptom does a TXV with a loose sensing bulb (no contact) cause?",options:["Low suction pressure.","Evaporator flooding (floodback) and high suction pressure, as the valve 'thinks' the gas is hot and opens fully.","Low refrigerant charge.","The condenser freezes."],explanation:"Sensing ambient temperature, the bulb commands maximum opening, sending liquid to the compressor."},{id:"refri_387",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de la 'V\xE1lvula de Retenci\xF3n' (Check Valve) en el drenaje de aceite de un evaporador?",opciones:["Aumentar la presi\xF3n.","Evitar que el refrigerante l\xEDquido regrese al separador de aceite cuando el sistema est\xE1 en reposo.","Enfriar el aceite.","Filtrar el gas."],respuesta_correcta:1,explicacion:"Asegura el flujo en una sola direcci\xF3n hacia el c\xE1rter o reservorio.",question:"What is the function of a check valve in the oil drain of an evaporator?",options:["To increase pressure.","To prevent liquid refrigerant from flowing back to the oil separator when the system is at rest.","To cool the oil.","To filter the gas."],explanation:"It ensures flow in only one direction toward the crankcase or reservoir."},{id:"refri_388",categoria:"REFRI_COMERCIAL",pregunta:"Si un compresor tiene un amperaje de 10A y un voltaje de 220V, y el factor de potencia es 0.9, \xBFcu\xE1ntos Watts reales consume?",opciones:["2200W","1980W","2444W","1100W"],respuesta_correcta:1,explicacion:"Watts = V x I x PF. Entonces 220 x 10 x 0.9 = 1980W.",question:"If a compressor draws 10A at 220V with a power factor of 0.9, how many actual watts does it consume?",options:["2200W","1980W","2444W","1100W"],explanation:"Watts = V x I x PF. Therefore, 220 x 10 x 0.9 = 1980W."},{id:"refri_389",categoria:"REFRI_COMERCIAL",pregunta:"\xBFC\xF3mo afecta un filtro de aire de evaporador tapado al funcionamiento de la TXV?",opciones:["La hace abrir m\xE1s.","La hace cerrar (Starve), ya que la temperatura del gas de succi\xF3n baja al no haber intercambio de calor.","No la afecta.","La rompe mec\xE1nicamente."],respuesta_correcta:1,explicacion:"Menos calor = gas m\xE1s fr\xEDo saliendo = la TXV cierra para evitar que el l\xEDquido llegue al compresor.",question:"How does a clogged evaporator air filter affect TXV operation?",options:["It makes it open more.","It causes the valve to close (starve), since the suction gas temperature drops due to lack of heat exchange.","It has no effect.","It breaks it mechanically."],explanation:"Less heat = cooler gas leaving = the TXV closes to prevent liquid from reaching the compressor."},{id:"refri_390",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR)?",opciones:["Subir la presi\xF3n de alta.","Evitar la sobrecarga del motor del compresor durante el arranque o tras un deshielo, limitando la presi\xF3n de succi\xF3n m\xE1xima.","Medir el aceite.","Enfriar el evaporador."],respuesta_correcta:1,explicacion:"Act\xFAa como un 'limitador' para que el motor no consuma m\xE1s amperaje del que puede soportar.",question:"What is the function of a crankcase pressure regulator (CPR) valve?",options:["To raise head pressure.","To prevent compressor motor overload during startup or after defrost by limiting maximum suction pressure.","To measure oil.","To cool the evaporator."],explanation:"It acts as a 'limiter' so the motor does not draw more amperage than it can handle."},{id:"refri_391",categoria:"REFRI_COMERCIAL",pregunta:"Un sistema comercial tiene el condensador ubicado a 20 metros de altura sobre el compresor. \xBFQu\xE9 componente es OBLIGATORIO?",opciones:["Una TXV m\xE1s grande.","Trampas de aceite (P-traps) cada 6 metros en la l\xEDnea de descarga vertical para asegurar el retorno de lubricante.","Un filtro de succi\xF3n.","Un ventilador extra."],respuesta_correcta:1,explicacion:"Sin trampas, el aceite nunca vencer\xEDa la gravedad en el tramo ascendente, matando al compresor por falta de lubricaci\xF3n.",question:"A commercial system has the condenser located 65 feet above the compressor. What component is MANDATORY?",options:["A larger TXV.","Oil traps (P-traps) every 20 feet on the vertical discharge line to ensure lubricant return.","A suction filter.","An extra fan."],explanation:"Without traps, the oil would never overcome gravity on the vertical rise, killing the compressor from lack of lubrication."},{id:"refri_392",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 2\xB0F en el compresor?",opciones:["Compresor muy eficiente.","Riesgo de golpe de l\xEDquido (Floodback), ya que el refrigerante est\xE1 muy cerca de su punto de saturaci\xF3n.","Falta de gas.","Filtro tapado."],respuesta_correcta:1,explicacion:"Idealmente, el compresor debe recibir gas a 20-30\xB0F de sobrecalentamiento total para estar seguro.",question:"What does a superheat of 2\xB0F at the compressor indicate?",options:["A very efficient compressor.","Risk of liquid slugging (floodback), as the refrigerant is very close to its saturation point.","Low refrigerant charge.","Clogged filter."],explanation:"Ideally, the compressor should receive gas at 20-30\xB0F of total superheat to be safe."},{id:"refri_393",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el compresor semi-herm\xE9tico 'golpea' r\xEDtmicamente al arrancar. \xBFCausa m\xE1s probable?",opciones:["Falta de gas.","Migraci\xF3n de refrigerante l\xEDquido al c\xE1rter durante el periodo de apagado.","El ventilador est\xE1 flojo.","Filtro tapado."],respuesta_correcta:1,explicacion:"Al arrancar, el l\xEDquido en el c\xE1rter se mezcla con el aceite y es succionado por los pistones, causando el golpe hidr\xE1ulico.",question:"A technician finds that a semi-hermetic compressor 'knocks' rhythmically at startup. What is the most likely cause?",options:["Low refrigerant charge.","Liquid refrigerant migration to the crankcase during the off period.","The fan is loose.","Clogged filter."],explanation:"On startup, the liquid in the crankcase mixes with the oil and is drawn in by the pistons, causing hydraulic slugging."},{id:"refri_394",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, si la presi\xF3n de descarga es normal pero el visor de l\xEDquido muestra burbujas y el subenfriamiento es de solo 1\xB0F, \xBFcu\xE1l es la acci\xF3n correcta?",opciones:["Cambiar el compresor.","Agregar refrigerante hasta alcanzar un subenfriamiento de 10\xB0F a 12\xB0F.","Limpiar el condensador.","Cerrar la TXV."],respuesta_correcta:1,explicacion:"Un subenfriamiento casi nulo (1\xB0F) con burbujas es la prueba definitiva de que falta refrigerante para completar la condensaci\xF3n.",question:"In an R-404A system, if discharge pressure is normal but the liquid sight glass shows bubbles and subcooling is only 1\xB0F, what is the correct action?",options:["Replace the compressor.","Add refrigerant until subcooling reaches 10-12\xB0F.","Clean the condenser.","Close the TXV."],explanation:"A subcooling of nearly zero (1\xB0F) with bubbles is definitive proof that there is not enough refrigerant to complete condensation."},{id:"refri_395",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 sucede si el 'Bulbo Sensor' de una TXV se instala en una parte de la tuber\xEDa que est\xE1 en contacto con el flujo de aire caliente del ventilador?",opciones:["La v\xE1lvula se cierra.","La v\xE1lvula se abre excesivamente (Overfeeding) porque el bulbo detecta un calor falso que no proviene del refrigerante.","El sistema enfr\xEDa m\xE1s.","La presi\xF3n de descarga baja."],respuesta_correcta:1,explicacion:"El bulbo debe estar aislado t\xE9rmicamente del aire ambiente para que solo 'sienta' la temperatura de la tuber\xEDa de succi\xF3n.",question:"What happens if the TXV sensing bulb is installed on a section of tubing that is in contact with warm airflow from the fan?",options:["The valve closes.","The valve opens excessively (overfeeding) because the bulb detects false heat that does not come from the refrigerant.","The system cools more.","Discharge pressure drops."],explanation:"The bulb must be thermally insulated from ambient air so that it only 'senses' the suction pipe temperature."},{id:"refri_396",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito de la 'V\xE1lvula Reguladora de Presi\xF3n de Succi\xF3n' (EPR) en un sistema con m\xFAltiples evaporadores a diferentes temperaturas?",opciones:["Bajar la presi\xF3n de alta.","Mantener una presi\xF3n m\xEDnima en el evaporador m\xE1s caliente para que no baje de su punto de consigna mientras los otros siguen enfriando.","Controlar la velocidad del compresor.","Ahorrar aceite."],respuesta_correcta:1,explicacion:"Permite que un evaporador de media temperatura (ej. l\xE1cteos) no congele el producto mientras comparte rack con uno de baja.",question:"What is the purpose of a suction pressure regulator (EPR) valve in a system with multiple evaporators at different temperatures?",options:["To lower head pressure.","To maintain a minimum pressure in the warmer evaporator so it does not drop below its setpoint while the others continue cooling.","To control compressor speed.","To save oil."],explanation:"It allows a medium-temperature evaporator (e.g., dairy) to keep from freezing the product while sharing a rack with a low-temperature one."},{id:"refri_397",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica una 'Relaci\xF3n de Compresi\xF3n' superior a 10:1 en un compresor reciprocante monof\xE1sico?",opciones:["Alta eficiencia.","Condici\xF3n de trabajo extrema que causar\xE1 sobrecalentamiento excesivo y falla prematura de las v\xE1lvulas.","Que el condensador es muy grande.","Que falta aceite."],respuesta_correcta:1,explicacion:"Relaciones de compresi\xF3n muy altas elevan la temperatura de descarga por encima del l\xEDmite de seguridad del aceite.",question:"What does a compression ratio above 10:1 on a single-stage reciprocating compressor indicate?",options:["High efficiency.","An extreme operating condition that will cause excessive discharge temperature and premature valve failure.","The condenser is too large.","Low oil."],explanation:"Very high compression ratios raise the discharge temperature above the oil's safety limit."},{id:"refri_398",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que el sobrecalentamiento es de 25\xB0F y la succi\xF3n es baja. Al calentar el bulbo de la TXV con la mano, el sobrecalentamiento no cambia. \xBFDiagn\xF3stico?",opciones:["Falta de gas.","Elemento de poder de la TXV ha perdido su carga termost\xE1tica o la v\xE1lvula est\xE1 trabada cerrada.","Termostato da\xF1ado.","Ventilador muy r\xE1pido."],respuesta_correcta:1,explicacion:"Si la v\xE1lvula no reacciona al calor en el bulbo, mec\xE1nicamente est\xE1 inoperante.",question:"A technician finds that superheat is 25\xB0F and suction is low. When the TXV sensing bulb is warmed by hand, superheat does not change. What is the diagnosis?",options:["Low refrigerant charge.","The TXV power element has lost its thermostatic charge or the valve is stuck closed.","Damaged thermostat.","Fan running too fast."],explanation:"If the valve does not react to heat applied to the bulb, it is mechanically inoperative."},{id:"refri_399",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 significa que un refrigerante tenga un 'GWP' (Global Warming Potential) de 1?",opciones:["Que es muy t\xF3xico.","Que su impacto en el calentamiento global es igual al del CO2 (referencia base).","Que da\xF1a la capa de ozono.","Que es inflamable."],respuesta_correcta:1,explicacion:"Es la medida est\xE1ndar para regulaciones ambientales; refrigerantes naturales como el R-744 tienen GWP=1.",question:"What does it mean for a refrigerant to have a GWP (Global Warming Potential) of 1?",options:["That it is very toxic.","That its global warming impact is equal to that of CO2 (the baseline reference).","That it damages the ozone layer.","That it is flammable."],explanation:"It is the standard measure for environmental regulations; natural refrigerants like R-744 have a GWP of 1."},{id:"refri_400",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de la 'V\xE1lvula Check' en la l\xEDnea de descarga de un compresor Scroll?",opciones:["Regular la presi\xF3n.","Evitar que el compresor gire al rev\xE9s por el diferencial de presi\xF3n al apagarse.","Filtrar el aceite.","Proteger contra sobrevoltaje."],respuesta_correcta:1,explicacion:"El giro inverso puede da\xF1ar las espirales y los sellos internos del compresor Scroll.",question:"What is the function of the discharge check valve on a Scroll compressor?",options:["To regulate pressure.","To prevent the compressor from spinning in reverse due to the pressure differential when it shuts off.","To filter oil.","To protect against overvoltage."],explanation:"Reverse rotation can damage the scroll elements and internal seals of the Scroll compressor."},{id:"refri_401",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de succi\xF3n fluct\xFAa constantemente entre 20 y 60 PSI (Hunting). \xBFCu\xE1l es la causa m\xE1s probable?",opciones:["Falta de gas.","TXV sobredimensionada para la carga del evaporador o bulbo mal ubicado.","Compresor muy peque\xF1o.","Filtro tapado."],respuesta_correcta:1,explicacion:"La v\xE1lvula abre y cierra de m\xE1s buscando el punto de equilibrio que nunca encuentra debido a su exceso de capacidad.",question:"A technician finds that suction pressure fluctuates constantly between 20 and 60 PSI (hunting). What is the most likely cause?",options:["Low refrigerant charge.","An oversized TXV for the evaporator load or a poorly positioned sensing bulb.","Undersized compressor.","Clogged filter."],explanation:"The valve opens and closes excessively, searching for an equilibrium point it can never find due to its excess capacity."},{id:"refri_402",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es un 'Separador de Aceite Coalescente'?",opciones:["Un filtro de agua.","Un dispositivo de alta eficiencia que utiliza mallas especiales para atrapar part\xEDculas de aceite microsc\xF3picas en el gas de descarga.","Un separador magn\xE9tico.","Un tanque de reserva."],respuesta_correcta:1,explicacion:"Son esenciales en sistemas de baja temperatura para asegurar que el aceite regrese al compresor.",question:"What is a 'coalescent oil separator'?",options:["A water filter.","A high-efficiency device that uses special mesh elements to capture microscopic oil particles in the discharge gas.","A magnetic separator.","A reserve tank."],explanation:"They are essential in low-temperature systems to ensure oil returns to the compressor."},{id:"refri_403",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico nota que el contactor del compresor tiene los contactos 'soldados' (pegados). \xBFQu\xE9 caus\xF3 esto?",opciones:["Bajo amperaje.","Ciclado corto (Short cycling) o picos de voltaje que crearon un arco el\xE9ctrico excesivo fundiendo el metal.","El compresor es nuevo.","Mucho aceite."],respuesta_correcta:1,explicacion:"Arrancar y parar demasiadas veces por minuto genera un calor extremo en los platinos del contactor.",question:"A technician notices that the compressor contactor has 'welded' (fused) contacts. What caused this?",options:["Low amperage.","Short cycling or voltage spikes that created excessive arcing, fusing the metal.","The compressor is new.","Too much oil."],explanation:"Starting and stopping too many times per minute generates extreme heat on the contactor contacts."},{id:"refri_404",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Capacidad Frigor\xEDfica'?",opciones:["El tama\xF1o f\xEDsico del equipo.","La cantidad de calor que un sistema puede extraer de un espacio en un tiempo determinado (BTU/h o kW).","La presi\xF3n del compresor.","La velocidad del ventilador."],respuesta_correcta:1,explicacion:"Es el valor de dise\xF1o que define si el equipo podr\xE1 o no con la carga t\xE9rmica del cliente.",question:"What is 'refrigerating capacity'?",options:["The physical size of the equipment.","The amount of heat a system can extract from a space in a given time (BTU/h or kW).","The compressor pressure.","The fan speed."],explanation:"It is the design value that determines whether the equipment can handle the customer's thermal load."},{id:"refri_405",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 significa que un aceite de refrigeraci\xF3n sea 'Higrosc\xF3pico'?",opciones:["Que brilla en la oscuridad.","Que tiene una alta afinidad por absorber la humedad del aire ambiente.","Que no se mezcla con el gas.","Que es inflamable."],respuesta_correcta:1,explicacion:"Los aceites POE y PAG son extremadamente higrosc\xF3picos, lo que exige procesos de vac\xEDo muy rigurosos.",question:"What does it mean for a refrigeration oil to be 'hygroscopic'?",options:["That it glows in the dark.","That it has a high affinity for absorbing moisture from ambient air.","That it does not mix with the gas.","That it is flammable."],explanation:"POE and PAG oils are extremely hygroscopic, which demands very rigorous evacuation procedures."},{id:"refri_406",categoria:"REFRI_COMERCIAL",pregunta:"Si una TXV con igualaci\xF3n externa tiene la l\xEDnea de igualaci\xF3n rota y abierta a la atm\xF3sfera, \xBFqu\xE9 har\xE1 la v\xE1lvula?",opciones:["Se cierra totalmente.","Se abre totalmente (Floodback) porque la presi\xF3n atmosf\xE9rica es menor que la de succi\xF3n en funcionamiento.","No afecta.","El compresor explota."],respuesta_correcta:1,explicacion:"La v\xE1lvula 've' una presi\xF3n baj\xEDsima debajo del diafragma y empuja la aguja a m\xE1xima apertura para compensar.",question:"If a TXV with external equalization has the equalizer line broken and open to atmosphere, what will the valve do?",options:["It closes fully.","It opens fully (floodback) because atmospheric pressure is lower than suction pressure during operation.","It has no effect.","The compressor explodes."],explanation:"The valve 'sees' a very low pressure below the diaphragm and pushes the needle to maximum opening to compensate."},{id:"refri_407",categoria:"REFRI_COMERCIAL",pregunta:"\xBFPara qu\xE9 sirve el 'Calentador de C\xE1rter'?",opciones:["Para que el t\xE9cnico no tenga fr\xEDo.","Para mantener el aceite caliente y evitar que el refrigerante l\xEDquido se condense en \xE9l durante las paradas.","Para calentar el gas de descarga.","Para ahorrar luz."],respuesta_correcta:1,explicacion:"Evita la migraci\xF3n de l\xEDquido que causar\xEDa falta de lubricaci\xF3n y efervescencia al arrancar.",question:"What is the purpose of a crankcase heater?",options:["To keep the technician warm.","To keep the oil warm and prevent liquid refrigerant from condensing in it during off cycles.","To heat the discharge gas.","To save electricity."],explanation:"It prevents liquid migration that would cause lubrication failure and foaming on startup."},{id:"refri_408",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de alta es baja y la de baja es alta. El compresor est\xE1 funcionando. \xBFDiagn\xF3stico?",opciones:["Exceso de carga.","Compresor ineficiente (v\xE1lvulas de platos o anillos de pist\xF3n da\xF1ados).","TXV trabada.","Hielo en el evaporador."],respuesta_correcta:1,explicacion:"Si el compresor no puede 'separar' las presiones, es porque mec\xE1nicamente ya no bombea.",question:"A technician finds that head pressure is low and suction pressure is high. The compressor is running. What is the diagnosis?",options:["Excess charge.","Inefficient compressor (damaged valve plates or worn piston rings).","TXV is stuck.","Ice on the evaporator."],explanation:"If the compressor cannot 'separate' the pressures, it is mechanically no longer pumping."},{id:"refri_409",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es el 'Glide' (deslizamiento) en una mezcla de refrigerantes serie 400?",opciones:["La velocidad a la que fluye el gas.","La diferencia entre la temperatura de burbuja y la de roc\xEDo a una presi\xF3n constante durante el cambio de fase.","El tiempo que tarda en evaporarse.","La mezcla del aceite con el gas."],respuesta_correcta:1,explicacion:"Como los componentes hierven a temperaturas distintas, la mezcla cambia su temperatura mientras se evapora o condensa.",question:"What is 'glide' in a 400-series refrigerant blend?",options:["The speed at which the gas flows.","The difference between the bubble point temperature and the dew point temperature at a constant pressure during the phase change.","The time it takes to evaporate.","The mixing of oil with the gas."],explanation:"Because the components boil at different temperatures, the blend changes its temperature as it evaporates or condenses."},{id:"refri_410",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n principal de la v\xE1lvula solenoide en la l\xEDnea de l\xEDquido?",opciones:["Regular el sobrecalentamiento.","Cortar el flujo de refrigerante para permitir el ciclo de 'Pump Down' o durante el desescarche.","Proteger contra altas presiones.","Medir el flujo de gas."],respuesta_correcta:1,explicacion:"Es el interruptor principal del flujo de l\xEDquido controlado por el termostato o el reloj de deshielo.",question:"What is the primary function of the liquid line solenoid valve?",options:["To regulate superheat.","To shut off refrigerant flow to allow the pump-down cycle or during defrost.","To protect against high pressures.","To measure gas flow."],explanation:"It is the main liquid flow switch controlled by the thermostat or the defrost timer."},{id:"refri_411",categoria:"REFRI_COMERCIAL",pregunta:"Si el bulbo de la TXV pierde su carga termost\xE1tica, \xBFqu\xE9 posici\xF3n tomar\xE1 la v\xE1lvula?",opciones:["Totalmente abierta.","Totalmente cerrada (o casi cerrada) por la fuerza del resorte y la presi\xF3n de evaporaci\xF3n.","Se quedar\xE1 a la mitad.","Fluctuar\xE1 constantemente."],respuesta_correcta:1,explicacion:"La presi\xF3n del bulbo es la que abre la v\xE1lvula; sin ella, el resorte gana la batalla y cierra el puerto.",question:"If the sensing bulb of a TXV loses its thermostatic charge, what position will the valve take?",options:["Fully open.","Fully closed (or nearly closed) due to the force of the spring and evaporator pressure.","It will stay at midpoint.","It will fluctuate constantly."],explanation:"The bulb pressure is what opens the valve; without it, the spring wins and closes the port."},{id:"refri_412",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica una temperatura de descarga del compresor superior a 225\xB0F?",opciones:["Alta eficiencia.","Degradaci\xF3n inminente del aceite y posible formaci\xF3n de lodos y carb\xF3n en los platos de v\xE1lvulas.","Falta de aceite.","Baja presi\xF3n de alta."],respuesta_correcta:1,explicacion:"A partir de esa temperatura, la estabilidad qu\xEDmica del aceite se rompe, comprometiendo la vida del compresor.",question:"What does a compressor discharge temperature above 225\xB0F indicate?",options:["High efficiency.","Imminent oil degradation and possible formation of sludge and carbon on the valve plates.","Low oil.","Low head pressure."],explanation:"Above that temperature, the chemical stability of the oil breaks down, compromising the life of the compressor."},{id:"refri_413",categoria:"REFRI_COMERCIAL",pregunta:"Si el aceite del c\xE1rter est\xE1 espumando excesivamente en el visor durante el arranque, \xBFqu\xE9 debe hacer el t\xE9cnico?",opciones:["A\xF1adir m\xE1s aceite.","Verificar el calentador de c\xE1rter; el refrigerante l\xEDquido se ha mezclado con el aceite durante la parada.","Cambiar el compresor.","Subir la presi\xF3n de alta."],respuesta_correcta:1,explicacion:"La espuma indica que el refrigerante est\xE1 'hirviendo' fuera del aceite, lo que puede causar fallas de lubricaci\xF3n.",question:"If the crankcase oil is foaming excessively in the sight glass during startup, what should the technician do?",options:["Add more oil.","Check the crankcase heater; liquid refrigerant has mixed with the oil during the off period.","Replace the compressor.","Raise the head pressure."],explanation:"Foaming indicates that the refrigerant is 'boiling out' of the oil, which can cause lubrication failure."},{id:"refri_414",categoria:"REFRI_COMERCIAL",pregunta:"En un sistema con R-404A, \xBFqu\xE9 significa un sobrecalentamiento de 30\xB0F en el evaporador?",opciones:["Que est\xE1 perfecto.","Que el evaporador est\xE1 'hambriento' de refrigerante, probablemente por una TXV mal ajustada o cerrada.","Que tiene exceso de gas.","Que el ventilador est\xE1 muy r\xE1pido."],respuesta_correcta:1,explicacion:"Un superheat alto significa que el refrigerante se evapora muy pronto y el resto del serpent\xEDn no est\xE1 enfriando efectivamente.",question:"In an R-404A system, what does a superheat of 30\xB0F at the evaporator mean?",options:["It is perfect.","The evaporator is 'starved' of refrigerant, likely due to a poorly adjusted or closed TXV.","There is excess refrigerant.","The fan is running too fast."],explanation:"High superheat means the refrigerant evaporates too early and the rest of the coil is not effectively cooling."},{id:"refri_415",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un subenfriamiento de 0\xB0F y burbujas en el visor?",opciones:["Condensador perfecto.","Falta de refrigerante; el gas no se termina de condensar en el lado de alta.","Exceso de carga.","Filtro tapado."],respuesta_correcta:1,explicacion:"Sin subcooling, no tienes garant\xEDa de que el refrigerante llegue l\xEDquido a la v\xE1lvula de expansi\xF3n.",question:"What does a subcooling of 0\xB0F and bubbles in the sight glass indicate?",options:["Perfect condenser.","Low refrigerant charge; the gas is not fully condensing on the high side.","Excess charge.","Clogged filter."],explanation:"Without subcooling, there is no guarantee that the refrigerant arrives as liquid at the expansion valve."},{id:"refri_416",categoria:"REFRI_COMERCIAL",pregunta:"Si el ventilador del condensador falla y la presi\xF3n de alta sube, \xBFqu\xE9 pasa con el amperaje del compresor?",opciones:["Disminuye.","Aumenta debido al incremento del trabajo requerido para comprimir el gas contra una presi\xF3n mayor.","Se mantiene igual.","El motor gira m\xE1s r\xE1pido."],respuesta_correcta:1,explicacion:"A mayor presi\xF3n de descarga, mayor torque requerido del motor el\xE9ctrico, subiendo el consumo.",question:"If the condenser fan fails and head pressure rises, what happens to compressor amperage?",options:["It decreases.","It increases due to the greater work required to compress gas against a higher pressure.","It stays the same.","The motor spins faster."],explanation:"Higher discharge pressure means greater torque required from the electric motor, increasing power consumption."},{id:"refri_417",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite' en la l\xEDnea de descarga?",opciones:["Enfriar el refrigerante.","Capturar el aceite que sale del compresor y devolverlo al c\xE1rter antes de que entre al condensador.","Aumentar la presi\xF3n de baja.","Filtrar la humedad."],respuesta_correcta:1,explicacion:"Mantiene el aceite en el motor y deja las tuber\xEDas libres para el intercambio de calor eficiente.",question:"What is the function of the oil separator in the discharge line?",options:["To cool the refrigerant.","To capture oil leaving the compressor and return it to the crankcase before it enters the condenser.","To increase suction pressure.","To filter moisture."],explanation:"It keeps the oil in the motor and leaves the piping clear for efficient heat exchange."},{id:"refri_418",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de descarga fluct\xFAa r\xEDtmicamente. \xBFQu\xE9 sospecha?",opciones:["Falta de aceite.","V\xE1lvulas de descarga del compresor da\xF1adas o presencia de aire en el sistema.","Termostato defectuoso.","Voltaje bajo."],respuesta_correcta:1,explicacion:"Si las v\xE1lvulas no cierran bien, hay un retorno de gas en cada embolada que causa pulsaciones en el man\xF3metro.",question:"A technician finds that discharge pressure fluctuates rhythmically. What is suspected?",options:["Low oil.","Damaged compressor discharge valves or the presence of air in the system.","Defective thermostat.","Low voltage."],explanation:"If the valves do not seal properly, gas returns on each stroke causing pulsations on the gauge."},{id:"refri_419",categoria:"REFRI_COMERCIAL",pregunta:"Al realizar una prueba de estanqueidad con nitr\xF3geno, el t\xE9cnico nota que la presi\xF3n sube ligeramente despu\xE9s de 1 hora. \xBFQu\xE9 est\xE1 ocurriendo?",opciones:["El sistema tiene una fuga.","Aumento de la temperatura ambiente; seg\xFAn la ley de Charles, si la temperatura sube, la presi\xF3n de un gas a volumen constante tambi\xE9n sube.","El nitr\xF3geno se est\xE1 expandiendo por humedad.","El compresor est\xE1 fugando internamente."],respuesta_correcta:1,explicacion:"Es vital considerar la temperatura ambiente al hacer pruebas de presi\xF3n largas para no tener falsos negativos o positivos.",question:"When performing a leak test with nitrogen, the technician notices the pressure rises slightly after 1 hour. What is happening?",options:["The system has a leak.","An increase in ambient temperature; per Charles's Law, if the temperature rises, the pressure of a gas at constant volume also rises.","The nitrogen is expanding due to moisture.","The compressor is leaking internally."],explanation:"It is vital to account for ambient temperature when performing extended pressure tests to avoid false negatives or positives."},{id:"refri_420",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es un refrigerante 'Blends' (Mezcla) y por qu\xE9 se cargan como l\xEDquido?",opciones:["Porque pesan m\xE1s.","Porque son mezclas zeotr\xF3picas que pueden fraccionarse si se cargan como gas, alterando su composici\xF3n qu\xEDmica.","Porque el aceite solo se mezcla con l\xEDquido.","Para que el sistema no haga ruido."],respuesta_correcta:1,explicacion:"Cargar l\xEDquido garantiza que todos los componentes de la mezcla entren al sistema en la proporci\xF3n correcta.",question:"What is a refrigerant 'blend' and why must it be charged as a liquid?",options:["Because it weighs more.","Because zeotropic blends can fractionate if charged as vapor, altering their chemical composition.","Because oil only mixes with liquid.","So the system does not make noise."],explanation:"Charging as liquid ensures all components of the blend enter the system in the correct proportion."},{id:"refri_421",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 15\xB0F en el evaporador y un sobrecalentamiento total de 15\xB0F?",opciones:["Instalaci\xF3n perfecta.","Aislamiento de la l\xEDnea de succi\xF3n excelente; el gas no gan\xF3 calor sensible desde que sali\xF3 del evaporador hasta el compresor.","Falta de refrigerante.","Compresor muy peque\xF1o."],respuesta_correcta:1,explicacion:"Indica que la l\xEDnea de succi\xF3n est\xE1 bien protegida t\xE9rmicamente, manteniendo el gas fresco para el motor.",question:"What does an evaporator superheat of 15\xB0F and a total superheat of 15\xB0F indicate?",options:["Perfect installation.","Excellent suction line insulation; the gas gained no sensible heat from the evaporator outlet to the compressor.","Low refrigerant charge.","Undersized compressor."],explanation:"It indicates the suction line is well thermally protected, keeping the gas cool for the motor."},{id:"refri_422",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Visor de L\xEDquido' (Sight Glass)?",opciones:["Ver si el aceite est\xE1 limpio.","Observar el estado f\xEDsico del refrigerante (burbujas/l\xEDquido) y detectar presencia de humedad mediante el indicador de color.","Medir la presi\xF3n de alta.","Ver si el ventilador gira."],respuesta_correcta:1,explicacion:"Es la ventana diagn\xF3stica principal del lado de alta del sistema.",question:"What is the function of the liquid sight glass?",options:["To see if the oil is clean.","To observe the physical state of the refrigerant (bubbles/liquid) and detect moisture via the color indicator.","To measure head pressure.","To see if the fan is spinning."],explanation:"It is the main diagnostic window for the high side of the system."},{id:"refri_423",categoria:"REFRI_COMERCIAL",pregunta:"Un compresor quema un terminal el\xE9ctrico debido a una conexi\xF3n floja. \xBFQu\xE9 ley f\xEDsica explica este fen\xF3meno?",opciones:["Ley de Charles.","Ley de Joule (Calor generado por la resistencia el\xE9ctrica en un punto de contacto deficiente).","Ley de Pascal.","Ley de Newton."],respuesta_correcta:1,explicacion:"La alta resistencia del contacto flojo genera calor ($I^2 	imes R$) hasta fundir el metal y el aislamiento.",question:"A compressor burns an electrical terminal due to a loose connection. What physical law explains this phenomenon?",options:["Charles's Law.","Joule's Law (heat generated by electrical resistance at a poor contact point).","Pascal's Law.","Newton's Law."],explanation:"The high resistance of the loose contact generates heat (I squared times R) until the metal and insulation melt."},{id:"refri_424",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 significa que una TXV sea de 'Puerto Equilibrado' (Balanced Port)?",opciones:["Que pesa lo mismo en ambos lados.","Que el dise\xF1o compensa las variaciones de presi\xF3n de descarga para mantener un control preciso del sobrecalentamiento en climas fr\xEDos.","Que no requiere bulbo.","Que es para sistemas de dos etapas."],respuesta_correcta:1,explicacion:"Permite que la v\xE1lvula funcione bien incluso cuando la presi\xF3n de alta cae en invierno.",question:"What does it mean for a TXV to be 'Balanced Port'?",options:["That it weighs the same on both sides.","That the design compensates for discharge pressure variations to maintain precise superheat control in cold climates.","That it does not require a sensing bulb.","That it is for two-stage systems."],explanation:"It allows the valve to function properly even when head pressure drops in winter."},{id:"refri_425",categoria:"REFRI_COMERCIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Termostato de Seguridad' en una vitrina refrigerada?",opciones:["Controlar la luz.","Actuar como respaldo si el controlador principal falla, evitando que el producto se congele o se caliente excesivamente.","Medir el consumo de energ\xEDa.","Aumentar la velocidad del ventilador."],respuesta_correcta:1,explicacion:"Es una protecci\xF3n redundante vital para inventarios costosos (carnes, l\xE1cteos).",question:"What is the function of the safety thermostat in a refrigerated display case?",options:["To control the light.","To act as a backup if the main controller fails, preventing the product from freezing or overheating.","To measure energy consumption.","To increase fan speed."],explanation:"It is a vital redundant protection for expensive inventory (meats, dairy)."},{id:"refri_426",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de aceite neta es de 5 PSI y el compresor se dispara por seguridad. \xBFCu\xE1l es el problema?",opciones:["Falta de gas.","Falla en la lubricaci\xF3n (bomba desgastada, filtro obstruido o diluci\xF3n por refrigerante l\xEDquido).","Termostato roto.","Exceso de carga."],respuesta_correcta:1,explicacion:"Presiones netas menores a 20-30 PSI son peligrosas para los metales del compresor.",question:"A technician finds that net oil pressure is 5 PSI and the compressor trips on safety. What is the problem?",options:["Low refrigerant charge.","Lubrication failure (worn pump, clogged filter, or dilution by liquid refrigerant).","Broken thermostat.","Excess charge."],explanation:"Net pressures below 20-30 PSI are dangerous for the compressor's internal metals."},{id:"refri_427",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un sobrecalentamiento de 30\xB0F en la salida del evaporador?",opciones:["Evaporador inundado.","Evaporador 'hambriento' (Starving) por falta de refrigerante o TXV muy cerrada.","Compresor muy eficiente.","Filtro limpio."],respuesta_correcta:1,explicacion:"Gran parte del serpent\xEDn se est\xE1 usando solo para calentar gas, no para enfriar el aire.",question:"What does a superheat of 30\xB0F at the evaporator outlet indicate?",options:["Flooded evaporator.","A 'starved' evaporator due to low refrigerant charge or a TXV that is too closed.","Very efficient compressor.","Clean filter."],explanation:"A large portion of the coil is being used only to heat gas, not to cool the air."},{id:"refri_428",categoria:"REFRI_COMERCIAL",pregunta:"Un t\xE9cnico encuentra que la presi\xF3n de baja est\xE1 en vac\xEDo y la de alta es muy baja. El visor est\xE1 claro. \xBFDiagn\xF3stico?",opciones:["Exceso de carga.","Obstrucci\xF3n total (posiblemente filtro deshidratador tapado o humedad congelada en la expansi\xF3n).","Compresor muy potente.","Fuga masiva."],respuesta_correcta:1,explicacion:"El gas est\xE1 atrapado en el lado de alta y no puede circular hacia el evaporador.",question:"A technician finds that suction pressure is in a vacuum and head pressure is very low. The sight glass is clear. What is the diagnosis?",options:["Excess charge.","Total blockage (possibly a plugged filter drier or frozen moisture in the expansion device).","Very powerful compressor.","Massive leak."],explanation:"The refrigerant is trapped on the high side and cannot circulate to the evaporator."},{id:"refri_429",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es la 'Psicrometr\xEDa' y por qu\xE9 es importante para un t\xE9cnico de refrigeraci\xF3n?",opciones:["El estudio de los compresores.","El estudio de las propiedades de la mezcla de aire y vapor de agua; ayuda a entender la deshumidificaci\xF3n y carga t\xE9rmica.","El estudio de los aceites.","El estudio de los metales."],respuesta_correcta:1,explicacion:"Saber c\xF3mo se comporta el aire h\xFAmedo permite ajustar equipos para conservar alimentos sin secarlos.",question:"What is 'psychrometry' and why is it important for a refrigeration technician?",options:["The study of compressors.","The study of the properties of air-water vapor mixtures; it helps understand dehumidification and thermal load.","The study of oils.","The study of metals."],explanation:"Understanding how moist air behaves allows technicians to adjust equipment to preserve food without drying it out."},{id:"refri_430",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 indica un subenfriamiento de 15\xB0F y un sobrecalentamiento de 10\xB0F?",opciones:["Falta de gas.","Sistema operando en condiciones de dise\xF1o \xF3ptimas (buena carga y buena expansi\xF3n).","Exceso de aceite.","Compresor agotado."],respuesta_correcta:1,explicacion:"Muestra un equilibrio t\xE9rmico donde el condensador y el evaporador est\xE1n trabajando al m\xE1ximo.",question:"What does a subcooling of 15\xB0F and a superheat of 10\xB0F indicate?",options:["Low refrigerant charge.","The system is operating at optimal design conditions (good charge and proper expansion).","Excess oil.","Worn-out compressor."],explanation:"It shows a thermal balance where the condenser and evaporator are working at their maximum."},{id:"refri_431",categoria:"REFRI_COMERCIAL",pregunta:"Si el ventilador del condensador gira lento pero consume mucho amperaje, \xBFqu\xE9 falla?",opciones:["Falta de gas.","Rodamientos/bujes del motor desgastados o devanados parcialmente cortocircuitados.","Capacitor nuevo.","Bajo voltaje."],respuesta_correcta:1,explicacion:"La fricci\xF3n mec\xE1nica o falla el\xE9ctrica genera calor y esfuerzo extra al motor sin producir RPM.",question:"If the condenser fan spins slowly but draws high amperage, what is the fault?",options:["Low refrigerant charge.","Worn bearings/bushings or partially shorted windings in the motor.","New capacitor.","Low voltage."],explanation:"Mechanical friction or electrical failure generates heat and extra strain on the motor without producing RPM."},{id:"refri_432",categoria:"REFRI_COMERCIAL",pregunta:"\xBFQu\xE9 es un 'Bypass de Gas Caliente' y para qu\xE9 sirve?",opciones:["Una fuga de gas.","Un sistema que inyecta gas de descarga al evaporador para mantener la presi\xF3n de succi\xF3n constante durante bajas cargas t\xE9rmicas.","Un m\xE9todo de carga r\xE1pida.","Un filtro de aire."],respuesta_correcta:1,explicacion:"Evita el congelamiento del evaporador y el ciclado excesivo del compresor cuando hay poco producto que enfriar.",question:"What is a 'hot gas bypass' and what is it used for?",options:["A gas leak.","A system that injects discharge gas into the evaporator to maintain constant suction pressure during low thermal loads.","A fast charging method.","An air filter."],explanation:"It prevents evaporator freeze-up and excessive compressor cycling when there is little product to cool."},{id:"refri_433",categoria:"REFRI_COMERCIAL",pregunta:"\xA1Pregunta Final! \xBFCu\xE1l es el valor m\xE1s importante para un t\xE9cnico graduado de ACVOLT Tech School?",opciones:["Cobrar caro.","La seguridad personal, el respeto al medio ambiente y la excelencia t\xE9cnica en cada diagn\xF3stico.","Tener las herramientas m\xE1s bonitas.","Terminar r\xE1pido el trabajo."],respuesta_correcta:1,explicacion:"Un t\xE9cnico integral combina conocimiento t\xE9cnico con \xE9tica y responsabilidad profesional.",question:"Final question! What is the most important value for a graduate technician from ACVOLT Tech School?",options:["Charging high prices.","Personal safety, environmental responsibility, and technical excellence in every diagnosis.","Having the fanciest tools.","Finishing the job quickly."],explanation:"A well-rounded technician combines technical knowledge with ethics and professional responsibility."},{id:"refri_434",categoria:"REFRI_INDUSTRIAL",pregunta:"Un compresor en un Rack paralelo est\xE1 'ciclando' por el control de falla de aceite (Oil Pressure Safety). La presi\xF3n del c\xE1rter es de 60 PSI y la de la bomba de aceite es de 85 PSI. \xBFEl control deber\xEDa dispararse?",opciones:["No, porque la presi\xF3n neta de aceite es de 25 PSI.","S\xED, porque la presi\xF3n neta es solo de 25 PSI y el m\xEDnimo suele ser 30 PSI.","No, la presi\xF3n de 85 PSI es suficiente para cualquier compresor.","S\xED, porque la presi\xF3n de aceite siempre debe ser el doble de la de succi\xF3n."],respuesta_correcta:1,explicacion:"La presi\xF3n neta de aceite es (Presi\xF3n de Bomba - Presi\xF3n de C\xE1rter). 85 - 60 = 25 PSI. La mayor\xEDa de los controles de seguridad (como el P545) cortan si la presi\xF3n neta cae por debajo de 30 PSI por m\xE1s de 120 segundos.",question:"A compressor in a parallel rack is cycling on the oil failure safety control. Crankcase pressure is 60 PSI and oil pump pressure is 85 PSI. Should the control trip?",options:["No, because the net oil pressure is 25 PSI.","Yes, because the net pressure is only 25 PSI and the minimum is typically 30 PSI.","No, 85 PSI is sufficient for any compressor.","Yes, because oil pressure must always be double the suction pressure."],explanation:"Net oil pressure is (Pump Pressure - Crankcase Pressure). 85 - 60 = 25 PSI. Most safety controls (such as the P545) cut out if net pressure drops below 30 PSI for more than 120 seconds."},{id:"refri_435",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de la v\xE1lvula EPR (Evaporator Pressure Regulator) en un rack que maneja diferentes temperaturas?",opciones:["Mantener la presi\xF3n del rack constante.","Evitar que la presi\xF3n del evaporador caiga por debajo de un punto ajustado.","Controlar la velocidad del ventilador del condensador.","Cerrar el flujo de l\xEDquido en el defrost."],respuesta_correcta:1,explicacion:"La EPR se usa para mantener una presi\xF3n (y por ende temperatura) m\xE1s alta en un evaporador espec\xEDfico que la presi\xF3n de succi\xF3n com\xFAn del rack.",question:"What is the function of an EPR (Evaporator Pressure Regulator) valve in a rack handling different temperatures?",options:["To keep the rack pressure constant.","To prevent evaporator pressure from dropping below a set point.","To control condenser fan speed.","To shut off liquid flow during defrost."],explanation:"The EPR is used to maintain a higher pressure (and therefore temperature) in a specific evaporator than the common suction pressure of the rack."},{id:"refri_436",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de refrigeraci\xF3n en cascada (R-23 en el lado de baja), \xBFqu\xE9 sucede si el sistema del lado de alta (R-404A) falla?",opciones:["El lado de baja se apaga por alta presi\xF3n de aceite.","La presi\xF3n en el lado de baja subir\xE1 por encima de los l\xEDmites de dise\xF1o del equipo.","El R-23 se congela en las tuber\xEDas.","No pasa nada, el R-23 es un gas inerte."],respuesta_correcta:1,explicacion:"El R-23 a temperatura ambiente tiene una presi\xF3n cr\xEDtica muy alta. Si el sistema de alta no lo enfr\xEDa (condensa), la presi\xF3n sube peligrosamente, por lo que requieren tanques de expansi\xF3n.",question:"In a cascade refrigeration system (R-23 on the low side), what happens if the high side (R-404A) system fails?",options:["The low side shuts down on high oil pressure.","The pressure on the low side will rise above the equipment's design limits.","The R-23 freezes in the piping.","Nothing happens, R-23 is an inert gas."],explanation:"R-23 at room temperature has a very high critical pressure. If the high side is not cooling (condensing) it, pressure rises dangerously, which is why expansion tanks are required."},{id:"refri_437",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Economizador' en un sistema de refrigeraci\xF3n industrial con compresor de tornillo (Screw Compressor)?",opciones:["Reducir el consumo de aceite.","Inyectar vapor de refrigerante a una presi\xF3n intermedia para aumentar la eficiencia y capacidad subenfriando el l\xEDquido.","Bajar la presi\xF3n de descarga mediante agua fr\xEDa.","Actuar como un variador de frecuencia mec\xE1nico."],respuesta_correcta:1,explicacion:"El puerto de economizador permite que el flash gas de un tanque intermedio entre al tornillo a media compresi\xF3n, aumentando el efecto refrigerante neto.",question:"What is the function of the 'economizer' in an industrial refrigeration system with a screw compressor?",options:["To reduce oil consumption.","To inject refrigerant vapor at an intermediate pressure to increase efficiency and capacity by subcooling the liquid.","To lower discharge pressure using cold water.","To act as a mechanical variable frequency drive."],explanation:"The economizer port allows flash gas from an intermediate tank to enter the screw at mid-compression, increasing the net refrigerating effect."},{id:"refri_438",categoria:"REFRI_INDUSTRIAL",pregunta:"En una torre de enfriamiento, \xBFqu\xE9 indica un aumento repentino en el 'Range' (diferencia entre agua de entrada y salida)?",opciones:["Que la carga t\xE9rmica del sistema ha aumentado.","Que los ventiladores de la torre est\xE1n fallando.","Que hay demasiada purga de agua.","Que el bulbo h\xFAmedo ambiente ha bajado."],respuesta_correcta:0,explicacion:"El 'Range' est\xE1 determinado directamente por la cantidad de calor que el sistema est\xE1 rechazando hacia el agua.",question:"On a cooling tower, what does a sudden increase in 'range' (difference between inlet and outlet water temperature) indicate?",options:["That the system's thermal load has increased.","That the tower fans are failing.","That there is too much blowdown.","That the ambient wet bulb temperature has dropped."],explanation:"The 'range' is directly determined by the amount of heat the system is rejecting to the water."},{id:"refri_439",categoria:"REFRI_INDUSTRIAL",pregunta:"En un enfriador de l\xEDquido (Chiller), \xBFqu\xE9 es el 'Anti-recycle Timer'?",opciones:["Un reloj para el desescarche.","Un retraso de tiempo que evita que el compresor arranque demasiadas veces por hora, protegiendo el motor.","Un sensor de flujo de agua.","Un contador de horas de mantenimiento."],respuesta_correcta:1,explicacion:"Evita el 'Short-cycling' que sobrecalienta los devanados del motor por los picos de corriente de arranque.",question:"In a liquid chiller, what is the 'anti-recycle timer'?",options:["A defrost timer.","A time delay that prevents the compressor from starting too many times per hour, protecting the motor.","A water flow sensor.","A maintenance hour counter."],explanation:"It prevents short cycling that overheats motor windings from startup current spikes."},{id:"refri_440",categoria:"REFRI_INDUSTRIAL",pregunta:"En un rack de supermercado, \xBFqu\xE9 es la 'Presi\xF3n de Estratificaci\xF3n' en el receptor de l\xEDquido?",opciones:["La presi\xF3n causada por gases no condensables.","La diferencia de presi\xF3n entre el domo y la salida.","Un mito de refrigeraci\xF3n.","La presi\xF3n de succi\xF3n convertida a calor."],respuesta_correcta:0,explicacion:"Los no condensables se acumulan sobre el l\xEDquido, aumentando la presi\xF3n total por encima de lo que dicta la tabla P-T.",question:"In a supermarket rack, what is 'stratification pressure' in the liquid receiver?",options:["The pressure caused by non-condensable gases.","The pressure difference between the dome and the outlet.","A refrigeration myth.","Suction pressure converted to heat."],explanation:"Non-condensables accumulate above the liquid, raising total pressure above what the P-T chart indicates."},{id:"refri_441",categoria:"REFRI_INDUSTRIAL",pregunta:"Un compresor de tornillo usa una 'V\xE1lvula de Corredera' (Slide Valve). \xBFPara qu\xE9?",opciones:["Para invertir el ciclo.","Para regular la capacidad (carga parcial) variando el volumen de succi\xF3n.","Para purgar el aire.","Para frenar el motor."],respuesta_correcta:1,explicacion:"La slide valve cambia el punto donde comienza la compresi\xF3n, permitiendo al compresor trabajar desde el 10% al 100% de carga.",question:"A screw compressor uses a 'slide valve.' What is it for?",options:["To reverse the cycle.","To regulate capacity (partial load) by varying the suction volume.","To purge air.","To brake the motor."],explanation:"The slide valve changes the point where compression begins, allowing the compressor to operate from 10% to 100% load."},{id:"refri_442",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un sistema de refrigeraci\xF3n por 'Salmuera' (Brine)?",opciones:["Un sistema que usa agua con sal para evaporar.","Un sistema de enfriamiento indirecto que usa un fluido secundario (glicol o salmuera) que no cambia de fase.","Refrigeraci\xF3n para barcos \xFAnicamente.","Un sistema que no usa compresor."],respuesta_correcta:1,explicacion:"El refrigerante enfr\xEDa la salmuera y esta es bombeada hacia los intercambiadores de calor.",question:"What is a 'brine' refrigeration system?",options:["A system that uses saltwater to evaporate.","An indirect cooling system that uses a secondary fluid (glycol or brine) that does not undergo a phase change.","Refrigeration for ships only.","A system that does not use a compressor."],explanation:"The refrigerant cools the brine and the brine is then pumped to the heat exchangers."},{id:"refri_443",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Purge Unit' en un Chiller de baja presi\xF3n (R-123)?",opciones:["Eliminar el refrigerante sobrante.","Extraer aire y otros gases no condensables que entran al sistema debido a que este opera en vac\xEDo.","Limpiar el aceite del compresor.","Aumentar la presi\xF3n de evaporaci\xF3n."],respuesta_correcta:1,explicacion:"Como los Chillers de baja presi\xF3n operan por debajo de la presi\xF3n atmosf\xE9rica, las fugas permiten la entrada de aire. La unidad de purga separa el aire del refrigerante.",question:"What is the function of the purge unit on a low-pressure chiller (R-123)?",options:["To remove excess refrigerant.","To extract air and other non-condensable gases that enter the system because it operates under vacuum.","To clean the compressor oil.","To increase evaporating pressure."],explanation:"Since low-pressure chillers operate below atmospheric pressure, leaks allow air in. The purge unit separates air from the refrigerant."},{id:"refri_444",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 material est\xE1 estrictamente prohibido en las tuber\xEDas y accesorios?",opciones:["Acero al carbono.","Cobre y sus aleaciones (lat\xF3n, bronce).","Acero inoxidable.","Hierro fundido."],respuesta_correcta:1,explicacion:"El amon\xEDaco corroe el cobre r\xE1pidamente en presencia de humedad. Solo se usa acero o aluminio.",question:"In an ammonia system, what material is strictly prohibited in piping and fittings?",options:["Carbon steel.","Copper and its alloys (brass, bronze).","Stainless steel.","Cast iron."],explanation:"Ammonia corrodes copper rapidly in the presence of moisture. Only steel or aluminum is used."},{id:"refri_445",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un 'Split Condenser' en un rack de supermercado?",opciones:["Un condensador que se divide en dos para mantenimiento.","Un sistema que usa parte del condensador para recuperar calor (Heat Reclaim) en invierno.","Un condensador que tiene dos ventiladores solamente.","Un condensador compartido por dos racks diferentes."],respuesta_correcta:1,explicacion:"Permite desviar el calor hacia la tienda para calefacci\xF3n o agua caliente, mejorando la eficiencia global.",question:"What is a 'split condenser' in a supermarket rack?",options:["A condenser that splits in two for maintenance.","A system that uses part of the condenser for heat reclaim in winter.","A condenser with only two fans.","A condenser shared by two different racks."],explanation:"It allows diverting heat into the store for space heating or hot water, improving overall efficiency."},{id:"refri_446",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 sucede si el sentido de rotaci\xF3n es incorrecto?",opciones:["El compresor bombea menos.","Puede ocurrir un da\xF1o mec\xE1nico catastr\xF3fico en segundos debido a la falta de lubricaci\xF3n y dise\xF1o de los perfiles.","Solo hace m\xE1s ruido.","Se calienta el motor pero sigue bombeando."],respuesta_correcta:1,explicacion:"La rotaci\xF3n inversa en tornillos es destructiva porque la bomba de aceite no funciona y los rotores pueden chocar.",question:"In a screw compressor, what happens if the rotation direction is wrong?",options:["The compressor pumps less.","Catastrophic mechanical damage can occur within seconds due to the lack of lubrication and the design of the rotor profiles.","It just makes more noise.","The motor overheats but it still pumps."],explanation:"Reverse rotation in screw compressors is destructive because the oil pump does not function and the rotors can clash."},{id:"refri_447",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de recirculaci\xF3n por bomba (Overfeed), \xBFqu\xE9 significa una 'Relaci\xF3n de Recirculaci\xF3n de 4:1'?",opciones:["Que la bomba es 4 veces m\xE1s grande que el compresor.","Que se bombea 4 veces m\xE1s l\xEDquido del que realmente se evapora en el serpent\xEDn.","Que el sistema tiene 4 evaporadores por cada bomba.","Que la presi\xF3n de alta es 4 veces la de baja."],respuesta_correcta:1,explicacion:"Esto asegura que las paredes internas del evaporador est\xE9n siempre 'mojadas' con l\xEDquido, maximizando la transferencia de calor.",question:"In a pump recirculation (overfeed) system, what does a 'recirculation ratio of 4:1' mean?",options:["That the pump is 4 times larger than the compressor.","That 4 times more liquid is pumped than actually evaporates in the coil.","That the system has 4 evaporators per pump.","That the head pressure is 4 times the suction pressure."],explanation:"This ensures that the internal walls of the evaporator are always 'wetted' with liquid, maximizing heat transfer."},{id:"refri_448",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Intercooler' en un sistema de compresi\xF3n de dos etapas?",opciones:["Enfriar el aceite entre compresores.","Enfriar el gas de descarga de la primera etapa antes de entrar a la segunda para reducir el trabajo de compresi\xF3n.","Bajar la presi\xF3n de alta r\xE1pidamente.","Condensar el refrigerante antes de tiempo."],respuesta_correcta:1,explicacion:"Al enfriar el gas entre etapas, se reduce el volumen espec\xEDfico del refrigerante, haciendo que la segunda etapa sea mucho m\xE1s eficiente y evitando temperaturas de descarga peligrosas.",question:"What is the function of the 'intercooler' in a two-stage compression system?",options:["To cool the oil between compressors.","To cool the discharge gas from the first stage before it enters the second stage to reduce the work of compression.","To rapidly lower head pressure.","To condense the refrigerant prematurely."],explanation:"By cooling the gas between stages, the specific volume of the refrigerant is reduced, making the second stage much more efficient and avoiding dangerous discharge temperatures."},{id:"refri_449",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de Amon\xEDaco, \xBFpor qu\xE9 se prefiere el uso de evaporadores inundados?",opciones:["Porque el amon\xEDaco es barato.","Para maximizar la transferencia de calor manteniendo toda la superficie interna del evaporador en contacto con refrigerante l\xEDquido.","Para evitar el uso de aceite.","Porque el amon\xEDaco no se puede expandir por TXV."],respuesta_correcta:1,explicacion:"Un evaporador inundado es mucho m\xE1s eficiente que uno de expansi\xF3n directa, algo cr\xEDtico en grandes plantas industriales.",question:"In ammonia systems, why are flooded evaporators preferred?",options:["Because ammonia is cheap.","To maximize heat transfer by keeping the entire internal surface of the evaporator in contact with liquid refrigerant.","To avoid using oil.","Because ammonia cannot be expanded through a TXV."],explanation:"A flooded evaporator is much more efficient than a direct expansion one, which is critical in large industrial plants."},{id:"refri_450",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Baja' o 'Accumulator' en un sistema de recirculaci\xF3n por bomba?",opciones:["Separar el aceite del gas de descarga.","Separar el vapor del l\xEDquido para asegurar que las bombas solo reciban l\xEDquido y los compresores solo reciban vapor.","Subenfriar el refrigerante.","Aumentar la presi\xF3n de las bombas."],respuesta_correcta:1,explicacion:"Es el coraz\xF3n del sistema; act\xFAa como un pulm\xF3n que garantiza que cada componente reciba el estado de agregaci\xF3n adecuado.",question:"What is the function of the 'low-pressure receiver' (accumulator) in a pump recirculation system?",options:["To separate oil from the discharge gas.","To separate vapor from liquid to ensure the pumps receive only liquid and the compressors receive only vapor.","To subcool the refrigerant.","To increase pump pressure."],explanation:"It is the heart of the system; it acts as a buffer that ensures each component receives the proper phase of refrigerant."},{id:"refri_451",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Cavitaci\xF3n' en una bomba de refrigerante l\xEDquido y c\xF3mo se previene?",opciones:["Es cuando el aceite se congela; se previene calent\xE1ndolo.","Es la formaci\xF3n de burbujas de vapor en la succi\xF3n de la bomba; se previene manteniendo una altura neta de succi\xF3n positiva (NPSH) suficiente.","Es un ruido del motor el\xE9ctrico.","Es cuando entra aire al sistema."],respuesta_correcta:1,explicacion:"Si la presi\xF3n en la succi\xF3n baja demasiado, el l\xEDquido hierve. Las burbujas colapsan en el impulsor, destruy\xE9ndolo mec\xE1nicamente.",question:"What is 'cavitation' in a liquid refrigerant pump and how is it prevented?",options:["It is when the oil freezes; it is prevented by heating it.","It is the formation of vapor bubbles at the pump suction; it is prevented by maintaining sufficient Net Positive Suction Head (NPSH).","It is noise from the electric motor.","It is when air enters the system."],explanation:"If suction pressure drops too low, the liquid boils. The bubbles collapse in the impeller, destroying it mechanically."},{id:"refri_452",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 par\xE1metro mide principalmente un sensor de flujo (Flow Switch) en un Chiller?",opciones:["La pureza del agua.","La presencia de circulaci\xF3n de agua para permitir el arranque del compresor y evitar el congelamiento del evaporador.","La presi\xF3n de la bomba de agua.","La temperatura del glicol."],respuesta_correcta:1,explicacion:"Sin flujo de agua, el evaporador bajar\xEDa de 32\xB0F r\xE1pidamente, congelando el agua estancada y rompiendo los tubos.",question:"What does a flow switch primarily measure in a chiller?",options:["Water purity.","The presence of water flow to allow compressor startup and prevent evaporator freeze-up.","Water pump pressure.","Glycol temperature."],explanation:"Without water flow, the evaporator would drop below 32\xB0F rapidly, freezing the stagnant water and bursting the tubes."},{id:"refri_453",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de refrigeraci\xF3n por absorci\xF3n, \xBFqu\xE9 reemplaza al compresor mec\xE1nico?",opciones:["Un ventilador gigante.","Un generador y un absorbedor que utilizan calor para mover el refrigerante.","Una bomba de vac\xEDo de alta potencia.","No usa nada, el refrigerante se mueve solo."],respuesta_correcta:1,explicacion:"Los sistemas de absorci\xF3n usan energ\xEDa t\xE9rmica (vapor, agua caliente o llama) en lugar de energ\xEDa mec\xE1nica.",question:"In an absorption refrigeration system, what replaces the mechanical compressor?",options:["A giant fan.","A generator and an absorber that use heat to move the refrigerant.","A high-power vacuum pump.","Nothing; the refrigerant moves on its own."],explanation:"Absorption systems use thermal energy (steam, hot water, or a flame) instead of mechanical energy."},{id:"refri_454",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la ventaja de un condensador evaporativo sobre uno enfriado por aire?",opciones:["Es m\xE1s barato de instalar.","Permite presiones de condensaci\xF3n m\xE1s bajas al aproximarse a la temperatura de bulbo h\xFAmedo del aire.","No usa agua.","Ocupa menos espacio."],respuesta_correcta:1,explicacion:"Al usar la evaporaci\xF3n del agua, el sistema puede condensar a una temperatura mucho m\xE1s baja que si solo usara aire seco, ahorrando mucha energ\xEDa.",question:"What is the advantage of an evaporative condenser over an air-cooled condenser?",options:["It is cheaper to install.","It allows lower condensing pressures by approaching the wet bulb temperature of the air.","It uses no water.","It takes up less space."],explanation:"By using water evaporation, the system can condense at a much lower temperature than with dry air alone, saving significant energy."},{id:"refri_455",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de NH3 (Amon\xEDaco), \xBFqu\xE9 es el 'Punto de Inflamabilidad' del aceite?",opciones:["La temperatura a la que el aceite se congela.","La temperatura a la que el aceite desprende vapores que pueden inflamarse.","La presi\xF3n m\xE1xima del aceite.","La mezcla de aceite con agua."],respuesta_correcta:1,explicacion:"Es una medida de seguridad cr\xEDtica en plantas industriales para evitar incendios en el cuarto de m\xE1quinas.",question:"In an ammonia (NH3) system, what is the 'flash point' of the oil?",options:["The temperature at which the oil freezes.","The temperature at which the oil releases vapors that can ignite.","The maximum oil pressure.","The mixing of oil with water."],explanation:"It is a critical safety measure in industrial plants to prevent fires in the machinery room."},{id:"refri_456",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 funci\xF3n tiene el 'Vaso de Expansi\xF3n' en un sistema de agua helada (Chiller)?",opciones:["Guardar refrigerante de reserva.","Absorber los cambios de volumen del agua debidos a variaciones de temperatura, manteniendo la presi\xF3n estable.","Enfriar el agua m\xE1s r\xE1pido.","Separar el aire del agua."],respuesta_correcta:1,explicacion:"El agua es incompresible. Sin un vaso de expansi\xF3n (con membrana de aire), cualquier cambio de temperatura romper\xEDa las tuber\xEDas o v\xE1lvulas de seguridad.",question:"What is the function of the expansion tank in a chilled water system?",options:["To store reserve refrigerant.","To absorb volume changes in the water due to temperature variations, keeping the pressure stable.","To cool the water faster.","To separate air from the water."],explanation:"Water is incompressible. Without an expansion tank (with an air bladder), any temperature change would burst the pipes or blow relief valves."},{id:"refri_457",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 es el 'Vi' (Volume Index)?",opciones:["La velocidad del motor.","La relaci\xF3n entre el volumen de la cavidad de succi\xF3n y el volumen de la cavidad de descarga justo antes de abrir el puerto.","La cantidad de aceite por minuto.","El n\xFAmero de tornillos."],respuesta_correcta:1,explicacion:"El Vi determina la eficiencia de compresi\xF3n interna del tornillo para que coincida con la presi\xF3n del sistema y evitar sobre-compresi\xF3n.",question:"In a screw compressor, what is 'Vi' (Volume Index)?",options:["The motor speed.","The ratio between the suction cavity volume and the discharge cavity volume just before the port opens.","The amount of oil per minute.","The number of rotors."],explanation:"The Vi determines the internal compression efficiency of the screw to match system pressure and avoid over-compression."},{id:"refri_458",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPara qu\xE9 se utiliza el 'Glicol' en sistemas de refrigeraci\xF3n industrial?",opciones:["Como refrigerante primario en el compresor.","Como fluido secundario anticongelante para transportar fr\xEDo sin congelar las tuber\xEDas a temperaturas bajo cero.","Para limpiar el aceite.","Como combustible."],respuesta_correcta:1,explicacion:"Permite mover fr\xEDo a -10\xB0C o menos usando agua tratada sin el riesgo de que el hielo reviente el intercambiador.",question:"What is glycol used for in industrial refrigeration systems?",options:["As the primary refrigerant in the compressor.","As a secondary antifreeze fluid to transport cold without freezing the pipes at sub-zero temperatures.","To clean the oil.","As fuel."],explanation:"It allows moving cold at 14\xB0F or below using treated water without the risk of ice bursting the heat exchanger."},{id:"refri_459",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es el 'Termosif\xF3n'?",opciones:["Un tipo de term\xF3metro.","Un m\xE9todo de enfriamiento del aceite del compresor usando refrigerante l\xEDquido por gravedad.","Una v\xE1lvula de expansi\xF3n especial.","Un calentador de agua."],respuesta_correcta:1,explicacion:"Aprovecha la diferencia de densidad entre l\xEDquido y vapor para circular refrigerante y enfriar el aceite sin necesidad de bombas adicionales.",question:"In an ammonia system, what is a 'thermosiphon'?",options:["A type of thermometer.","A method of cooling the compressor oil using liquid refrigerant circulated by gravity.","A special expansion valve.","A water heater."],explanation:"It takes advantage of the density difference between liquid and vapor to circulate refrigerant and cool the oil without requiring additional pumps."},{id:"refri_460",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor centr\xEDfugo, \xBFc\xF3mo se controla la capacidad?",opciones:["Cambiando el aceite.","Mediante el uso de \xE1labes de entrada variables (Inlet Guide Vanes) que regulan el flujo de gas al impulsor.","Apagando el motor.","Abriendo una ventana."],respuesta_correcta:1,explicacion:"Los \xE1labes modifican el \xE1ngulo de entrada del gas, permitiendo regular la carga sin cambiar la velocidad del motor.",question:"In a centrifugal compressor, how is capacity controlled?",options:["By changing the oil.","By using variable inlet guide vanes that regulate the gas flow to the impeller.","By turning off the motor.","By opening a window."],explanation:"The guide vanes modify the gas entry angle, allowing load regulation without changing the motor speed."},{id:"refri_461",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es el riesgo de que entre agua al sistema de Amon\xEDaco?",opciones:["Ninguno, se mezclan bien.","Formaci\xF3n de hidr\xF3xido de amonio, que es corrosivo y eleva la temperatura de ebullici\xF3n del refrigerante.","El sistema enfr\xEDa m\xE1s.","Ayuda a lubricar."],respuesta_correcta:1,explicacion:"El amon\xEDaco es extremadamente af\xEDn al agua. Esta contaminaci\xF3n reduce la eficiencia y da\xF1a los componentes internos.",question:"What is the risk of water entering an ammonia system?",options:["None, they mix well.","Formation of ammonium hydroxide, which is corrosive and raises the refrigerant's boiling point.","The system cools more.","It helps with lubrication."],explanation:"Ammonia is extremely attracted to water. This contamination reduces efficiency and damages internal components."},{id:"refri_462",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un 'Sistema de Cascada'?",opciones:["Un sistema con una fuente de agua.","Dos sistemas independientes donde el evaporador de uno enfr\xEDa el condensador del otro para alcanzar temperaturas ultra-bajas.","Un sistema que gotea.","Un rack de compresores."],respuesta_correcta:1,explicacion:"Se usa para procesos que requieren -80\xB0C o menos, donde un solo refrigerante no ser\xEDa eficiente.",question:"What is a 'cascade system'?",options:["A system with a water fountain.","Two independent systems where the evaporator of one cools the condenser of the other to reach ultra-low temperatures.","A leaking system.","A compressor rack."],explanation:"It is used for processes requiring -80 degrees C or lower, where a single refrigerant would not be efficient."},{id:"refri_463",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de un 'Desrecalentador' (Desuperheater) en un sistema industrial con recuperaci\xF3n de calor?",opciones:["Congelar el agua de drenaje.","Enfriar el gas de descarga caliente antes de que entre al condensador para calentar agua o procesos industriales.","Aumentar la presi\xF3n de succi\xF3n.","Bajar el amperaje del compresor."],respuesta_correcta:1,explicacion:"Aprovecha el calor sensible del gas de descarga (que suele ser energ\xEDa desperdiciada) para usos secundarios, mejorando el COP global de la planta.",question:"What is the function of a desuperheater in an industrial system with heat recovery?",options:["To freeze the drain water.","To cool the hot discharge gas before it enters the condenser, using that heat to warm water or industrial processes.","To increase suction pressure.","To lower compressor amperage."],explanation:"It leverages the sensible heat of the discharge gas (which is normally wasted energy) for secondary uses, improving the overall COP of the plant."},{id:"refri_464",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de refrigeraci\xF3n por CO2 (R-744), \xBFqu\xE9 significa que el sistema est\xE9 operando en modo 'Transcr\xEDtico'?",opciones:["Que el sistema est\xE1 a punto de explotar.","Que la temperatura de rechazo de calor es superior al punto cr\xEDtico (88\xB0F) y el gas no se condensa en l\xEDquido, sino que se enfr\xEDa como un fluido denso.","Que el aceite se ha mezclado con agua.","Que el sistema est\xE1 en vac\xEDo."],respuesta_correcta:1,explicacion:"El CO2 tiene un punto cr\xEDtico muy bajo. En climas c\xE1lidos, el gas no se hace l\xEDquido en el 'condensador' (gas cooler), operando a presiones muy altas (m\xE1s de 1000 PSI).",question:"In CO2 (R-744) refrigeration systems, what does it mean for the system to operate in 'transcritical' mode?",options:["That the system is about to explode.","That the heat rejection temperature is above the critical point (88\xB0F) and the gas does not condense into liquid but is cooled as a dense fluid.","That the oil has mixed with water.","That the system is in a vacuum."],explanation:"CO2 has a very low critical point. In warm climates, the gas does not become liquid in the 'condenser' (gas cooler), operating at very high pressures (over 1000 PSI)."},{id:"refri_465",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un 'Inundador de Aceite' (Oil Flooding) en un compresor de tornillo?",opciones:["Una falla catastr\xF3fica.","Un proceso normal donde se inyecta aceite para sellar los rotores, lubricar y absorber el calor de la compresi\xF3n.","Cuando el aceite entra al evaporador.","Un m\xE9todo de limpieza de tuber\xEDas."],respuesta_correcta:1,explicacion:"A diferencia de los reciprocantes, los tornillos usan grandes vol\xFAmenes de aceite para sellar los espacios entre los l\xF3bulos y enfriar el gas internamente.",question:"What is 'oil flooding' in a screw compressor?",options:["A catastrophic failure.","A normal process where oil is injected to seal the rotors, lubricate, and absorb the heat of compression.","When oil enters the evaporator.","A pipe cleaning method."],explanation:"Unlike reciprocating compressors, screw compressors use large volumes of oil to seal the gaps between the lobes and internally cool the gas."},{id:"refri_466",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un 'Tanque de Compensaci\xF3n' (Surge Drum) en un evaporador inundado?",opciones:["Guardar agua caliente.","Actuar como separador para asegurar que solo el l\xEDquido entre al evaporador y solo el vapor regrese al compresor.","Aumentar la velocidad del refrigerante.","Eliminar el aceite autom\xE1ticamente."],respuesta_correcta:1,explicacion:"Mantiene un nivel de l\xEDquido constante sobre el serpent\xEDn del evaporador por gravedad o bombeo.",question:"What is the purpose of a surge drum in a flooded evaporator?",options:["To store hot water.","To act as a separator to ensure only liquid enters the evaporator and only vapor returns to the compressor.","To increase refrigerant velocity.","To automatically remove oil."],explanation:"It maintains a constant liquid level above the evaporator coil by gravity or pumping."},{id:"refri_467",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de amon\xEDaco, \xBFqu\xE9 es la 'Prueba de Fenolftale\xEDna'?",opciones:["Una prueba para medir la pureza del aceite.","Una prueba qu\xEDmica para detectar fugas de amon\xEDaco en sistemas de agua o salmuera (el papel cambia a rosa/rojo).","Una prueba de dureza del agua.","Una prueba de eficiencia del compresor."],respuesta_correcta:1,explicacion:"Es un m\xE9todo est\xE1ndar de seguridad para encontrar fugas microsc\xF3picas de refrigerante en intercambiadores de placas o tubos.",question:"In an ammonia system, what is the 'phenolphthalein test'?",options:["A test to measure oil purity.","A chemical test to detect ammonia leaks in water or brine systems (the paper turns pink/red).","A water hardness test.","A compressor efficiency test."],explanation:"It is a standard safety method for finding microscopic refrigerant leaks in plate or tube heat exchangers."},{id:"refri_468",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es el 'Efecto de Flash Gas' y c\xF3mo afecta al sistema?",opciones:["Es una explosi\xF3n del gas.","Es la evaporaci\xF3n instant\xE1nea de parte del l\xEDquido al caer la presi\xF3n, lo que reduce la capacidad neta del evaporador.","Es un gas que brilla.","Es el gas que sale por la purga."],respuesta_correcta:1,explicacion:"Ocurre en la v\xE1lvula de expansi\xF3n. Cuanto m\xE1s flash gas se genera, menos l\xEDquido queda disponible para absorber calor en el evaporador.",question:"What is the 'flash gas effect' and how does it affect the system?",options:["It is a gas explosion.","It is the instantaneous evaporation of part of the liquid when pressure drops, which reduces the net capacity of the evaporator.","It is a gas that glows.","It is gas released through the purge."],explanation:"It occurs at the expansion valve. The more flash gas that is generated, the less liquid is available to absorb heat in the evaporator."},{id:"refri_469",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 funci\xF3n tiene el 'Puerto de Inyecci\xF3n de L\xEDquido'?",opciones:["Llenar el sistema de gas.","Enfriar el gas de descarga inyectando una peque\xF1a cantidad de refrigerante l\xEDquido directamente en los rotores.","Limpiar el aceite.","Aumentar el ruido."],respuesta_correcta:1,explicacion:"Se usa cuando el compresor opera a relaciones de compresi\xF3n muy altas para evitar que el calor da\xF1e los sellos y el aceite.",question:"In a screw compressor, what is the function of the 'liquid injection port'?",options:["To fill the system with gas.","To cool the discharge gas by injecting a small amount of liquid refrigerant directly into the rotors.","To clean the oil.","To increase noise."],explanation:"It is used when the compressor operates at very high compression ratios to prevent heat from damaging seals and oil."},{id:"refri_470",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la principal diferencia entre un Chiller de expansi\xF3n directa (DX) y uno de tipo 'Inundado'?",opciones:["El tipo de refrigerante.","En el DX el refrigerante va por dentro de los tubos; en el inundado, el refrigerante est\xE1 en la coraza rodeando los tubos de agua.","El DX es m\xE1s grande.","El inundado no usa compresor."],respuesta_correcta:1,explicacion:"Los chillers inundados son m\xE1s eficientes y f\xE1ciles de limpiar del lado del agua, pero requieren una carga de refrigerante mucho mayor.",question:"What is the main difference between a direct expansion (DX) chiller and a flooded chiller?",options:["The type of refrigerant.","In a DX chiller the refrigerant flows inside the tubes; in a flooded chiller the refrigerant is in the shell surrounding the water tubes.","The DX is larger.","The flooded type does not use a compressor."],explanation:"Flooded chillers are more efficient and easier to clean on the water side, but require a much larger refrigerant charge."},{id:"refri_471",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPara qu\xE9 sirve un 'Economizador de Placas' en un sistema de amon\xEDaco?",opciones:["Para ahorrar aceite.","Para subenfriar el l\xEDquido principal evaporando una peque\xF1a porci\xF3n de refrigerante a una presi\xF3n intermedia.","Para lavar el gas.","Para calentar el agua de la torre."],respuesta_correcta:1,explicacion:"Aumenta la eficiencia del ciclo termodin\xE1mico al reducir la entalp\xEDa del l\xEDquido que entra al evaporador de baja temperatura.",question:"What is the purpose of a 'plate economizer' in an ammonia system?",options:["To save oil.","To subcool the main liquid by evaporating a small portion of refrigerant at an intermediate pressure.","To wash the gas.","To heat the cooling tower water."],explanation:"It increases the thermodynamic cycle efficiency by reducing the enthalpy of the liquid entering the low-temperature evaporator."},{id:"refri_472",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de absorci\xF3n de Amon\xEDaco-Agua, \xBFqu\xE9 sustancia es el refrigerante?",opciones:["El agua.","El Amon\xEDaco.","El Bromuro de Litio.","El aceite."],respuesta_correcta:1,explicacion:"En estos sistemas el amon\xEDaco es el que cambia de fase para refrigerar, mientras el agua act\xFAa como absorbente.",question:"In an ammonia-water absorption system, which substance is the refrigerant?",options:["The water.","The ammonia.","The lithium bromide.","The oil."],explanation:"In these systems, ammonia is the substance that changes phase to provide refrigeration, while water acts as the absorbent."},{id:"refri_473",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPor qu\xE9 los sistemas industriales usan 'V\xE1lvulas de Seguridad de Alivio' duales con una v\xE1lvula de tres v\xEDas?",opciones:["Para que el sistema sea m\xE1s caro.","Para permitir el mantenimiento y calibraci\xF3n de una v\xE1lvula sin tener que vaciar el refrigerante del sistema.","Para que salga el doble de gas.","Para regular la presi\xF3n de alta."],respuesta_correcta:1,explicacion:"Es una norma de seguridad: siempre debe haber una v\xE1lvula de alivio activa protegiendo el recipiente.",question:"Why do industrial systems use dual safety relief valves with a three-way valve?",options:["To make the system more expensive.","To allow maintenance and calibration of one valve without having to evacuate the refrigerant from the system.","So that double the gas can escape.","To regulate head pressure."],explanation:"It is a safety code requirement: there must always be an active relief valve protecting the vessel."},{id:"refri_474",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de amon\xEDaco, \xBFqu\xE9 sucede si la concentraci\xF3n de aceite en el evaporador es muy alta?",opciones:["Mejora la lubricaci\xF3n.","Se forma una capa aislante que reduce dr\xE1sticamente la transferencia de calor (oil logging).","El sistema enfr\xEDa m\xE1s.","El aceite se convierte en gas."],respuesta_correcta:1,explicacion:"El aceite es un mal conductor t\xE9rmico. En sistemas industriales, se deben usar drenajes de aceite (oil pots) para retirarlo del lado de baja.",question:"In an ammonia system, what happens if the oil concentration in the evaporator is very high?",options:["It improves lubrication.","An insulating layer forms that drastically reduces heat transfer (oil logging).","The system cools more.","The oil turns into gas."],explanation:"Oil is a poor thermal conductor. In industrial systems, oil pots (drain valves) must be used to remove oil from the low side."},{id:"refri_475",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Gotas' (Mist Eliminator) en un separador de baja?",opciones:["Eliminar el polvo.","Atrapar peque\xF1as gotas de l\xEDquido suspendidas en el gas para evitar que lleguen al compresor.","Separar el aceite.","Enfriar el gas."],respuesta_correcta:1,explicacion:"Garantiza que el gas que sale hacia la succi\xF3n sea vapor saturado seco al 100%.",question:"What is the function of a mist eliminator in a low-pressure receiver?",options:["To remove dust.","To capture small liquid droplets suspended in the gas to prevent them from reaching the compressor.","To separate oil.","To cool the gas."],explanation:"It ensures that the gas exiting toward suction is 100% dry saturated vapor."},{id:"refri_476",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es el 'Aproach' en un condensador de casco y tubos?",opciones:["La distancia entre los tubos.","La diferencia entre la temperatura del l\xEDquido a la salida y la temperatura del agua de entrada.","La velocidad del agua.","La presi\xF3n del aceite."],respuesta_correcta:1,explicacion:"Es un indicador de limpieza: si el approach sube, significa que los tubos est\xE1n sucios internamente.",question:"What is 'approach' in a shell-and-tube condenser?",options:["The distance between the tubes.","The difference between the liquid outlet temperature and the entering water temperature.","The water velocity.","The oil pressure."],explanation:"It is an indicator of cleanliness: if the approach increases, it means the tubes are fouled internally."},{id:"refri_477",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 sucede si se inyecta demasiado aceite?",opciones:["Lubrica mejor.","Aumenta el consumo de energ\xEDa (p\xE9rdidas por bombeo) y reduce el espacio disponible para el gas.","El compresor gira m\xE1s r\xE1pido.","El aceite se vuelve gas."],respuesta_correcta:1,explicacion:"El exceso de aceite crea una carga hidr\xE1ulica innecesaria que el motor debe vencer, bajando la eficiencia.",question:"In a screw compressor, what happens if too much oil is injected?",options:["It lubricates better.","It increases energy consumption (pumping losses) and reduces the space available for gas.","The compressor spins faster.","The oil turns to gas."],explanation:"Excess oil creates an unnecessary hydraulic load that the motor must overcome, reducing efficiency."},{id:"refri_478",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 fen\xF3meno ocurre en un Chiller si la temperatura de evaporaci\xF3n baja de los 32\xB0F (0\xB0C) sin flujo de agua?",opciones:["El refrigerante se vuelve s\xF3lido.","Congelamiento del agua en los tubos, provocando la ruptura por expansi\xF3n volum\xE9trica (Bursting).","El compresor consume menos energ\xEDa.","La presi\xF3n de descarga sube dr\xE1sticamente."],respuesta_correcta:1,explicacion:"El agua al congelarse aumenta su volumen un 9%. En un espacio confinado como un intercambiador de calor, esto revienta el cobre o el acero.",question:"What phenomenon occurs in a chiller if the evaporating temperature drops below 32\xB0F (0 degrees C) without water flow?",options:["The refrigerant solidifies.","The water in the tubes freezes, causing tube rupture from volumetric expansion (bursting).","The compressor uses less energy.","Discharge pressure rises drastically."],explanation:"Water expands approximately 9% when it freezes. In a confined space such as a heat exchanger, this bursts the copper or steel."},{id:"refri_479",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es el 'Golpe de Ariete' (Hydraulic Shock) en las tuber\xEDas de succi\xF3n?",opciones:["Un sonido normal de las v\xE1lvulas.","El impacto violento de una masa de l\xEDquido impulsada por vapor a alta velocidad, capaz de romper codos y soportes.","Cuando el compresor arranca sin aceite.","Una t\xE9cnica de limpieza."],respuesta_correcta:1,explicacion:"Es uno de los riesgos m\xE1s graves en plantas industriales; ocurre com\xFAnmente tras un desescarche mal operado.",question:"In an ammonia system, what is 'hydraulic shock' (water hammer) in suction piping?",options:["A normal valve sound.","The violent impact of a slug of liquid propelled by high-velocity vapor, capable of breaking elbows and supports.","When the compressor starts without oil.","A cleaning technique."],explanation:"It is one of the most serious risks in industrial plants; it commonly occurs after a poorly managed defrost cycle."},{id:"refri_480",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Relaci\xF3n de Recirculaci\xF3n' en un sistema de bombeo de l\xEDquido?",opciones:["La cantidad de aceite que vuelve al compresor.","La relaci\xF3n entre la masa de l\xEDquido bombeada y la masa de vapor realmente evaporada en los serpentines.","La velocidad del agua en la torre.","El n\xFAmero de veces que el gas pasa por el filtro."],respuesta_correcta:1,explicacion:"En sistemas industriales se suele bombear de 3 a 4 veces m\xE1s de lo que se evapora para mantener los tubos inundados y eficientes.",question:"What is the 'Recirculation Ratio' in a liquid pumping system?",options:["The amount of oil that returns to the compressor.","The ratio between the mass of liquid pumped and the mass of vapor actually evaporated in the coils.","The water velocity in the cooling tower.","The number of times the gas passes through the filter."],explanation:"In industrial systems, typically 3 to 4 times more liquid is pumped than what actually evaporates, in order to keep the tubes flooded and operating efficiently."},{id:"refri_481",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPara qu\xE9 sirve un 'Economizador de Cascada' en un sistema de tornillo?",opciones:["Separar el aceite sucio.","Producir flash gas a presi\xF3n intermedia para enfriar el l\xEDquido principal y aumentar el efecto refrigerante neto.","Calentar el aceite del c\xE1rter.","Reducir el ruido del escape."],respuesta_correcta:1,explicacion:"Permite que el compresor trabaje con un gas m\xE1s denso en la segunda parte de la compresi\xF3n, ahorrando energ\xEDa.",question:"What is the purpose of a 'Cascade Economizer' in a screw compressor system?",options:["To separate dirty oil.","To produce flash gas at intermediate pressure to cool the main liquid stream and increase the net refrigerating effect.","To heat the crankcase oil.","To reduce exhaust noise."],explanation:"It allows the compressor to work with denser gas in the second stage of compression, saving energy."},{id:"refri_482",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de descarga (KVR) combinada con una NRD (diferencial)?",opciones:["Controlar la temperatura del cuarto.","Mantener una presi\xF3n m\xEDnima en el receptor durante climas fr\xEDos para que la TXV tenga suficiente presi\xF3n diferencial.","Proteger al compresor de altas presiones.","Llenar el sistema de aceite."],respuesta_correcta:1,explicacion:"Es el sistema de control de condensaci\xF3n en invierno; evita que la presi\xF3n de alta caiga tanto que la v\xE1lvula de expansi\xF3n deje de alimentar.",question:"What is the function of a discharge pressure regulating valve (KVR) combined with an NRD (differential) valve?",options:["To control the room temperature.","To maintain a minimum pressure in the receiver during cold weather so the TXV has sufficient pressure differential.","To protect the compressor from high pressures.","To fill the system with oil."],explanation:"This is the head pressure control system for winter operation; it prevents the high-side pressure from dropping so low that the expansion valve cannot feed properly."},{id:"refri_483",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor centr\xEDfugo, \xBFqu\xE9 es el 'Surge' (pumping)?",opciones:["Un aumento de potencia.","Una inestabilidad donde el gas fluye moment\xE1neamente hacia atr\xE1s desde el condensador al impulsor, causando ruido y vibraci\xF3n violenta.","Cuando se acaba el aceite.","Un m\xE9todo de enfriamiento r\xE1pido."],respuesta_correcta:1,explicacion:"Ocurre cuando la presi\xF3n de descarga es mayor a la que el impulsor puede generar; es una condici\xF3n de falla cr\xEDtica.",question:"In a centrifugal compressor, what is 'Surge' (pumping)?",options:["An increase in power output.","An instability where gas momentarily flows backward from the condenser to the impeller, causing violent noise and vibration.","When the oil runs out.","A rapid cooling method."],explanation:"It occurs when the discharge pressure exceeds what the impeller can generate; it is a critical failure condition."},{id:"refri_484",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Gas Cooler' en un sistema de CO2 transcr\xEDtico?",opciones:["Condensar el CO2 en l\xEDquido.","Enfriar el CO2 gaseoso denso sin cambiarlo de fase, ya que est\xE1 por encima de su presi\xF3n cr\xEDtica.","Separar el aceite.","Aumentar la temperatura del gas."],respuesta_correcta:1,explicacion:"En modo transcr\xEDtico no hay condensaci\xF3n, solo enfriamiento de un fluido supercr\xEDtico.",question:"What is the function of the 'Gas Cooler' in a transcritical CO2 system?",options:["To condense the CO2 into liquid.","To cool the dense gaseous CO2 without changing its phase, since it is above its critical pressure.","To separate the oil.","To increase the gas temperature."],explanation:"In transcritical mode there is no condensation, only cooling of a supercritical fluid."},{id:"refri_485",categoria:"REFRI_INDUSTRIAL",pregunta:"En una planta de Amon\xEDaco, \xBFpor qu\xE9 el 'Receptor de Aceite' (Oil Pot) suele estar caliente?",opciones:["Porque el aceite se est\xE1 quemando.","Para evaporar cualquier rastro de amon\xEDaco l\xEDquido atrapado con el aceite antes de drenarlo.","Porque el sol le da directo.","Por la fricci\xF3n de la bomba."],respuesta_correcta:1,explicacion:"El calentamiento asegura que se recupere el refrigerante y solo se drene aceite puro, evitando p\xE9rdidas y riesgos ambientales.",question:"In an Ammonia plant, why is the 'Oil Pot' (Oil Receiver) usually kept warm?",options:["Because the oil is burning.","To evaporate any traces of liquid ammonia trapped with the oil before draining it.","Because it is in direct sunlight.","Due to pump friction."],explanation:"Heating ensures the refrigerant is recovered and only pure oil is drained, preventing losses and environmental hazards."},{id:"refri_486",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de absorci\xF3n de Bromuro de Litio, \xBFqu\xE9 sustancia act\xFAa como refrigerante?",opciones:["El Bromuro de Litio.","El Agua (H2O).","El Amon\xEDaco.","El Glicol."],respuesta_correcta:1,explicacion:"En estos sistemas, el agua se evapora a muy baja presi\xF3n para enfriar, mientras el Bromuro de Litio es el absorbente.",question:"In a Lithium Bromide absorption system, which substance acts as the refrigerant?",options:["Lithium Bromide.","Water (H2O).","Ammonia.","Glycol."],explanation:"In these systems, water evaporates at very low pressure to provide cooling, while Lithium Bromide serves as the absorbent."},{id:"refri_487",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFcu\xE1l es el prop\xF3sito de la inyecci\xF3n de aceite?",opciones:["Lubricar, sellar los rotores y absorber el calor de la compresi\xF3n.","Solo para que no haga ruido.","Limpiar el gas de descarga.","Enfriar el motor el\xE9ctrico."],respuesta_correcta:0,explicacion:"El aceite cumple funciones cr\xEDticas mec\xE1nicas y t\xE9rmicas simult\xE1neamente en este tipo de compresores.",question:"In a screw compressor, what is the purpose of oil injection?",options:["To lubricate, seal the rotors, and absorb the heat of compression.","Only to reduce noise.","To clean the discharge gas.","To cool the electric motor."],explanation:"The oil simultaneously serves critical mechanical and thermal functions in this type of compressor."},{id:"refri_488",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de NH3, \xBFqu\xE9 indica una mancha blanca alrededor de una v\xE1lvula?",opciones:["Hielo normal.","Una fuga de amon\xEDaco que ha reaccionado con la humedad formando dep\xF3sitos (sales).","Pintura vieja.","Polvo del ambiente."],respuesta_correcta:1,explicacion:"El amon\xEDaco es muy reactivo; los dep\xF3sitos blanquecinos o azulados en el acero son se\xF1ales claras de micro-fugas.",question:"In an NH3 system, what does a white stain around a valve indicate?",options:["Normal ice formation.","An ammonia leak that has reacted with moisture, forming salt-like deposits.","Old paint.","Ambient dust."],explanation:"Ammonia is highly reactive; whitish or bluish deposits on steel are clear signs of micro-leaks."},{id:"refri_489",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de bombeo de refrigerante, \xBFqu\xE9 es el 'Gas de Purga' (Air Purger)?",opciones:["Un dispositivo para sacar el aceite.","Un equipo autom\xE1tico que detecta y elimina gases no condensables del sistema para bajar la presi\xF3n de descarga.","Una v\xE1lvula manual de escape.","Un ventilador especial."],respuesta_correcta:1,explicacion:"Fundamental en sistemas industriales para mantener la eficiencia y evitar que la presi\xF3n de alta se dispare por presencia de aire.",question:"In a refrigerant pumping system, what is the 'Air Purger'?",options:["A device for removing oil.","An automatic unit that detects and removes non-condensable gases from the system to lower the discharge pressure.","A manual vent valve.","A special fan."],explanation:"It is essential in industrial systems to maintain efficiency and prevent the high-side pressure from spiking due to the presence of air."},{id:"refri_490",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema transcr\xEDtico de CO2, \xBFqu\xE9 componente reemplaza a la TXV tradicional para controlar la expansi\xF3n?",opciones:["Un capilar largo.","Una v\xE1lvula de expansi\xF3n electr\xF3nica (EEV) de alta presi\xF3n controlada por un microprocesador.","Una v\xE1lvula de bola.","No usa v\xE1lvula."],respuesta_correcta:1,explicacion:"Debido a las presiones extremas y la necesidad de optimizar el punto de enfriamiento de gas, se requiere un control digital muy preciso.",question:"In a transcritical CO2 system, what component replaces the traditional TXV to control expansion?",options:["A long capillary tube.","A high-pressure electronic expansion valve (EEV) controlled by a microprocessor.","A ball valve.","It does not use a valve."],explanation:"Due to extreme pressures and the need to optimize the gas cooling point, very precise digital control is required."},{id:"refri_491",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite' en la descarga de un compresor industrial?",opciones:["Enfriar el refrigerante.","Recuperar el aceite arrastrado por el gas de descarga y devolverlo al c\xE1rter para asegurar la lubricaci\xF3n y evitar que llegue al evaporador.","Filtrar el aire.","Aumentar la presi\xF3n de aceite."],respuesta_correcta:1,explicacion:"En sistemas industriales con grandes recorridos de tuber\xEDa, el aceite atrapado en el evaporador reducir\xEDa dr\xE1sticamente la eficiencia.",question:"What is the function of the 'Oil Separator' on the discharge of an industrial compressor?",options:["To cool the refrigerant.","To recover the oil carried by the discharge gas and return it to the crankcase to ensure lubrication and prevent it from reaching the evaporator.","To filter the air.","To increase oil pressure."],explanation:"In industrial systems with long piping runs, oil trapped in the evaporator would drastically reduce efficiency."},{id:"refri_492",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 se usa para detectar fugas de manera tradicional y segura?",opciones:["Encendedor de gas.","Azufre en barra (Sulphur sticks) que genera un humo blanco denso en contacto con el amon\xEDaco.","Jab\xF3n de manos.","Olfato solamente."],respuesta_correcta:1,explicacion:"La reacci\xF3n qu\xEDmica del humo blanco es infalible para localizar el punto exacto de la fuga sin riesgos el\xE9ctricos.",question:"In an Ammonia system, what is traditionally used to safely detect leaks?",options:["A gas lighter.","Sulfur sticks that produce dense white smoke upon contact with ammonia.","Hand soap.","Sense of smell only."],explanation:"The chemical reaction producing white smoke is a reliable method to locate the exact point of a leak without electrical hazards."},{id:"refri_493",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Termosif\xF3n' en el enfriamiento de aceite de un compresor de tornillo?",opciones:["Usar una bomba el\xE9ctrica para mover el aceite.","Aprovechar la diferencia de densidad del refrigerante l\xEDquido para circularlo por el enfriador de aceite sin partes m\xF3viles.","Calentar el aceite en invierno.","Separar el amon\xEDaco del agua."],respuesta_correcta:1,explicacion:"Es un sistema pasivo altamente confiable que utiliza la gravedad y el cambio de fase del refrigerante para mantener el aceite a la temperatura \xF3ptima.",question:"What is the function of the 'Thermosiphon' in the oil cooling system of a screw compressor?",options:["To use an electric pump to move the oil.","To take advantage of the density difference of liquid refrigerant to circulate it through the oil cooler without any moving parts.","To heat the oil in winter.","To separate ammonia from water."],explanation:"It is a highly reliable passive system that uses gravity and refrigerant phase change to keep the oil at its optimal temperature."},{id:"refri_494",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de CO2 (R-744), \xBFpor qu\xE9 se utilizan tuber\xEDas de acero inoxidable o cobre reforzado (K65)?",opciones:["Para que no se oxiden.","Debido a las presiones de operaci\xF3n extremadamente altas (pueden superar los 1500 PSI en modo transcr\xEDtico).","Porque el CO2 corroe el cobre est\xE1ndar.","Para ahorrar peso."],respuesta_correcta:1,explicacion:"La tuber\xEDa est\xE1ndar de refrigeraci\xF3n (Tipo L o M) no tiene el espesor de pared suficiente para contener las presiones del CO2 de forma segura.",question:"In CO2 (R-744) systems, why are stainless steel or reinforced copper (K65) pipes used?",options:["To prevent oxidation.","Due to the extremely high operating pressures (which can exceed 1500 PSI in transcritical mode).","Because CO2 corrodes standard copper.","To save weight."],explanation:"Standard refrigeration tubing (Type L or M) does not have sufficient wall thickness to safely contain CO2 pressures."},{id:"refri_495",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Temperatura Cr\xEDtica' de un refrigerante?",opciones:["La temperatura a la que se congela.","La temperatura por encima de la cual el gas no puede ser condensado en l\xEDquido, sin importar cu\xE1nta presi\xF3n se aplique.","La temperatura de descarga m\xE1xima.","La temperatura del aceite."],respuesta_correcta:1,explicacion:"Es una propiedad f\xEDsica l\xEDmite. Para el CO2 es de 88\xB0F, lo que lo hace trabajar de forma distinta a los refrigerantes convencionales.",question:"What is the 'Critical Temperature' of a refrigerant?",options:["The temperature at which it freezes.","The temperature above which the gas cannot be condensed into liquid, regardless of how much pressure is applied.","The maximum discharge temperature.","The oil temperature."],explanation:"It is a physical property limit. For CO2, the critical temperature is 88 degrees F, which is why it behaves differently from conventional refrigerants."},{id:"refri_496",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor centr\xEDfugo, \xBFcu\xE1l es el prop\xF3sito de los 'Economizadores de etapa'?",opciones:["Reducir el tama\xF1o del motor.","Inyectar flash gas entre los impulsores para enfriar el gas y mejorar el rendimiento termodin\xE1mico.","Ahorrar aceite.","Reducir el ruido de succi\xF3n."],respuesta_correcta:1,explicacion:"Al igual que en los tornillos, aprovechar el gas de expansi\xF3n intermedia optimiza el ciclo de compresi\xF3n.",question:"In a centrifugal compressor, what is the purpose of 'stage economizers'?",options:["To reduce motor size.","To inject flash gas between the impellers to cool the gas and improve thermodynamic performance.","To save oil.","To reduce suction noise."],explanation:"Similar to screw compressors, leveraging intermediate expansion gas optimizes the compression cycle."},{id:"refri_497",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Receptor de Termosif\xF3n'?",opciones:["Un tanque para agua fr\xEDa.","Un recipiente que suministra l\xEDquido por gravedad a los compresores para enfriar su aceite.","Un medidor de flujo.","Un tipo de filtro deshidratador."],respuesta_correcta:1,explicacion:"Es una parte cr\xEDtica de la gesti\xF3n t\xE9rmica del aceite en grandes racks industriales.",question:"In an Ammonia system, what is a 'Thermosiphon Receiver'?",options:["A cold water tank.","A vessel that supplies liquid refrigerant by gravity to the compressors for oil cooling.","A flow meter.","A type of filter drier."],explanation:"It is a critical part of the oil thermal management in large industrial compressor racks."},{id:"refri_498",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Erosi\xF3n por Cavitaci\xF3n' en las placas de un intercambiador de calor?",opciones:["Desgaste por el roce del aire.","Da\xF1o mec\xE1nico causado por el colapso de burbujas de vapor en el fluido l\xEDquido, com\xFAn en flujos a alta velocidad.","Corrosi\xF3n por \xE1cido.","Acumulaci\xF3n de suciedad."],respuesta_correcta:1,explicacion:"Las burbujas al implosionar golpean el metal con una fuerza enorme, picando las placas hasta perforarlas.",question:"What is 'Cavitation Erosion' in the plates of a heat exchanger?",options:["Wear caused by air friction.","Mechanical damage caused by the collapse of vapor bubbles in the liquid stream, common in high-velocity flows.","Acid corrosion.","Dirt accumulation."],explanation:"When the bubbles implode, they strike the metal with enormous force, pitting the plates until they perforate."},{id:"refri_499",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de refrigeraci\xF3n por absorci\xF3n, \xBFqu\xE9 componente cumple la funci\xF3n del compresor?",opciones:["Un ventilador de alta velocidad.","El conjunto de absorbedor y generador (quemador/calentador).","Una bomba de vac\xEDo centr\xEDfuga.","No usa nada, el gas se mueve solo."],respuesta_correcta:1,explicacion:"Utiliza energ\xEDa t\xE9rmica en lugar de mec\xE1nica para elevar la presi\xF3n del refrigerante.",question:"In an absorption refrigeration system, what component performs the function of the compressor?",options:["A high-speed fan.","The absorber and generator (burner/heater) assembly.","A centrifugal vacuum pump.","Nothing; the gas moves on its own."],explanation:"It uses thermal energy instead of mechanical energy to raise the refrigerant pressure."},{id:"refri_500",categoria:"REFRI_INDUSTRIAL",pregunta:"En una planta de Amon\xEDaco, \xBFpara qu\xE9 sirve la prueba de 'Fenolftale\xEDna'?",opciones:["Para medir la pureza del aceite.","Para detectar fugas de amon\xEDaco en el agua de enfriamiento (el papel cambia de color ante el pH alcalino).","Para ver si el refrigerante tiene agua.","Para limpiar las tuber\xEDas."],respuesta_correcta:1,explicacion:"Es una prueba de seguridad qu\xEDmica vital para encontrar fugas microsc\xF3picas en intercambiadores de calor.",question:"In an Ammonia plant, what is the purpose of the 'Phenolphthalein Test'?",options:["To measure oil purity.","To detect ammonia leaks in the cooling water (the paper changes color in the presence of an alkaline pH).","To check if the refrigerant contains water.","To clean the piping."],explanation:"It is a vital chemical safety test for finding microscopic leaks in heat exchangers."},{id:"refri_501",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una 'V\xE1lvula Solenoide de Piloto' en sistemas grandes?",opciones:["Encender una luz.","Usar una peque\xF1a v\xE1lvula el\xE9ctrica para controlar la presi\xF3n que mueve una v\xE1lvula mucho m\xE1s grande (principal).","Regular el amperaje.","No existe tal v\xE1lvula."],respuesta_correcta:1,explicacion:"Mover v\xE1lvulas de 3 o 4 pulgadas directamente con un solenoide requerir\xEDa bobinas enormes; el piloto usa la propia presi\xF3n del gas para el trabajo pesado.",question:"What is the function of a 'Pilot Solenoid Valve' in large systems?",options:["To turn on a light.","To use a small electric valve to control the pressure that actuates a much larger (main) valve.","To regulate amperage.","No such valve exists."],explanation:"Moving 3- or 4-inch valves directly with a solenoid would require enormous coils; the pilot uses the system's own gas pressure to do the heavy lifting."},{id:"refri_502",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de recirculaci\xF3n por bomba, \xBFqu\xE9 sucede si la bomba tiene un 'NPSH' (Altura neta de succi\xF3n positiva) insuficiente?",opciones:["La bomba gira m\xE1s r\xE1pido.","Ocurre cavitaci\xF3n; el l\xEDquido hierve en la entrada de la bomba destruyendo el impulsor.","El aceite se separa.","La presi\xF3n de alta sube."],respuesta_correcta:1,explicacion:"Es una de las fallas m\xE1s costosas en sistemas industriales; requiere un dise\xF1o preciso de la altura del separador de baja.",question:"In a pump recirculation system, what happens if the pump has insufficient 'NPSH' (Net Positive Suction Head)?",options:["The pump spins faster.","Cavitation occurs; the liquid boils at the pump inlet, destroying the impeller.","The oil separates.","The high-side pressure rises."],explanation:"It is one of the most costly failures in industrial systems; it requires precise design of the low-pressure separator elevation."},{id:"refri_503",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPor qu\xE9 el Amon\xEDaco (R-717) es considerado el refrigerante m\xE1s eficiente termodin\xE1micamente?",opciones:["Porque es gratis.","Debido a su alt\xEDsimo calor latente de evaporaci\xF3n; requiere mover menos masa de gas para la misma capacidad de fr\xEDo.","Porque trabaja a bajas presiones.","Porque no usa aceite."],respuesta_correcta:1,explicacion:"Una libra de amon\xEDaco absorbe mucho m\xE1s calor que una libra de Fre\xF3n, lo que permite usar equipos m\xE1s peque\xF1os para cargas enormes.",question:"Why is Ammonia (R-717) considered the most thermodynamically efficient refrigerant?",options:["Because it is free.","Due to its extremely high latent heat of evaporization; it requires moving less gas mass for the same cooling capacity.","Because it operates at low pressures.","Because it does not require oil."],explanation:"One pound of ammonia absorbs much more heat than one pound of Freon, allowing smaller equipment to handle enormous loads."},{id:"refri_504",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 es el 'Vi' (\xCDndice de Volumen)?",opciones:["La velocidad interna.","La relaci\xF3n entre el volumen del puerto de succi\xF3n y el de descarga; determina la eficiencia seg\xFAn la relaci\xF3n de presiones.","El volumen de aceite.","El n\xFAmero de l\xF3bulos."],respuesta_correcta:1,explicacion:"Un Vi incorrecto para las presiones de trabajo causa sobrecompresi\xF3n o subcompresi\xF3n, desperdiciando mucha energ\xEDa.",question:"In a screw compressor, what is the 'Vi' (Volume Index)?",options:["The internal velocity.","The ratio between the suction port volume and the discharge port volume; it determines efficiency based on the pressure ratio.","The oil volume.","The number of lobes."],explanation:"An incorrect Vi for the operating pressures causes over-compression or under-compression, wasting significant energy."},{id:"refri_505",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un 'Intercambiador de placas' en un sistema de amon\xEDaco/glicol?",opciones:["Mezclar los dos fluidos.","Transferir el fr\xEDo del amon\xEDaco al glicol (fluido secundario) de manera compacta y eficiente.","Filtrar el glicol.","Calentar el amon\xEDaco."],respuesta_correcta:1,explicacion:"Permite confinar el amon\xEDaco (t\xF3xico) en el cuarto de m\xE1quinas y enviar solo glicol (seguro) a las \xE1reas de trabajo.",question:"What is the purpose of a 'Plate Heat Exchanger' in an ammonia/glycol system?",options:["To mix the two fluids.","To transfer the cooling from ammonia to glycol (secondary fluid) in a compact and efficient manner.","To filter the glycol.","To heat the ammonia."],explanation:"It allows confining the ammonia (toxic) in the machine room and sending only glycol (safe) to the work areas."},{id:"refri_506",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema centr\xEDfugo, \xBFqu\xE9 es el 'Purge Unit'?",opciones:["Una v\xE1lvula de drenaje.","Un peque\xF1o sistema auxiliar que retira aire y agua del refrigerante en sistemas que operan en vac\xEDo.","Un ventilador de emergencia.","Un sistema para vaciar el aceite."],respuesta_correcta:1,explicacion:"Vital en Chillers de baja presi\xF3n (R-123) para mantener los no condensables fuera del sistema.",question:"In a centrifugal system, what is the 'Purge Unit'?",options:["A drain valve.","A small auxiliary system that removes air and water from the refrigerant in systems operating under vacuum.","An emergency fan.","A system for draining oil."],explanation:"It is vital in low-pressure chillers (R-123) to keep non-condensables out of the system."},{id:"refri_507",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFc\xF3mo se controla la capacidad si no se tiene un variador de frecuencia?",opciones:["Apagando el motor.","Mediante el uso de una 'V\xE1lvula Corredera' (Slide Valve) que var\xEDa el punto de inicio de la compresi\xF3n.","Cerrando la v\xE1lvula de succi\xF3n.","Inyectando m\xE1s aceite."],respuesta_correcta:1,explicacion:"Permite una regulaci\xF3n suave del 10% al 100% de la carga mec\xE1nica.",question:"In a screw compressor, how is capacity controlled if there is no variable frequency drive?",options:["By turning the motor off.","By using a 'Slide Valve' that varies the point at which compression begins.","By closing the suction valve.","By injecting more oil."],explanation:"It allows smooth capacity regulation from 10% to 100% of the mechanical load."},{id:"refri_508",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Recuperador de Alta Presi\xF3n' (High Pressure Float)?",opciones:["Un tipo de compresor.","Un dispositivo de expansi\xF3n que drena todo el l\xEDquido del condensador hacia el lado de baja, manteniendo el lado de alta libre de l\xEDquido.","Un filtro de part\xEDculas.","Un sensor de nivel de aceite."],respuesta_correcta:1,explicacion:"Es com\xFAn en sistemas inundados industriales; permite que el condensador trabaje siempre al 100% de su superficie de intercambio.",question:"In an Ammonia system, what is a 'High Pressure Float'?",options:["A type of compressor.","An expansion device that drains all liquid from the condenser to the low side, keeping the high side free of liquid.","A particle filter.","An oil level sensor."],explanation:"It is common in industrial flooded systems; it allows the condenser to always operate at 100% of its heat exchange surface."},{id:"refri_509",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de CO2 transcr\xEDtico, \xBFcu\xE1l es la funci\xF3n de la 'Flash Gas Bypass Valve'?",opciones:["Enfriar el aceite.","Mantener una presi\xF3n estable en el receptor de l\xEDquido desviando el exceso de vapor hacia la succi\xF3n de los compresores.","Aumentar la presi\xF3n del Gas Cooler.","Limpiar el sistema."],respuesta_correcta:1,explicacion:"Es vital para el control de presi\xF3n del tanque receptor, asegurando que solo llegue l\xEDquido puro a los servicios de baja temperatura.",question:"In a transcritical CO2 system, what is the function of the 'Flash Gas Bypass Valve'?",options:["To cool the oil.","To maintain stable pressure in the liquid receiver by diverting excess vapor to the compressor suction.","To increase the Gas Cooler pressure.","To clean the system."],explanation:"It is vital for receiver tank pressure control, ensuring only pure liquid reaches the low-temperature services."},{id:"refri_510",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Corrosi\xF3n Galv\xE1nica' en un sistema de refrigeraci\xF3n industrial?",opciones:["Oxidaci\xF3n por aire.","Deterioro del metal causado por el contacto de dos metales diferentes en presencia de un electrolito (como agua de torre).","Corrosi\xF3n por \xE1cido del aceite.","Fuga de amon\xEDaco."],respuesta_correcta:1,explicacion:"Es com\xFAn en intercambiadores donde se unen acero y cobre; requiere \xE1nodos de sacrificio para proteger los componentes costosos.",question:"What is 'Galvanic Corrosion' in an industrial refrigeration system?",options:["Oxidation by air.","Metal deterioration caused by contact between two different metals in the presence of an electrolyte (such as cooling tower water).","Corrosion from oil acid.","An ammonia leak."],explanation:"It is common in heat exchangers where steel and copper meet; sacrificial anodes are required to protect the expensive components."},{id:"refri_511",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFcu\xE1l es el prop\xF3sito de un 'Acumulador de Succi\xF3n' con serpent\xEDn de recalentamiento?",opciones:["Calentar el cuarto de m\xE1quinas.","Hervir el amon\xEDaco l\xEDquido atrapado usando el calor del refrigerante l\xEDquido que viene del condensador.","Aumentar la presi\xF3n de descarga.","Filtrar el aceite."],respuesta_correcta:1,explicacion:"Es una forma eficiente de hacer dos cosas: asegurar que solo gas llegue al compresor y subenfriar el l\xEDquido para el evaporador.",question:"In an Ammonia system, what is the purpose of a 'Suction Accumulator' with a reheat coil?",options:["To heat the machine room.","To boil off trapped liquid ammonia using the heat from the liquid refrigerant coming from the condenser.","To increase discharge pressure.","To filter the oil."],explanation:"It is an efficient way to accomplish two things: ensuring only gas reaches the compressor and subcooling the liquid for the evaporator."},{id:"refri_512",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 significa el t\xE9rmino 'NPSH Disponible' en una bomba de recirculaci\xF3n de refrigerante?",opciones:["La potencia del motor.","La presi\xF3n absoluta en la succi\xF3n de la bomba por encima de la presi\xF3n de saturaci\xF3n del l\xEDquido.","La velocidad del refrigerante.","La cantidad de aceite en el l\xEDquido."],respuesta_correcta:1,explicacion:"Debe ser siempre mayor al NPSH requerido por la bomba para evitar la cavitaci\xF3n destructiva.",question:"What does the term 'Available NPSH' mean for a refrigerant recirculation pump?",options:["The motor horsepower.","The absolute pressure at the pump suction above the saturation pressure of the liquid.","The refrigerant velocity.","The amount of oil in the liquid."],explanation:"It must always be greater than the NPSH required by the pump to avoid destructive cavitation."},{id:"refri_513",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFpor qu\xE9 se utiliza una 'V\xE1lvula de Expansi\xF3n de Mano' (Manual Expansion Valve) en paralelo con la autom\xE1tica?",opciones:["Para que el t\xE9cnico tenga algo que hacer.","Como bypass de emergencia para mantener el sistema operando si la v\xE1lvula autom\xE1tica o solenoide falla.","Para ahorrar energ\xEDa.","Para drenar el aceite."],respuesta_correcta:1,explicacion:"En la industria, el fr\xEDo no puede detenerse. La v\xE1lvula manual permite el control humano mientras se repara la principal.",question:"In an Ammonia system, why is a 'Manual Expansion Valve' installed in parallel with the automatic one?",options:["To give the technician something to do.","As an emergency bypass to keep the system running if the automatic valve or solenoid fails.","To save energy.","To drain the oil."],explanation:"In industry, cooling cannot stop. The manual valve allows human control while the main valve is being repaired."},{id:"refri_514",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema transcr\xEDtico de CO2, \xBFqu\xE9 es el 'Punto Triple'?",opciones:["Cuando fallan tres compresores.","La condici\xF3n de presi\xF3n y temperatura donde el CO2 puede existir como s\xF3lido, l\xEDquido y gas al mismo tiempo.","Un tipo de v\xE1lvula.","La presi\xF3n m\xE1xima de seguridad."],respuesta_correcta:1,explicacion:"Es una curiosidad f\xEDsica importante para evitar la formaci\xF3n de 'hielo seco' dentro de las tuber\xEDas durante una carga mal realizada.",question:"In a transcritical CO2 system, what is the 'Triple Point'?",options:["When three compressors fail.","The condition of pressure and temperature where CO2 can exist as solid, liquid, and gas simultaneously.","A type of valve.","The maximum safety pressure."],explanation:"It is an important physical property to be aware of, to avoid the formation of dry ice inside the piping during an improper charging procedure."},{id:"refri_515",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 es el 'Separador de Aceite Primario'?",opciones:["Un filtro de cartucho.","Un tanque centr\xEDfugo donde el aceite se separa del gas de descarga por velocidad y cambio de direcci\xF3n.","Una bomba el\xE9ctrica.","El propio c\xE1rter del compresor."],respuesta_correcta:1,explicacion:"Es la primera etapa de separaci\xF3n; retiene el 99% del aceite antes de que el gas pase a los filtros coalescentes.",question:"In a screw compressor, what is the 'Primary Oil Separator'?",options:["A cartridge filter.","A centrifugal tank where oil is separated from the discharge gas by velocity and directional changes.","An electric pump.","The compressor crankcase itself."],explanation:"It is the first stage of separation; it retains 99% of the oil before the gas passes through the coalescing filters."},{id:"refri_516",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 sucede en un condensador de Amon\xEDaco si hay una acumulaci\xF3n de aceite?",opciones:["El aceite ayuda a la condensaci\xF3n.","Se reduce la transferencia de calor y la presi\xF3n de descarga sube, ya que el aceite act\xFAa como un aislante.","El amon\xEDaco se vuelve m\xE1s puro.","El aceite se evapora r\xE1pidamente."],respuesta_correcta:1,explicacion:"El aceite debe ser purgado regularmente del lado de alta para mantener la eficiencia t\xE9rmica.",question:"What happens in an Ammonia condenser if oil accumulates?",options:["The oil aids condensation.","Heat transfer is reduced and the discharge pressure rises, as the oil acts as an insulator.","The ammonia becomes purer.","The oil evaporates quickly."],explanation:"Oil must be purged regularly from the high side to maintain thermal efficiency."},{id:"refri_517",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de refrigeraci\xF3n por absorci\xF3n, \xBFqu\xE9 refrigerante se usa com\xFAnmente con el Bromuro de Litio?",opciones:["Amon\xEDaco.","Agua (H2O).","R-22.","Helio."],respuesta_correcta:1,explicacion:"En estos sistemas el agua act\xFAa como refrigerante, evapor\xE1ndose en alto vac\xEDo para generar fr\xEDo.",question:"In an absorption refrigeration system, what refrigerant is commonly used with Lithium Bromide?",options:["Ammonia.","Water (H2O).","R-22.","Helium."],explanation:"In these systems, water acts as the refrigerant, evaporating under high vacuum to produce cooling."},{id:"refri_518",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 material est\xE1 prohibido para las tuber\xEDas?",opciones:["Acero inoxidable.","Cobre y sus aleaciones (lat\xF3n, bronce), ya que el amon\xEDaco los corroe r\xE1pidamente en presencia de humedad.","Acero al carbono.","Hierro fundido."],respuesta_correcta:1,explicacion:"El amon\xEDaco reacciona agresivamente con el cobre; solo se permiten sistemas ferrosos o de aluminio.",question:"In an Ammonia system, what material is prohibited for piping?",options:["Stainless steel.","Copper and its alloys (brass, bronze), as ammonia corrodes them rapidly in the presence of moisture.","Carbon steel.","Cast iron."],explanation:"Ammonia reacts aggressively with copper; only ferrous or aluminum systems are permitted."},{id:"refri_519",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR) en sistemas industriales?",opciones:["Mantener la presi\xF3n de aceite alta.","Evitar que el compresor se sobrecargue durante el arranque limitando la presi\xF3n m\xE1xima de succi\xF3n.","Controlar el subenfriamiento.","No se usa en la industria."],respuesta_correcta:1,explicacion:"Es crucial en sistemas con grandes cargas iniciales o tras un deshielo por gas caliente.",question:"What is the function of a Crankcase Pressure Regulating valve (CPR) in industrial systems?",options:["To keep oil pressure high.","To prevent the compressor from overloading during startup by limiting the maximum suction pressure.","To control subcooling.","It is not used in industrial applications."],explanation:"It is crucial in systems with large initial loads or after a hot gas defrost cycle."},{id:"refri_520",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 componente de seguridad se usa en sistemas de Amon\xEDaco para detectar fugas microsc\xF3picas en el agua?",opciones:["Un detector de llama.","Un sensor de pH o conductividad en el circuito de agua.","Un term\xF3metro de precisi\xF3n.","No se pueden detectar."],respuesta_correcta:1,explicacion:"El amon\xEDaco cambia el pH del agua; monitorear esto permite detectar fugas internas antes de que el da\xF1o sea mayor.",question:"What safety component is used in Ammonia systems to detect microscopic leaks in the water?",options:["A flame detector.","A pH or conductivity sensor in the water circuit.","A precision thermometer.","They cannot be detected."],explanation:"Ammonia changes the pH of water; monitoring this allows internal leaks to be detected before major damage occurs."},{id:"refri_521",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFpara qu\xE9 sirve la inyecci\xF3n de l\xEDquido opcional?",opciones:["Para lavar los rotores.","Para enfriar el gas de descarga en aplicaciones de alta relaci\xF3n de compresi\xF3n.","Para aumentar la presi\xF3n de succi\xF3n.","Para calentar el aceite."],respuesta_correcta:1,explicacion:"Es una alternativa o complemento al enfriamiento de aceite para proteger los sellos del compresor.",question:"In a screw compressor, what is the purpose of optional liquid injection?",options:["To wash the rotors.","To cool the discharge gas in high compression ratio applications.","To increase the suction pressure.","To heat the oil."],explanation:"It is an alternative or complement to oil cooling to protect the compressor seals."},{id:"refri_522",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un 'Intercambiador de placas' y por qu\xE9 se usa en refrigeraci\xF3n industrial?",opciones:["Un tipo de filtro.","Un intercambiador muy compacto que usa placas met\xE1licas para transferir calor entre dos fluidos de manera eficiente.","Una placa de hielo.","Un control de presi\xF3n."],respuesta_correcta:1,explicacion:"Es ideal para enfriar glicol o salmuera con amon\xEDaco debido a su alta eficiencia y bajo volumen de carga.",question:"What is a 'Plate Heat Exchanger' and why is it used in industrial refrigeration?",options:["A type of filter.","A very compact heat exchanger that uses metal plates to efficiently transfer heat between two fluids.","An ice plate.","A pressure control."],explanation:"It is ideal for cooling glycol or brine with ammonia due to its high efficiency and low refrigerant charge volume."},{id:"refri_523",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito de la 'V\xE1lvula de Retenci\xF3n de Aceite' (Oil Check Valve) en la l\xEDnea de inyecci\xF3n de un compresor de tornillo?",opciones:["Filtrar el aceite.","Evitar que el refrigerante migre hacia el sistema de aceite cuando el compresor est\xE1 apagado.","Aumentar la presi\xF3n de inyecci\xF3n.","Enfriar los rotores."],respuesta_correcta:1,explicacion:"Mantiene los sistemas de lubricaci\xF3n y refrigeraci\xF3n separados mec\xE1nicamente durante los periodos de inactividad para evitar contaminaciones.",question:"What is the purpose of the 'Oil Check Valve' in the injection line of a screw compressor?",options:["To filter the oil.","To prevent refrigerant from migrating into the oil system when the compressor is off.","To increase injection pressure.","To cool the rotors."],explanation:"It keeps the lubrication and refrigeration systems mechanically separated during idle periods to prevent contamination."},{id:"refri_524",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFpor qu\xE9 los man\xF3metros suelen tener una escala de temperatura adem\xE1s de la de presi\xF3n?",opciones:["Para que se vean m\xE1s complejos.","Para permitir la lectura directa de la temperatura de saturaci\xF3n y facilitar el c\xE1lculo de sobrecalentamiento y subenfriamiento.","Porque el amon\xEDaco cambia de color con la temperatura.","Es una norma est\xE9tica."],respuesta_correcta:1,explicacion:"Es la herramienta b\xE1sica de diagn\xF3stico r\xE1pido (Tabla P-T integrada) para cualquier t\xE9cnico de refrigeraci\xF3n.",question:"In an Ammonia system, why do gauges usually have a temperature scale in addition to the pressure scale?",options:["To make them look more complex.","To allow direct reading of the saturation temperature and facilitate the calculation of superheat and subcooling.","Because ammonia changes color with temperature.","It is an aesthetic standard."],explanation:"It is the basic quick-diagnosis tool (integrated P-T chart) for any refrigeration technician."},{id:"refri_525",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de un 'Desgasificador' (Deaerator) en un sistema de agua de enfriamiento?",opciones:["A\xF1adir burbujas al agua.","Eliminar el ox\xEDgeno y otros gases disueltos para prevenir la corrosi\xF3n interna de las tuber\xEDas de acero.","Enfriar el agua.","Filtrar la arena."],respuesta_correcta:1,explicacion:"El ox\xEDgeno es altamente corrosivo a altas temperaturas; eliminarlo alarga la vida de los intercambiadores.",question:"What is the function of a 'Deaerator' in a cooling water system?",options:["To add bubbles to the water.","To remove oxygen and other dissolved gases to prevent internal corrosion of steel piping.","To cool the water.","To filter sand."],explanation:"Oxygen is highly corrosive at high temperatures; removing it extends the life of the heat exchangers."},{id:"refri_526",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor centr\xEDfugo, \xBFqu\xE9 sucede si la carga cae por debajo del 10-20%?",opciones:["El compresor es m\xE1s eficiente.","Riesgo de 'Surge' (bombeo), donde la presi\xF3n del condensador vence al compresor y el gas fluye en reversa.","El aceite se evapora.","El motor se acelera solo."],respuesta_correcta:1,explicacion:"Los centr\xEDfugos tienen un l\xEDmite de estabilidad operativa; por debajo de este, vibran violentamente y pueden destruirse.",question:"In a centrifugal compressor, what happens if the load drops below 10-20%?",options:["The compressor becomes more efficient.","Risk of 'Surge' (pumping), where the condenser pressure overcomes the compressor and gas flows in reverse.","The oil evaporates.","The motor speeds up on its own."],explanation:"Centrifugal compressors have an operational stability limit; below it, they vibrate violently and can self-destruct."},{id:"refri_527",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de Amon\xEDaco, \xBFqu\xE9 significa que una v\xE1lvula sea de 'Asiento Suave' (Soft Seat)?",opciones:["Que es de pl\xE1stico.","Que usa materiales como PTFE (Tefl\xF3n) para asegurar un cierre herm\xE9tico sin fugas microsc\xF3picas.","Que no requiere herramientas para abrirla.","Que se rompe f\xE1cil."],respuesta_correcta:1,explicacion:"El amon\xEDaco es dif\xEDcil de contener; los sellos de tefl\xF3n son el est\xE1ndar para evitar fugas constantes en v\xE1lvulas de paso.",question:"In Ammonia systems, what does it mean for a valve to have a 'Soft Seat'?",options:["That it is made of plastic.","That it uses materials such as PTFE (Teflon) to ensure a leak-tight seal without microscopic leaks.","That it can be opened without tools.","That it breaks easily."],explanation:"Ammonia is difficult to contain; Teflon seals are the standard for preventing constant leaks in shut-off valves."},{id:"refri_528",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de un 'Purger' autom\xE1tico en un sistema de Amon\xEDaco?",opciones:["A\xF1adir amon\xEDaco nuevo.","Eliminar aire y otros gases no condensables sin perder refrigerante, mejorando la presi\xF3n de descarga.","Limpiar el aceite.","Drenar el agua."],respuesta_correcta:1,explicacion:"El aire en el condensador reduce el \xE1rea de intercambio y dispara la presi\xF3n de alta; el purger lo saca de forma inteligente.",question:"What is the function of an automatic 'Purger' in an Ammonia system?",options:["To add fresh ammonia.","To remove air and other non-condensable gases without losing refrigerant, thereby improving the discharge pressure.","To clean the oil.","To drain the water."],explanation:"Air in the condenser reduces the heat exchange area and spikes the high-side pressure; the purger removes it intelligently."},{id:"refri_529",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Economizador' en un compresor de tornillo?",opciones:["Reduce el consumo de aceite.","Inyecta vapor de refrigerante a presi\xF3n intermedia para subenfriar el l\xEDquido principal, aumentando la capacidad y eficiencia del ciclo.","Detiene el compresor en emergencias.","Enfr\xEDa el motor el\xE9ctrico."],respuesta_correcta:1,explicacion:"Permite obtener un efecto refrigerante mayor con el mismo tama\xF1o de compresor.",question:"What is the function of the 'Economizer' in a screw compressor?",options:["It reduces oil consumption.","It injects refrigerant vapor at intermediate pressure to subcool the main liquid, increasing the cycle's capacity and efficiency.","It stops the compressor in emergencies.","It cools the electric motor."],explanation:"It allows a greater refrigerating effect from the same compressor size."},{id:"refri_530",categoria:"REFRI_INDUSTRIAL",pregunta:"En un Chiller de gran escala, \xBFqu\xE9 es la 'Carga T\xE9rmica de Inercia'?",opciones:["El peso del agua.","La capacidad del sistema para mantener la temperatura del agua debido al gran volumen almacenado en las tuber\xEDas y tanques.","El calor generado por la fricci\xF3n de las bombas.","La temperatura del cuarto de m\xE1quinas."],respuesta_correcta:1,explicacion:"Sistemas con gran inercia ciclan menos el compresor, lo que ahorra energ\xEDa y alarga la vida mec\xE1nica.",question:"In a large-scale Chiller, what is 'Thermal Inertia Load'?",options:["The weight of the water.","The system's ability to maintain water temperature due to the large volume stored in piping and tanks.","The heat generated by pump friction.","The machine room temperature."],explanation:"Systems with high thermal inertia cycle the compressor less frequently, saving energy and extending mechanical life."},{id:"refri_531",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 significa un 'Sistema Overfeed' (Sobrealimentado) de l\xEDquido?",opciones:["Que tiene exceso de gas.","Que se bombea m\xE1s refrigerante l\xEDquido al evaporador del que se puede evaporar en una pasada, para mojar todas las paredes del tubo.","Que el compresor es muy grande.","Que el aceite se desborda."],respuesta_correcta:1,explicacion:"Es el m\xE9todo m\xE1s eficiente de transferencia de calor en evaporadores industriales de gran tama\xF1o.",question:"What does a 'Liquid Overfeed System' mean?",options:["That there is excess gas.","That more liquid refrigerant is pumped to the evaporator than can evaporate in a single pass, in order to wet all tube walls.","That the compressor is oversized.","That the oil overflows."],explanation:"It is the most efficient method of heat transfer in large-scale industrial evaporators."},{id:"refri_532",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Recipiente de Termosif\xF3n'?",opciones:["Un filtro de gas.","Un tanque elevado que suministra refrigerante l\xEDquido para enfriar el aceite de los compresores de tornillo por gravedad.","Un calentador de agua.","Un separador de purga."],respuesta_correcta:1,explicacion:"Es una forma pasiva y muy segura de manejar el calor generado por el aceite del compresor.",question:"In an Ammonia system, what is a 'Thermosiphon Vessel'?",options:["A gas filter.","An elevated tank that supplies liquid refrigerant to cool screw compressor oil by gravity.","A water heater.","A purge separator."],explanation:"It is a passive and very safe way to manage the heat generated by compressor oil."},{id:"refri_533",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 significa 'Relaci\xF3n de Compresi\xF3n' y c\xF3mo afecta la vida del compresor?",opciones:["Es el peso del compresor.","Es la presi\xF3n de descarga absoluta entre la de succi\xF3n absoluta; a mayor relaci\xF3n, m\xE1s calor se genera y m\xE1s sufre el compresor.","Es la cantidad de aceite por gas.","Es la velocidad del motor."],respuesta_correcta:1,explicacion:"Mantener relaciones de compresi\xF3n bajas es la clave para que un compresor dure 20 a\xF1os.",question:"What does 'Compression Ratio' mean and how does it affect compressor life?",options:["It is the weight of the compressor.","It is the absolute discharge pressure divided by the absolute suction pressure; the higher the ratio, the more heat is generated and the more the compressor suffers.","It is the ratio of oil to gas.","It is the motor speed."],explanation:"Keeping compression ratios low is the key to making a compressor last 20 years."},{id:"refri_534",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Vaso Intermedio' (Intercooler)?",opciones:["Un tanque de agua.","Un recipiente que enfr\xEDa el gas de descarga de la etapa de baja antes de que entre a la etapa de alta en compresi\xF3n de dos etapas.","Un filtro de aceite.","Un sensor de presi\xF3n."],respuesta_correcta:1,explicacion:"Reduce el trabajo de compresi\xF3n y evita temperaturas de descarga que degradar\xEDan el aceite.",question:"In an Ammonia system, what is an 'Intercooler' (Intermediate Vessel)?",options:["A water tank.","A vessel that cools the discharge gas from the low stage before it enters the high stage in a two-stage compression system.","An oil filter.","A pressure sensor."],explanation:"It reduces the work of compression and prevents discharge temperatures that would degrade the oil."},{id:"refri_535",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de NH3, \xBFqu\xE9 sucede si se mezcla aire con el amon\xEDaco?",opciones:["Enfr\xEDa mejor.","Aumenta la presi\xF3n de descarga y existe riesgo de explosi\xF3n si las concentraciones y presiones son extremas.","El aceite se vuelve verde.","Nada, son gases compatibles."],respuesta_correcta:1,explicacion:"El aire es un contaminante peligroso que reduce la eficiencia y pone en riesgo la integridad f\xEDsica de la planta.",question:"In an NH3 system, what happens if air mixes with the ammonia?",options:["It cools better.","The discharge pressure increases and there is a risk of explosion if concentrations and pressures reach extreme levels.","The oil turns green.","Nothing; they are compatible gases."],explanation:"Air is a dangerous contaminant that reduces efficiency and puts the physical integrity of the plant at risk."},{id:"refri_536",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Aceite Mineral' en un sistema de Amon\xEDaco?",opciones:["Lubricar y sellar las partes m\xF3viles.","No se usa, se usa POE.","Limpiar las tuber\xEDas.","Subenfriar el gas."],respuesta_correcta:0,explicacion:"El amon\xEDaco no es miscible con aceite mineral, lo que facilita su separaci\xF3n en el lado de alta.",question:"What is the function of 'Mineral Oil' in an Ammonia system?",options:["To lubricate and seal the moving parts.","It is not used; POE oil is used instead.","To clean the piping.","To subcool the gas."],explanation:"Ammonia is not miscible with mineral oil, which makes it easy to separate the oil on the high side."},{id:"refri_537",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es el 'Efecto de Glaceado' en un evaporador industrial?",opciones:["Cuando se ve bonito.","Formaci\xF3n de una capa de hielo transparente y densa que reduce dr\xE1sticamente el flujo de aire y el intercambio t\xE9rmico.","Limpieza con agua.","Inyecci\xF3n de aceite."],respuesta_correcta:1,explicacion:"Suele ocurrir por desescarches incompletos o humedad excesiva en el ambiente.",question:"What is the 'Glazing Effect' on an industrial evaporator?",options:["When it looks nice.","The formation of a clear, dense ice layer that drastically reduces airflow and heat exchange.","Cleaning with water.","Oil injection."],explanation:"It usually occurs due to incomplete defrosts or excessive ambient humidity."},{id:"refri_538",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Termosif\xF3n' en el enfriamiento de aceite de un compresor de tornillo?",opciones:["Usar una bomba el\xE9ctrica para mover el aceite.","Aprovechar la diferencia de densidad del refrigerante l\xEDquido para circularlo por el enfriador de aceite sin partes m\xF3viles.","Calentar el aceite en invierno.","Separar el amon\xEDaco del agua."],respuesta_correcta:1,explicacion:"Es un sistema pasivo altamente confiable que utiliza la gravedad y el cambio de fase del refrigerante para mantener el aceite a la temperatura \xF3ptima.",question:"What is the function of the 'Thermosiphon' in the oil cooling system of a screw compressor?",options:["To use an electric pump to move the oil.","To take advantage of the density difference of liquid refrigerant to circulate it through the oil cooler without any moving parts.","To heat the oil in winter.","To separate ammonia from water."],explanation:"It is a highly reliable passive system that uses gravity and refrigerant phase change to keep the oil at its optimal temperature."},{id:"refri_539",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de NH3, \xBFqu\xE9 indica una mancha blanca alrededor de una v\xE1lvula?",opciones:["Hielo normal.","Una fuga de amon\xEDaco que ha reaccionado con la humedad formando dep\xF3sitos (sales).","Pintura vieja.","Polvo del ambiente."],respuesta_correcta:1,explicacion:"El amon\xEDaco es muy reactivo; los dep\xF3sitos blanquecinos o azulados en el acero son se\xF1ales claras de micro-fugas.",question:"In an NH3 system, what does a white stain around a valve indicate?",options:["Normal ice formation.","An ammonia leak that has reacted with moisture, forming salt-like deposits.","Old paint.","Ambient dust."],explanation:"Ammonia is highly reactive; whitish or bluish deposits on steel are clear signs of micro-leaks."},{id:"refri_540",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de bombeo de refrigerante, \xBFqu\xE9 es el 'Gas de Purga' (Air Purger)?",opciones:["Un dispositivo para sacar el aceite.","Un equipo autom\xE1tico que detecta y elimina gases no condensables del sistema para bajar la presi\xF3n de descarga.","Una v\xE1lvula manual de escape.","Un ventilador especial."],respuesta_correcta:1,explicacion:"Fundamental en sistemas industriales para mantener la eficiencia y evitar que la presi\xF3n de alta se dispare por presencia de aire.",question:"In a refrigerant pumping system, what is the 'Air Purger'?",options:["A device for removing oil.","An automatic unit that detects and removes non-condensable gases from the system to lower the discharge pressure.","A manual vent valve.","A special fan."],explanation:"It is essential in industrial systems to maintain efficiency and prevent the high-side pressure from spiking due to the presence of air."},{id:"refri_541",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema transcr\xEDtico de CO2, \xBFqu\xE9 componente reemplaza a la TXV tradicional para controlar la expansi\xF3n?",opciones:["Un capilar largo.","Una v\xE1lvula de expansi\xF3n electr\xF3nica (EEV) de alta presi\xF3n controlada por un microprocesador.","Una v\xE1lvula de bola.","No usa v\xE1lvula."],respuesta_correcta:1,explicacion:"Debido a las presiones extremas y la necesidad de optimizar el punto de enfriamiento de gas, se requiere un control digital muy preciso.",question:"In a transcritical CO2 system, what component replaces the traditional TXV to control expansion?",options:["A long capillary tube.","A high-pressure electronic expansion valve (EEV) controlled by a microprocessor.","A ball valve.","It does not use a valve."],explanation:"Due to extreme pressures and the need to optimize the gas cooling point, very precise digital control is required."},{id:"refri_542",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite' en la descarga de un compresor industrial?",opciones:["Enfriar el refrigerante.","Recuperar el aceite arrastrado por el gas de descarga y devolverlo al c\xE1rter para asegurar la lubricaci\xF3n y evitar que llegue al evaporador.","Filtrar el aire.","Aumentar la presi\xF3n de aceite."],respuesta_correcta:1,explicacion:"En sistemas industriales con grandes recorridos de tuber\xEDa, el aceite atrapado en el evaporador reducir\xEDa dr\xE1sticamente la eficiencia.",question:"What is the function of the 'Oil Separator' on the discharge of an industrial compressor?",options:["To cool the refrigerant.","To recover the oil carried by the discharge gas and return it to the crankcase to ensure lubrication and prevent it from reaching the evaporator.","To filter the air.","To increase oil pressure."],explanation:"In industrial systems with long piping runs, oil trapped in the evaporator would drastically reduce efficiency."},{id:"refri_543",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 se usa para detectar fugas de manera tradicional y segura?",opciones:["Encendedor de gas.","Azufre en barra (Sulphur sticks) que genera un humo blanco denso en contacto con el amon\xEDaco.","Jab\xF3n de manos.","Olfato solamente."],respuesta_correcta:1,explicacion:"La reacci\xF3n qu\xEDmica del humo blanco es infalible para localizar el punto exacto de la fuga sin riesgos el\xE9ctricos.",question:"In an Ammonia system, what is traditionally used to safely detect leaks?",options:["A gas lighter.","Sulfur sticks that produce dense white smoke upon contact with ammonia.","Hand soap.","Sense of smell only."],explanation:"The chemical reaction producing white smoke is a reliable method to locate the exact point of a leak without electrical hazards."},{id:"refri_544",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es el 'Efecto Leidenfrost' y c\xF3mo afecta a los evaporadores inundados?",opciones:["Una falla del aceite.","La formaci\xF3n de una capa de vapor aislante entre el l\xEDquido y la superficie caliente, reduciendo la transferencia de calor.","Un m\xE9todo de limpieza por vac\xEDo.","La congelaci\xF3n del agua en los tubos."],respuesta_correcta:1,explicacion:"Es una condici\xF3n cr\xEDtica donde la ebullici\xF3n se vuelve ineficiente debido al exceso de flujo t\xE9rmico local.",question:"What is the 'Leidenfrost Effect' and how does it affect flooded evaporators?",options:["An oil failure.","The formation of an insulating vapor layer between the liquid and the hot surface, reducing heat transfer.","A vacuum cleaning method.","The freezing of water in the tubes."],explanation:"It is a critical condition where boiling becomes inefficient due to excessive local heat flux."},{id:"refri_545",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPor qu\xE9 se utiliza el 'Recubrimiento de Nitruro de Titanio' en ciertos rotores de tornillo?",opciones:["Por est\xE9tica.","Para aumentar la dureza superficial y reducir el desgaste por erosi\xF3n y part\xEDculas met\xE1licas en el aceite.","Para que el aceite no se pegue.","Para conducir mejor el calor."],respuesta_correcta:1,explicacion:"En aplicaciones industriales pesadas, la durabilidad de los perfiles del rotor es clave para mantener la eficiencia.",question:"Why is 'Titanium Nitride Coating' used on certain screw compressor rotors?",options:["For aesthetics.","To increase surface hardness and reduce wear from erosion and metallic particles in the oil.","To prevent oil from sticking.","To conduct heat better."],explanation:"In heavy industrial applications, the durability of the rotor profiles is key to maintaining efficiency."},{id:"refri_546",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Vaso Intermedio' (Intercooler)?",opciones:["Un tanque de agua.","Un recipiente que enfr\xEDa el gas de descarga de la etapa de baja antes de que entre a la etapa de alta en compresi\xF3n de dos etapas.","Un filtro de aceite.","Un sensor de presi\xF3n."],respuesta_correcta:1,explicacion:"Reduce el trabajo de compresi\xF3n y evita temperaturas de descarga que degradar\xEDan el aceite.",question:"In an Ammonia system, what is an 'Intercooler' (Intermediate Vessel)?",options:["A water tank.","A vessel that cools the discharge gas from the low stage before it enters the high stage in a two-stage compression system.","An oil filter.","A pressure sensor."],explanation:"It reduces the work of compression and prevents discharge temperatures that would degrade the oil."},{id:"refri_547",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de NH3, \xBFqu\xE9 sucede si se mezcla aire con el amon\xEDaco?",opciones:["Enfr\xEDa mejor.","Aumenta la presi\xF3n de descarga y existe riesgo de explosi\xF3n si las concentraciones y presiones son extremas.","El aceite se vuelve verde.","Nada, son gases compatibles."],respuesta_correcta:1,explicacion:"El aire es un contaminante peligroso que reduce la eficiencia y pone en riesgo la integridad f\xEDsica de la planta.",question:"In an NH3 system, what happens if air mixes with the ammonia?",options:["It cools better.","The discharge pressure increases and there is a risk of explosion if concentrations and pressures reach extreme levels.","The oil turns green.","Nothing; they are compatible gases."],explanation:"Air is a dangerous contaminant that reduces efficiency and puts the physical integrity of the plant at risk."},{id:"refri_548",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Aceite Mineral' en un sistema de Amon\xEDaco?",opciones:["Lubricar y sellar las partes m\xF3viles.","No se usa, se usa POE.","Limpiar las tuber\xEDas.","Subenfriar el gas."],respuesta_correcta:0,explicacion:"El amon\xEDaco no es miscible con aceite mineral, lo que facilita su separaci\xF3n en el lado de alta.",question:"What is the function of 'Mineral Oil' in an Ammonia system?",options:["To lubricate and seal the moving parts.","It is not used; POE oil is used instead.","To clean the piping.","To subcool the gas."],explanation:"Ammonia is not miscible with mineral oil, which makes it easy to separate the oil on the high side."},{id:"refri_549",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es el 'Efecto de Glaceado' en un evaporador industrial?",opciones:["Cuando se ve bonito.","Formaci\xF3n de una capa de hielo transparente y densa que reduce dr\xE1sticamente el flujo de aire y el intercambio t\xE9rmico.","Limpieza con agua.","Inyecci\xF3n de aceite."],respuesta_correcta:1,explicacion:"Suele ocurrir por desescarches incompletos o humedad excesiva en el ambiente.",question:"What is the 'Glazing Effect' on an industrial evaporator?",options:["When it looks nice.","The formation of a clear, dense ice layer that drastically reduces airflow and heat exchange.","Cleaning with water.","Oil injection."],explanation:"It usually occurs due to incomplete defrosts or excessive ambient humidity."},{id:"refri_550",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de un 'Purger' en un sistema de amon\xEDaco?",opciones:["Drenar el aceite.","Eliminar el aire y gases no condensables del condensador para bajar la presi\xF3n de descarga.","Filtrar impurezas s\xF3lidas.","Inyectar refrigerante nuevo."],respuesta_correcta:1,explicacion:"El aire acumulado ocupa espacio en el condensador, subiendo la presi\xF3n de alta y reduciendo la eficiencia.",question:"What is the function of a 'Purger' in an ammonia system?",options:["To drain the oil.","To remove air and non-condensable gases from the condenser to lower the discharge pressure.","To filter solid impurities.","To inject new refrigerant."],explanation:"Accumulated air takes up space in the condenser, raising the high-side pressure and reducing efficiency."},{id:"refri_551",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de recirculaci\xF3n por bomba, \xBFqu\xE9 significa una 'Relaci\xF3n de Recirculaci\xF3n' de 4:1?",opciones:["Que hay 4 bombas por compresor.","Que se bombea 4 veces la cantidad de l\xEDquido que realmente se evapora en los serpentines.","Que la presi\xF3n de alta es 4 veces la de baja.","Que el aceite se filtra 4 veces por hora."],respuesta_correcta:1,explicacion:"Garantiza que el evaporador est\xE9 siempre mojado internamente para maximizar la transferencia t\xE9rmica.",question:"In a pump recirculation system, what does a 'Recirculation Ratio' of 4:1 mean?",options:["That there are 4 pumps per compressor.","That 4 times the amount of liquid that actually evaporates in the coils is pumped.","That the high-side pressure is 4 times the low-side pressure.","That the oil is filtered 4 times per hour."],explanation:"It ensures the evaporator is always internally wetted to maximize heat transfer."},{id:"refri_552",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de absorci\xF3n de Bromuro de Litio, \xBFqu\xE9 sustancia act\xFAa como refrigerante?",opciones:["El Bromuro de Litio.","El Agua (H2O).","El Amon\xEDaco.","El Glicol."],respuesta_correcta:1,explicacion:"En estos sistemas, el agua se evapora a muy baja presi\xF3n para enfriar, mientras el Bromuro de Litio es el absorbente.",question:"In a Lithium Bromide absorption system, which substance acts as the refrigerant?",options:["Lithium Bromide.","Water (H2O).","Ammonia.","Glycol."],explanation:"In these systems, water evaporates at very low pressure to provide cooling, while Lithium Bromide serves as the absorbent."},{id:"refri_553",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un 'Intercambiador de Calor de Placas Semi-Soldadas' y d\xF3nde se usa?",opciones:["Un filtro de aceite.","Un intercambiador donde el refrigerante fluye por canales soldados y el fluido secundario por canales con juntas, usado com\xFAnmente con NH3.","Una placa de hielo para enfriar bebidas.","Un sensor de flujo."],respuesta_correcta:1,explicacion:"Permite confinar el refrigerante peligroso en secciones selladas mientras permite la limpieza del lado del agua/glicol.",question:"What is a 'Semi-Welded Plate Heat Exchanger' and where is it used?",options:["An oil filter.","A heat exchanger where the refrigerant flows through welded channels and the secondary fluid flows through gasketed channels, commonly used with NH3.","An ice plate for cooling beverages.","A flow sensor."],explanation:"It allows confining the hazardous refrigerant in sealed sections while permitting cleaning on the water/glycol side."},{id:"refri_554",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es el 'Punto de Floculaci\xF3n' del aceite?",opciones:["La temperatura a la que el aceite se quema.","La temperatura a la que las parafinas del aceite se separan y forman dep\xF3sitos cerosos que pueden tapar v\xE1lvulas.","La presi\xF3n m\xE1xima de lubricaci\xF3n.","La mezcla de aceite con agua."],respuesta_correcta:1,explicacion:"Es un par\xE1metro cr\xEDtico al elegir aceites para sistemas de muy baja temperatura.",question:"In an Ammonia system, what is the oil's 'Floc Point'?",options:["The temperature at which the oil burns.","The temperature at which the paraffins in the oil separate and form waxy deposits that can clog valves.","The maximum lubrication pressure.","The mixture of oil and water."],explanation:"It is a critical parameter when selecting oils for very low temperature systems."},{id:"refri_555",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite Coalescente'?",opciones:["Calentar el aceite.","Utilizar filtros de malla fina para unir micro-gotas de aceite y separarlas del gas con una eficiencia superior al 99.9%.","Mezclar el aceite con el gas.","Aumentar la presi\xF3n de descarga."],respuesta_correcta:1,explicacion:"Es el est\xE1ndar en compresores de tornillo para evitar que el aceite inunde el lado de baja.",question:"What is the function of a 'Coalescing Oil Separator'?",options:["To heat the oil.","To use fine mesh filters to merge micro-droplets of oil and separate them from the gas with an efficiency exceeding 99.9%.","To mix the oil with the gas.","To increase the discharge pressure."],explanation:"It is the standard in screw compressors to prevent oil from flooding the low side."},{id:"refri_556",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de cascada NH3/CO2, \xBFqu\xE9 refrigerante circula por el lado de baja temperatura (evaporadores del congelador)?",opciones:["El Amon\xEDaco.","El CO2 (R-744).","El Glicol.","El R-404A."],respuesta_correcta:1,explicacion:"El CO2 es excelente para bajas temperaturas y seguro para \xE1reas de trabajo, mientras el NH3 se queda confinado en la sala de m\xE1quinas enfriando el condensador de CO2.",question:"In an NH3/CO2 cascade system, which refrigerant circulates on the low-temperature side (freezer evaporators)?",options:["Ammonia.","CO2 (R-744).","Glycol.","R-404A."],explanation:"CO2 is excellent for low temperatures and safe for work areas, while NH3 remains confined in the machine room cooling the CO2 condenser."},{id:"refri_557",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPor qu\xE9 se utiliza acero inoxidable en las tuber\xEDas de sistemas de Amon\xEDaco modernos?",opciones:["Porque es m\xE1s barato.","Por su alta resistencia a la corrosi\xF3n y mayor durabilidad mec\xE1nica comparado con el acero al carbono.","Porque es m\xE1s f\xE1cil de soldar con esta\xF1o.","Para que el sistema sea magn\xE9tico."],respuesta_correcta:1,explicacion:"Aunque es m\xE1s caro, reduce el mantenimiento y elimina el riesgo de picaduras por oxidaci\xF3n externa.",question:"Why is stainless steel used for piping in modern Ammonia systems?",options:["Because it is cheaper.","Because of its high corrosion resistance and greater mechanical durability compared to carbon steel.","Because it is easier to solder with tin.","To make the system magnetic."],explanation:"Although more expensive, it reduces maintenance and eliminates the risk of pitting from external oxidation."},{id:"refri_558",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 funci\xF3n tiene la 'Slide Valve' (V\xE1lvula de Corredera)?",opciones:["Regular la presi\xF3n de aceite.","Controlar la capacidad del compresor variando la longitud efectiva de los rotores.","Abrir el puerto de succi\xF3n.","Limpiar los l\xF3bulos."],respuesta_correcta:1,explicacion:"Permite que el compresor trabaje al 25%, 50% o 75% de su capacidad total seg\xFAn la demanda.",question:"In a screw compressor, what is the function of the 'Slide Valve'?",options:["To regulate oil pressure.","To control the compressor capacity by varying the effective length of the rotors.","To open the suction port.","To clean the lobes."],explanation:"It allows the compressor to operate at 25%, 50%, or 75% of its total capacity based on demand."},{id:"refri_559",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPara qu\xE9 se utiliza el 'Glicol' en sistemas de refrigeraci\xF3n industrial?",opciones:["Como refrigerante para el compresor.","Como fluido secundario anticongelante para transportar el fr\xEDo desde el intercambiador central a los servicios.","Para limpiar el aceite.","Como combustible para el generador."],respuesta_correcta:1,explicacion:"Permite mover fr\xEDo a temperaturas bajo cero sin que el agua del circuito se congele y rompa las tuber\xEDas.",question:"What is 'Glycol' used for in industrial refrigeration systems?",options:["As a refrigerant for the compressor.","As an antifreeze secondary fluid to transport cooling from the central heat exchanger to the services.","To clean the oil.","As fuel for the generator."],explanation:"It allows moving cooling capacity at sub-zero temperatures without the water in the circuit freezing and breaking the pipes."},{id:"refri_560",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es el 'Golpe de Ariete'?",opciones:["Un sonido normal de v\xE1lvulas.","Impacto violento de l\xEDquido impulsado por gas a alta velocidad, capaz de romper tuber\xEDas y v\xE1lvulas.","Falla el\xE9ctrica del motor.","Presi\xF3n de aceite muy alta."],respuesta_correcta:1,explicacion:"Es extremadamente peligroso en sistemas industriales; se previene con una operaci\xF3n lenta de v\xE1lvulas y buen dise\xF1o de tuber\xEDa.",question:"In an Ammonia system, what is 'Water Hammer'?",options:["A normal valve noise.","A violent impact of liquid propelled by high-velocity gas, capable of rupturing piping and valves.","An electrical motor failure.","Very high oil pressure."],explanation:"It is extremely dangerous in industrial systems; it is prevented through slow valve operation and proper piping design."},{id:"refri_561",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Aceite' en un compresor centr\xEDfugo?",opciones:["Sellar los rotores.","Lubricar los cojinetes y en algunos casos actuar como fluido de control para los \xE1labes (vanes).","Enfriar el refrigerante directamente.","No usa aceite."],respuesta_correcta:1,explicacion:"A diferencia de los de tornillo, los centr\xEDfugos no inyectan aceite en el flujo de gas refrigerante.",question:"What is the function of 'Oil' in a centrifugal compressor?",options:["To seal the rotors.","To lubricate the bearings and, in some cases, act as a control fluid for the inlet guide vanes.","To directly cool the refrigerant.","It does not use oil."],explanation:"Unlike screw compressors, centrifugal compressors do not inject oil into the refrigerant gas flow."},{id:"refri_562",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es la 'Prueba de Fenolftale\xEDna'?",opciones:["Para medir el aceite.","Una prueba qu\xEDmica para detectar fugas de amon\xEDaco en sistemas de agua o salmuera (el papel cambia a rosa/rojo).","Para ver si el compresor tiene fuerza.","Para limpiar tuber\xEDas."],respuesta_correcta:1,explicacion:"Es un m\xE9todo est\xE1ndar de seguridad para encontrar fugas en intercambiadores de placas o tubos.",question:"In an Ammonia system, what is the 'Phenolphthalein Test'?",options:["To measure the oil.","A chemical test to detect ammonia leaks in water or brine systems (the paper turns pink/red).","To check if the compressor has enough power.","To clean the piping."],explanation:"It is a standard safety method for finding leaks in plate or tube heat exchangers."},{id:"refri_563",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Cavitaci\xF3n' en una bomba de refrigerante l\xEDquido?",opciones:["Cuando la bomba se oxida.","Formaci\xF3n de burbujas de vapor en la succi\xF3n de la bomba que implosionan y destruyen el impulsor.","Cuando el aceite se congela.","Cuando entra aire al sistema."],respuesta_correcta:1,explicacion:"Ocurre cuando la presi\xF3n en la succi\xF3n cae por debajo de la presi\xF3n de saturaci\xF3n del l\xEDquido.",question:"What is 'Cavitation' in a liquid refrigerant pump?",options:["When the pump rusts.","The formation of vapor bubbles at the pump suction that implode and destroy the impeller.","When the oil freezes.","When air enters the system."],explanation:"It occurs when the pressure at the suction drops below the saturation pressure of the liquid."},{id:"refri_564",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 material est\xE1 estrictamente prohibido?",opciones:["Acero inoxidable.","Cobre y sus aleaciones (lat\xF3n, bronce), debido a la corrosi\xF3n qu\xEDmica violenta.","Aluminio.","Acero al carbono."],respuesta_correcta:1,explicacion:"El amon\xEDaco ataca el cobre en presencia de humedad, destruyendo los componentes en poco tiempo.",question:"In an Ammonia system, what material is strictly prohibited?",options:["Stainless steel.","Copper and its alloys (brass, bronze), due to violent chemical corrosion.","Aluminum.","Carbon steel."],explanation:"Ammonia attacks copper in the presence of moisture, destroying components in a short time."},{id:"refri_565",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Vaso de Expansi\xF3n' en un sistema de agua helada (Chiller)?",opciones:["Guardar refrigerante de reserva.","Absorber los cambios de volumen del agua debidos a cambios de temperatura, manteniendo la presi\xF3n estable.","Enfriar el agua m\xE1s r\xE1pido.","Filtrar el aire del agua."],respuesta_correcta:1,explicacion:"Como el agua es incompresible, sin este vaso las tuber\xEDas o v\xE1lvulas de seguridad se romper\xEDan al calentarse el agua.",question:"What is the function of the 'Expansion Tank' in a chilled water system?",options:["To store reserve refrigerant.","To absorb the volume changes of the water due to temperature changes, keeping the pressure stable.","To cool the water faster.","To filter air from the water."],explanation:"Since water is incompressible, without this tank the pipes or safety valves would rupture when the water heats up."},{id:"refri_566",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFqu\xE9 es el 'Vi' (Volume Index)?",opciones:["La velocidad interna.","La relaci\xF3n entre el volumen de la cavidad de succi\xF3n y el de descarga; determina la eficiencia seg\xFAn la presi\xF3n del sistema.","El volumen de aceite inyectado.","El n\xFAmero de tornillos del motor."],respuesta_correcta:1,explicacion:"Un Vi optimizado evita la sobrecompresi\xF3n o subcompresi\xF3n, ahorrando energ\xEDa.",question:"In a screw compressor, what is the 'Vi' (Volume Index)?",options:["The internal velocity.","The ratio between the suction cavity volume and the discharge cavity volume; it determines efficiency based on system pressure.","The volume of oil injected.","The number of motor screws."],explanation:"An optimized Vi prevents over-compression or under-compression, saving energy."},{id:"refri_567",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 sucede si el sentido de giro de un compresor centr\xEDfugo es incorrecto?",opciones:["Bombea menos gas.","No bombea nada y puede sufrir da\xF1os mec\xE1nicos graves en los sellos y cojinetes.","El gas fluye al rev\xE9s.","Consume menos amperaje."],respuesta_correcta:1,explicacion:"El dise\xF1o de los impulsores es unidireccional para generar la fuerza centr\xEDfuga necesaria.",question:"What happens if the rotation direction of a centrifugal compressor is incorrect?",options:["It pumps less gas.","It pumps nothing and can suffer severe mechanical damage to the seals and bearings.","The gas flows in reverse.","It draws less amperage."],explanation:"The impeller design is unidirectional to generate the required centrifugal force."},{id:"refri_568",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Separador de Aceite de Etapa Secundaria' en un compresor de tornillo?",opciones:["Enfriar el refrigerante.","Utilizar filtros coalescentes para retirar las micro-nieblas de aceite que el separador primario no pudo atrapar.","Aumentar la presi\xF3n de succi\xF3n.","Separar el agua del amon\xEDaco."],respuesta_correcta:1,explicacion:"Sin esta etapa, el aceite viajar\xEDa hacia los evaporadores, creando una capa aislante que matar\xEDa la eficiencia del sistema.",question:"What is the function of the 'Secondary Oil Separator' in a screw compressor?",options:["To cool the refrigerant.","To use coalescing filters to remove the oil micro-mist that the primary separator could not capture.","To increase suction pressure.","To separate water from ammonia."],explanation:"Without this stage, oil would travel to the evaporators, creating an insulating layer that would kill the system's efficiency."},{id:"refri_569",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 sucede si se utiliza una v\xE1lvula con partes internas de bronce?",opciones:["Funciona mejor.","El amon\xEDaco reacciona con el cobre del bronce y destruye la v\xE1lvula r\xE1pidamente en presencia de humedad.","La v\xE1lvula se vuelve magn\xE9tica.","Ahorra refrigerante."],respuesta_correcta:1,explicacion:"El R-717 y el cobre son incompatibles; el metal se vuelve quebradizo y se deshace (corrosi\xF3n azul).",question:"In an Ammonia system, what happens if a valve with bronze internal parts is used?",options:["It works better.","The ammonia reacts with the copper in the bronze and rapidly destroys the valve in the presence of moisture.","The valve becomes magnetic.","It saves refrigerant."],explanation:"R-717 and copper are incompatible; the metal becomes brittle and disintegrates (blue corrosion)."},{id:"refri_570",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un 'Intercambiador de Placas Soldadas' (BPHE)?",opciones:["Una placa para hacer hielo.","Un intercambiador compacto donde las placas de acero inoxidable est\xE1n unidas por cobre o n\xEDquel al vac\xEDo, sin juntas.","Un filtro de succi\xF3n.","Un sensor de nivel."],respuesta_correcta:1,explicacion:"Son extremadamente eficientes y soportan altas presiones, ideales para sistemas de CO2 o enfriadores de aceite.",question:"What is a 'Brazed Plate Heat Exchanger' (BPHE)?",options:["A plate for making ice.","A compact heat exchanger where stainless steel plates are joined by copper or nickel brazing under vacuum, with no gaskets.","A suction filter.","A level sensor."],explanation:"They are extremely efficient and can withstand high pressures, making them ideal for CO2 systems or oil coolers."},{id:"refri_571",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFcu\xE1l es el prop\xF3sito de un 'Vasos Decantador de Aceite' (Oil Still)?",opciones:["Calentar el aceite.","Separar y recolectar el aceite que se ha mezclado con el amon\xEDaco en el lado de baja presi\xF3n.","Filtrar el refrigerante.","Drenar el agua."],respuesta_correcta:1,explicacion:"El aceite es m\xE1s denso que el amon\xEDaco l\xEDquido; el decantador permite retirarlo sin detener el sistema.",question:"In an Ammonia system, what is an 'Oil Still' (Oil Decanting Vessel)?",options:["To heat the oil.","To separate and collect oil that has mixed with the ammonia on the low-pressure side.","To filter the refrigerant.","To drain the water."],explanation:"Oil is denser than liquid ammonia; the decanting vessel allows it to be removed without shutting down the system."},{id:"refri_572",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Presi\xF3n Neta de Aceite' en un compresor reciprocante industrial?",opciones:["La presi\xF3n que marca el man\xF3metro de aceite.","La presi\xF3n de la bomba de aceite menos la presi\xF3n del c\xE1rter (succi\xF3n).","La presi\xF3n de descarga m\xE1s 10 PSI.","La presi\xF3n del receptor de aceite."],respuesta_correcta:1,explicacion:"Es la presi\xF3n real que empuja el lubricante por los canales internos hacia los cojinetes.",question:"What is 'Net Oil Pressure' in an industrial reciprocating compressor?",options:["The pressure shown on the oil gauge.","The oil pump pressure minus the crankcase (suction) pressure.","The discharge pressure plus 10 PSI.","The oil receiver pressure."],explanation:"It is the actual pressure that pushes the lubricant through the internal passages to the bearings."},{id:"refri_573",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es el 'Efecto de No Condensables' en un sistema de refrigeraci\xF3n?",opciones:["Que el gas no se acaba.","Aumento de la presi\xF3n de descarga y de la temperatura de descarga debido al aire atrapado que no cambia de fase.","Que el aceite se vuelve s\xF3lido.","Que el evaporador enfr\xEDa m\xE1s."],respuesta_correcta:1,explicacion:"El aire ocupa espacio en el condensador, reduciendo el \xE1rea disponible para el refrigerante y forzando al compresor.",question:"What is the 'Effect of Non-Condensables' in a refrigeration system?",options:["That the gas does not run out.","An increase in discharge pressure and discharge temperature due to trapped air that does not change phase.","That the oil becomes solid.","That the evaporator cools more."],explanation:"Air occupies space in the condenser, reducing the area available for the refrigerant and forcing the compressor to work harder."},{id:"refri_574",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de recirculaci\xF3n por bomba, \xBFqu\xE9 sucede si la bomba tiene un 'NPSH' insuficiente?",opciones:["Bombea m\xE1s l\xEDquido.","Cavitaci\xF3n; se forman burbujas de vapor que implosionan y destruyen el impulsor met\xE1lico.","El aceite se separa mejor.","El motor consume menos amperaje."],respuesta_correcta:1,explicacion:"La cavitaci\xF3n suena como si hubiera 'canicas' dentro de la bomba y es destructiva.",question:"In a pump recirculation system, what happens if the pump has insufficient 'NPSH'?",options:["It pumps more liquid.","Cavitation occurs; vapor bubbles form and implode, destroying the metal impeller.","The oil separates better.","The motor draws less amperage."],explanation:"Cavitation sounds as though there are marbles inside the pump and is destructive."},{id:"refri_575",categoria:"REFRI_INDUSTRIAL",pregunta:"En una planta de Amon\xEDaco, \xBFpara qu\xE9 sirve la m\xE1scara de cara completa con filtro K (color verde)?",opciones:["Para protegerse del fr\xEDo.","Es el EPP obligatorio para proteger ojos y sistema respiratorio contra vapores de amon\xEDaco en caso de fugas.","Para ver mejor en la oscuridad.","Para filtrar polvo met\xE1lico."],respuesta_correcta:1,explicacion:"El amon\xEDaco es t\xF3xico e irritante; la seguridad personal es prioridad absoluta en ACVOLT Industrial.",question:"In an Ammonia plant, what is the purpose of the full-face mask with a K-rated (green) filter?",options:["To protect against the cold.","It is the mandatory PPE to protect the eyes and respiratory system from ammonia vapors in case of leaks.","To see better in the dark.","To filter metallic dust."],explanation:"Ammonia is toxic and irritating; personal safety is the absolute priority in industrial refrigeration."},{id:"refri_576",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Purger' en un Chiller centr\xEDfugo de baja presi\xF3n?",opciones:["Sacar el aceite viejo.","Eliminar el aire y los no condensables que se filtran al sistema porque este opera en vac\xEDo.","Aumentar el amperaje.","Enfriar el agua de la torre."],respuesta_correcta:1,explicacion:"Al operar por debajo de la presi\xF3n atmosf\xE9rica, cualquier poro succiona aire hacia adentro del equipo.",question:"What is the function of the 'Purger' in a low-pressure centrifugal Chiller?",options:["To remove old oil.","To remove air and non-condensables that infiltrate the system because it operates under vacuum.","To increase the amperage.","To cool the cooling tower water."],explanation:"When operating below atmospheric pressure, any tiny opening allows air to be sucked into the equipment."},{id:"refri_577",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor centr\xEDfugo, \xBFqu\xE9 sucede si la carga cae por debajo del 10-20%?",opciones:["El compresor es m\xE1s eficiente.","Riesgo de 'Surge' (bombeo), donde la presi\xF3n del condensador vence al compresor y el gas fluye en reversa.","El aceite se evapora.","El motor se acelera solo."],respuesta_correcta:1,explicacion:"Los centr\xEDfugos tienen un l\xEDmite de estabilidad operativa; por debajo de este, vibran violentamente y pueden destruirse.",question:"In a centrifugal compressor, what happens if the load drops below 10-20%?",options:["The compressor becomes more efficient.","Risk of 'Surge' (pumping), where the condenser pressure overcomes the compressor and gas flows in reverse.","The oil evaporates.","The motor speeds up on its own."],explanation:"Centrifugal compressors have an operational stability limit; below it, they vibrate violently and can self-destruct."},{id:"refri_578",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de Amon\xEDaco, \xBFqu\xE9 significa que una v\xE1lvula sea de 'Asiento Suave' (Soft Seat)?",opciones:["Que es de pl\xE1stico.","Que usa materiales como PTFE (Tefl\xF3n) para asegurar un cierre herm\xE9tico sin fugas microsc\xF3picas.","Que no requiere herramientas para abrirla.","Que se rompe f\xE1cil."],respuesta_correcta:1,explicacion:"El amon\xEDaco es dif\xEDcil de contener; los sellos de tefl\xF3n son el est\xE1ndar para evitar fugas constantes en v\xE1lvulas de paso.",question:"In Ammonia systems, what does it mean for a valve to have a 'Soft Seat'?",options:["That it is made of plastic.","That it uses materials such as PTFE (Teflon) to ensure a leak-tight seal without microscopic leaks.","That it can be opened without tools.","That it breaks easily."],explanation:"Ammonia is difficult to contain; Teflon seals are the standard for preventing constant leaks in shut-off valves."},{id:"refri_579",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de un 'Purger' autom\xE1tico en un sistema de Amon\xEDaco?",opciones:["A\xF1adir amon\xEDaco nuevo.","Eliminar aire y otros gases no condensables sin perder refrigerante, mejorando la presi\xF3n de descarga.","Limpiar el aceite.","Drenar el agua."],respuesta_correcta:1,explicacion:"El aire en el condensador reduce el \xE1rea de intercambio y dispara la presi\xF3n de alta; el purger lo saca de forma inteligente.",question:"What is the function of an automatic 'Purger' in an Ammonia system?",options:["To add fresh ammonia.","To remove air and other non-condensable gases without losing refrigerant, thereby improving the discharge pressure.","To clean the oil.","To drain the water."],explanation:"Air in the condenser reduces the heat exchange area and spikes the high-side pressure; the purger removes it intelligently."},{id:"refri_580",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Economizador' en un compresor de tornillo?",opciones:["Reduce el consumo de aceite.","Inyecta vapor de refrigerante a presi\xF3n intermedia para subenfriar el l\xEDquido principal, aumentando la capacidad y eficiencia del ciclo.","Detiene el compresor en emergencias.","Enfr\xEDa el motor el\xE9ctrico."],respuesta_correcta:1,explicacion:"Permite obtener un efecto refrigerante mayor con el mismo tama\xF1o de compresor.",question:"What is the function of the 'Economizer' in a screw compressor?",options:["It reduces oil consumption.","It injects refrigerant vapor at intermediate pressure to subcool the main liquid, increasing the cycle's capacity and efficiency.","It stops the compressor in emergencies.","It cools the electric motor."],explanation:"It allows a greater refrigerating effect from the same compressor size."},{id:"refri_581",categoria:"REFRI_INDUSTRIAL",pregunta:"En un Chiller de gran escala, \xBFqu\xE9 es la 'Carga T\xE9rmica de Inercia'?",opciones:["El peso del agua.","La capacidad del sistema para mantener la temperatura del agua debido al gran volumen almacenado en las tuber\xEDas y tanques.","El calor generado por la fricci\xF3n de las bombas.","La temperatura del cuarto de m\xE1quinas."],respuesta_correcta:1,explicacion:"Sistemas con gran inercia ciclan menos el compresor, lo que ahorra energ\xEDa y alarga la vida mec\xE1nica.",question:"In a large-scale Chiller, what is 'Thermal Inertia Load'?",options:["The weight of the water.","The system's ability to maintain water temperature due to the large volume stored in piping and tanks.","The heat generated by pump friction.","The machine room temperature."],explanation:"Systems with high thermal inertia cycle the compressor less frequently, saving energy and extending mechanical life."},{id:"refri_582",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 significa un 'Sistema Overfeed' (Sobrealimentado) de l\xEDquido?",opciones:["Que tiene exceso de gas.","Que se bombea m\xE1s refrigerante l\xEDquido al evaporador del que se puede evaporar en una pasada, para mojar todas las paredes del tubo.","Que el compresor es muy grande.","Que el aceite se desborda."],respuesta_correcta:1,explicacion:"Es el m\xE9todo m\xE1s eficiente de transferencia de calor en evaporadores industriales de gran tama\xF1o.",question:"What does a 'Liquid Overfeed System' mean?",options:["That there is excess gas.","That more liquid refrigerant is pumped to the evaporator than can evaporate in a single pass, in order to wet all tube walls.","That the compressor is oversized.","That the oil overflows."],explanation:"It is the most efficient method of heat transfer in large-scale industrial evaporators."},{id:"refri_583",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Eyectora de L\xEDquido' en un sistema de CO2 transcr\xEDtico avanzado?",opciones:["Aumentar la presi\xF3n de aceite.","Aprovechar la energ\xEDa de la expansi\xF3n para succionar gas de los evaporadores, reduciendo el trabajo del compresor.","Eliminar el aire del sistema.","Enfriar el Gas Cooler."],respuesta_correcta:1,explicacion:"El eyector mejora el COP del sistema al recuperar energ\xEDa mec\xE1nica que normalmente se pierde en el proceso de expansi\xF3n.",question:"What is the function of a 'Liquid Ejector' in an advanced transcritical CO2 system?",options:["To increase oil pressure.","To harness the expansion energy to draw gas from the evaporators, reducing compressor workload.","To remove air from the system.","To cool the Gas Cooler."],explanation:"The ejector improves the system COP by recovering mechanical energy that is normally lost during the expansion process."},{id:"refri_584",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFcu\xE1l es el s\xEDntoma de 'Agua en el sistema'?",opciones:["El amon\xEDaco huele m\xE1s fuerte.","Aumento de la temperatura de evaporaci\xF3n para una presi\xF3n dada y formaci\xF3n de lodos corrosivos.","El aceite se vuelve transparente.","La presi\xF3n de descarga baja."],respuesta_correcta:1,explicacion:"El agua es extremadamente af\xEDn al amon\xEDaco; su presencia eleva el punto de ebullici\xF3n, robando capacidad de enfriamiento.",question:"In an Ammonia system, what is the symptom of 'Water in the System'?",options:["The ammonia smells stronger.","An increase in the evaporating temperature for a given pressure and formation of corrosive sludge.","The oil becomes transparent.","The discharge pressure drops."],explanation:"Water has an extremely high affinity for ammonia; its presence raises the boiling point, robbing cooling capacity."},{id:"refri_585",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'L\xEDnea de Ecualizaci\xF3n de Aceite' en un rack de compresores de tornillo?",opciones:["Un cable el\xE9ctrico.","Una tuber\xEDa que mantiene el mismo nivel de aceite y presi\xF3n en todos los separadores de aceite del rack.","Una l\xEDnea para vaciar el sistema.","Un sensor de temperatura."],respuesta_correcta:1,explicacion:"Garantiza que ning\xFAn compresor se quede sin lubricaci\xF3n mientras otros tienen exceso de aceite.",question:"What is the 'Oil Equalization Line' in a screw compressor rack?",options:["An electrical cable.","A pipe that maintains the same oil level and pressure in all oil separators in the rack.","A line for draining the system.","A temperature sensor."],explanation:"It ensures that no compressor runs out of lubrication while others have excess oil."},{id:"refri_586",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Tanque de expansi\xF3n' (Surge Drum)?",opciones:["Un tanque para gas caliente.","Un recipiente que separa el l\xEDquido del vapor antes de que el refrigerante entre al compresor en sistemas inundados.","Un filtro de succi\xF3n.","Un sensor de nivel de aceite."],respuesta_correcta:1,explicacion:"Es el pulm\xF3n de los sistemas inundados, garantizando que el compresor reciba vapor saturado seco.",question:"In an Ammonia system, what is a 'Surge Drum' (Expansion Vessel)?",options:["A hot gas tank.","A vessel that separates liquid from vapor before the refrigerant enters the compressor in flooded systems.","A suction filter.","An oil level sensor."],explanation:"It is the lung of flooded systems, ensuring the compressor receives dry saturated vapor."},{id:"refri_587",categoria:"REFRI_INDUSTRIAL",pregunta:"En una planta industrial, \xBFqu\xE9 indica una diferencia de presi\xF3n alta a trav\xE9s del filtro coalescente de aceite?",opciones:["Funcionamiento normal.","Saturaci\xF3n del filtro; debe reemplazarse para evitar que el aceite pase hacia el condensador.","Que el aceite es muy fluido.","Que el compresor gira r\xE1pido."],respuesta_correcta:1,explicacion:"La ca\xEDda de presi\xF3n mide qu\xE9 tan obstruido est\xE1 el medio filtrante.",question:"In an industrial plant, what does a high pressure differential across the coalescing oil filter indicate?",options:["Normal operation.","Filter saturation; it must be replaced to prevent oil from passing through to the condenser.","That the oil is very fluid.","That the compressor is spinning fast."],explanation:"The pressure drop measures how obstructed the filter media has become."},{id:"refri_588",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula de 'Inyecci\xF3n de Aceite' asistida por solenoide en un compresor de tornillo?",opciones:["Lavar el compresor.","Asegurar que el aceite entre a los rotores solo cuando el compresor est\xE1 operando, evitando inundar el c\xE1rter en la parada.","Enfriar el gas de descarga.","Regular la velocidad."],respuesta_correcta:1,explicacion:"Evita el retorno de aceite masivo que causar\xEDa un arranque hidr\xE1ulicamente bloqueado.",question:"What is the function of a solenoid-assisted 'Oil Injection Valve' in a screw compressor?",options:["To flush the compressor.","To ensure oil enters the rotors only when the compressor is running, preventing crankcase flooding during shutdown.","To cool the discharge gas.","To regulate speed."],explanation:"It prevents the massive oil return that would cause a hydraulically locked start."},{id:"refri_589",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor centr\xEDfugo, \xBFqu\xE9 sucede si la carga cae por debajo del 10-20%?",opciones:["El compresor es m\xE1s eficiente.","Riesgo de 'Surge' (bombeo), donde la presi\xF3n del condensador vence al compresor y el gas fluye en reversa.","El aceite se evapora.","El motor se acelera solo."],respuesta_correcta:1,explicacion:"Los centr\xEDfugos tienen un l\xEDmite de estabilidad operativa; por debajo de este, vibran violentamente y pueden destruirse.",question:"In a centrifugal compressor, what happens if the load drops below 10-20%?",options:["The compressor becomes more efficient.","Risk of 'Surge' (pumping), where the condenser pressure overcomes the compressor and gas flows in reverse.","The oil evaporates.","The motor speeds up on its own."],explanation:"Centrifugal compressors have an operational stability limit; below it, they vibrate violently and can self-destruct."},{id:"refri_590",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de Amon\xEDaco, \xBFqu\xE9 significa que una v\xE1lvula sea de 'Asiento Suave' (Soft Seat)?",opciones:["Que es de pl\xE1stico.","Que usa materiales como PTFE (Tefl\xF3n) para asegurar un cierre herm\xE9tico sin fugas microsc\xF3picas.","Que no requiere herramientas para abrirla.","Que se rompe f\xE1cil."],respuesta_correcta:1,explicacion:"El amon\xEDaco es dif\xEDcil de contener; los sellos de tefl\xF3n son el est\xE1ndar para evitar fugas constantes en v\xE1lvulas de paso.",question:"In Ammonia systems, what does it mean for a valve to have a 'Soft Seat'?",options:["That it is made of plastic.","That it uses materials such as PTFE (Teflon) to ensure a leak-tight seal without microscopic leaks.","That it can be opened without tools.","That it breaks easily."],explanation:"Ammonia is difficult to contain; Teflon seals are the standard for preventing constant leaks in shut-off valves."},{id:"refri_591",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de un 'Purger' autom\xE1tico en un sistema de Amon\xEDaco?",opciones:["A\xF1adir amon\xEDaco nuevo.","Eliminar aire y otros gases no condensables sin perder refrigerante, mejorando la presi\xF3n de descarga.","Limpiar el aceite.","Drenar el agua."],respuesta_correcta:1,explicacion:"El aire en el condensador reduce el \xE1rea de intercambio y dispara la presi\xF3n de alta; el purger lo saca de forma inteligente.",question:"What is the function of an automatic 'Purger' in an Ammonia system?",options:["To add fresh ammonia.","To remove air and other non-condensable gases without losing refrigerant, thereby improving the discharge pressure.","To clean the oil.","To drain the water."],explanation:"Air in the condenser reduces the heat exchange area and spikes the high-side pressure; the purger removes it intelligently."},{id:"refri_592",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Economizador' en un compresor de tornillo?",opciones:["Reduce el consumo de aceite.","Inyecta vapor de refrigerante a presi\xF3n intermedia para subenfriar el l\xEDquido principal, aumentando la capacidad y eficiencia del ciclo.","Detiene el compresor en emergencias.","Enfr\xEDa el motor el\xE9ctrico."],respuesta_correcta:1,explicacion:"Permite obtener un efecto refrigerante mayor con el mismo tama\xF1o de compresor.",question:"What is the function of the 'Economizer' in a screw compressor?",options:["It reduces oil consumption.","It injects refrigerant vapor at intermediate pressure to subcool the main liquid, increasing the cycle's capacity and efficiency.","It stops the compressor in emergencies.","It cools the electric motor."],explanation:"It allows a greater refrigerating effect from the same compressor size."},{id:"refri_593",categoria:"REFRI_INDUSTRIAL",pregunta:"En un Chiller de gran escala, \xBFqu\xE9 es la 'Carga T\xE9rmica de Inercia'?",opciones:["El peso del agua.","La capacidad del sistema para mantener la temperatura del agua debido al gran volumen almacenado en las tuber\xEDas y tanques.","El calor generado por la fricci\xF3n de las bombas.","La temperatura del cuarto de m\xE1quinas."],respuesta_correcta:1,explicacion:"Sistemas con gran inercia ciclan menos el compresor, lo que ahorra energ\xEDa y alarga la vida mec\xE1nica.",question:"In a large-scale Chiller, what is 'Thermal Inertia Load'?",options:["The weight of the water.","The system's ability to maintain water temperature due to the large volume stored in piping and tanks.","The heat generated by pump friction.","The machine room temperature."],explanation:"Systems with high thermal inertia cycle the compressor less frequently, saving energy and extending mechanical life."},{id:"refri_594",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 significa un 'Sistema Overfeed' (Sobrealimentado) de l\xEDquido?",opciones:["Que tiene exceso de gas.","Que se bombea m\xE1s refrigerante l\xEDquido al evaporador del que se puede evaporar en una pasada, para mojar todas las paredes del tubo.","Que el compresor es muy grande.","Que el aceite se desborda."],respuesta_correcta:1,explicacion:"Es el m\xE9todo m\xE1s eficiente de transferencia de calor en evaporadores industriales de gran tama\xF1o.",question:"What does a 'Liquid Overfeed System' mean?",options:["That there is excess gas.","That more liquid refrigerant is pumped to the evaporator than can evaporate in a single pass, in order to wet all tube walls.","That the compressor is oversized.","That the oil overflows."],explanation:"It is the most efficient method of heat transfer in large-scale industrial evaporators."},{id:"refri_595",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Recipiente de Termosif\xF3n'?",opciones:["Un filtro de gas.","Un tanque elevado que suministra refrigerante l\xEDquido para enfriar el aceite de los compresores de tornillo por gravedad.","Un calentador de agua.","Un separador de purga."],respuesta_correcta:1,explicacion:"Es una forma pasiva y muy segura de manejar el calor generado por el aceite del compresor.",question:"In an Ammonia system, what is a 'Thermosiphon Vessel'?",options:["A gas filter.","An elevated tank that supplies liquid refrigerant to cool screw compressor oil by gravity.","A water heater.","A purge separator."],explanation:"It is a passive and very safe way to manage the heat generated by compressor oil."},{id:"refri_596",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 significa 'Relaci\xF3n de Compresi\xF3n' y c\xF3mo afecta la vida del compresor?",opciones:["Es el peso del compresor.","Es la presi\xF3n de descarga absoluta entre la de succi\xF3n absoluta; a mayor relaci\xF3n, m\xE1s calor se genera y m\xE1s sufre el compresor.","Es la cantidad de aceite por gas.","Es la velocidad del motor."],respuesta_correcta:1,explicacion:"Mantener relaciones de compresi\xF3n bajas es la clave para que un compresor dure 20 a\xF1os.",question:"What does 'Compression Ratio' mean and how does it affect compressor life?",options:["It is the weight of the compressor.","It is the absolute discharge pressure divided by the absolute suction pressure; the higher the ratio, the more heat is generated and the more the compressor suffers.","It is the ratio of oil to gas.","It is the motor speed."],explanation:"Keeping compression ratios low is the key to making a compressor last 20 years."},{id:"refri_597",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Vaso Intermedio' (Intercooler)?",opciones:["Un tanque de agua.","Un recipiente que enfr\xEDa el gas de descarga de la etapa de baja antes de que entre a la etapa de alta en compresi\xF3n de dos etapas.","Un filtro de aceite.","Un sensor de presi\xF3n."],respuesta_correcta:1,explicacion:"Reduce el trabajo de compresi\xF3n y evita temperaturas de descarga que degradar\xEDan el aceite.",question:"In an Ammonia system, what is an 'Intercooler' (Intermediate Vessel)?",options:["A water tank.","A vessel that cools the discharge gas from the low stage before it enters the high stage in a two-stage compression system.","An oil filter.","A pressure sensor."],explanation:"It reduces the work of compression and prevents discharge temperatures that would degrade the oil."},{id:"refri_598",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n principal de un 'Economizador de Tanque Flash' en un sistema de amon\xEDaco de dos etapas?",opciones:["Separar el aceite.","Enfriar el l\xEDquido que va a los evaporadores de baja temperatura mediante la expansi\xF3n parcial del refrigerante a una presi\xF3n intermedia.","Aumentar el flujo de agua en la torre.","Reducir el ruido de succi\xF3n."],respuesta_correcta:1,explicacion:"Aumenta la eficiencia del ciclo al reducir la entalp\xEDa del l\xEDquido antes de entrar a la etapa de menor temperatura.",question:"What is the primary function of a 'Flash Tank Economizer' in a two-stage ammonia system?",options:["To separate the oil.","To cool the liquid going to the low-temperature evaporators by partially expanding the refrigerant to an intermediate pressure.","To increase water flow in the cooling tower.","To reduce suction noise."],explanation:"It increases the cycle efficiency by reducing the enthalpy of the liquid before it enters the lowest temperature stage."},{id:"refri_599",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de refrigeraci\xF3n industrial, \xBFqu\xE9 es un 'Vaso de Purga de Aceite' (Oil Pot) y por qu\xE9 debe operarse con cuidado?",opciones:["Es para echar aceite nuevo.","Es un recipiente para drenar aceite del lado de baja; debe operarse con cuidado para no liberar amon\xEDaco l\xEDquido o vapores t\xF3xicos al ambiente.","Es un filtro de aire.","Es para calentar el refrigerante."],respuesta_correcta:1,explicacion:"Drenar aceite en sistemas industriales es una tarea de alto riesgo que requiere equipo de protecci\xF3n personal completo.",question:"In industrial refrigeration systems, what is an 'Oil Pot' (Oil Purge Vessel) and why must it be operated with care?",options:["It is for adding new oil.","It is a vessel for draining oil from the low side; it must be operated carefully to avoid releasing liquid ammonia or toxic vapors into the environment.","It is an air filter.","It is for heating the refrigerant."],explanation:"Draining oil in industrial systems is a high-risk task that requires full personal protective equipment."},{id:"refri_600",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Desrecalentador' en un sistema de amon\xEDaco?",opciones:["Enfriar el cuarto fr\xEDo.","Quitar el calor sensible del gas de descarga antes de que entre al condensador, a menudo para calentar agua de proceso.","Subenfriar el l\xEDquido.","Aumentar la presi\xF3n de succi\xF3n."],respuesta_correcta:1,explicacion:"Es una forma de recuperaci\xF3n de energ\xEDa que mejora el rendimiento global de la planta.",question:"What is the function of the 'Desuperheater' in an ammonia system?",options:["To cool the cold room.","To remove sensible heat from the discharge gas before it enters the condenser, often used to heat process water.","To subcool the liquid.","To increase suction pressure."],explanation:"It is a form of heat recovery that improves the overall plant performance."},{id:"refri_601",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es la 'Corrosi\xF3n bajo aislamiento' (CUI)?",opciones:["Un hongo en la tuber\xEDa.","Deterioro del metal (acero al carbono) debido a la humedad atrapada entre el aislamiento y la tuber\xEDa, acelerada por ciclos de temperatura.","Fuga de aceite.","Efecto magn\xE9tico."],respuesta_correcta:1,explicacion:"Es un problema oculto muy peligroso que puede causar fugas catastr\xF3ficas si no se inspecciona.",question:"In an Ammonia system, what is 'Corrosion Under Insulation' (CUI)?",options:["A fungus on the pipe.","Deterioration of the metal (carbon steel) due to moisture trapped between the insulation and the pipe, accelerated by temperature cycling.","An oil leak.","A magnetic effect."],explanation:"It is a hidden and very dangerous problem that can cause catastrophic leaks if not inspected."},{id:"refri_602",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFpara qu\xE9 sirve la 'Inyecci\xF3n de Aceite Dual'?",opciones:["Para usar dos tipos de aceite.","Para lubricar los rodamientos por un lado y sellar/enfriar los rotores por el otro.","Para limpiar el sistema.","Para aumentar el ruido."],respuesta_correcta:1,explicacion:"Asegura una gesti\xF3n hidr\xE1ulica precisa para la longevidad mec\xE1nica y la eficiencia t\xE9rmica.",question:"In a screw compressor, what is the purpose of 'Dual Oil Injection'?",options:["To use two types of oil.","To lubricate the bearings through one circuit and seal/cool the rotors through another.","To clean the system.","To increase noise."],explanation:"It ensures precise hydraulic management for both mechanical longevity and thermal efficiency."},{id:"refri_603",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un 'Intercambiador de Placas' en un sistema de amon\xEDaco/glicol?",opciones:["Mezclar el amon\xEDaco con el glicol.","Transferir el fr\xEDo del amon\xEDaco al fluido secundario (glicol) de forma compacta y eficiente.","Calentar el amon\xEDaco.","Filtrar impurezas."],respuesta_correcta:1,explicacion:"Permite mantener el amon\xEDaco confinado y circular un fluido seguro hacia las \xE1reas de proceso.",question:"What is the purpose of a 'Plate Heat Exchanger' in an ammonia/glycol system?",options:["To mix ammonia with glycol.","To transfer the cooling from ammonia to the secondary fluid (glycol) in a compact and efficient manner.","To heat the ammonia.","To filter impurities."],explanation:"It allows keeping the ammonia confined and circulating a safe fluid to the process areas."},{id:"refri_604",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es la 'Purga de Aire' y d\xF3nde se realiza t\xEDpicamente?",opciones:["En el evaporador.","En el punto m\xE1s alto y lento del lado de alta presi\xF3n (generalmente el condensador o el receptor de l\xEDquido).","En el c\xE1rter del compresor.","En el drenaje."],respuesta_correcta:1,explicacion:"Los no condensables se acumulan all\xED; sacarlos baja la presi\xF3n de descarga y ahorra mucha energ\xEDa.",question:"In an Ammonia system, what is 'Air Purging' and where is it typically performed?",options:["At the evaporator.","At the highest and slowest point on the high-pressure side (typically the condenser or liquid receiver).","At the compressor crankcase.","At the drain."],explanation:"Non-condensables accumulate there; removing them lowers the discharge pressure and saves considerable energy."},{id:"refri_605",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Vaso de expansi\xF3n' en un sistema de agua helada industrial?",opciones:["Guardar refrigerante.","Compensar las variaciones de volumen del agua debido a cambios de temperatura para evitar rupturas por presi\xF3n.","Enfriar el agua.","Filtrar el lodo."],respuesta_correcta:1,explicacion:"Como el agua es incompresible, el aire dentro del vaso de expansi\xF3n act\xFAa como un amortiguador.",question:"What is the function of the 'Expansion Tank' in an industrial chilled water system?",options:["To store refrigerant.","To compensate for volume changes in the water due to temperature fluctuations, preventing pressure-related ruptures.","To cool the water.","To filter sludge."],explanation:"Since water is incompressible, the air inside the expansion tank acts as a cushion."},{id:"refri_606",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es la 'Relaci\xF3n de Recirculaci\xF3n' (Overfeed ratio) en sistemas industriales?",opciones:["Veces que el aceite pasa por el filtro.","La relaci\xF3n entre el l\xEDquido bombeado al evaporador y el l\xEDquido realmente evaporado (t\xEDpicamente 3:1 o 4:1).","La velocidad del gas.","El tama\xF1o del compresor."],respuesta_correcta:1,explicacion:"Garantiza que el evaporador est\xE9 siempre inundado de l\xEDquido para una eficiencia m\xE1xima.",question:"What is the 'Recirculation Ratio' (Overfeed Ratio) in industrial systems?",options:["The number of times oil passes through the filter.","The ratio between the liquid pumped to the evaporator and the liquid actually evaporated (typically 3:1 or 4:1).","The gas velocity.","The compressor size."],explanation:"It ensures the evaporator is always flooded with liquid for maximum efficiency."},{id:"refri_607",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de refrigeraci\xF3n por absorci\xF3n, \xBFqu\xE9 refrigerante se usa com\xFAnmente con el Bromuro de Litio?",opciones:["Amon\xEDaco.","Agua (H2O).","R-22.","Helio."],respuesta_correcta:1,explicacion:"En estos sistemas el agua act\xFAa como refrigerante, evapor\xE1ndose en alto vac\xEDo para generar fr\xEDo.",question:"In an absorption refrigeration system, what refrigerant is commonly used with Lithium Bromide?",options:["Ammonia.","Water (H2O).","R-22.","Helium."],explanation:"In these systems, water acts as the refrigerant, evaporating under high vacuum to produce cooling."},{id:"refri_608",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 material est\xE1 estrictamente prohibido para las tuber\xEDas?",opciones:["Acero inoxidable.","Cobre y sus aleaciones (lat\xF3n, bronce), ya que el amon\xEDaco los corroe r\xE1pidamente en presencia de humedad.","Acero al carbono.","Hierro fundido."],respuesta_correcta:1,explicacion:"El amon\xEDaco reacciona agresivamente con el cobre; solo se permiten sistemas ferrosos o de aluminio.",question:"In an Ammonia system, what material is strictly prohibited for piping?",options:["Stainless steel.","Copper and its alloys (brass, bronze), as ammonia corrodes them rapidly in the presence of moisture.","Carbon steel.","Cast iron."],explanation:"Ammonia reacts aggressively with copper; only ferrous or aluminum systems are permitted."},{id:"refri_609",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR) en sistemas industriales?",opciones:["Mantener la presi\xF3n de aceite alta.","Evitar que el compresor se sobrecargue durante el arranque limitando la presi\xF3n m\xE1xima de succi\xF3n.","Controlar el subenfriamiento.","No se usa en la industria."],respuesta_correcta:1,explicacion:"Es crucial en sistemas con grandes cargas iniciales o tras un deshielo por gas caliente.",question:"What is the function of a Crankcase Pressure Regulating valve (CPR) in industrial systems?",options:["To keep oil pressure high.","To prevent the compressor from overloading during startup by limiting the maximum suction pressure.","To control subcooling.","It is not used in industrial applications."],explanation:"It is crucial in systems with large initial loads or after a hot gas defrost cycle."},{id:"refri_610",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 componente de seguridad se usa en sistemas de Amon\xEDaco para detectar fugas microsc\xF3picas en el agua?",opciones:["Un detector de llama.","Un sensor de pH o conductividad en el circuito de agua.","Un term\xF3metro de precisi\xF3n.","No se pueden detectar."],respuesta_correcta:1,explicacion:"El amon\xEDaco cambia el pH del agua; monitorear esto permite detectar fugas internas antes de que el da\xF1o sea mayor.",question:"What safety component is used in Ammonia systems to detect microscopic leaks in the water?",options:["A flame detector.","A pH or conductivity sensor in the water circuit.","A precision thermometer.","They cannot be detected."],explanation:"Ammonia changes the pH of water; monitoring this allows internal leaks to be detected before major damage occurs."},{id:"refri_611",categoria:"REFRI_INDUSTRIAL",pregunta:"En un compresor de tornillo, \xBFpara qu\xE9 sirve la inyecci\xF3n de l\xEDquido opcional?",opciones:["Para lavar los rotores.","Para enfriar el gas de descarga en aplicaciones de alta relaci\xF3n de compresi\xF3n.","Para aumentar la presi\xF3n de succi\xF3n.","Para calentar el aceite."],respuesta_correcta:1,explicacion:"Es una alternativa o complemento al enfriamiento de aceite para proteger los sellos del compresor.",question:"In a screw compressor, what is the purpose of optional liquid injection?",options:["To wash the rotors.","To cool the discharge gas in high compression ratio applications.","To increase the suction pressure.","To heat the oil."],explanation:"It is an alternative or complement to oil cooling to protect the compressor seals."},{id:"refri_612",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 es un 'Intercambiador de placas' y por qu\xE9 se usa en refrigeraci\xF3n industrial?",opciones:["Un tipo de filtro.","Un intercambiador muy compacto que usa placas met\xE1licas para transferir calor entre dos fluidos de manera eficiente.","Una placa de hielo.","Un control de presi\xF3n."],respuesta_correcta:1,explicacion:"Es ideal para enfriar glicol o salmuera con amon\xEDaco debido a su alta eficiencia y bajo volumen de carga.",question:"What is a 'Plate Heat Exchanger' and why is it used in industrial refrigeration?",options:["A type of filter.","A very compact heat exchanger that uses metal plates to efficiently transfer heat between two fluids.","An ice plate.","A pressure control."],explanation:"It is ideal for cooling glycol or brine with ammonia due to its high efficiency and low refrigerant charge volume."},{id:"refri_613",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es el prop\xF3sito del 'Intercambiador de Calor de Succi\xF3n-L\xEDquido' en sistemas industriales?",opciones:["Calentar el cuarto de m\xE1quinas.","Subenfriar el l\xEDquido antes de la expansi\xF3n y sobrecalentar el gas de succi\xF3n para asegurar que no llegue l\xEDquido al compresor.","Filtrar el aceite.","Aumentar la presi\xF3n de descarga."],respuesta_correcta:1,explicacion:"Mejora la eficiencia volum\xE9trica y protege mec\xE1nicamente al compresor en una sola operaci\xF3n.",question:"What is the purpose of the 'Suction-Liquid Heat Exchanger' in industrial systems?",options:["To heat the machine room.","To subcool the liquid before expansion and superheat the suction gas to ensure no liquid reaches the compressor.","To filter the oil.","To increase discharge pressure."],explanation:"It improves volumetric efficiency and mechanically protects the compressor in a single operation."},{id:"refri_614",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es la 'Respiraci\xF3n del Aceite'?",opciones:["Cuando el aceite huele mal.","El movimiento de vapores de aceite y refrigerante en el c\xE1rter durante los cambios de presi\xF3n del arranque.","Un m\xE9todo de filtrado.","La ventilaci\xF3n del cuarto de m\xE1quinas."],respuesta_correcta:1,explicacion:"Un dise\xF1o correcto de la ventilaci\xF3n del c\xE1rter evita la p\xE9rdida excesiva de aceite hacia el sistema de descarga.",question:"In an Ammonia system, what is 'Oil Breathing'?",options:["When the oil smells bad.","The movement of oil vapors and refrigerant in the crankcase during the pressure changes at startup.","A filtration method.","The ventilation of the machine room."],explanation:"Proper crankcase venting design prevents excessive oil loss into the discharge system."},{id:"refri_615",categoria:"REFRI_INDUSTRIAL",pregunta:"En un Chiller industrial, \xBFqu\xE9 es el 'L\xEDmite de Congelaci\xF3n' (Freeze Stat)?",opciones:["Un term\xF3metro manual.","Un control de seguridad que apaga el compresor si la temperatura del agua se acerca peligrosamente al punto de congelaci\xF3n.","La temperatura del aceite.","Un ventilador de emergencia."],respuesta_correcta:1,explicacion:"Evita que el agua se convierta en hielo dentro de los tubos y reviente el intercambiador.",question:"In an industrial Chiller, what is the 'Freeze Stat' (Freeze Limit)?",options:["A manual thermometer.","A safety control that shuts down the compressor if the water temperature dangerously approaches the freezing point.","The oil temperature.","An emergency fan."],explanation:"It prevents the water from turning into ice inside the tubes and bursting the heat exchanger."},{id:"refri_616",categoria:"REFRI_INDUSTRIAL",pregunta:"En sistemas de Amon\xEDaco, \xBFqu\xE9 es la 'Prueba de Presi\xF3n Hidrost\xE1tica'?",opciones:["Prueba con gas nitr\xF3geno.","Prueba de resistencia de un recipiente llen\xE1ndolo con agua a presiones superiores a las de operaci\xF3n.","Prueba de flujo de aceite.","Prueba de vac\xEDo profundo."],respuesta_correcta:1,explicacion:"Se usa en la fabricaci\xF3n y recertificaci\xF3n de recipientes de presi\xF3n para garantizar su integridad estructural.",question:"In Ammonia systems, what is a 'Hydrostatic Pressure Test'?",options:["A test with nitrogen gas.","A vessel strength test performed by filling it with water at pressures exceeding the operating pressure.","An oil flow test.","A deep vacuum test."],explanation:"It is used during the manufacture and recertification of pressure vessels to verify their structural integrity."},{id:"refri_617",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFPor qu\xE9 los compresores de tornillo industriales requieren un separador de aceite tan grande?",opciones:["Por est\xE9tica de la planta.","Debido al enorme volumen de aceite inyectado para sellar, lubricar y enfriar los rotores durante la compresi\xF3n.","Porque el aceite se expande con el amon\xEDaco.","Para que el motor no haga ruido."],respuesta_correcta:1,explicacion:"El tornillo mueve una 'sopa' de aceite y gas; separarlos con alta eficiencia es cr\xEDtico para el resto del sistema.",question:"Why do industrial screw compressors require such a large oil separator?",options:["For plant aesthetics.","Due to the enormous volume of oil injected to seal, lubricate, and cool the rotors during compression.","Because the oil expands with the ammonia.","To keep the motor quiet."],explanation:"The screw compressor moves a mixture of oil and gas; separating them with high efficiency is critical for the rest of the system."},{id:"refri_618",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n de una 'V\xE1lvula de Alivio' (Safety Relief Valve)?",opciones:["Regular la presi\xF3n de succi\xF3n.","Liberar la presi\xF3n excesiva del sistema hacia la atm\xF3sfera (o tanque de agua) para evitar explosiones del recipiente.","Enfriar el aceite.","Ahorrar gas."],respuesta_correcta:1,explicacion:"Es el \xFAltimo dispositivo de seguridad mec\xE1nica en cualquier sistema de presi\xF3n.",question:"What is the function of a 'Safety Relief Valve'?",options:["To regulate suction pressure.","To release excess system pressure to the atmosphere (or a water tank) to prevent vessel explosions.","To cool the oil.","To conserve gas."],explanation:"It is the last line of mechanical safety defense in any pressure system."},{id:"refri_619",categoria:"REFRI_INDUSTRIAL",pregunta:"En un sistema de Amon\xEDaco, \xBFqu\xE9 es un 'Enfriador de Aceite por Aire'?",opciones:["Un ventilador de techo.","Un radiador externo (tipo dry cooler) que usa aire para bajar la temperatura del aceite del compresor.","Un aire acondicionado para el aceite.","No existe."],respuesta_correcta:1,explicacion:"Es una alternativa al enfriamiento por agua o termosif\xF3n en climas adecuados.",question:"In an Ammonia system, what is an 'Air-Cooled Oil Cooler'?",options:["A ceiling fan.","An external radiator (dry cooler type) that uses air to reduce the temperature of the compressor oil.","An air conditioner for the oil.","It does not exist."],explanation:"It is an alternative to water cooling or thermosiphon cooling in suitable climates."},{id:"refri_620",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFCu\xE1l es la funci\xF3n del 'Intercambiador de Placas de Seguridad' (Double Wall) en la industria alimentaria?",opciones:["Enfriar el doble de r\xE1pido.","Prevenir la contaminaci\xF3n del producto (ej. leche) con el refrigerante en caso de una perforaci\xF3n interna de las placas.","Hacer el equipo m\xE1s pesado.","Ahorrar agua."],respuesta_correcta:1,explicacion:"La doble pared asegura que cualquier fuga salga al exterior antes de mezclarse con el fluido secundario.",question:"What is the function of a 'Double Wall Safety Plate Heat Exchanger' in the food industry?",options:["To cool twice as fast.","To prevent contamination of the product (e.g., milk) with refrigerant in case of an internal plate perforation.","To make the equipment heavier.","To save water."],explanation:"The double wall ensures any leak escapes to the outside before mixing with the secondary fluid."},{id:"refri_621",categoria:"REFRI_INDUSTRIAL",pregunta:"\xBFQu\xE9 componente monitorea la vibraci\xF3n en un compresor de tornillo grande?",opciones:["Un term\xF3metro.","Un aceler\xF3metro o sensor de vibraci\xF3n conectado al sistema de protecci\xF3n para evitar fallas mec\xE1nicas catastr\xF3ficas.","Un man\xF3metro.","El o\xEDdo del t\xE9cnico solamente."],respuesta_correcta:1,explicacion:"La vibraci\xF3n excesiva es la primera se\xF1al de falla de rodamientos o desequilibrio de rotores.",question:"What component monitors vibration in a large screw compressor?",options:["A thermometer.","An accelerometer or vibration sensor connected to the protection system to prevent catastrophic mechanical failures.","A pressure gauge.","The technician's ear only."],explanation:"Excessive vibration is the first sign of bearing failure or rotor imbalance."},{id:"refri_622",categoria:"REFRI_CONTROLES",pregunta:"Al configurar un controlador electr\xF3nico para un evaporador de baja temperatura, \xBFcu\xE1l es el prop\xF3sito principal del 'Fan Delay' tras el desescarche (defrost)?",opciones:["Evitar que el calor del desescarche se sople hacia el gabinete.","Permitir que el agua residual en las aletas se congele para no atomizarla.","Reducir el consumo el\xE9ctrico del arranque de los motores.","A y B son correctas."],respuesta_correcta:3,explicacion:"El retardo de ventiladores permite que el serpent\xEDn se enfr\xEDe (evitando soplar calor) y que las gotas de agua remanentes se congelen en la aleta para que no salgan volando hacia el producto.",question:"When configuring an electronic controller for a low-temperature evaporator, what is the main purpose of 'Fan Delay' after defrost?",options:["To prevent defrost heat from being blown into the cabinet.","To allow residual water on the fins to freeze so it is not atomized.","To reduce the electrical consumption of the motor startup.","Both A and B are correct."],explanation:"The fan delay allows the coil to cool down (avoiding blowing heat) and lets remaining water droplets freeze on the fins so they are not blown onto the product."},{id:"refri_623",categoria:"REFRI_CONTROLES",pregunta:"En un sistema de desescarche por gas caliente, \xBFqu\xE9 componente evita que el l\xEDquido condensado en el evaporador regrese bruscamente al compresor?",opciones:["V\xE1lvula Check de bypass.","Acumulador de succi\xF3n.","V\xE1lvula reguladora de presi\xF3n de c\xE1rter (CPR).","Separador de aceite."],respuesta_correcta:1,explicacion:"El acumulador de succi\xF3n es la \xFAltima l\xEDnea de defensa para atrapar el l\xEDquido que se condensa en el evaporador durante el ciclo de gas caliente.",question:"In a hot gas defrost system, what component prevents liquid condensed in the evaporator from rushing back to the compressor?",options:["Bypass check valve.","Suction accumulator.","Crankcase pressure regulating valve (CPR).","Oil separator."],explanation:"The suction accumulator is the last line of defense for trapping liquid that condenses in the evaporator during the hot gas cycle."},{id:"refri_624",categoria:"REFRI_CONTROLES",pregunta:"Usando un transductor de presi\xF3n y un sensor NTC para medir sobrecalentamiento en tiempo real, el controlador marca 'LSH'. \xBFQu\xE9 significa esto usualmente?",opciones:["Low Superheat (Sobrecalentamiento Bajo).","Liquid Suction High (Succi\xF3n de L\xEDquido Alta).","Load System High (Carga de Sistema Alta).","Line Sensor Hazard (Falla en el sensor)."],respuesta_correcta:0,explicacion:"LSH es la alarma est\xE1ndar para Low Superheat, indicando riesgo inminente de golpe de l\xEDquido al compresor.",question:"Using a pressure transducer and an NTC sensor to measure superheat in real time, the controller displays 'LSH'. What does this usually mean?",options:["Low Superheat.","Liquid Suction High.","Load System High.","Line Sensor Hazard."],explanation:"LSH is the standard alarm for Low Superheat, indicating an imminent risk of liquid slugging to the compressor."},{id:"refri_625",categoria:"REFRI_CONTROLES",pregunta:"En un sistema de desescarche el\xE9ctrico, \xBFqu\xE9 componente act\xFAa como seguridad final si el reloj de tiempo falla y no termina el ciclo?",opciones:["El presostato de alta.","El termostato de terminaci\xF3n de desescarche (Klixon).","El contactor del compresor.","El solenoide de l\xEDquido."],respuesta_correcta:1,explicacion:"El bimetal o termostato de seguridad abre el circuito de las resistencias cuando detecta que el evaporador alcanz\xF3 una temperatura segura (ej. 50\xB0F).",question:"In an electric defrost system, what component acts as the final safety if the timer fails and does not end the defrost cycle?",options:["The high-pressure switch.","The defrost termination thermostat (Klixon).","The compressor contactor.","The liquid line solenoid."],explanation:"The bimetal or safety thermostat opens the heater circuit when it detects the evaporator has reached a safe temperature (e.g., 50 degrees F)."},{id:"refri_626",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 es el 'Hunting' en una v\xE1lvula de expansi\xF3n?",opciones:["Cuando la v\xE1lvula busca fugas de refrigerante.","Cuando la v\xE1lvula abre y cierra constantemente sin estabilizar el sobrecalentamiento.","Cuando el bulbo se congela por fuera.","Es el proceso de ajuste inicial del v\xE1stago."],respuesta_correcta:1,explicacion:"El Hunting ocurre cuando la TXV sobre-reacciona, causando fluctuaciones de presi\xF3n y riesgo de retorno de l\xEDquido.",question:"What is 'Hunting' in an expansion valve?",options:["When the valve searches for refrigerant leaks.","When the valve constantly opens and closes without stabilizing the superheat.","When the sensing bulb freezes externally.","It is the initial stem adjustment process."],explanation:"Hunting occurs when the TXV overreacts, causing pressure fluctuations and risk of liquid return."},{id:"refri_627",categoria:"REFRI_CONTROLES",pregunta:"Un motor de ventilador de condensador monof\xE1sico tiene tres terminales: R, S y C. Si mides resistencia entre R y S y obtienes 15 ohms, entre C y R obtienes 5 ohms, y entre C y S obtienes 10 ohms, \xBFcu\xE1l es el devanado de arranque (Start)?",opciones:["El que mide 5 ohms.","El que mide 10 ohms.","El que mide 15 ohms.","Ninguno, el motor est\xE1 cruzado."],respuesta_correcta:1,explicacion:"En un motor PSC, el devanado de arranque (Start) siempre tiene una resistencia mayor que el de marcha (Run). C-S (10 ohms) > C-R (5 ohms).",question:"A single-phase condenser fan motor has three terminals: R, S, and C. If resistance between R and S is 15 ohms, between C and R is 5 ohms, and between C and S is 10 ohms, which is the Start winding?",options:["The one measuring 5 ohms.","The one measuring 10 ohms.","The one measuring 15 ohms.","None; the motor has a crossed winding."],explanation:"In a PSC motor, the Start winding always has a higher resistance than the Run winding. C-S (10 ohms) is greater than C-R (5 ohms)."},{id:"refri_628",categoria:"REFRI_CONTROLES",pregunta:"En un sistema con desescarche por aire (Off-cycle defrost), \xBFcu\xE1ndo ocurre el deshielo?",opciones:["Cuando se activan las resistencias el\xE9ctricas.","Cada vez que el termostato llega a su setpoint y apaga el compresor, pero deja los ventiladores encendidos.","Solo cuando el t\xE9cnico activa el modo manual.","Mediante la inversi\xF3n de la v\xE1lvula de 4 v\xEDas."],respuesta_correcta:1,explicacion:"El 'Off-cycle defrost' se usa en media temperatura (mantenedores de frescos). El calor del aire del gabinete (arriba de 35\xB0F) derrite el hielo mientras el compresor descansa.",question:"In a system with off-cycle defrost, when does the defrosting occur?",options:["When the electric heaters are activated.","Every time the thermostat reaches its setpoint and shuts off the compressor, but keeps the fans running.","Only when the technician activates manual mode.","By reversing the four-way valve."],explanation:"Off-cycle defrost is used in medium-temperature applications (walk-in coolers). The heat of the cabinet air (above 35 degrees F) melts the ice while the compressor rests."},{id:"refri_629",categoria:"REFRI_CONTROLES",pregunta:"Est\xE1s midiendo un capacitor de marcha (Run Capacitor) marcado como 35 \xB5F. Tu mult\xEDmetro lee 28 \xB5F. \xBFCu\xE1l es el procedimiento correcto?",opciones:["Dejarlo, todav\xEDa est\xE1 dentro del 25% de tolerancia.","Reemplazarlo inmediatamente; la tolerancia est\xE1ndar es +/- 5% a 10%.","Poner otro de 7 \xB5F en serie.","Invertir la polaridad de los cables."],respuesta_correcta:1,explicacion:"Un capacitor con m\xE1s del 10% de p\xE9rdida de capacitancia causar\xE1 sobrecalentamiento en el devanado de arranque y aumentar\xE1 el consumo.",question:"You are measuring a Run Capacitor rated at 35 microfarads. Your multimeter reads 28 microfarads. What is the correct procedure?",options:["Leave it; it is still within the 25% tolerance range.","Replace it immediately; the standard tolerance is plus or minus 5% to 10%.","Add another 7 microfarad capacitor in series.","Reverse the polarity of the leads."],explanation:"A capacitor with more than 10% loss in capacitance will cause overheating in the start winding and increase power consumption."},{id:"refri_630",categoria:"REFRI_CONTROLES",pregunta:"\xBFCu\xE1l es la funci\xF3n de una v\xE1lvula KVP (Reguladora de Presi\xF3n de Evaporaci\xF3n)?",opciones:["Evitar que el compresor se inunde.","Evitar que la temperatura del producto baje demasiado (congelamiento de vegetales).","Aumentar la presi\xF3n de descarga.","Controlar el subenfriamiento."],respuesta_correcta:1,explicacion:"La KVP se cierra si la presi\xF3n del evaporador baja del setpoint, manteniendo una temperatura m\xEDnima de evaporaci\xF3n.",question:"What is the function of a KVP valve (Evaporator Pressure Regulating Valve)?",options:["To prevent the compressor from flooding.","To prevent the product temperature from dropping too low (e.g., freezing vegetables).","To increase the discharge pressure.","To control subcooling."],explanation:"The KVP closes if the evaporator pressure drops below the setpoint, maintaining a minimum evaporating temperature."},{id:"refri_631",categoria:"REFRI_CONTROLES",pregunta:"Configuras un presostato de baja para un equipo de R-404A. Si el Cut-out es 20 PSI y el Diferencial es 15 PSI, \xBFa qu\xE9 presi\xF3n arrancar\xE1 el equipo (Cut-in)?",opciones:["5 PSI","20 PSI","35 PSI","15 PSI"],respuesta_correcta:2,explicacion:"Cut-in = Cut-out + Diferencial. 20 + 15 = 35 PSI.",question:"You set up a low-pressure switch for an R-404A unit. If the Cut-out is 20 PSI and the Differential is 15 PSI, at what pressure will the unit start (Cut-in)?",options:["5 PSI","20 PSI","35 PSI","15 PSI"],explanation:"Cut-in = Cut-out + Differential. 20 + 15 = 35 PSI."},{id:"refri_632",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 funci\xF3n cumple el 'Potencial Relay' en un compresor?",opciones:["Protege contra sobretensiones.","Desconecta el capacitor de arranque bas\xE1ndose en la fuerza electromotriz (Back EMF) generada por el motor.","Cambia el giro del motor.","Mide el amperaje de consumo."],respuesta_correcta:1,explicacion:"El rel\xE9 de potencial detecta cuando el motor alcanza el 75-80% de su velocidad nominal mediante el voltaje generado en el devanado de arranque.",question:"What function does the 'Potential Relay' serve in a compressor?",options:["It protects against power surges.","It disconnects the start capacitor based on the back-EMF (electromotive force) generated by the motor.","It reverses motor rotation.","It measures current draw."],explanation:"The potential relay detects when the motor reaches 75-80% of its rated speed by measuring the voltage generated in the start winding."},{id:"refri_633",categoria:"REFRI_CONTROLES",pregunta:"Mides 120V entre L\xEDnea y Tierra, y 120V entre Neutro y Tierra. \xBFQu\xE9 est\xE1 pasando?",opciones:["La instalaci\xF3n es perfecta.","El Neutro est\xE1 abierto o tiene una falla de tierra seria.","El mult\xEDmetro est\xE1 da\xF1ado.","Es un sistema de 240V sin neutro."],respuesta_correcta:1,explicacion:"Normalmente, entre Neutro y Tierra debe haber cerca de 0V. Una lectura de 120V indica una falla peligrosa o neutro flotante.",question:"You measure 120V between Line and Ground, and 120V between Neutral and Ground. What is happening?",options:["The installation is perfect.","The Neutral is open or there is a serious ground fault.","The multimeter is damaged.","It is a 240V system without a neutral."],explanation:"Normally, between Neutral and Ground there should be close to 0V. A reading of 120V indicates a dangerous fault or a floating neutral."},{id:"refri_634",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 hace una v\xE1lvula de derivaci\xF3n de gas caliente (Hot Gas Bypass Valve)?",opciones:["Aumenta la eficiencia del equipo al 100%.","Mantiene una presi\xF3n de succi\xF3n m\xEDnima inyectando gas caliente al lado de baja durante cargas t\xE9rmicas bajas.","Se usa solo para el deshielo.","Enfr\xEDa el aceite del compresor."],respuesta_correcta:1,explicacion:"Evita que el evaporador se congele y que el compresor cicle excesivamente cuando hay poca demanda de fr\xEDo.",question:"What does a Hot Gas Bypass Valve do?",options:["It increases the system efficiency to 100%.","It maintains a minimum suction pressure by injecting hot gas to the low side during low thermal loads.","It is used only for defrosting.","It cools the compressor oil."],explanation:"It prevents the evaporator from freezing up and stops the compressor from short-cycling when there is low cooling demand."},{id:"refri_635",categoria:"REFRI_CONTROLES",pregunta:"\xBFC\xF3mo se conecta un capacitor de arranque respecto al devanado de Start?",opciones:["En paralelo.","En serie.","Directo a la carcasa.","En serie con el devanado de marcha."],respuesta_correcta:1,explicacion:"Para crear el desfase necesario y aumentar el torque, el capacitor de arranque se coloca en serie con el devanado de Start.",question:"How is a start capacitor connected relative to the Start winding?",options:["In parallel.","In series.","Directly to the housing.","In series with the Run winding."],explanation:"To create the required phase shift and increase starting torque, the start capacitor is placed in series with the Start winding."},{id:"refri_636",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 ocurre si el bulbo de la TXV se instala ANTES de la trampa de aceite en la succi\xF3n?",opciones:["Nada, es la posici\xF3n ideal.","La TXV 'cazar\xE1' (hunting) debido a que el aceite atrapado falsea la temperatura.","La v\xE1lvula se cerrar\xE1 permanentemente.","El sobrecalentamiento ser\xE1 siempre 0."],respuesta_correcta:1,explicacion:"El aceite acumulado tiene una inercia t\xE9rmica distinta, lo que confunde al bulbo y genera inestabilidad.",question:"What happens if the TXV sensing bulb is installed BEFORE the oil trap on the suction line?",options:["Nothing; that is the ideal position.","The TXV will hunt because the trapped oil falsifies the temperature reading.","The valve will close permanently.","The superheat will always be zero."],explanation:"Accumulated oil has a different thermal inertia, which confuses the sensing bulb and generates instability."},{id:"refri_637",categoria:"REFRI_CONTROLES",pregunta:"Un protector t\xE9rmico externo (Klixon) se dispara por:",opciones:["Solo por exceso de corriente (amperaje).","Solo por exceso de temperatura de la carcasa.","Por una combinaci\xF3n de calor y amperaje.","Por bajo voltaje solamente."],respuesta_correcta:2,explicacion:"El disco bimet\xE1lico reacciona tanto al calor del motor como al calor generado por el paso del exceso de corriente a trav\xE9s de \xE9l.",question:"An external thermal protector (Klixon) trips due to:",options:["Excess current (amperage) only.","Excess housing temperature only.","A combination of heat and amperage.","Low voltage only."],explanation:"The bimetallic disc reacts to both the motor heat and the heat generated by excessive current passing through it."},{id:"refri_638",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 es la 'Banda Muerta' en un controlador digital?",opciones:["Cuando el equipo est\xE1 quemado.","El rango de temperatura entre el encendido y el apagado donde no ocurre ninguna acci\xF3n.","La m\xE1xima temperatura permitida.","El tiempo de desescarche."],respuesta_correcta:1,explicacion:"Es el diferencial que evita que el equipo encienda y apague constantemente ante cambios m\xEDnimos de temperatura.",question:"What is the 'Dead Band' in a digital controller?",options:["When the equipment is burned out.","The temperature range between the on and off points where no action occurs.","The maximum allowable temperature.","The defrost duration."],explanation:"It is the differential that prevents the equipment from constantly turning on and off in response to minimal temperature changes."},{id:"refri_639",categoria:"REFRI_CONTROLES",pregunta:"Un motor trif\xE1sico est\xE1 'consumiendo' 10A en la Fase A, 10A en la Fase B y 25A en la Fase C. \xBFQu\xE9 indica?",opciones:["Funcionamiento normal.","Un desequilibrio de carga grave o un devanado con falla parcial de aislamiento.","Que la Fase C es la de arranque.","Que el voltaje es demasiado alto."],respuesta_correcta:1,explicacion:"En sistemas trif\xE1sicos, el amperaje debe estar equilibrado (m\xE1ximo 10% de diferencia).",question:"A three-phase motor is drawing 10A on Phase A, 10A on Phase B, and 25A on Phase C. What does this indicate?",options:["Normal operation.","A severe load imbalance or a winding with partial insulation failure.","That Phase C is the starting phase.","That the voltage is too high."],explanation:"In three-phase systems, amperage should be balanced (maximum 10% difference)."},{id:"refri_640",categoria:"REFRI_CONTROLES",pregunta:"\xBFPor qu\xE9 las TXV modernas suelen ser de 'Puerto Equilibrado' (Balanced Port)?",opciones:["Para que sean m\xE1s baratas.","Para que la presi\xF3n de descarga no afecte la operaci\xF3n de la v\xE1lvula en climas fr\xEDos.","Para que el refrigerante no haga ruido.","Para eliminar la necesidad de bulbo."],respuesta_correcta:1,explicacion:"Permiten un control preciso incluso cuando la presi\xF3n de condensaci\xF3n cae (invierno), evitando que la v\xE1lvula se cierre por falta de presi\xF3n diferencial.",question:"Why do modern TXVs often feature a 'Balanced Port' design?",options:["To make them cheaper.","So that discharge pressure does not affect the valve's operation in cold climates.","To prevent the refrigerant from making noise.","To eliminate the need for a sensing bulb."],explanation:"They allow precise control even when condensing pressure drops in winter, preventing the valve from closing due to insufficient pressure differential."},{id:"refri_641",categoria:"REFRI_CONTROLES",pregunta:"En un sistema trif\xE1sico, si una de las fases se abre mientras el motor est\xE1 funcionando (Single Phasing), \xBFqu\xE9 sucede con el amperaje en las otras dos fases?",opciones:["El amperaje baja a la mitad.","El amperaje sube dr\xE1sticamente (aprox. 1.73 veces) en las fases activas.","El amperaje se mantiene igual.","El motor gira m\xE1s r\xE1pido."],respuesta_correcta:1,explicacion:"Al perder una fase, las otras dos deben compensar el torque necesario, lo que dispara la corriente y quemar\xE1 el motor si no hay una protecci\xF3n t\xE9rmica adecuada.",question:"In a three-phase system, if one phase opens while the motor is running (Single Phasing), what happens to the amperage on the other two phases?",options:["The amperage drops by half.","The amperage rises drastically (approximately 1.73 times) on the remaining active phases.","The amperage stays the same.","The motor spins faster."],explanation:"Upon losing one phase, the other two must compensate for the needed torque, causing a current spike that will burn the motor if there is no adequate thermal protection."},{id:"refri_642",categoria:"REFRI_CONTROLES",pregunta:"Si una v\xE1lvula solenoide en la l\xEDnea de l\xEDquido 'vibra' o hace un ruido fuerte (chatter), \xBFcu\xE1l es la causa m\xE1s probable?",opciones:["Baja presi\xF3n de succi\xF3n.","Bajo voltaje en la bobina o suciedad en el v\xE1stago interno.","Exceso de subenfriamiento.","El refrigerante est\xE1 en estado gaseoso."],respuesta_correcta:1,explicacion:"El bajo voltaje impide que el campo magn\xE9tico mantenga el \xE9mbolo firme contra el resorte, causando la vibraci\xF3n mec\xE1nica.",question:"If a liquid line solenoid valve 'vibrates' or makes a loud noise (chatter), what is the most likely cause?",options:["Low suction pressure.","Low voltage at the coil or dirt on the internal plunger.","Excessive subcooling.","The refrigerant is in a gaseous state."],explanation:"Low voltage prevents the magnetic field from firmly holding the plunger against the spring, causing the mechanical vibration."},{id:"refri_643",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 sucede si instalas un capacitor de arranque con un voltaje nominal menor al del sistema (ej. capacitor de 125V en sistema de 240V)?",opciones:["El motor arranca m\xE1s r\xE1pido.","El capacitor estallar\xE1 o fallar\xE1 casi instant\xE1neamente por ruptura del diel\xE9ctrico.","No pasa nada, el voltaje no importa en los capacitores.","El motor consumir\xE1 menos energ\xEDa."],respuesta_correcta:1,explicacion:"El voltaje nominal del capacitor debe ser siempre igual o mayor al voltaje pico que encontrar\xE1 en el circuito.",question:"What happens if you install a start capacitor with a voltage rating lower than the system voltage (e.g., a 125V capacitor in a 240V system)?",options:["The motor starts faster.","The capacitor will burst or fail almost instantly due to dielectric breakdown.","Nothing happens; voltage does not matter in capacitors.","The motor will consume less energy."],explanation:"The capacitor voltage rating must always be equal to or greater than the peak voltage it will encounter in the circuit."},{id:"refri_644",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 mide un transductor de presi\xF3n comparado con un presostato mec\xE1nico?",opciones:["Lo mismo, pero el transductor es de metal.","El transductor env\xEDa una se\xF1al anal\xF3gica (V o mA) proporcional a la presi\xF3n para monitoreo continuo.","El transductor solo sirve para emergencias.","El presostato es m\xE1s preciso."],respuesta_correcta:1,explicacion:"El presostato es un interruptor (ON/OFF). El transductor permite al controlador saber la presi\xF3n exacta en todo momento (ej. 54.3 PSI).",question:"What does a pressure transducer measure compared to a mechanical pressure switch?",options:["The same thing, but the transducer is made of metal.","The transducer sends an analog signal (voltage or milliamps) proportional to the pressure for continuous monitoring.","The transducer is only for emergencies.","The pressure switch is more precise."],explanation:"A pressure switch is a simple on/off switch. A transducer allows the controller to know the exact pressure at all times (e.g., 54.3 PSI)."},{id:"refri_645",categoria:"REFRI_CONTROLES",pregunta:"Mides un compresor y encuentras continuidad entre el terminal 'S' y la tuber\xEDa de cobre. \xBFQu\xE9 significa?",opciones:["El motor tiene un buen aterrizaje de seguridad.","El devanado de arranque est\xE1 'aterrizado' (short to ground) y el compresor debe reemplazarse.","Es normal en compresores de alta eficiencia.","Falta conectar el capacitor."],respuesta_correcta:1,explicacion:"Nunca debe haber continuidad entre los terminales el\xE9ctricos y la carcasa met\xE1lica/tuber\xEDa.",question:"You measure a compressor and find continuity between the 'S' terminal and the copper tubing. What does this mean?",options:["The motor has a good safety ground.","The start winding is grounded (short to ground) and the compressor must be replaced.","This is normal in high-efficiency compressors.","The capacitor needs to be connected."],explanation:"There must never be continuity between the electrical terminals and the metal housing or tubing."},{id:"refri_646",categoria:"REFRI_CONTROLES",pregunta:"Un controlador digital de temperatura muestra la alarma 'E1'. Seg\xFAn la mayor\xEDa de fabricantes (Carel, Dixell), \xBFqu\xE9 indica?",opciones:["Error de voltaje.","Falla en la sonda de temperatura del gabinete (abierta o en corto).","Puerta abierta.","Compresor quemado."],respuesta_correcta:1,explicacion:"E1 suele referirse a la sonda principal. Sin esta lectura, el controlador no puede saber cu\xE1ndo encender el equipo.",question:"A digital temperature controller displays the alarm 'E1'. According to most manufacturers (Carel, Dixell), what does this indicate?",options:["A voltage error.","A cabinet temperature probe failure (open or shorted).","Door open.","Burned compressor."],explanation:"E1 usually refers to the main probe. Without this reading, the controller cannot know when to turn the equipment on."},{id:"refri_647",categoria:"REFRI_CONTROLES",pregunta:"Al usar un mult\xEDmetro en la escala de Ohms, \xBFqu\xE9 significa la lectura 'O.L'?",opciones:["Only Low (Resistencia baja).","Open Loop (Circuito abierto o resistencia mayor al rango del mult\xEDmetro).","Over Load (Exceso de corriente).","Operaci\xF3n Local."],respuesta_correcta:1,explicacion:"Indica que no hay continuidad entre las puntas de prueba.",question:"When using a multimeter on the Ohms scale, what does the reading 'O.L' mean?",options:["Only Low (Low resistance).","Open Loop (Open circuit or resistance exceeding the meter range).","Over Load (Excess current).","Local Operation."],explanation:"It indicates there is no continuity between the test leads."},{id:"refri_648",categoria:"REFRI_CONTROLES",pregunta:"\xBFPor qu\xE9 las v\xE1lvulas de expansi\xF3n electr\xF3nica (EEV) son superiores a las TXV mec\xE1nicas?",opciones:["Son m\xE1s baratas.","Permiten un control de sobrecalentamiento mucho m\xE1s preciso en un rango amplio de cargas t\xE9rmicas.","No requieren sensores.","Funcionan sin electricidad."],respuesta_correcta:1,explicacion:"Las EEV pueden ajustar el flujo bas\xE1ndose en algoritmos PID, manteniendo el superheat \xF3ptimo incluso con presiones de descarga bajas.",question:"Why are Electronic Expansion Valves (EEV) superior to mechanical TXVs?",options:["They are cheaper.","They allow much more precise superheat control over a wide range of thermal loads.","They do not require sensors.","They operate without electricity."],explanation:"EEVs can adjust flow based on PID algorithms, maintaining optimal superheat even at low discharge pressures."},{id:"refri_649",categoria:"REFRI_CONTROLES",pregunta:"Si un contactor de compresor tiene los contactos 'picados' o carbonizados, \xBFqu\xE9 efecto tiene sobre el motor?",opciones:["Ninguno, el contactor solo cierra el circuito.","Causa una ca\xEDda de voltaje y posible sobrecalentamiento de los devanados del motor.","Aumenta la velocidad del compresor.","Reduce el ruido el\xE9ctrico."],respuesta_correcta:1,explicacion:"La carbonizaci\xF3n aumenta la resistencia el\xE9ctrica. Seg\xFAn la ley de Ohm, esto provoca una ca\xEDda de tensi\xF3n ($V = I 	imes R$) que llega al motor.",question:"If a compressor contactor has pitted or carbonized contacts, what effect does this have on the motor?",options:["None; the contactor only closes the circuit.","It causes a voltage drop and possible overheating of the motor windings.","It increases compressor speed.","It reduces electrical noise."],explanation:"Carbonization increases electrical resistance. According to Ohm's law, this causes a voltage drop (V = I x R) at the motor."},{id:"refri_650",categoria:"REFRI_CONTROLES",pregunta:"\xBFCu\xE1l es el ajuste t\xEDpico de un presostato de seguridad de alta presi\xF3n para R-410A?",opciones:["250 PSI","450-550 PSI","150 PSI","800 PSI"],respuesta_correcta:1,explicacion:"El R-410A opera a presiones mucho m\xE1s altas; su punto cr\xEDtico requiere cortes de seguridad cercanos a los 550 PSI para proteger la integridad de las tuber\xEDas.",question:"What is the typical setting for a high-pressure safety switch for R-410A?",options:["250 PSI","450-550 PSI","150 PSI","800 PSI"],explanation:"R-410A operates at much higher pressures; its critical point requires safety cutouts near 550 PSI to protect the piping integrity."},{id:"refri_651",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 mide un meg\xF3hmetro (Megger) que un mult\xEDmetro est\xE1ndar no puede medir con precisi\xF3n?",opciones:["El amperaje de arranque.","La resistencia del aislamiento de los devanados del motor bajo alta tensi\xF3n.","La capacitancia de los capacitores de marcha.","La frecuencia de la red el\xE9ctrica."],respuesta_correcta:1,explicacion:"El Megger aplica un voltaje alto (500V-1000V) para detectar fallas de aislamiento incipientes que un mult\xEDmetro de 9V no ver\xEDa.",question:"What does a megohmmeter (Megger) measure that a standard multimeter cannot measure accurately?",options:["The starting amperage.","The insulation resistance of the motor windings under high voltage.","The capacitance of run capacitors.","The frequency of the power supply."],explanation:"A Megger applies high voltage (500V-1000V) to detect incipient insulation failures that a 9V multimeter would not reveal."},{id:"refri_652",categoria:"REFRI_CONTROLES",pregunta:"\xBFPara qu\xE9 sirve el 'ajuste de superheat' en una TXV?",opciones:["Para cambiar la temperatura del gabinete.","Para asegurar que el evaporador se use al m\xE1ximo sin que regrese l\xEDquido al compresor.","Para aumentar la presi\xF3n de descarga.","Para ahorrar gas."],respuesta_correcta:1,explicacion:"El ajuste de f\xE1brica busca el equilibrio entre eficiencia del evaporador y protecci\xF3n del compresor.",question:"What is the purpose of the 'superheat adjustment' on a TXV?",options:["To change the cabinet temperature.","To ensure the evaporator is used to its fullest without liquid returning to the compressor.","To increase the discharge pressure.","To conserve gas."],explanation:"The factory setting seeks the balance between evaporator efficiency and compressor protection."},{id:"refri_653",categoria:"REFRI_CONTROLES",pregunta:"En un diagrama el\xE9ctrico de refrigeraci\xF3n, \xBFqu\xE9 representa el s\xEDmbolo de un c\xEDrculo con una 'M' dentro y tres l\xEDneas de entrada?",opciones:["Un ventilador monof\xE1sico.","Un motor trif\xE1sico.","Un medidor de energ\xEDa.","Un solenoide."],respuesta_correcta:1,explicacion:"Es la representaci\xF3n est\xE1ndar de un motor alimentado por tres fases (L1, L2, L3).",question:"In a refrigeration electrical diagram, what does the symbol of a circle with an 'M' inside and three input lines represent?",options:["A single-phase fan.","A three-phase motor.","An energy meter.","A solenoid."],explanation:"It is the standard representation of a motor powered by three phases (L1, L2, L3)."},{id:"refri_654",categoria:"REFRI_CONTROLES",pregunta:"\xBFQu\xE9 funci\xF3n tiene el 'Crankcase Heater' (Calentador de C\xE1rter)?",opciones:["Ayudar al compresor a arrancar en caliente.","Mantener el aceite a una temperatura mayor que la del resto del sistema para evitar la migraci\xF3n de refrigerante l\xEDquido al c\xE1rter durante paradas.","Calentar el aire de la sala.","Reducir el consumo el\xE9ctrico."],respuesta_correcta:1,explicacion:"Si el aceite est\xE1 fr\xEDo, el refrigerante se condensa en \xE9l (migraci\xF3n). Al arrancar, esto causa espuma y falta de lubricaci\xF3n.",question:"What is the function of the 'Crankcase Heater'?",options:["To help the compressor start up warm.","To keep the oil at a temperature higher than the rest of the system to prevent liquid refrigerant from migrating to the crankcase during shutdowns.","To heat the room air.","To reduce electrical consumption."],explanation:"If the oil is cold, refrigerant condenses in it (migration). Upon startup, this causes foaming and lack of lubrication."},{id:"refri_655",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un cliente reporta que su Walk-in Cooler no baja de 45\xB0F. Encuentras escarcha pesada en el \xFAltimo tercio del evaporador \xFAnicamente. El sobrecalentamiento en el compresor es de 40\xB0F. \xBFQu\xE9 sucede?",opciones:["Filtro de aire sucio.","Baja carga de refrigerante.","TXV demasiado abierta.","Humedad en el sistema bloqueando parcialmente la TXV."],respuesta_correcta:1,explicacion:"La escarcha parcial al final del evaporador y un sobrecalentamiento muy alto (40\xB0F) en el compresor son signos cl\xE1sicos de falta de refrigerante ( starving evaporator).",question:"A customer reports that their Walk-in Cooler will not drop below 45 degrees F. You find heavy frost on only the last third of the evaporator. The superheat at the compressor is 40 degrees F. What is happening?",options:["Dirty air filter.","Low refrigerant charge.","TXV too far open.","Moisture in the system partially blocking the TXV."],explanation:"Partial frost at the end of the evaporator and very high superheat (40 degrees F) at the compressor are classic signs of a low refrigerant charge (starving evaporator)."},{id:"refri_656",categoria:"REFRI_DIAGNOSTICO",pregunta:"En un sistema de baja temperatura, \xBFqu\xE9 propiedad del aceite es cr\xEDtica para evitar que se quede atrapado en el evaporador?",opciones:["Punto de inflamaci\xF3n.","Punto de fluidez (Pour Point).","Viscosidad ISO.","Rigidez diel\xE9ctrica."],respuesta_correcta:1,explicacion:"El Pour Point es la temperatura m\xE1s baja a la cual el aceite a\xFAn puede fluir. Si es muy alta, el aceite se vuelve 'cera' en el evaporador de baja temperatura.",question:"In a low-temperature system, what oil property is critical to prevent it from becoming trapped in the evaporator?",options:["Flash point.","Pour Point.","ISO viscosity.","Dielectric strength."],explanation:"The Pour Point is the lowest temperature at which the oil can still flow. If it is too high, the oil turns to wax in the low-temperature evaporator."},{id:"refri_657",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un compresor semi-herm\xE9tico tiene escarcha en el c\xE1rter. \xBFEs esto normal en un sistema de baja temperatura?",opciones:["S\xED, siempre que el sobrecalentamiento sea de 20\xB0F.","No, indica que el refrigerante l\xEDquido est\xE1 hirviendo en el aceite del c\xE1rter.","S\xED, es se\xF1al de que el separador de aceite funciona bien.","Solo si el sistema es de amon\xEDaco."],respuesta_correcta:1,explicacion:"La escarcha en el c\xE1rter indica retorno de l\xEDquido, lo cual diluye el aceite y destruye los cojinetes por falta de lubricaci\xF3n.",question:"A semi-hermetic compressor has frost on the crankcase. Is this normal in a low-temperature system?",options:["Yes, as long as the superheat is 20 degrees F.","No, it indicates liquid refrigerant is boiling in the crankcase oil.","Yes, it is a sign that the oil separator is working properly.","Only if the system uses ammonia."],explanation:"Frost on the crankcase indicates liquid return, which dilutes the oil and destroys the bearings due to lack of lubrication."},{id:"refri_658",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFPara qu\xE9 sirve el 'Oil Differential Pressure Switch'?",opciones:["Para medir la presi\xF3n de descarga del compresor.","Para asegurar que la bomba de aceite entrega una presi\xF3n superior a la del c\xE1rter.","Para igualar el aceite entre dos compresores.","Para filtrar las part\xEDculas de carb\xF3n."],respuesta_correcta:1,explicacion:"Mide la diferencia entre la salida de la bomba y la presi\xF3n interna del c\xE1rter para garantizar flujo de lubricaci\xF3n.",question:"What is the purpose of the 'Oil Differential Pressure Switch'?",options:["To measure the compressor discharge pressure.","To ensure the oil pump delivers a pressure higher than the crankcase pressure.","To equalize oil between two compressors.","To filter carbon particles."],explanation:"It measures the difference between the pump outlet and the internal crankcase pressure to guarantee lubrication flow."},{id:"refri_659",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un sistema tiene aire. \xBFEn qu\xE9 parte del sistema se acumular\xE1 principalmente este gas no condensable durante el funcionamiento?",opciones:["En la parte inferior del evaporador.","En el c\xE1rter del compresor.","En la parte superior del condensador y receptor.","En la trampa de aceite."],respuesta_correcta:2,explicacion:"El aire no se condensa; por lo tanto, se queda atrapado en el \xE1rea de alta presi\xF3n donde el refrigerante intenta hacerse l\xEDquido (condensador/receptor).",question:"A system has air in it. Where will this non-condensable gas primarily accumulate during operation?",options:["At the bottom of the evaporator.","In the compressor crankcase.","At the top of the condenser and receiver.","In the oil trap."],explanation:"Air does not condense; therefore, it gets trapped in the high-pressure area where the refrigerant is trying to turn into liquid (condenser/receiver)."},{id:"refri_660",categoria:"REFRI_DIAGNOSTICO",pregunta:"Si el aire que entra a un evaporador tiene una temperatura de bulbo h\xFAmedo igual a la temperatura de bulbo seco, \xBFcu\xE1l es la humedad relativa?",opciones:["0%","50%","100%","No se puede determinar sin la presi\xF3n atmosf\xE9rica."],respuesta_correcta:2,explicacion:"Cuando el bulbo seco y el h\xFAmedo coinciden, el aire est\xE1 saturado, lo que equivale al 100% de HR.",question:"If the air entering an evaporator has a wet-bulb temperature equal to its dry-bulb temperature, what is the relative humidity?",options:["0%","50%","100%","It cannot be determined without atmospheric pressure."],explanation:"When the dry-bulb and wet-bulb temperatures coincide, the air is fully saturated, which equals 100% relative humidity."},{id:"refri_661",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un sistema de refrigeraci\xF3n comercial usa una v\xE1lvula solenoide en la l\xEDnea de l\xEDquido para el ciclo de 'Pump Down'. Si la solenoide se quema en posici\xF3n cerrada, \xBFqu\xE9 har\xE1 el compresor?",opciones:["Seguir\xE1 trabajando hasta quemarse.","Se detendr\xE1 por el control de baja presi\xF3n.","Explotar\xE1 por alta presi\xF3n de succi\xF3n.","Ciclar\xE1 por el protector t\xE9rmico interno."],respuesta_correcta:1,explicacion:"Al cerrarse la solenoide, el compresor succiona el refrigerante restante del evaporador hasta que el presostato de baja corta el circuito.",question:"A commercial refrigeration system uses a liquid line solenoid valve for the 'Pump Down' cycle. If the solenoid burns out in the closed position, what will the compressor do?",options:["It will keep running until it burns out.","It will stop on the low-pressure control.","It will explode from high suction pressure.","It will cycle on the internal thermal protector."],explanation:"With the solenoid closed, the compressor evacuates the remaining refrigerant from the evaporator until the low-pressure switch cuts the circuit."},{id:"refri_662",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFPor qu\xE9 nunca se debe usar ox\xEDgeno para presurizar un sistema de refrigeraci\xF3n para buscar fugas?",opciones:["Porque el ox\xEDgeno es muy caro.","Porque el ox\xEDgeno reacciona violentamente con el aceite (combusti\xF3n espont\xE1nea).","Porque el ox\xEDgeno no se puede detectar con jab\xF3n.","Porque el ox\xEDgeno humedece el filtro deshidratador."],respuesta_correcta:1,explicacion:"El ox\xEDgeno bajo presi\xF3n en contacto con aceite mineral o POE provoca una explosi\xF3n por oxidaci\xF3n r\xE1pida.",question:"Why should you never use oxygen to pressurize a refrigeration system for leak testing?",options:["Because oxygen is very expensive.","Because oxygen reacts violently with the oil (spontaneous combustion).","Because oxygen cannot be detected with soap bubbles.","Because oxygen moistens the filter drier."],explanation:"Oxygen under pressure in contact with mineral or POE oil causes an explosion through rapid oxidation."},{id:"refri_663",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFQu\xE9 significa que un refrigerante sea 'Azeotr\xF3pico'?",opciones:["Que tiene un deslizamiento t\xE9rmico (glide) muy alto.","Que se comporta como un refrigerante puro, hirviendo y condensando a una temperatura constante para una presi\xF3n dada.","Que solo se puede cargar en estado gaseoso.","Que contiene cloro en su mol\xE9cula."],respuesta_correcta:1,explicacion:"Los aze\xF3tropos (como el R-502) no se fraccionan y mantienen su composici\xF3n en los cambios de fase.",question:"What does it mean for a refrigerant to be 'Azeotropic'?",options:["That it has a very high temperature glide.","That it behaves like a pure refrigerant, boiling and condensing at a constant temperature for a given pressure.","That it can only be charged in a gaseous state.","That it contains chlorine in its molecule."],explanation:"Azeotropes (such as R-502) do not fractionate and maintain their composition during phase changes."},{id:"refri_664",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un compresor quema su terminal 'C' (Com\xFAn). El t\xE9cnico encuentra que el cable estaba flojo. \xBFQu\xE9 fen\xF3meno caus\xF3 la falla?",opciones:["Efecto Joule (Resistencia de contacto alta creando calor excesivo).","Inductancia par\xE1sita.","Cortocircuito a tierra.","Baja tensi\xF3n de l\xEDnea."],respuesta_correcta:0,explicacion:"Una conexi\xF3n floja crea una resistencia alta. Al pasar corriente, se genera calor ($P = I^2 	imes R$), lo que termina fundiendo el terminal.",question:"A compressor burns its 'C' (Common) terminal. The technician finds the wire was loose. What phenomenon caused the failure?",options:["Joule effect (high contact resistance creating excessive heat).","Parasitic inductance.","Short circuit to ground.","Low line voltage."],explanation:"A loose connection creates high resistance. When current passes through it, heat is generated (P = I squared x R), which eventually melts the terminal."},{id:"refri_665",categoria:"REFRI_DIAGNOSTICO",pregunta:"Si tienes una fuga de 2 lbs de refrigerante en un sistema que contiene 100 lbs de carga, \xBFcu\xE1l es la tasa de fuga anual si ocurri\xF3 en 1 mes?",opciones:["2%","12%","24%","50%"],respuesta_correcta:2,explicacion:"2 lbs/mes $	imes$ 12 meses = 24 lbs al a\xF1o. 24 lbs de 100 lbs totales = 24% anual.",question:"If you have a 2 lb refrigerant leak in a system containing 100 lbs of charge, what is the annual leak rate if the leak occurred over 1 month?",options:["2%","12%","24%","50%"],explanation:"2 lbs per month times 12 months = 24 lbs per year. 24 lbs out of 100 lbs total = 24% annual leak rate."},{id:"refri_666",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFPor qu\xE9 se instalan trampas de aceite (P-traps) en las l\xEDneas de succi\xF3n verticales?",opciones:["Para evitar que el l\xEDquido baje al evaporador.","Para facilitar el retorno de aceite al compresor en tramos ascendentes.","Para aumentar la presi\xF3n de succi\xF3n.","Para reducir las vibraciones del compresor."],respuesta_correcta:1,explicacion:"La trampa permite que el aceite se acumule hasta que la velocidad del gas sea suficiente para 'empujarlo' hacia arriba.",question:"Why are oil traps (P-traps) installed on vertical suction lines?",options:["To prevent liquid from flowing down to the evaporator.","To facilitate oil return to the compressor on ascending runs.","To increase suction pressure.","To reduce compressor vibration."],explanation:"The trap allows oil to accumulate until the gas velocity is sufficient to push it upward."},{id:"refri_667",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1l es el valor GWP (Global Warming Potential) del refrigerante R-290 (Propano)?",opciones:["Alrededor de 3","Cerca de 1430","Exactamente 0","Superior a 2000"],respuesta_correcta:0,explicacion:"Los hidrocarburos como el R-290 tienen un impacto ambiental baj\xEDsimo comparado con los HFC.",question:"What is the GWP (Global Warming Potential) value of refrigerant R-290 (Propane)?",options:["Approximately 3.","Around 1430.","Exactly 0.","Greater than 2000."],explanation:"Hydrocarbons like R-290 have an extremely low environmental impact compared to HFCs."},{id:"refri_668",categoria:"REFRI_DIAGNOSTICO",pregunta:"Encuentras una unidad de condensaci\xF3n con el ventilador girando al rev\xE9s. \xBFQu\xE9 efecto tiene esto en el Subcooling?",opciones:["El subcooling sube dr\xE1sticamente.","El subcooling baja o desaparece.","El subcooling no cambia, solo sube la presi\xF3n.","Mejora la eficiencia."],respuesta_correcta:1,explicacion:"Al no haber flujo de aire correcto, el refrigerante no condensa bien; la temperatura del l\xEDquido sale muy alta y cercana a la de saturaci\xF3n.",question:"You find a condensing unit with the fan spinning in reverse. What effect does this have on subcooling?",options:["Subcooling increases drastically.","Subcooling drops or disappears.","Subcooling does not change; only the pressure rises.","It improves efficiency."],explanation:"Without proper airflow, the refrigerant does not condense well; the liquid exits at a very high temperature, close to the saturation temperature."},{id:"refri_669",categoria:"REFRI_DIAGNOSTICO",pregunta:"Al usar una bomba de vac\xEDo, el aceite se vuelve 'lechoso'. \xBFQu\xE9 significa?",opciones:["El aceite es de buena calidad.","El aceite se ha contaminado con humedad.","La bomba est\xE1 demasiado caliente.","Es normal durante los primeros 5 minutos."],respuesta_correcta:1,explicacion:"La apariencia lechosa es el resultado de la emulsi\xF3n del agua con el aceite de la bomba. Debe cambiarse inmediatamente.",question:"When using a vacuum pump, the oil turns milky. What does this mean?",options:["The oil is of good quality.","The oil has been contaminated with moisture.","The pump is running too hot.","It is normal during the first 5 minutes."],explanation:"The milky appearance results from the emulsification of water with the pump oil. The oil must be changed immediately."},{id:"refri_670",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1l es el prop\xF3sito del 'Puntero' o 'Sling' en la l\xEDnea de descarga de un compresor?",opciones:["Reducir el ruido.","Evitar que el aceite regrese a la culata del compresor durante paradas.","Aumentar la presi\xF3n de aceite.","Filtrar el refrigerante."],respuesta_correcta:1,explicacion:"El dise\xF1o de la tuber\xEDa de descarga debe evitar que el aceite condensado fluya por gravedad hacia las v\xE1lvulas del compresor al apagarse.",question:"What is the purpose of the 'Loop' or 'Trap' in the discharge line of a compressor?",options:["To reduce noise.","To prevent oil from flowing back to the compressor head during shutdowns.","To increase oil pressure.","To filter the refrigerant."],explanation:"The discharge piping design must prevent condensed oil from flowing by gravity back to the compressor valves when it shuts off."},{id:"refri_671",categoria:"REFRI_DIAGNOSTICO",pregunta:"El visor de l\xEDquido est\xE1 lleno de burbujas, pero las presiones de alta y baja son normales y el equipo enfr\xEDa bien. \xBFQu\xE9 sospechas?",opciones:["Fuga masiva de gas.","Obstrucci\xF3n en el filtro deshidratador (ca\xEDda de presi\xF3n).","Compresor sin compresi\xF3n.","Demasiado aceite en el sistema."],respuesta_correcta:1,explicacion:"Una peque\xF1a ca\xEDda de presi\xF3n en el filtro hace que el l\xEDquido saturado se convierta parcialmente en vapor (flash gas), creando burbujas aunque la carga sea correcta.",question:"The liquid sight glass is full of bubbles, but the high-side and low-side pressures are normal and the unit is cooling well. What do you suspect?",options:["A massive refrigerant leak.","A restriction in the filter drier (pressure drop).","A compressor with no compression.","Too much oil in the system."],explanation:"A small pressure drop across the filter drier causes the saturated liquid to partially convert into vapor (flash gas), creating bubbles even though the charge is correct."},{id:"refri_672",categoria:"REFRI_DIAGNOSTICO",pregunta:"El refrigerante R-410A es una mezcla de:",opciones:["R-22 y R-12","R-32 y R-125","R-134a y R-32","R-290 y R-600a"],respuesta_correcta:1,explicacion:"Es una mezcla casi azeotr\xF3pica (50/50) de difluorometano y pentafluoroetano.",question:"Refrigerant R-410A is a blend of:",options:["R-22 and R-12.","R-32 and R-125.","R-134a and R-32.","R-290 and R-600a."],explanation:"It is a near-azeotropic blend (50/50) of difluoromethane and pentafluoroethane."},{id:"refri_673",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFA cu\xE1ntos micrones equivale 1 pulgada de mercurio (Hg)?",opciones:["1,000","25,400","500","100"],respuesta_correcta:1,explicacion:"1 pulgada = 25.4 mm. 1 mm de Hg = 1,000 micrones. Por tanto, 1 pulgada = 25,400 micrones.",question:"How many microns are in 1 inch of mercury (Hg)?",options:["1,000","25,400","500","100"],explanation:"1 inch = 25.4 mm. 1 mm of Hg = 1,000 microns. Therefore, 1 inch = 25,400 microns."},{id:"refri_674",categoria:"REFRI_DIAGNOSTICO",pregunta:"En un sistema con R-22, la presi\xF3n de succi\xF3n es 60 PSI y la temperatura de la tuber\xEDa de succi\xF3n es 55\xB0F. \xBFCu\xE1l es el superheat? (Dato: R-22 a 60 PSI = 34\xB0F)",opciones:["5\xB0F","21\xB0F","55\xB0F","115\xB0F"],respuesta_correcta:1,explicacion:"Superheat = Temp. Tubo - Temp. Saturaci\xF3n. 55\xB0F - 34\xB0F = 21\xB0F.",question:"In a system with R-22, the suction pressure is 60 PSI and the suction line temperature is 55 degrees F. What is the superheat? (Given: R-22 at 60 PSI = 34 degrees F)",options:["5 degrees F","21 degrees F","55 degrees F","115 degrees F"],explanation:"Superheat = Line Temperature minus Saturation Temperature. 55 degrees F minus 34 degrees F = 21 degrees F."},{id:"refri_675",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1l es la funci\xF3n de un 'Vibrasorber' (eliminador de vibraci\xF3n)?",opciones:["Soportar el peso del compresor.","Evitar que las vibraciones del compresor se transmitan a la tuber\xEDa y causen fugas por fatiga.","Reducir el consumo de corriente.","Enfriar el gas de descarga."],respuesta_correcta:1,explicacion:"Se instalan paralelos al cig\xFCe\xF1al del compresor para absorber el movimiento mec\xE1nico.",question:"What is the purpose of a 'Vibration Eliminator' (Vibrasorber)?",options:["To support the weight of the compressor.","To prevent compressor vibrations from being transmitted to the piping and causing fatigue-related leaks.","To reduce current consumption.","To cool the discharge gas."],explanation:"They are installed parallel to the compressor crankshaft to absorb the mechanical movement."},{id:"refri_676",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1ntos BTU/h hay en 1 Tonelada de Refrigeraci\xF3n?",opciones:["10,000","12,000","14,000","288,000"],respuesta_correcta:1,explicacion:"1 TR es la capacidad de extraer el calor necesario para fundir 2000 lbs de hielo en 24h, lo que equivale a 12,000 BTU/h.",question:"How many BTU/h are in 1 Ton of Refrigeration?",options:["10,000","12,000","14,000","288,000"],explanation:"1 Ton of Refrigeration is the capacity to extract the heat needed to melt 2,000 lbs of ice in 24 hours, which equals 12,000 BTU/h."},{id:"refri_677",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFPor qu\xE9 el refrigerante R-123 requiere detectores de fuga y ventilaci\xF3n especial en salas de m\xE1quinas?",opciones:["Porque es extremadamente inflamable.","Porque tiene un nivel de toxicidad B1 seg\xFAn ASHRAE.","Porque huele muy mal.","Porque da\xF1a el cobre."],respuesta_correcta:1,explicacion:"El R-123 es un refrigerante de baja presi\xF3n usado en Chillers, clasificado como t\xF3xico en exposiciones prolongadas.",question:"Why does refrigerant R-123 require leak detectors and special ventilation in machine rooms?",options:["Because it is extremely flammable.","Because it has a B1 toxicity rating according to ASHRAE.","Because it smells very bad.","Because it damages copper."],explanation:"R-123 is a low-pressure refrigerant used in Chillers, classified as toxic under prolonged exposure."},{id:"refri_678",categoria:"REFRI_DIAGNOSTICO",pregunta:"Al recuperar refrigerante, \xBFcu\xE1l es el peso m\xE1ximo permitido en un cilindro de recuperaci\xF3n?",opciones:["100% de su capacidad.","80% de su capacidad de agua por seguridad.","50% para que no pese tanto.","80% de la capacidad de gas."],respuesta_correcta:1,explicacion:"La regla del 80% previene explosiones por expansi\xF3n hidrost\xE1tica del l\xEDquido ante cambios de temperatura.",question:"When recovering refrigerant, what is the maximum allowable weight in a recovery cylinder?",options:["100% of its capacity.","80% of its water capacity for safety.","50% so it is not too heavy.","80% of its gas capacity."],explanation:"The 80% rule prevents explosions from hydrostatic expansion of liquid due to temperature changes."},{id:"refri_679",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un compresor arranca pero se apaga por alta presi\xF3n de descarga. El condensador est\xE1 limpio y el ventilador funciona. \xBFQu\xE9 puede ser?",opciones:["Filtro de succi\xF3n tapado.","Incondensables (aire) o exceso de carga.","Termostato da\xF1ado.","Baja carga de gas."],respuesta_correcta:1,explicacion:"El aire se acumula en el condensador y ocupa espacio que deber\xEDa ser para el refrigerante, disparando la presi\xF3n.",question:"A compressor starts but trips on high discharge pressure. The condenser is clean and the fan is working. What could be the cause?",options:["A clogged suction filter.","Non-condensables (air) or overcharge.","A damaged thermostat.","Low refrigerant charge."],explanation:"Air accumulates in the condenser and occupies space that should be used by the refrigerant, causing the pressure to spike."},{id:"refri_680",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un compresor semi-herm\xE9tico tiene una temperatura de descarga de 240\xB0F. \xBFCu\xE1l es el riesgo inmediato para el sistema?",opciones:["No hay riesgo, es una temperatura normal de operaci\xF3n.","Falla en la lubricaci\xF3n debido a que el aceite se polimeriza y pierde viscosidad.","Que el refrigerante se congele en la l\xEDnea de descarga.","Que el motor consuma menos amperaje."],respuesta_correcta:1,explicacion:"Por encima de los 225\xB0F-250\xB0F, el aceite de refrigeraci\xF3n comienza a degradarse qu\xEDmicamente, perdiendo su capacidad de lubricar y da\xF1ando los platos de v\xE1lvulas.",question:"A semi-hermetic compressor has a discharge temperature of 240 degrees F. What is the immediate risk to the system?",options:["No risk; this is a normal operating temperature.","Lubrication failure because the oil polymerizes and loses viscosity.","The refrigerant will freeze in the discharge line.","The motor will draw less amperage."],explanation:"Above 225-250 degrees F, refrigeration oil begins to chemically degrade, losing its ability to lubricate and damaging the valve plates."},{id:"refri_681",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1l es la relaci\xF3n de compresi\xF3n (Compression Ratio) de un sistema con 250 PSIA de descarga y 50 PSIA de succi\xF3n?",opciones:["200:1","5:1","12,500:1","0.2:1"],respuesta_correcta:1,explicacion:"Relaci\xF3n de compresi\xF3n = Presi\xF3n Absoluta de Alta / Presi\xF3n Absoluta de Baja. 250 / 50 = 5.",question:"What is the Compression Ratio of a system with 250 PSIA discharge and 50 PSIA suction?",options:["200:1","5:1","12,500:1","0.2:1"],explanation:"Compression Ratio = Absolute Discharge Pressure divided by Absolute Suction Pressure. 250 / 50 = 5."},{id:"refri_682",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFQu\xE9 tipo de extintor de incendios es el adecuado para un fuego en un panel el\xE9ctrico de un cuarto de m\xE1quinas?",opciones:["Clase A (Agua).","Clase B (Espuma).","Clase C (CO2 o Polvo Qu\xEDmico Seco).","Clase D (Metales)."],respuesta_correcta:2,explicacion:"La Clase C es espec\xEDfica para equipos el\xE9ctricos energizados ya que el agente extintor no conduce electricidad.",question:"What type of fire extinguisher is appropriate for an electrical panel fire in a machine room?",options:["Class A (Water).","Class B (Foam).","Class C (CO2 or Dry Chemical Powder).","Class D (Metals)."],explanation:"Class C is specifically for energized electrical equipment since the extinguishing agent does not conduct electricity."},{id:"refri_683",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFPor qu\xE9 no se debe mezclar aceite Mineral con aceite POE en un sistema con HFC?",opciones:["Porque explotan.","Porque el aceite mineral no se mezcla con los HFC y causar\xE1 problemas de retorno de aceite al compresor.","Porque el aceite POE da\xF1a el cobre.","Porque el sistema se vuelve inflamable."],respuesta_correcta:1,explicacion:"Los refrigerantes HFC (como R-134a, R-404A) no tienen afinidad con el aceite mineral. El aceite se quedar\xEDa estancado en el evaporador.",question:"Why should mineral oil not be mixed with POE oil in an HFC system?",options:["Because they explode.","Because mineral oil does not mix with HFCs and will cause oil return problems to the compressor.","Because POE oil damages copper.","Because the system becomes flammable."],explanation:"HFC refrigerants (such as R-134a, R-404A) have no affinity with mineral oil. The oil would remain stagnant in the evaporator."},{id:"refri_684",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un condensador evaporativo tiene una formaci\xF3n de escamas blancas muy dura en los tubos. \xBFQu\xE9 efecto tiene en la presi\xF3n de alta?",opciones:["La hace bajar.","La hace subir dr\xE1sticamente debido a la mala transferencia de calor.","No la afecta si la bomba de agua funciona.","Limpia el refrigerante internamente."],respuesta_correcta:1,explicacion:"Las escamas (calcio/minerales) act\xFAan como un aislante t\xE9rmico, impidiendo que el calor del refrigerante pase al agua y al aire.",question:"An evaporative condenser has a hard white scale buildup on the tubes. What effect does this have on the high-side pressure?",options:["It makes it drop.","It causes it to rise drastically due to poor heat transfer.","No effect as long as the water pump is working.","It cleans the refrigerant internally."],explanation:"The scale (calcium/mineral deposits) acts as a thermal insulator, preventing the heat from the refrigerant from transferring to the water and air."},{id:"refri_685",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1l es el prop\xF3sito de un 'Oil Equalization Line' en un rack de compresores en paralelo?",opciones:["Mantener el mismo nivel de aceite en todos los c\xE1rteres de los compresores.","Mezclar diferentes tipos de aceite.","Aumentar la presi\xF3n de descarga de los compresores m\xE1s peque\xF1os.","Enfriar el aceite de los compresores de alta."],respuesta_correcta:0,explicacion:"Sin ecualizaci\xF3n, un compresor podr\xEDa 'robarse' el aceite de los dem\xE1s y fallar por falta de lubricaci\xF3n.",question:"What is the purpose of an 'Oil Equalization Line' in a parallel compressor rack?",options:["To maintain the same oil level in all compressor crankcases.","To mix different types of oil.","To increase the discharge pressure of the smaller compressors.","To cool the oil in the high-stage compressors."],explanation:"Without equalization, one compressor could steal all the oil from the others and fail due to lack of lubrication."},{id:"refri_686",categoria:"REFRI_DIAGNOSTICO",pregunta:"Encuentras un evaporador de congelado (Freezer) bloqueado de hielo 'limpio' (transparente) en la bandeja de drenaje. \xBFCu\xE1l es la causa?",opciones:["Falta de gas.","Drenaje obstruido o calentador de drenaje (Drain Heater) quemado.","Ventiladores girando lento.","Puerta mal sellada."],respuesta_correcta:1,explicacion:"Si el agua del deshielo no puede salir por el drenaje (porque est\xE1 congelado o tapado), se queda en la bandeja y se congela al reiniciar el ciclo.",question:"You find a freezer evaporator blocked with clean (clear) ice in the drain pan. What is the cause?",options:["Low refrigerant charge.","A clogged drain or a burned-out drain heater.","Fans spinning too slowly.","A poorly sealed door."],explanation:"If the defrost water cannot exit through the drain (because it is frozen or clogged), it remains in the pan and freezes when the next cooling cycle starts."},{id:"refri_687",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFPara qu\xE9 sirve la funci\xF3n 'Gas Ballast' en una bomba de vac\xEDo?",opciones:["Para que la bomba sople aire fr\xEDo.","Para permitir que una peque\xF1a cantidad de aire seco limpie la humedad del aceite de la bomba durante el vac\xEDo inicial.","Para aumentar el torque del motor de la bomba.","Para vaciar el aceite usado."],respuesta_correcta:1,explicacion:"El lastre de gas evita que el vapor de agua se condense dentro del aceite de la bomba durante las primeras etapas del vac\xEDo.",question:"What is the purpose of the 'Gas Ballast' function on a vacuum pump?",options:["To make the pump blow cold air.","To allow a small amount of dry air to purge moisture from the pump oil during the initial vacuum stage.","To increase the torque of the pump motor.","To drain used oil."],explanation:"The gas ballast prevents water vapor from condensing inside the pump oil during the early stages of evacuation."},{id:"refri_688",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFQu\xE9 es el 'Retrofit' en refrigeraci\xF3n?",opciones:["Pintar el equipo para que parezca nuevo.","Cambiar un refrigerante antiguo (ej. R-22) por uno moderno (ej. R-407C) realizando los cambios de aceite y sellos necesarios.","Aumentar el tama\xF1o del evaporador.","Limpiar el condensador con \xE1cido."],respuesta_correcta:1,explicacion:"Es el proceso de actualizar un sistema para usar un refrigerante con menor impacto ambiental o para el cual haya suministro disponible.",question:"What is a 'Retrofit' in refrigeration?",options:["Painting the equipment to make it look new.","Changing an older refrigerant (e.g., R-22) to a modern one (e.g., R-407C) while performing the necessary oil and seal changes.","Increasing the evaporator size.","Cleaning the condenser with acid."],explanation:"It is the process of updating a system to use a refrigerant with lower environmental impact or one with available supply."},{id:"refri_689",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un t\xE9cnico a\xF1ade refrigerante a un sistema con capilar hasta que el visor est\xE1 lleno. El amperaje est\xE1 un 20% arriba del nominal. \xBFQu\xE9 pasar\xE1?",opciones:["El equipo enfriar\xE1 mejor que nunca.","Habr\xE1 retorno de l\xEDquido (floodback) al compresor, arriesgando las v\xE1lvulas.","El condensador se limpiar\xE1 solo.","Nada, el sistema capilar se autorregula."],respuesta_correcta:1,explicacion:"Los sistemas capilares NO tienen receptor; el exceso de gas se acumula en el evaporador e inunda el compresor.",question:"A technician adds refrigerant to a capillary tube system until the sight glass is clear. The amperage is 20% above the nameplate rating. What will happen?",options:["The unit will cool better than ever.","There will be liquid floodback to the compressor, risking damage to the valve plates.","The condenser will self-clean.","Nothing; a capillary tube system is self-regulating."],explanation:"Capillary tube systems do not have a receiver; excess refrigerant accumulates in the evaporator and floods the compressor."},{id:"refri_690",categoria:"REFRI_DIAGNOSTICO",pregunta:"Encuentras un compresor que 'zumba' pero no arranca. Al medir el capacitor de arranque, este marca su valor correcto. \xBFCu\xE1l es el siguiente paso?",opciones:["Cambiar el compresor.","Verificar el voltaje en los terminales del compresor durante el intento de arranque.","A\xF1adir m\xE1s gas.","Cambiar el termostato."],respuesta_correcta:1,explicacion:"Si hay una ca\xEDda de voltaje excesiva (cables delgados, conexiones flojas), el motor no tendr\xE1 el torque suficiente para vencer la inercia inicial.",question:"You find a compressor that hums but will not start. When measuring the start capacitor, it reads its correct value. What is the next step?",options:["Replace the compressor.","Verify the voltage at the compressor terminals during the start attempt.","Add more refrigerant.","Replace the thermostat."],explanation:"If there is an excessive voltage drop (thin wires, loose connections), the motor will not have enough torque to overcome the initial inertia."},{id:"refri_691",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1l es la forma correcta de cargar refrigerante R-404A en un sistema?",opciones:["Siempre en estado gaseoso.","Siempre en estado l\xEDquido (cilindro invertido si no tiene tubo inmerso) para evitar el fraccionamiento de la mezcla.","No importa el estado.","En estado gaseoso pero calentando el cilindro."],respuesta_correcta:1,explicacion:"Al ser una mezcla (serie 400), si se carga como gas, los componentes se separan y la mezcla dentro del sistema no tendr\xE1 las propiedades correctas.",question:"What is the correct way to charge refrigerant R-404A into a system?",options:["Always as a gas.","Always as a liquid (cylinder inverted if it does not have a dip tube) to prevent fractionation of the blend.","The state does not matter.","As a gas, but while heating the cylinder."],explanation:"Being a blend (400 series), if it is charged as a gas, the components separate and the mixture inside the system will not have the correct properties."},{id:"refri_692",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFQu\xE9 factor tiene m\xE1s impacto en la carga t\xE9rmica de un Walk-in Freezer de uso frecuente?",opciones:["El color de las paredes externas.","La carga por infiltraci\xF3n de aire (apertura de puertas).","La iluminaci\xF3n LED interna.","El tipo de aceite del compresor."],respuesta_correcta:1,explicacion:"En aplicaciones comerciales, el aire caliente y h\xFAmedo que entra al abrir las puertas suele representar la mayor parte del trabajo del sistema.",question:"What factor has the greatest impact on the thermal load of a frequently used Walk-in Freezer?",options:["The color of the exterior walls.","The infiltration load from air (door openings).","The internal LED lighting.","The type of compressor oil."],explanation:"In commercial applications, the warm and humid air that enters when doors are opened typically represents the largest portion of the system workload."},{id:"refri_693",categoria:"REFRI_DIAGNOSTICO",pregunta:"Un cliente se queja de que su aire acondicionado 'huele a calcet\xEDn sucio' (Dirty Sock Syndrome). \xBFD\xF3nde est\xE1 el origen del problema?",opciones:["En el filtro deshidratador de la l\xEDnea de l\xEDquido.","Crecimiento de bacterias y hongos en las aletas del evaporador debido a la humedad acumulada.","Fuga de refrigerante R-22.","El aceite del compresor se est\xE1 quemando."],respuesta_correcta:1,explicacion:"La acumulaci\xF3n de materia org\xE1nica en el evaporador h\xFAmedo crea colonias bacterianas que emiten gases malolientes.",question:"A customer complains that their air conditioner smells like 'dirty socks' (Dirty Sock Syndrome). Where does the problem originate?",options:["In the liquid line filter drier.","Bacteria and mold growth on the evaporator fins due to accumulated moisture.","An R-22 refrigerant leak.","The compressor oil is burning."],explanation:"The accumulation of organic matter on the moist evaporator creates bacterial colonies that emit foul-smelling gases."},{id:"refri_694",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFQu\xE9 sucede con la humedad de una sala si la temperatura del evaporador est\xE1 por debajo del 'Punto de Roc\xEDo' (Dew Point) del aire ambiente?",opciones:["La humedad aumenta.","El agua se condensa en el evaporador y la humedad de la sala disminuye.","No hay ning\xFAn cambio en la humedad.","El aire se vuelve niebla densa."],respuesta_correcta:1,explicacion:"Es el principio b\xE1sico de deshumidificaci\xF3n: enfriar el aire por debajo de su punto de roc\xEDo para retirar el agua.",question:"What happens to room humidity if the evaporator temperature is below the 'Dew Point' of the ambient air?",options:["Humidity increases.","Water condenses on the evaporator and the room humidity decreases.","There is no change in humidity.","The air becomes dense fog."],explanation:"This is the basic principle of dehumidification: cooling the air below its dew point to remove the water."},{id:"refri_695",categoria:"REFRI_DIAGNOSTICO",pregunta:"Al usar un detector de fugas electr\xF3nico, \xBFcu\xE1l es la velocidad de movimiento recomendada de la punta del sensor?",opciones:["Lo m\xE1s r\xE1pido posible.","Aproximadamente 1 a 2 pulgadas por segundo y lo m\xE1s cerca posible de la tuber\xEDa.","Se debe dejar quieto en un solo lugar.","A 1 metro de distancia de las soldaduras."],respuesta_correcta:1,explicacion:"Moverlo muy r\xE1pido impide que el sensor capte la concentraci\xF3n de refrigerante; moverlo muy lento puede dar falsos positivos por acumulaci\xF3n.",question:"When using an electronic leak detector, what is the recommended speed for moving the sensor tip?",options:["As fast as possible.","Approximately 1 to 2 inches per second, as close to the piping as possible.","It should be held still in one spot.","At 1 meter away from the solder joints."],explanation:"Moving it too fast prevents the sensor from detecting the refrigerant concentration; moving it too slowly may give false positives due to gas accumulation."},{id:"refri_696",categoria:"REFRI_DIAGNOSTICO",pregunta:"Si un t\xE9cnico encuentra 'Cera' (waxing) obstruyendo la v\xE1lvula de expansi\xF3n en un sistema de ultra-baja temperatura, \xBFcu\xE1l es el error de mantenimiento previo?",opciones:["Uso de un refrigerante incorrecto.","Uso de aceite mineral no adecuado para bajas temperaturas o mezcla con aceites incompatibles.","Falta de aislamiento en la succi\xF3n.","Carga excesiva de gas."],respuesta_correcta:1,explicacion:"Ciertos aceites separan parafinas (cera) a temperaturas muy bajas, las cuales se solidifican y tapan los orificios peque\xF1os de las v\xE1lvulas.",question:"If a technician finds 'Waxing' blocking the expansion valve in an ultra-low temperature system, what was the previous maintenance error?",options:["Use of an incorrect refrigerant.","Use of mineral oil not suited for low temperatures or mixing with incompatible oils.","Lack of suction line insulation.","Excessive refrigerant charge."],explanation:"Certain oils separate paraffins (wax) at very low temperatures, which solidify and block the small orifices of the valves."},{id:"refri_697",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFQu\xE9 es un 'Suction Line Accumulator' y d\xF3nde debe instalarse?",opciones:["Un tanque para guardar l\xEDquido antes de la TXV.","Un recipiente que atrapa l\xEDquido para que solo gas llegue al compresor, se instala lo m\xE1s cerca posible de la succi\xF3n del compresor.","Un filtro de part\xEDculas met\xE1licas.","Un dispositivo para enfriar el aceite."],respuesta_correcta:1,explicacion:"Evita el golpe de l\xEDquido (slugging), protegiendo mec\xE1nicamente al compresor.",question:"What is a 'Suction Line Accumulator' and where should it be installed?",options:["A tank for storing liquid before the TXV.","A vessel that traps liquid so only gas reaches the compressor, installed as close as possible to the compressor suction.","A metallic particle filter.","A device for cooling the oil."],explanation:"It prevents liquid slugging, mechanically protecting the compressor."},{id:"refri_698",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFCu\xE1l es el procedimiento correcto antes de abrir un sistema de refrigeraci\xF3n industrial para mantenimiento?",opciones:["Simplemente aflojar los tornillos con cuidado.","Recuperar el refrigerante (Pump down) y verificar que la presi\xF3n sea 0 PSI o ligeramente superior con nitr\xF3geno para evitar entrada de aire.","Cerrar los ojos y ventilar.","Aumentar la presi\xF3n de alta para que el gas salga r\xE1pido."],respuesta_correcta:1,explicacion:"Abrir un sistema bajo presi\xF3n es extremadamente peligroso y liberar refrigerante es ilegal en muchas jurisdicciones.",question:"What is the correct procedure before opening an industrial refrigeration system for maintenance?",options:["Simply loosen the bolts carefully.","Recover the refrigerant (Pump Down) and verify the pressure is at 0 PSI or slightly positive with nitrogen to prevent air ingress.","Close your eyes and ventilate.","Increase the high-side pressure so the gas exits quickly."],explanation:"Opening a system under pressure is extremely dangerous, and releasing refrigerant is illegal in many jurisdictions."},{id:"refri_699",categoria:"REFRI_DIAGNOSTICO",pregunta:"Encuentras burbujas en el visor de l\xEDquido, pero el subenfriamiento es de 12\xB0F. \xBFQu\xE9 est\xE1 causando las burbujas?",opciones:["Falta de refrigerante.","Ca\xEDda de presi\xF3n excesiva en la l\xEDnea de l\xEDquido (filtro tapado o tuber\xEDa muy larga/delgada).","Compresor con mucha fuerza.","El condensador est\xE1 muy limpio."],respuesta_correcta:1,explicacion:"Si hay subenfriamiento pero el visor burbujea, el refrigerante se est\xE1 convirtiendo en vapor (flash gas) debido a una p\xE9rdida de presi\xF3n local.",question:"You find bubbles in the liquid sight glass, but the subcooling is 12 degrees F. What is causing the bubbles?",options:["Low refrigerant charge.","Excessive pressure drop in the liquid line (clogged filter drier or piping that is too long or undersized).","Compressor with too much power.","The condenser is too clean."],explanation:"If there is subcooling but the sight glass shows bubbles, the refrigerant is flashing into vapor (flash gas) due to a local pressure loss."},{id:"refri_700",categoria:"REFRI_DIAGNOSTICO",pregunta:"\xBFQu\xE9 significa que un refrigerante sea 'HFO' (Hidrofluoroolefina)?",opciones:["Que contiene cloro.","Que es una nueva generaci\xF3n de refrigerantes con GWP extremadamente bajo debido a su corta vida atmosf\xE9rica.","Que es un gas natural como el propano.","Que es muy t\xF3xico."],respuesta_correcta:1,explicacion:"Los HFO (como el R-1234yf) son la respuesta a las regulaciones contra el calentamiento global.",question:"What does it mean for a refrigerant to be an 'HFO' (Hydrofluoroolefin)?",options:["That it contains chlorine.","That it is a new generation of refrigerants with extremely low GWP due to their short atmospheric lifetime.","That it is a natural gas like propane.","That it is very toxic."],explanation:"HFOs (such as R-1234yf) are the industry's response to global warming regulations."}],REFRI_CATEGORIAS={REFRI_DOMESTICA:{nombre:"Refrigeraci\xF3n Dom\xE9stica",en:"Domestic Refrigeration",icon:"\u{1F3E0}",color:"#0288D1",count:127},REFRI_COMERCIAL:{nombre:"Refrigeraci\xF3n Comercial",en:"Commercial Refrigeration",icon:"\u{1F3EA}",color:"#00838F",count:306},REFRI_INDUSTRIAL:{nombre:"Refrigeraci\xF3n Industrial y Rack",en:"Industrial Refrigeration and Rack",icon:"\u{1F3ED}",color:"#4527A0",count:188},REFRI_CONTROLES:{nombre:"Controles y Electricidad",en:"Controls and Electricity",icon:"\u26A1",color:"#F57F17",count:33},REFRI_DIAGNOSTICO:{nombre:"Diagn\xF3stico y Herramientas",en:"Diagnostics and Tools",icon:"\u{1F527}",color:"#2E7D32",count:46}};
